function act(obs, mem) {
  const clamp = (v, a, b) => (v < a ? a : (v > b ? b : v));
  const wr = (d) => { d = d % 360; if (d > 180) d -= 360; if (d < -180) d += 360; return d; };
  const D2R = Math.PI / 180, R2D = 180 / Math.PI;
  const hyp = (a, b) => Math.sqrt(a * a + b * b);
  const dt = 0.1;
  const RAYA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

  // ================= INIT =================
  if (!mem.init) {
    const M = obs.mission;
    mem.init = 1;
    let sz = 400;
    if (M && M.size) sz = (typeof M.size === 'number') ? M.size : (M.size.x || 400);
    mem.size = sz;
    mem.bx = M.base.x; mem.by = M.base.y;
    mem.cap = M.capacity || 5;
    mem.hints = (M.hints || []).map(h => ({ x: h.x, y: h.y, est: h.estimate || 1, st: 0, hint: true }));
    mem.px = obs.x; mem.py = obs.y; mem.h = obs.heading;
    mem.cbias = 0;
    mem.lgx = obs.x; mem.lgy = obs.y; mem.lgt = obs.t;
    mem.gspd = 0; mem.vs = 0;
    mem.gL = 1.6; mem.gR = 1.6; mem.dz = 0.06;
    mem.epm0 = 0.001; mem.epmS = 0.00008;
    mem.avgV = 1.15;
    mem.state = 'decide'; mem.tgt = null;
    mem.escT = 0; mem.escPhase = 0; mem.escDir = 1;
    mem.drillPos = null; mem.sampleT = 0;
    mem.searchT = 0; mem.bestSci = -1; mem.bestSciPos = null;
    mem.noImproveT = 0; mem.probePos = null; mem.probeN = 0; mem.noSciT = 0;
    mem.lastBatt = obs.battery;
    mem.posX = obs.x; mem.posY = obs.y; mem.posT = 0;
    mem.compBadT = -1e9;
    mem.explTried = [];
    mem.sitePos = null; mem.lastCmd = null;
    mem.raySameT = 0; mem.raysBad = false;
    mem.stillCount = 0;
  }

  // ================= SENSING =================
  const wl = obs.wheelLeft || 0, wrt = obs.wheelRight || 0;
  const spd = (wl + wrt) / 2, aspd = Math.abs(spd);
  const omg = (wrt - wl) / 0.6;
  const RAYS = obs.rays || [];
  const carried = obs.carried || 0;

  // ---- motor model learning ----
  if (mem.lastCmd) {
    const lc = mem.lastCmd.left, rc = mem.lastCmd.right;
    if (Math.abs(lc) > 0.15 && Math.abs(wl) > 0.03) {
      const g = wl / lc;
      if (g > 0.15 && g < 8) mem.gL = mem.gL * 0.98 + g * 0.02;
    }
    if (Math.abs(rc) > 0.15 && Math.abs(wrt) > 0.03) {
      const g = wrt / rc;
      if (g > 0.15 && g < 8) mem.gR = mem.gR * 0.98 + g * 0.02;
    }
    if (Math.abs(lc) > 0.05 && Math.abs(lc) < 0.35 && Math.abs(wl) < 0.02 && Math.abs(wrt) > 0.06) {
      mem.dz = clamp(Math.max(mem.dz, Math.abs(lc) * 1.1), 0.02, 0.3);
    }
    if (Math.abs(rc) > 0.05 && Math.abs(rc) < 0.35 && Math.abs(wrt) < 0.02 && Math.abs(wl) > 0.06) {
      mem.dz = clamp(Math.max(mem.dz, Math.abs(rc) * 1.1), 0.02, 0.3);
    }
    mem.dz = Math.max(0.02, mem.dz * 0.9996);
    mem.gL = clamp(mem.gL, 0.3, 6); mem.gR = clamp(mem.gR, 0.3, 6);
  }

  // ---- ray health (stuck / blind sensors) ----
  let raysSame = (RAYS.length === 9);
  if (raysSame) for (let i = 1; i < 9; i++) if (RAYS[i] !== RAYS[0]) { raysSame = false; break; }
  if (raysSame && typeof RAYS[0] === 'number' && RAYS[0] < 14.5) mem.raySameT += dt; else mem.raySameT = 0;
  mem.raysBad = mem.raySameT > 20;

  // ---- position / heading fusion ----
  const gpsNew = (obs.x !== mem.lgx || obs.y !== mem.lgy);
  const hR0 = mem.h * D2R;
  mem.px += spd * Math.cos(hR0) * dt;
  mem.py += spd * Math.sin(hR0) * dt;
  mem.h = wr(mem.h + omg * dt * R2D);
  if (obs.t - mem.compBadT > 35) {
    mem.h = wr(mem.h + 0.045 * wr((obs.heading + mem.cbias) - mem.h));
  }
  if (gpsNew) {
    const gdt = Math.max(0.05, obs.t - mem.lgt);
    const gvx = (obs.x - mem.lgx) / gdt, gvy = (obs.y - mem.lgy) / gdt;
    const gs = hyp(gvx, gvy);
    mem.gspd = mem.gspd * 0.6 + gs * 0.4;
    const hR1 = mem.h * D2R;
    mem.vs = mem.vs * 0.5 + clamp(gvx * Math.cos(hR1) + gvy * Math.sin(hR1), -4, 4) * 0.5;
    if (gs > 0.6 && gs < 12) {
      const hv = Math.atan2(gvy, gvx) * R2D;
      const err = wr(hv - mem.h);
      if (Math.abs(err) > 55) {
        mem.compBadT = obs.t;
        mem.h = wr(mem.h + 0.4 * err);
      } else {
        mem.h = wr(mem.h + 0.10 * err);
        if (gs > 1.0 && Math.abs(omg) < 0.15) mem.cbias = wr(mem.cbias + 0.015 * wr(hv - (obs.heading + mem.cbias)));
      }
    }
    const dxg = obs.x - mem.px, dyg = obs.y - mem.py;
    const jump = hyp(dxg, dyg);
    if (jump < 15) { mem.px += 0.45 * dxg; mem.py += 0.45 * dyg; }
    else { mem.px += 0.05 * dxg; mem.py += 0.05 * dyg; }
    mem.lgx = obs.x; mem.lgy = obs.y; mem.lgt = obs.t;
  } else {
    mem.gspd *= 0.96; mem.vs *= 0.94;
  }

  mem.stillCount = (aspd < 0.13) ? ((mem.stillCount || 0) + 1) : 0;
  const still = mem.stillCount >= 5;

  // ---- energy model ----
  const usedE = (obs.solar || 0) * dt - (obs.battery - mem.lastBatt);
  mem.lastBatt = obs.battery;
  const distM = aspd * dt;
  if (distM > 0.012 && usedE > -0.005) {
    const cpm = usedE / distM;
    if (cpm > -0.001 && cpm < 0.5) {
      if (carried === 0) mem.epm0 = mem.epm0 * 0.99 + cpm * 0.01;
      else {
        const sl = (cpm - mem.epm0) / carried;
        if (sl > -0.0002 && sl < 0.1) mem.epmS = mem.epmS * 0.99 + sl * 0.01;
      }
    }
    mem.avgV = clamp(mem.avgV * 0.995 + aspd * 0.005, 0.3, 3.5);
  }

  // ---- site observation ----
  if (obs.site) {
    const s = obs.site;
    const a = (mem.h + s.bearing) * D2R;
    mem.sitePos = { x: mem.px + s.distance * Math.cos(a), y: mem.py + s.distance * Math.sin(a) };
  }

  // ================= DERIVED =================
  const x = mem.px, y = mem.py;
  const dBase = hyp(mem.bx - x, mem.by - y);
  const epmNow = Math.max(2e-5, mem.epm0 + mem.epmS * carried);
  const bfE = dBase * epmNow * 1.55 + 0.03;
  const bfT = dBase / Math.max(0.35, mem.avgV) * 1.35 + 6;
  const mustReturn = (obs.battery < bfE * 1.12 + 0.015) || (obs.timeLeft < bfT * 1.12 + 8) || (carried >= mem.cap);

  // ================= HELPERS =================
  function tripFeasible(h) {
    const d = hyp(h.x - x, h.y - y) + hyp(mem.bx - h.x, mem.by - h.y);
    const k = carried + 1;
    const e = d * Math.max(2e-5, mem.epm0 + mem.epmS * k) * 1.35 + 0.04;
    const t = d / Math.max(0.35, mem.avgV) * 1.25 + 15;
    return (obs.battery - e > 0.025) && (obs.timeLeft - t > 12);
  }

  function toCmds(vl, vr) {
    let cl = vl / mem.gL, cr = vr / mem.gR;
    if (Math.abs(vl) > 0.05 && Math.abs(cl) < mem.dz) cl = (vl > 0 ? 1 : -1) * mem.dz;
    if (Math.abs(vr) > 0.05 && Math.abs(cr) < mem.dz) cr = (vr > 0 ? 1 : -1) * mem.dz;
    return { left: clamp(cl, -1, 1), right: clamp(cr, -1, 1) };
  }

  function driveTo(tgtX, tgtY, vmax, stopR) {
    const dxw = tgtX - mem.px, dyw = tgtY - mem.py;
    const dT = hyp(dxw, dyw);
    if (dT < 0.06) return { left: 0, right: 0 };
    const e0 = wr(Math.atan2(dyw, dxw) * R2D - mem.h);
    const vx = Math.cos(e0 * D2R), vy = Math.sin(e0 * D2R);
    let rx = 0, ry = 0, minR = 15;
    if (!mem.raysBad) {
      for (let i = 0; i < 9; i++) {
        const d = RAYS[i];
        if (typeof d === 'number' && d > 0.05 && d < 14.8) {
          if (d < minR) minR = d;
          const a = RAYA[i] * D2R;
          const w = (11 - Math.min(d, 11)) / 11;
          const w2 = w * w * 2.4;
          rx -= w2 * Math.cos(a); ry -= w2 * Math.sin(a);
        }
      }
    }
    const rep = dT < 10 ? (0.45 + 0.055 * dT) : 1;
    const e = Math.atan2(vy + ry * rep, vx + rx * rep) * R2D;
    let v = Math.max(0, vmax);
    if (!mem.raysBad && minR < 4.5) {
      const cap = minR < 1.6 ? (0.16 + (minR - 0.5) * 0.32) : (0.3 + (minR - 0.6) * 0.5);
      v = Math.min(v, Math.max(0.12, cap));
    }
    const ae = Math.abs(e);
    v *= clamp(1 - ae / 85, 0.12, 1);
    if (dT < stopR + 4) v = Math.min(v, clamp((dT - stopR) * 0.8, -0.35, vmax));
    if (ae > 105 && dT > 3) v = 0;
    const om = clamp(0.030 * e, -1.25, 1.25);
    return toCmds(v - om * 0.3, v + om * 0.3);
  }

  function holdCmd() {
    const dp = mem.drillPos || { x: mem.px, y: mem.py, h: mem.h };
    const hR2 = mem.h * D2R;
    const ex = (dp.x - mem.px) * Math.cos(hR2) + (dp.y - mem.py) * Math.sin(hR2);
    const eh = wr(dp.h - mem.h);
    const damp = 0.18 * clamp(mem.vs || 0, -0.5, 0.5);
    let vl = 0.20 * ex - 0.28 * wl - damp;
    let vr = 0.20 * ex - 0.28 * wrt - damp;
    const omc = clamp(0.0032 * eh, -0.18, 0.18);
    vl = clamp(vl - omc, -0.28, 0.28);
    vr = clamp(vr + omc, -0.28, 0.28);
    return toCmds(vl, vr);
  }

  function pickExplore() {
    for (let i = 0; i < 25; i++) {
      const ang = Math.random() * Math.PI * 2;
      const r = 55 + Math.random() * 120;
      const ex = clamp(mem.bx + r * Math.cos(ang), 15, mem.size - 15);
      const ey = clamp(mem.by + r * Math.sin(ang), 15, mem.size - 15);
      let ok = true;
      for (let j = 0; j < mem.explTried.length; j++) {
        const p = mem.explTried[j];
        if (hyp(p.x - ex, p.y - ey) < 45) { ok = false; break; }
      }
      if (ok) {
        mem.explTried.push({ x: ex, y: ey });
        const h = { x: ex, y: ey, est: 2, st: 4, hint: false };
        if (tripFeasible(h)) return h;
      }
    }
    return null;
  }

  // ================= STATE MACHINE =================
  let mode = 'drive', tx = x, ty = y, vmax = 1.9, stopR = 1.2;

  if (obs.docked && still && (mem.state === 'return' || mem.state === 'decide')) mem.state = 'dock';

  if (mem.state === 'decide') {
    let best = null, bs = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.st !== 0) continue;
      const d = hyp(h.x - x, h.y - y);
      const sc = h.est / (d + 30);
      if (sc > bs && tripFeasible(h)) { bs = sc; best = h; }
    }
    if (best && !mustReturn) { mem.tgt = best; mem.state = 'outbound'; }
    else if (carried > 0 || dBase > 10) { mem.state = 'return'; }
    else if (!best && obs.timeLeft > 420 && obs.battery > 0.62 && carried === 0) {
      const e2 = pickExplore();
      if (e2) { mem.tgt = e2; mem.state = 'outbound'; } else { mem.state = 'dock'; }
    } else { mem.state = 'dock'; }
  }

  // global safety: abandon work and go home when running out of time/energy/capacity
  if (mustReturn && (mem.state === 'outbound' || mem.state === 'search' ||
      (mem.state === 'approach' && !(obs.site && obs.site.distance < 2.2)))) {
    mem.state = 'return'; mem.tgt = null;
  }

  if (mem.state === 'sample') {
    mode = 'hold';
    mem.sampleT += dt;
    const drilled = (typeof obs.drilling === 'number' && obs.drilling >= 6.0);
    const lost = (!obs.site && mem.sampleT > 3);
    if (drilled || lost || mem.sampleT > 28 || obs.battery < 0.04) {
      if (drilled || lost) {
        for (let i = 0; i < mem.hints.length; i++) {
          const h = mem.hints[i];
          if (h.st === 0 && hyp(h.x - mem.px, h.y - mem.py) < 24) h.st = 1;
        }
      }
      mem.state = 'decide'; mem.tgt = null; mem.drillPos = null; mode = 'idle';
    } else if (obs.site && obs.site.distance > 1.7 && mem.sampleT > 8) {
      mem.state = 'approach'; mode = 'drive';
    }
  } else if (mem.state === 'dock') {
    mode = 'idle';
    if (!mustReturn && obs.timeLeft > 30) {
      let best = null, bs = -1;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (h.st !== 0) continue;
        const d = hyp(h.x - x, h.y - y);
        const sc = h.est / (d + 30);
        if (sc > bs && tripFeasible(h)) { bs = sc; best = h; }
      }
      if (best) { mem.tgt = best; mem.state = 'outbound'; mode = 'drive'; }
      else if (obs.timeLeft > 420 && obs.battery > 0.62 && carried === 0) {
        const e2 = pickExplore();
        if (e2) { mem.tgt = e2; mem.state = 'outbound'; mode = 'drive'; }
      }
    }
  } else if (mem.state === 'return') {
    tx = mem.bx; ty = mem.by; vmax = 1.9; stopR = 1.0;
    if (obs.beacon) {
      const a = (mem.h + obs.beacon.bearing) * D2R;
      tx = x + obs.beacon.distance * Math.cos(a);
      ty = y + obs.beacon.distance * Math.sin(a);
    }
    if (dBase < 6) vmax = 1.1;
    if (dBase < 3.2 && still) { mem.state = 'dock'; mode = 'idle'; }
  } else if (mem.state === 'approach') {
    if (obs.site) {
      const s = obs.site;
      const a = (mem.h + s.bearing) * D2R;
      mem.sitePos = { x: x + s.distance * Math.cos(a), y: y + s.distance * Math.sin(a) };
      tx = mem.sitePos.x; ty = mem.sitePos.y;
      vmax = clamp(0.3 + s.distance * 0.55, 0.28, 1.5);
      stopR = 0.75;
      if (s.distance < 1.15 && still) {
        mem.state = 'sample'; mem.drillPos = { x: mem.px, y: mem.py, h: mem.h }; mem.sampleT = 0;
        mode = 'hold';
      }
    } else if (mem.sitePos) {
      tx = mem.sitePos.x; ty = mem.sitePos.y; vmax = 1.1; stopR = 1.0;
      if (hyp(mem.sitePos.x - x, mem.sitePos.y - y) < 1.8) {
        if (mem.tgt) {
          mem.state = 'search'; mem.searchT = 35;
          mem.bestSci = -1; mem.probePos = null; mem.noImproveT = 0; mem.noSciT = 0;
        } else { mem.state = 'decide'; mode = 'idle'; }
      }
    } else { mem.state = 'decide'; mode = 'idle'; }
  } else if (mem.state === 'search') {
    if (!mem.tgt) { mem.state = 'decide'; mode = 'idle'; }
    else {
      mem.searchT += dt;
      const dHint = hyp(mem.tgt.x - x, mem.tgt.y - y);
      if (obs.site && carried < mem.cap) {
        mem.state = 'approach';
      } else if (dHint > 11) {
        tx = mem.tgt.x; ty = mem.tgt.y; vmax = 1.7; stopR = 2.0;
      } else {
        const sci = obs.science || 0;
        if (sci > 1e-6) {
          if (mem.probePos && hyp(mem.probePos.x - x, mem.probePos.y - y) < 2.2) mem.probePos = null;
          if (mem.bestSci < 0 || sci > mem.bestSci * 1.02) {
            mem.bestSci = sci; mem.bestSciPos = { x: mem.px, y: mem.py };
            mem.noImproveT = 0; mem.probePos = null;
          } else mem.noImproveT += dt;
          if (!mem.probePos && mem.noImproveT > 3.0) {
            mem.probeN++;
            const ang = (mem.probeN * 137.5) * D2R;
            const bp = mem.bestSciPos || { x: mem.tgt.x, y: mem.tgt.y };
            mem.probePos = {
              x: clamp(bp.x + 10 * Math.cos(ang), 8, mem.size - 8),
              y: clamp(bp.y + 10 * Math.sin(ang), 8, mem.size - 8)
            };
            mem.noImproveT = 0;
          }
          const p = mem.probePos || mem.bestSciPos || { x: mem.tgt.x, y: mem.tgt.y };
          tx = p.x; ty = p.y; vmax = 1.25; stopR = 1.5;
        } else {
          mem.noSciT += dt;
          if (mem.noSciT > 4.5) { mem.tgt.st = 2; mem.tgt = null; mem.state = 'decide'; mode = 'idle'; }
          else { tx = mem.tgt.x; ty = mem.tgt.y; vmax = 0.9; stopR = 3.0; }
        }
      }
      if (mem.state === 'search' && mem.searchT > 75) {
        mem.tgt.st = 2; mem.tgt = null; mem.state = 'decide'; mode = 'idle';
      }
    }
  } else if (mem.state === 'outbound') {
    if (!mem.tgt) { mem.state = 'decide'; mode = 'idle'; }
    else {
      tx = mem.tgt.x; ty = mem.tgt.y; vmax = 1.9; stopR = 1.5;
      const dT = hyp(tx - x, ty - y);
      if (obs.site && carried < mem.cap && !mustReturn) mem.state = 'approach';
      else if (mem.tgt.hint && dT < 28) {
        mem.state = 'search';
        mem.searchT = 0; mem.bestSci = -1; mem.bestSciPos = null;
        mem.probePos = null; mem.noImproveT = 0; mem.noSciT = 0;
      } else if (!mem.tgt.hint && dT < 3.5) { mem.tgt = null; mem.state = 'decide'; }
    }
  } else { mode = 'idle'; }

  // ================= COMMAND =================
  let out;
  if (mode === 'hold') out = holdCmd();
  else if (mode === 'idle') out = { left: 0, right: 0 };
  else out = driveTo(tx, ty, vmax, stopR);

  const nearTgt = (mem.state === 'approach' && obs.site && obs.site.distance < 2.5) ||
                  (mem.state === 'return' && dBase < 5);
  if (mode === 'drive' && mem.escT <= 0 && !nearTgt) {
    mem.posT += dt;
    if (mem.posT >= 2) {
      const moved = hyp(mem.px - mem.posX, mem.py - mem.posY);
      if (moved < 0.55) { mem.escT = 2.0; mem.escPhase = 0; }
      mem.posX = mem.px; mem.posY = mem.py; mem.posT = 0;
    }
  }
  if (obs.bumped && mem.escT < 1.0 && mode !== 'hold') { mem.escT = 1.5; mem.escPhase = 0; }
  if (mem.escT > 0 && mode === 'drive') {
    mem.escT -= dt;
    if (mem.escPhase === 0) {
      out = toCmds(-0.55, -0.55);
      if (mem.escT < 1.3) mem.escPhase = 1;
    } else {
      out = toCmds(-0.55 * mem.escDir, 0.55 * mem.escDir);
    }
    if (mem.escT <= 0) mem.escDir = -mem.escDir;
  }

  mem.lastCmd = out;
  return { left: out.left, right: out.right, drill: mem.state === 'sample' };
}

function act(obs, mem) {
    const DT = 0.1;
    const cl = (v, a, b) => v < a ? a : (v > b ? b : v);
    const w180 = d => { d = d % 360; if (d > 180) d -= 360; if (d < -180) d += 360; return d; };
    const hyp2 = (a, b) => Math.sqrt(a * a + b * b);
    const D2R = Math.PI / 180, R2D = 180 / Math.PI;

    if (!mem.init) {
        const M = obs.mission || {};
        mem.size = typeof M.size === 'number' ? M.size : ((M.size && M.size.x) || 400);
        mem.bx = (M.base && M.base.x) || obs.x;
        mem.by = (M.base && M.base.y) || obs.y;
        mem.cap = M.capacity || 5;
        mem.hints = (M.hints || []).map((h, i) => ({ x: h.x, y: h.y, est: h.estimate || 1, id: i, st: 0 }));
        mem.px = obs.x; mem.py = obs.y; mem.h = obs.heading || 0;
        mem.cpm = 0.0008;
        mem.avgSpd = 1.5;
        mem.state = 'PLAN'; mem.tgt = null; mem.stT = 0; mem.driveT = 120;
        mem.sitePos = null;
        mem.holdX = 0; mem.holdY = 0; mem.holdH = 0;
        mem.stuckT = 0; mem.escT = 0; mem.escDir = 1;
        mem.startBatt = obs.battery; mem.totalDist = 0;
        mem.prevCarried = obs.carried || 0;
        mem.init = 1;
    }

    const wL = obs.wheelLeft || 0, wR = obs.wheelRight || 0;
    const spd = (wL + wR) / 2, aspd = Math.abs(spd);
    const omg = (wR - wL) / 0.6;

    mem.px += spd * Math.cos(mem.h * D2R) * DT;
    mem.py += spd * Math.sin(mem.h * D2R) * DT;
    mem.h = w180(mem.h + omg * DT * R2D);
    if (!isFinite(mem.px)) mem.px = obs.x || 0;
    if (!isFinite(mem.py)) mem.py = obs.y || 0;
    if (!isFinite(mem.h)) mem.h = obs.heading || 0;

    const gx = isFinite(obs.x) ? obs.x : mem.px;
    const gy = isFinite(obs.y) ? obs.y : mem.py;
    const gdx = gx - mem.px, gdy = gy - mem.py, gerr = hyp2(gdx, gdy);
