    mem.energyDist = 0;
    mem.prevCarried = carried;
    mem.lastDelivered = finite(obs.delivered, 0);
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
  if (!Number.isFinite(mem.activeTask)) mem.activeTask = -1;
  if (!Number.isFinite(mem.sampleTaskId)) mem.sampleTaskId = -1;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.001;
  if (!Number.isFinite(mem.ePerSec)) mem.ePerSec = 0.001;
  if (!Number.isFinite(mem.navX)) mem.navX = rawX;
  if (!Number.isFinite(mem.navY)) mem.navY = rawY;
  if (!Number.isFinite(mem.headEst)) mem.headEst = rawHeading;

  const dtRaw = now - finite(mem.lastT, now);
  const dt = (dtRaw > 0 && dtRaw <= 0.5) ? dtRaw : 0.1;
  const vAvg = (wl + wr) * 0.5;
  const expectedYaw = clamp((wr - wl) / 0.6 * dt * 57.2957795, -60, 60);
  const rawHeadingDelta = angleDiff(rawHeading, finite(mem.lastRawHeading, rawHeading));

  if (Math.abs(rawHeadingDelta) > 55 && Math.abs(expectedYaw) < 22) {
    mem.compassBias = wrap(finite(mem.compassBias, 0) + rawHeadingDelta);
  }

  if (Math.abs(rawHeadingDelta) < 0.12 && Math.abs(expectedYaw) > 1.2) {
    mem.compStall = finite(mem.compStall, 0) + dt;
  } else {
    mem.compStall = Math.max(0, finite(mem.compStall, 0) - 1.5 * dt);
  }

  const predictedHeading = wrap(mem.headEst + expectedYaw);
  const correctedSensorHeading = wrap(rawHeading - finite(mem.compassBias, 0));
  if (mem.compStall > 0.8) {
    mem.headEst = predictedHeading;
  } else {
    mem.headEst = wrap(predictedHeading + 0.72 * angleDiff(correctedSensorHeading, predictedHeading));
  }

  const rawMove = dist(rawX, rawY, finite(mem.lastRawX, rawX), finite(mem.lastRawY, rawY));
  const wasGpsBad = !!mem.gpsBad;

  if (rawMove > 0.12) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsStallOdom = 0;
    mem.gpsBad = false;
  } else {
    if (dist(rawX, rawY, finite(mem.gpsAnchorX, rawX), finite(mem.gpsAnchorY, rawY)) > 0.28) {
      mem.gpsAnchorX = rawX;
      mem.gpsAnchorY = rawY;
      mem.gpsStallOdom = 0;
    } else {
      mem.gpsStallOdom = finite(mem.gpsStallOdom, 0) + Math.abs(vAvg) * dt;
    }
    if (mem.gpsStallOdom > 2.0 &&
        dist(rawX, rawY, finite(mem.gpsAnchorX, rawX), finite(mem.gpsAnchorY, rawY)) < 0.28) {
      mem.gpsBad = true;
    }
  }

  const predX = mem.navX + vAvg * Math.cos(mem.headEst * Math.PI / 180) * dt;
  const predY = mem.navY + vAvg * Math.sin(mem.headEst * Math.PI / 180) * dt;
  if (mem.gpsBad) {
    mem.navX = predX;
    mem.navY = predY;
  } else {
    const rx = rawX - predX;
    const ry = rawY - predY;
    const residual = Math.hypot(rx, ry);
    let gain = Math.abs(vAvg) > 0.2 ? 0.16 : 0.045;
    if (residual > 18) gain = 0.015;
    else if (residual > 5) gain = 0.045;
    if (wasGpsBad) gain = 0.38;
    mem.navX = predX + gain * rx;
    mem.navY = predY + gain * ry;
  }

  if (now - finite(mem.calT, now) >= 2.0) {
    const cx = rawX - finite(mem.calX, rawX);
    const cy = rawY - finite(mem.calY, rawY);
    const cd = Math.hypot(cx, cy);
    const headingChange = Math.abs(angleDiff(mem.headEst, finite(mem.calHead, mem.headEst)));
    if (!mem.gpsBad && cd > 1.1 && headingChange < 14 &&
        Math.abs(wr - wl) < 0.65 && Math.abs(vAvg) > 0.25) {
      const motionBearing = Math.atan2(cy, cx) * 180 / Math.PI;
      const biasMeasurement = wrap(rawHeading - motionBearing);
      const err = angleDiff(biasMeasurement, finite(mem.compassBias, 0));
      const alpha = Math.abs(err) > 35 ? 0.16 : 0.07;
      mem.compassBias = wrap(mem.compassBias + alpha * err);
      const calibrated = wrap(rawHeading - mem.compassBias);
      mem.headEst = wrap(mem.headEst + 0.22 * angleDiff(calibrated, mem.headEst));
    }
    mem.calX = rawX;
    mem.calY = rawY;
    mem.calT = now;
    mem.calHead = mem.headEst;
  }

  mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
  if (now - finite(mem.energyStartT, now) >= 4.0) {
    const eDur = Math.max(0.1, now - finite(mem.energyStartT, now));
    const eDist = finite(mem.energyDist, 0);
    const loss = finite(mem.energyStartBattery, battery) - battery;
    if (!obs.docked && loss > 0.0002) {
      if (eDist > 1.0) {
        const measured = clamp(loss / eDist, 0.00025, 0.03);
        mem.ePerM = clamp(0.78 * mem.ePerM + 0.22 * measured, 0.00025, 0.03);
        const perSecond = clamp(loss / eDur, 0.00005, 0.08);
        mem.ePerSec = clamp(0.78 * mem.ePerSec + 0.22 * perSecond, 0.00005, 0.08);
      } else if (!obs.drilling) {
        const perSecond = clamp(loss / eDur, 0.00005, 0.04);
        mem.ePerSec = clamp(0.88 * mem.ePerSec + 0.12 * perSecond, 0.00005, 0.04);
      }
    }
    mem.energyStartT = now;
    mem.energyStartBattery = battery;
    mem.energyDist = 0;
  }

  const navX = mem.navX;
  const navY = mem.navY;
  const head = mem.headEst;
  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let staleRays = 0;
  if (rays) {
    for (let i = 0; i < rays.length; i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.015 && Math.abs(vAvg) > 0.35 && r < 14.7) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 2.6 && r < 14.7) staleRays++;
    }
  }
  const raysBlind = !rays || rays.length < 5 || staleRays >= 6;

  let baseDist = dist(navX, navY, mem.baseX, mem.baseY);
  const beacon = obs.beacon;
  const beaconValid = beacon && Number.isFinite(beacon.distance) &&
                      Number.isFinite(beacon.bearing) && beacon.distance >= 0;
  if (beaconValid) {
    baseDist = Math.max(beacon.distance, baseDist * 0.72);
  }

  if (mem.leaving && (!obs.docked || baseDist > 4.0)) mem.leaving = false;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) if (task.id === id) return task;
    return null;
  }

  function makeSearchPoints(task, centerX, centerY, pass, offsets) {
    task.searchCenterX = centerX;
    task.searchCenterY = centerY;
    task.searchPass = pass;
    task.searchPoints = [];
    task.searchIdx = 0;
    task.searchSamples = [];
    for (const p of offsets) {
      task.searchPoints.push({
        x: clamp(centerX + p[0], 2, mem.mapW - 2),
        y: clamp(centerY + p[1], 2, mem.mapH - 2)
      });
    }
  }

  function startSearch(task, centerX, centerY, pass) {
    task.searchStarted = true;
    task.searchUsed = finite(task.searchUsed, 0);
    task.bestScience = Math.max(0, finite(obs.science, 0));
    task.bestX = navX;
    task.bestY = navY;
    task.searchStage = 0;
    if (pass === 0) {
      makeSearchPoints(task, centerX, centerY, 0,
        [[0, 0], [8, 0], [0, 8], [-8, 0], [0, -8]]);
    } else {
      makeSearchPoints(task, centerX, centerY, 1,
        [[0, 0], [6, 0], [0, 6], [-6, 0], [0, -6],
         [6, 6], [-6, 6], [-6, -6], [6, -6]]);
    }
  }

  function finishSearchStage(task) {
    const sig = Math.max(0, finite(task.bestScience, 0));
    if (task.searchPass === 0 && task.searchStage === 0) {
      const s = task.searchSamples || [];
      const east = finite(s[1], 0);
      const north = finite(s[2], 0);
      const west = finite(s[3], 0);
      const south = finite(s[4], 0);
      let gx = east - west;
      let gy = north - south;
      const gn = Math.hypot(gx, gy);
      const threshold = Math.max(0.002, sig * 0.035);
      if (gn > threshold) {
        gx /= gn;
        gy /= gn;
        const cx = finite(task.searchCenterX, task.x);
        const cy = finite(task.searchCenterY, task.y);
        task.searchStage = 1;
        makeSearchPoints(task, cx, cy, 0,
          [[gx * 12, gy * 12], [gx * 18, gy * 18], [gx * 24, gy * 24]]);
      } else {
        const cx = finite(task.searchCenterX, task.x);
        const cy = finite(task.searchCenterY, task.y);
        task.searchStage = 2;
        makeSearchPoints(task, cx, cy, 0,
          [[12, -12], [12, 12], [-12, 12], [-12, -12]]);
      }
      return true;
    }
    if (task.searchPass === 0 && task.searchStage === 1) {
      const cx = finite(task.searchCenterX, task.x);
      const cy = finite(task.searchCenterY, task.y);
      task.searchStage = 2;
      makeSearchPoints(task, cx, cy, 0,
        [[12, -12], [12, 12], [-12, 12], [-12, -12]]);
      return true;
    }
    if (task.searchPass === 0 && task.searchStage === 2 && sig > 0.002 &&
        finite(task.searchUsed, 0) < 145) {
      startSearch(task, finite(task.bestX, task.x), finite(task.bestY, task.y), 1);
      return true;
    }
    task.status = 3;
    task.searchStarted = false;
    return false;
  }

  function advanceSearch(task) {
    if (!task.searchStarted) return null;
    task.searchUsed = finite(task.searchUsed, 0) + dt;
    const signal = Math.max(0, finite(obs.science, 0));
    const oldBest = Math.max(0, finite(task.bestScience, 0));
    if (signal > oldBest + Math.max(0.001, oldBest * 0.025)) {
      task.bestScience = signal;
      task.bestX = navX;
      task.bestY = navY;
    }

    if (!Array.isArray(task.searchPoints) || task.searchPoints.length === 0) {
      startSearch(task, finite(task.searchCenterX, task.x), finite(task.searchCenterY, task.y),
                  finite(task.searchPass, 0));
    }

    let guard = 0;
    while (task.searchIdx < task.searchPoints.length && guard++ < 8) {
      const p = task.searchPoints[task.searchIdx];
      if (dist(navX, navY, p.x, p.y) > 2.5) break;
      task.searchSamples[task.searchIdx] = Math.max(
        finite(task.searchSamples[task.searchIdx], 0), signal);
      task.searchIdx++;
    }

    if (task.searchIdx >= task.searchPoints.length) {
      if (task.searchUsed > 155 || !finishSearchStage(task)) return null;
    }
    if (task.status === 3) return null;
    if (task.searchIdx >= task.searchPoints.length) return null;
    return task.searchPoints[task.searchIdx];
  }

  function taskGoal(task) {
    if (task.actual) return { x: task.x, y: task.y, key: "site-" + task.id };
    if (task.searchStarted && Array.isArray(task.searchPoints) &&
        task.searchIdx < task.searchPoints.length) {
      const p = task.searchPoints[task.searchIdx];
      return { x: p.x, y: p.y, key: "search-" + task.id + "-" + task.searchPass + "-" + task.searchStage + "-" + task.searchIdx };
    }
    return { x: task.x, y: task.y, key: "hint-" + task.id };
  }

  function taskMetrics(task, fromX, fromY) {
    const goal = taskGoal(task);
    const d1 = dist(fromX, fromY, goal.x, goal.y);
    const dBase = dist(task.x, task.y, mem.baseX, mem.baseY) + (task.actual ? 0 : 7);
    let searchExtra = 0;
    if (!task.actual) {
      if (task.searchStarted) {
        const remain = Math.max(0, task.searchPoints.length - task.searchIdx);
        searchExtra = Math.min(100, remain * 6.0);
      } else {
        searchExtra = 42;
      }
    }
    const rate = Math.max(finite(mem.ePerM, 0.001), finite(mem.ePerSec, 0.001));
    const cargoFactor = 1 + 0.09 * carried;
    const need = 0.09 + rate * (d1 + dBase + searchExtra) * 1.82 * cargoFactor +
                 (task.actual ? 0.012 : 0.028);
    const timeNeed = (d1 + dBase + searchExtra) * 1.25 + (task.actual ? 20 : 24);
    return { d1, dBase, searchExtra, need, timeNeed, goal };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      const m = taskMetrics(task, fromX, fromY);
      if (m.need > 1.04 || timeLeft < m.timeNeed) continue;
      if (!atDock && battery < m.need + 0.025) continue;
      let value = Math.max(0.15, finite(task.val, 1));
      if (!task.actual) value *= task.hinted ? 0.78 : 0.58;
      let score = value / (34 + m.d1 + 0.62 * m.dBase + 0.48 * m.searchExtra);
      if (task.searchStarted) score *= 1.12;
      if (task.id === mem.activeTask) score *= 1.14;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  let siteId = null;
  let siteDistance = Infinity;
  let siteBearing = 0;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(siteObs.distance) && Number.isFinite(siteObs.bearing) &&
      siteObs.distance >= 0 && siteObs.distance <= 8.5) {
    siteDistance = siteObs.distance;
    siteBearing = siteObs.bearing;
    const globalBearing = (head + siteBearing) * Math.PI / 180;
    const sx = clamp(navX + siteDistance * Math.cos(globalBearing), 0, mem.mapW);
    const sy = clamp(navY + siteDistance * Math.sin(globalBearing), 0, mem.mapH);
    let match = null;
    let matchD = Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2) continue;
      const d = dist(sx, sy, task.x, task.y);
      const limit = task.actual ? 5.5 : 30;
      if (d <= limit && d < matchD) {
        match = task;
        matchD = d;
      }
    }
    if (!match) {
      match = addTask(sx, sy, finite(siteObs.value, 1), "site");
    }
    if (!match.actual) {
      match.x = sx;
      match.y = sy;
      match.origX = sx;
      match.origY = sy;
    } else {
      const alpha = siteDistance < 3 ? 0.42 : 0.24;
      match.x = clamp(match.x * (1 - alpha) + sx * alpha, 0, mem.mapW);
      match.y = clamp(match.y * (1 - alpha) + sy * alpha, 0, mem.mapH);
    }
    match.actual = true;
    if (Number.isFinite(siteObs.value) && siteObs.value > 0) match.val = siteObs.value;
    if (match.status === 3) match.status = 0;
    match.searchStarted = false;
    match.searchPoints = [];
    match.searchIdx = 0;
    siteId = match.id;
  }

  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    let completed = getTask(mem.sampleTaskId);
    if (!completed) completed = getTask(mem.activeTask);
    if (!completed) {
      let nearest = null;
      let nearD = 4;
      for (const task of mem.tasks) {
        if (task && task.actual && task.status !== 2) {
          const d = dist(navX, navY, task.x, task.y);
          if (d < nearD) {
            nearD = d;
            nearest = task;
          }
        }
      }
      completed = nearest;
    }
    if (completed) completed.status = 2;
    mem.sampling = false;
    mem.sampleTaskId = -1;
    mem.activeTask = -1;
  }
  mem.prevCarried = carried;
  mem.lastDelivered = finite(obs.delivered, finite(mem.lastDelivered, 0));

  if (mem.returning && obs.docked) {
    const unfinished = getTask(mem.activeTask);
    if (unfinished && unfinished.status === 1) unfinished.status = 0;
    mem.returning = false;
    mem.leaving = false;
    mem.charging = false;
    mem.activeTask = -1;
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  if (siteId !== null && !mem.returning && !mem.sampling) {
    const current = getTask(mem.activeTask);
    if (!current || current.id !== siteId) {
      if (current && current.status === 1) current.status = 0;
      mem.activeTask = siteId;
      const found = getTask(siteId);
      if (found && found.status !== 2) found.status = 1;
    }
  }

  function driveWheels(v, omega) {
    const leftTarget = clamp(v - omega * 0.3, -2.8, 2.8);
    const rightTarget = clamp(v + omega * 0.3, -2.8, 2.8);
    const errL = leftTarget - wl;
    const errR = rightTarget - wr;

    if (Math.abs(leftTarget) > 0.18) {
      mem.integralL = clamp(finite(mem.integralL, 0) + 0.045 * errL * dt, -0.22, 0.22);
    } else {
      mem.integralL = finite(mem.integralL, 0) * 0.92;
    }
    if (Math.abs(rightTarget) > 0.18) {
      mem.integralR = clamp(finite(mem.integralR, 0) + 0.045 * errR * dt, -0.22, 0.22);
    } else {
      mem.integralR = finite(mem.integralR, 0) * 0.92;
    }

    let left = leftTarget / 3 + 0.20 * errL + mem.integralL;
    let right = rightTarget / 3 + 0.20 * errR + mem.integralR;
    if (Math.abs(leftTarget) > 0.22 && Math.abs(left) < 0.12) left = Math.sign(leftTarget) * 0.12;
    if (Math.abs(rightTarget) > 0.22 && Math.abs(right) < 0.12) right = Math.sign(rightTarget) * 0.12;
    mem.lastNavV = v;
    return {
      left: clamp(left, -1, 1),
      right: clamp(right, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    mem.integralL = finite(mem.integralL, 0) * 0.90;
    mem.integralR = finite(mem.integralR, 0) * 0.90;
    mem.lastNavV = 0;

    const pitch = finite(obs.pitch, 0) * Math.PI / 180;
    let posU = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - navX;
      const dy = anchorY - navY;
      const along = dx * Math.cos(head * Math.PI / 180) +
                    dy * Math.sin(head * Math.PI / 180);
      posU = clamp(0.18 * along, -0.10, 0.10);
    }
    const slopeU = 0.42 * Math.sin(pitch);
    const left = clamp(-0.72 * wl + slopeU + posU, -0.34, 0.34);
    const right = clamp(-0.72 * wr + slopeU + posU, -0.34, 0.34);
    const centerSpeed = Math.abs((wl + wr) * 0.5);
    const stationary = centerSpeed < 0.14 &&
                       Math.max(Math.abs(wl), Math.abs(wr)) < 0.22;
    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < rays.length; i++) {
      const a = -80 + 20 * i;
      if ((sign > 0 && a > 0) || (sign < 0 && a < 0)) {
        const r = finite(rays[i], 0);
        score += r > 0 ? Math.min(12, r) : 0;
      }
    }
    return score;
  }

  function analyzeAlpha(alpha, goalRel) {
    let cost = Math.pow(Math.abs(angleDiff(goalRel, alpha)) / 28, 2);
    let clear = Infinity;
    if (rays) {
      for (let i = 0; i < rays.length; i++) {
        const d = finite(rays[i], NaN);
        if (!Number.isFinite(d) || d <= 0.25 || d >= 14.7) continue;
        if (finite(mem.rayStale[i], 0) > 2.6) continue;
        const beta = -80 + 20 * i;
        const rel = (beta - alpha) * Math.PI / 180;
        const along = d * Math.cos(rel);
        const cross = Math.abs(d * Math.sin(rel));
        if (along <= 0 || along >= 9) continue;
        const width = 0.82 + 0.105 * along;
        if (cross < width) {
          const severity = (width - cross) / width;
          const closeWeight = 4.8 + 3.2 * Math.max(0, 1 - along / 8);
          cost += closeWeight * severity * severity;
        }
        if (cross < 1.05) clear = Math.min(clear, along);
      }
    }
    const worldA = (head + alpha) * Math.PI / 180;
    const px = navX + 5.0 * Math.cos(worldA);
    const py = navY + 5.0 * Math.sin(worldA);
    if (px < 2.2 || px > mem.mapW - 2.2) cost += 18;
    if (py < 2.2 || py > mem.mapH - 2.2) cost += 18;
    if (Number.isFinite(mem.lastAvoidAlpha)) {
      cost += 0.003 * Math.abs(alpha - mem.lastAvoidAlpha);
    }
    return { cost, clear };
  }

  function navCommand(gx, gy, key, options) {
    options = options || {};
    let targetDistance = dist(navX, navY, gx, gy);
    let goalRel = wrap(Math.atan2(gy - navY, gx - navX) * 180 / Math.PI - head);
    if (Number.isFinite(options.rel)) goalRel = wrap(options.rel);
    if (Number.isFinite(options.distance)) targetDistance = Math.max(0, options.distance);

    const goalKey = String(key || "goal");
    if (mem.progressKey !== goalKey) {
      mem.progressKey = goalKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
    } else if (now - finite(mem.progressT, now) >= 5) {
      const improvement = finite(mem.progressD, targetDistance) - targetDistance;
      if (finite(mem.lastNavV, 0) > 0.55 && improvement < 0.55) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        let sign = sideOpenScore(1) >= sideOpenScore(-1) ? 1 : -1;
        if (Math.abs(sideOpenScore(1) - sideOpenScore(-1)) < 0.2) {
          sign = (mem.stuckCount % 2 === 0) ? 1 : -1;
        }
        if (mem.stuckCount % 3 === 0) sign = -sign;
        mem.escapeSign = sign;
        mem.escapeUntil = now + 2.0;
      }
      mem.progressT = now;
      mem.progressD = targetDistance;
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(0, finite(mem.escapeSign, 1) * 1.45);
    }

    if (Math.abs(goalRel) > 80) {
      const omega = clamp(2.15 * goalRel * Math.PI / 180, -2.0, 2.0);
      return driveWheels(0, omega);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;
    for (const a of candidates) {
      const result = analyzeAlpha(a, goalRel);
      if (result.cost < bestCost) {
        bestCost = result.cost;
        bestAlpha = a;
        bestClear = result.clear;
      }
    }
    mem.lastAvoidAlpha = bestAlpha;

    let speed = 1.55 - 0.075 * carried;
    speed = clamp(speed, 1.05, 1.55);
    if (Math.abs(bestAlpha) > 42) speed = Math.min(speed, 1.0);
    if (targetDistance < 10) speed = Math.min(speed, 0.34 + 0.12 * targetDistance);
    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.4) speed = Math.min(speed, 0.28);
      else if (bestClear < 2.4) speed = Math.min(speed, 0.48);
      else if (bestClear < 3.4) speed = Math.min(speed, 0.72);
      else if (bestClear < 5.0) speed = Math.min(speed, 1.02);
      else if (bestClear < 7.0) speed = Math.min(speed, 1.28);
    }
    if (raysBlind) speed = Math.min(speed, 1.05);
    if (Math.abs(bestAlpha) > 70) speed = 0;

    const omega = clamp(2.1 * bestAlpha * Math.PI / 180, -1.75, 1.75);
    return driveWheels(speed, omega);
  }

  function requestReturn() {
    if (!mem.returning) {
      const unfinished = getTask(mem.activeTask);
      if (unfinished && unfinished.status === 1) unfinished.status = 0;
      mem.activeTask = -1;
      mem.sampling = false;
      mem.sampleTaskId = -1;
    }
    mem.returning = true;
    mem.leaving = false;
    mem.charging = false;
  }

  function createScienceTask() {
    if (finite(mem.exploreMade, 0) >= 2) return null;
    const signal = Math.max(0, finite(obs.science, 0));
    if (signal <= 0.003) return null;
    for (const task of mem.tasks) {
      if (task && dist(navX, navY, task.x, task.y) < 27) return null;
    }
    const task = addTask(navX, navY, Math.max(1, signal), "science");
    task.status = 0;
    startSearch(task, navX, navY, 0);
    mem.exploreMade = finite(mem.exploreMade, 0) + 1;
    return task;
  }

  function tryStartSample(task) {
    if (!task || task.status === 2 || task.status === 3 || carried >= mem.capacity) return false;
    let close = false;
    if (siteId === task.id && siteDistance <= 1.38) close = true;
    if (task.actual && dist(navX, navY, task.x, task.y) <= 1.12) close = true;
    if (!close) return false;

    mem.sampling = true;
    mem.sampleTaskId = task.id;
    mem.sampleAnchorX = task.x;
    mem.sampleAnchorY = task.y;
    mem.sampleCarryStart = carried;
    task.status = 1;
    return true;
  }

  function sampleCommand() {
    const sampleTask = getTask(mem.sampleTaskId);
    let close = false;
    if (sampleTask && siteId === sampleTask.id && siteDistance <= 1.48) close = true;
    if (sampleTask && sampleTask.actual &&
        dist(navX, navY, finite(mem.sampleAnchorX, sampleTask.x),
             finite(mem.sampleAnchorY, sampleTask.y)) <= 1.48) close = true;

    if (!close) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }
    return holdAt(finite(mem.sampleAnchorX, sampleTask.x),
                  finite(mem.sampleAnchorY, sampleTask.y), true, close);
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (!task.actual && !task.searchStarted &&
        dist(navX, navY, task.x, task.y) <= 6.0) {
      startSearch(task, task.x, task.y, 0);
    }

    if (tryStartSample(task)) {
      return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, true, true);
    }

    let goal;
    if (task.actual) {
      goal = { x: task.x, y: task.y, key: "site-" + task.id };
    } else if (task.searchStarted) {
      goal = advanceSearch(task);
      if (!goal || task.status === 3) {
        mem.activeTask = -1;
        return null;
      }
      goal = {
        x: goal.x,
        y: goal.y,
        key: "search-" + task.id + "-" + task.searchPass + "-" +
             task.searchStage + "-" + task.searchIdx
      };
    } else {
      goal = { x: task.x, y: task.y, key: "hint-" + task.id };
    }

    const options = {};
    if (task.actual && siteId === task.id) {
      options.rel = siteBearing;
      options.distance = siteDistance;
    }
    return navCommand(goal.x, goal.y, goal.key, options);
  }

  const stableDock = !!obs.docked && !mem.leaving && !mem.returning;

  if (mem.returning) {
    if (obs.docked) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if ((beaconValid && beacon.distance < 1.8) ||
        (!beaconValid && dist(navX, navY, mem.baseX, mem.baseY) < 1.25)) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const opts = beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {};
    return navCommand(mem.baseX, mem.baseY, "base-return", opts);
  }

  if (mem.charging && !obs.docked && !mem.leaving) {
    requestReturn();
    return navCommand(mem.baseX, mem.baseY, "base-redock",
      beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {});
  }

  if (stableDock) {
    if (carried > 0) {
      mem.charging = true;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeTask);
    if (!task || task.status === 2 || task.status === 3) {
      mem.activeTask = -1;
      task = null;
    }
    if (task) {
      const m = taskMetrics(task, navX, navY);
      if (m.need > 1.04 || timeLeft < m.timeNeed) {
        if (task.status === 1) task.status = 0;
        mem.activeTask = -1;
        task = null;
      }
    }
    if (!task) task = selectTask(navX, navY, true);
    if (!task) {
      task = createScienceTask();
      if (task && (taskMetrics(task, navX, navY).need > 1.04 ||
                   timeLeft < taskMetrics(task, navX, navY).timeNeed)) {
        task.status = 3;
        task = null;
      }
    }

    if (!task) {
      mem.activeTask = -1;
      mem.charging = true;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    mem.activeTask = task.id;
    task.status = 1;

    if (tryStartSample(task)) {
      mem.charging = false;
      return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, true, true);
    }

    const m = taskMetrics(task, navX, navY);
    if (m.need > 1.04 || timeLeft < m.timeNeed) {
      task.status = 0;
      mem.activeTask = -1;
      mem.charging = true;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const chargeGoal = clamp(Math.max(0.20, m.need + 0.04), 0.20, 0.96);
    if (battery + 0.001 < chargeGoal) {
      mem.charging = true;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    mem.charging = false;
    mem.leaving = true;
    return controlTask(task) || holdAt(mem.baseX, mem.baseY, false, false);
  }

  const eRate = Math.max(finite(mem.ePerM, 0.001), finite(mem.ePerSec, 0.001));
  const returnReserve = 0.085 + baseDist * eRate * (1.82 + 0.07 * carried) +
                        0.012 * carried;
  const returnTime = baseDist * 1.48 + 12;
  let mustReturn = false;
  if (carried >= mem.capacity) mustReturn = true;
  if (timeLeft < returnTime + (carried > 0 ? 3 : 8)) mustReturn = true;
  if (battery < returnReserve + 0.025) mustReturn = true;

  if (mustReturn && mem.sampling && carried < mem.capacity &&
      battery > Math.max(0.045, returnReserve - 0.10) &&
      timeLeft > returnTime + 7) {
    mustReturn = false;
  }
  if (mustReturn) {
    requestReturn();
    return navCommand(mem.baseX, mem.baseY, "base-return",
      beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {});
  }

  if (mem.sampling) {
    const sc = sampleCommand();
    if (sc) return sc;
  }

  let active = getTask(mem.activeTask);
  if (active && (active.status === 2 || active.status === 3)) {
    mem.activeTask = -1;
    active = null;
  }

  if (!active) {
    active = selectTask(navX, navY, false);
    if (!active) active = createScienceTask();
    if (active) {
      mem.activeTask = active.id;
      active.status = 1;
    }
  }

  if (!active) {
    const hasPending = mem.tasks.some(t => t && (t.status === 0 || t.status === 1));
    if (carried > 0 || hasPending || mem.charging || battery < 0.62) {
      requestReturn();
      return navCommand(mem.baseX, mem.baseY, "base-return",
        beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {});
    }
    return holdAt(navX, navY, false, false);
  }

  const metrics = taskMetrics(active, navX, navY);
  if (battery < metrics.need + 0.02 || timeLeft < metrics.timeNeed) {
    requestReturn();
    return navCommand(mem.baseX, mem.baseY, "base-return",
      beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {});
  }

  if (tryStartSample(active)) {
    return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, true, true);
  }

  const command = controlTask(active);
  if (command) return command;

  if (active.status === 3) {
    mem.activeTask = -1;
    if (carried > 0) {
      requestReturn();
      return navCommand(mem.baseX, mem.baseY, "base-return",
        beaconValid ? { rel: beacon.bearing, distance: beacon.distance } : {});
    }
    return holdAt(navX, navY, false, false);
  }

  return holdAt(navX, navY, false, false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, fallback) => Number.isFinite(v) ? v : fallback;
  const wrap = (a) => {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const now = finite(obs.t, 0);
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const solar = Math.max(0, finite(obs.solar, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 0));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.1, finite(value, 1)),
      kind: kind || "hint",
      actual: kind === "site",
      status: 0,
      searchStarted: false,
      searchCenterX: x,
      searchCenterY: y,
      searchPoints: [],
      searchIdx: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeId = -1;
    mem.sampleTaskId = -1;
    mem.sampling = false;
    mem.returning = false;
    mem.departing = false;
    mem.departTime = -1;
    mem.departX = rawX;
    mem.departY = rawY;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.stuckCount = 0;
    mem.progressKey = "";
    mem.integralL = 0;
    mem.integralR = 0;
    mem.lastNavV = 0;
    mem.lastAvoidAlpha = 0;
    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.compassIgnoreUntil = -1;
    mem.compassStall = 0;
    mem.gpsBad = false;
    mem.gpsOdom = 0;
    mem.ePerM = 0.0008;
    mem.ePerSec = 0.0008;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
    mem.batteryShockUntil = -1;
    mem.lastBattery = battery;
    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.prevCarried = carried;
    mem.prevDelivered = finite(obs.delivered, 0);
    mem.exploreMade = 0;
    mem.bestSignal = science;
    mem.bestSignalX = rawX;
    mem.bestSignalY = rawY;
    mem.lastScienceX = rawX;
    mem.lastScienceY = rawY;
    mem.lastScienceT = now;
    mem.straightActive = false;
    mem.straightSign = 1;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 250; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      const value = finite(h.estimate, 1);
      let duplicate = null;
      for (const old of mem.tasks) {
        if (dist(x, y, old.x, old.y) < 7) {
          duplicate = old;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, value);
      } else {
        addTask(
          clamp(x, 1, mem.mapW - 1),
          clamp(y, 1, mem.mapH - 1),
          value,
          "hint"
        );
      }
    }

    mem.posX = rawX;
    mem.posY = rawY;
    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
  if (!Number.isFinite(mem.activeId)) mem.activeId = -1;
  if (!Number.isFinite(mem.sampleTaskId)) mem.sampleTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.0008;
  if (!Number.isFinite(mem.ePerSec)) mem.ePerSec = 0.0008;

  const dtRaw = now - finite(mem.lastT, now);
  const dt = dtRaw > 0 && dtRaw < 1 ? clamp(dtRaw, 0.04, 0.30) : 0.1;

  // Fuse wheel yaw with compass increments; reject large compass discontinuities.
  const rawHeadingDelta = angleDiff(rawHeading, finite(mem.lastRawHeading, rawHeading));
  const wheelYaw = (wr - wl) / 0.6 * dt * 57.2957795;
  const compassJump =
    (Math.abs(rawHeadingDelta) > 55 && Math.abs(wheelYaw) < 38) ||
    (Math.abs(rawHeadingDelta) > 35 &&
     Math.abs(angleDiff(rawHeadingDelta, wheelYaw)) > 48);

  if (compassJump) {
    mem.headingEst = wrap(mem.headingEst + clamp(wheelYaw, -45, 45));
    mem.compassIgnoreUntil = now + 1.0;
    mem.compassStall = 0;
  } else {
    if (Math.abs(rawHeadingDelta) < 0.015 && Math.abs(wheelYaw) > 0.8) {
      mem.compassStall = finite(mem.compassStall, 0) + dt;
    } else {
      mem.compassStall = Math.max(0, finite(mem.compassStall, 0) - 1.5 * dt);
    }
    let compassWeight = 0.32;
    if (now < finite(mem.compassIgnoreUntil, -1) ||
        finite(mem.compassStall, 0) > 0.55) {
      compassWeight = 0;
    }
    mem.headingEst = wrap(
      mem.headingEst + wheelYaw * (1 - compassWeight) +
      rawHeadingDelta * compassWeight
    );
  }

  // Detect a frozen GPS and blend valid fixes with wheel dead reckoning.
  const wasGpsBad = !!mem.gpsBad;
  const gpsAnchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );
  if (gpsAnchorMove > 0.48) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsOdom = 0;
    mem.gpsBad = false;
  } else {
    if (Math.abs(vAvg) > 0.25) {
      mem.gpsOdom = finite(mem.gpsOdom, 0) + Math.abs(vAvg) * dt;
    }
    if (mem.gpsOdom > 2.5) mem.gpsBad = true;
  }

  let headMap = wrap(mem.headingEst - mem.headingBias);
  const predX = mem.posX + vAvg * Math.cos(headMap * Math.PI / 180) * dt;
  const predY = mem.posY + vAvg * Math.sin(headMap * Math.PI / 180) * dt;

  if (mem.gpsBad) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.2 ? 0.42 : 0.16;
    if (residual > 12) gain = 0.025;
    else if (residual > 5) gain = 0.10;
    if (wasGpsBad) gain = 0.60;
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  // Calibrate compass-to-map bias from long, straight GPS motion.
  const straightOk = !mem.gpsBad &&
    Math.abs(vAvg) > 0.45 && Math.abs(wr - wl) < 0.35;
  if (straightOk) {
    const sign = vAvg >= 0 ? 1 : -1;
    if (!mem.straightActive || sign !== mem.straightSign) {
      mem.straightActive = true;
      mem.straightSign = sign;
      mem.straightX = rawX;
      mem.straightY = rawY;
      mem.straightHead = mem.headingEst;
      mem.straightT = now;
    } else {
      const moved = dist(rawX, rawY, mem.straightX, mem.straightY);
      const turned = Math.abs(angleDiff(mem.headingEst, mem.straightHead));
      if (moved > 4.5 && turned < 18) {
        let course = Math.atan2(rawY - mem.straightY, rawX - mem.straightX) *
                     180 / Math.PI;
        if (sign < 0) course = wrap(course + 180);
        const measuredBias = angleDiff(mem.headingEst, course);
        mem.headingBias = wrap(
          mem.headingBias + 0.20 * angleDiff(measuredBias, mem.headingBias)
        );
        mem.straightX = rawX;
        mem.straightY = rawY;
        mem.straightHead = mem.headingEst;
        mem.straightT = now;
      } else if (turned > 25 || now - finite(mem.straightT, now) > 16) {
        mem.straightX = rawX;
        mem.straightY = rawY;
        mem.straightHead = mem.headingEst;
        mem.straightT = now;
      }
    }
  } else {
    mem.straightActive = false;
  }

  headMap = wrap(mem.headingEst - mem.headingBias);
  mem.posX = clamp(mem.posX, -2, mem.mapW + 2);
  mem.posY = clamp(mem.posY, -2, mem.mapH + 2);
  const posX = mem.posX;
  const posY = mem.posY;

  // Estimate gross energy use, accounting for solar input while driving.
  const previousBattery = finite(mem.lastBattery, battery);
  if (previousBattery - battery > 0.07 && dt < 0.7) {
    mem.batteryShockUntil = now + 12;
  }
  mem.lastBattery = battery;
  if (!Number.isFinite(mem.energyT)) {
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }
  if (!obs.docked) {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    mem.energySolar = finite(mem.energySolar, 0) + solar * dt;
  }
  if (now - finite(mem.energyT, now) >= 5) {
    const duration = Math.max(0.1, now - finite(mem.energyT, now));
    const grossUse = finite(mem.energyBat, battery) - battery +
                     finite(mem.energySolar, 0);
    if (!obs.docked && now > finite(mem.batteryShockUntil, -1) &&
        mem.energyDist > 1.5 && grossUse > 0.0005 && grossUse < 0.8) {
      const measured = clamp(grossUse / mem.energyDist, 0.00025, 0.02);
      mem.ePerM = clamp(0.90 * mem.ePerM + 0.10 * measured, 0.00025, 0.02);
    } else if (!obs.docked && now > finite(mem.batteryShockUntil, -1) &&
               mem.energyDist < 1.0 && grossUse > 0.0005 &&
               grossUse < 0.25 && duration > 4) {
      const measuredSec = clamp(grossUse / duration, 0.00005, 0.02);
      mem.ePerSec = clamp(0.92 * mem.ePerSec + 0.08 * measuredSec,
                          0.00005, 0.02);
    }
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let staleRayCount = 0;
  let validRayCount = 0;
  if (rays) {
    for (let i = 0; i < rays.length && i < 9; i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.01 && Math.abs(vAvg) > 0.35 && r < 14.7) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 2.2 && r < 14.7) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  function activateTask(task) {
    if (!task) return;
    const old = getTask(mem.activeId);
    if (old && old.id !== task.id && old.status === 1 && !mem.sampling) {
      old.status = 0;
    }
    mem.activeId = task.id;
    if (task.status !== 2 && task.status !== 3) task.status = 1;
  }

  const searchOffsets = [
    [0, 0],
    [-15, -15], [-5, -15], [5, -15], [15, -15],
    [15, -5], [5, -5], [-5, -5], [-15, -5],
    [-15, 5], [-5, 5], [5, 5], [15, 5],
    [15, 15], [5, 15], [-5, 15], [-15, 15]
  ];

  function buildSearch(task, cx, cy) {
    task.searchCenterX = cx;
    task.searchCenterY = cy;
    task.searchPoints = [];
    task.searchIdx = 0;
    task.searchStarted = true;
    for (const o of searchOffsets) {
      const p = {
        x: clamp(cx + o[0], 2, mem.mapW - 2),
        y: clamp(cy + o[1], 2, mem.mapH - 2)
      };
      let duplicate = false;
      for (const old of task.searchPoints) {
        if (dist(p.x, p.y, old.x, old.y) < 1.5) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.searchPoints.push(p);
    }
  }

  if (science > finite(mem.bestSignal, 0)) {
    mem.bestSignal = science;
    mem.bestSignalX = posX;
    mem.bestSignalY = posY;
    mem.bestSignalT = now;
  }

  // Convert observed site bearings to map coordinates and prioritize known sites.
  let siteId = -1;
  let siteDistance = Infinity;
  let siteBearing = 0;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(siteObs.distance) &&
      Number.isFinite(siteObs.bearing) && siteObs.distance >= 0 &&
      siteObs.distance <= 8.5) {
    siteDistance = siteObs.distance;
    siteBearing = siteObs.bearing;
    const a = (headMap + siteBearing) * Math.PI / 180;
    const sx = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    const sy = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);

    let match = null;
    let matchDist = Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2) continue;
      const d = dist(sx, sy, task.x, task.y);
      const limit = task.actual ? 5.5 : 26;
      if (d <= limit && d < matchDist) {
        match = task;
        matchDist = d;
      }
    }
    if (!match) {
      match = addTask(sx, sy, finite(siteObs.value, 1), "site");
    }

    const wasActual = !!match.actual;
    if (!wasActual) {
      match.x = sx;
      match.y = sy;
      match.searchStarted = false;
      match.searchPoints = [];
      match.searchIdx = 0;
    } else {
      const alpha = siteDistance < 3 ? 0.28 : 0.13;
      match.x = clamp(match.x * (1 - alpha) + sx * alpha, 0, mem.mapW);
      match.y = clamp(match.y * (1 - alpha) + sy * alpha, 0, mem.mapH);
    }
    match.actual = true;
    match.kind = "site";
    if (Number.isFinite(siteObs.value) && siteObs.value > 0) {
      match.val = siteObs.value;
    }
    if (match.status === 3) match.status = 0;
    match.retryAfter = 0;
    siteId = match.id;

    if (!mem.returning && !mem.sampling) activateTask(match);
  }

  // Mark sampled sites when the carried count increases.
  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    let completed = getTask(mem.sampleTaskId);
    if (!completed) completed = getTask(mem.activeId);
    if (!completed) {
      let nearest = null;
      let nearestD = 5;
      for (const task of mem.tasks) {
        if (!task || !task.actual || task.status === 2) continue;
        const d = dist(posX, posY, task.x, task.y);
        if (d < nearestD) {
          nearest = task;
          nearestD = d;
        }
      }
      completed = nearest;
    }
    if (completed) completed.status = 2;
    mem.sampling = false;
    mem.sampleTaskId = -1;
    mem.activeId = -1;
    mem.sampleStart = -1;
    if (siteId >= 0) {
      const nextSite = getTask(siteId);
      if (nextSite && nextSite.status !== 2 && !mem.returning) {
        activateTask(nextSite);
      }
    }
  }
  mem.prevCarried = carried;
  mem.prevDelivered = finite(obs.delivered, finite(mem.prevDelivered, 0));

  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const beacon = obs.beacon;
  const beaconValid = beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 && beacon.distance <= 20.5;
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < rays.length && i < 9; i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) <= 2.2) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * 0.3, -2.5, 2.5);
    const targetR = clamp(v + omega * 0.3, -2.5, 2.5);
    const errL = targetL - wl;
    const errR = targetR - wr;

    if (Math.abs(targetL) > 0.16) {
      mem.integralL = clamp(
        finite(mem.integralL, 0) + 0.10 * errL * dt, -0.18, 0.18
      );
    } else {
      mem.integralL = finite(mem.integralL, 0) * 0.76;
    }
    if (Math.abs(targetR) > 0.16) {
      mem.integralR = clamp(
        finite(mem.integralR, 0) + 0.10 * errR * dt, -0.18, 0.18
      );
    } else {
      mem.integralR = finite(mem.integralR, 0) * 0.76;
    }

    let left = targetL / 3 + 0.30 * errL + mem.integralL;
    let right = targetR / 3 + 0.30 * errR + mem.integralR;
    if (Math.abs(targetL) > 0.25 && Math.abs(left) < 0.11) {
      left = Math.sign(targetL) * 0.11;
    }
    if (Math.abs(targetR) > 0.25 && Math.abs(right) < 0.11) {
      right = Math.sign(targetR) * 0.11;
    }

    mem.lastNavV = v;
    return {
      left: clamp(left, -1, 1),
      right: clamp(right, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    mem.integralL = finite(mem.integralL, 0) * 0.88;
    mem.integralR = finite(mem.integralR, 0) * 0.88;
    mem.lastNavV = 0;

    const pitch = finite(obs.pitch, 0) * Math.PI / 180;
    let posU = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      const along = dx * Math.cos(headMap * Math.PI / 180) +
                    dy * Math.sin(headMap * Math.PI / 180);
      posU = clamp(0.18 * along, -0.14, 0.14);
    }
    const slopeU = clamp(0.40 * Math.sin(pitch), -0.30, 0.30);
    const left = clamp(-0.76 * wl + slopeU + posU, -0.42, 0.42);
    const right = clamp(-0.76 * wr + slopeU + posU, -0.42, 0.42);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function analyzeAlpha(alpha, goalRel) {
    let cost = Math.pow(angleDiff(goalRel, alpha) / 34, 2);
    let clear = Infinity;

    if (rays) {
      for (let i = 0; i < rays.length && i < 9; i++) {
        const r = finite(rays[i], NaN);
        if (!Number.isFinite(r) || r <= 0.2 || r >= 14.7 ||
            finite(mem.rayStale[i], 0) > 2.2) {
          continue;
        }
        const beta = -80 + 20 * i;
        const rel = (beta - alpha) * Math.PI / 180;
        const along = r * Math.cos(rel);
        const cross = Math.abs(r * Math.sin(rel));
        if (along <= 0 || along >= 7.5) continue;

        const width = 0.72 + 0.085 * along;
        if (cross < width + 0.12) clear = Math.min(clear, along);
        if (cross < width) {
          const severity = (width - cross) / width;
          cost += (7 + 9 * Math.max(0, 1 - along / 7.5)) *
                  severity * severity;
          if (along < 1.7) cost += 5 * severity;
        }
      }
    }

    const worldA = (headMap + alpha) * Math.PI / 180;
    const px = posX + 4.0 * Math.cos(worldA);
    const py = posY + 4.0 * Math.sin(worldA);
    if (px < 2.0 || px > mem.mapW - 2.0) cost += 20;
    if (py < 2.0 || py > mem.mapH - 2.0) cost += 20;

    if (Number.isFinite(mem.lastAvoidAlpha)) {
      cost += 0.002 * Math.abs(alpha - mem.lastAvoidAlpha);
    }
    return { cost: cost, clear: clear };
  }

  function navCommand(gx, gy, key, options) {
    options = options || {};
    let targetDistance = dist(posX, posY, gx, gy);
    let goalRel = wrap(
      Math.atan2(gy - posY, gx - posX) * 180 / Math.PI - headMap
    );
    if (Number.isFinite(options.rel)) goalRel = wrap(options.rel);
    if (Number.isFinite(options.distance)) {
      targetDistance = Math.max(0, options.distance);
    }

    const goalKey = String(key || "goal");
    if (mem.progressKey !== goalKey) {
      mem.progressKey = goalKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.stuckCount = 0;
    } else if (now - finite(mem.progressT, now) >= 6) {
      const improvement = finite(mem.progressD, targetDistance) -
                          targetDistance;
      if (targetDistance > 4 && improvement < 0.7 &&
          Math.abs(finite(mem.lastNavV, 0)) > 0.35) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 1.0;
        if (mem.stuckCount >= 3) {
          const active = getTask(mem.activeId);
          if (active && active.searchStarted &&
              goalKey.indexOf("search-" + active.id + "-") === 0) {
            active.searchIdx = Math.min(
              active.searchPoints.length,
              active.searchIdx + 1
            );
            mem.stuckCount = 0;
            mem.progressKey = "";
          }
        }
      } else if (improvement > 0.8) {
        mem.stuckCount = 0;
      }
      mem.progressT = now;
      mem.progressD = targetDistance;
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.24, finite(mem.escapeSign, 1) * 1.05);
    }

    if (Math.abs(goalRel) > 105 && targetDistance > 2) {
      const omega = clamp(
        2.0 * goalRel * Math.PI / 180, -1.65, 1.65
      );
      return driveWheels(0, omega);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;
    for (const a of candidates) {
      const result = analyzeAlpha(a, goalRel);
      if (result.cost < bestCost) {
        bestCost = result.cost;
        bestAlpha = a;
        bestClear = result.clear;
      }
    }
    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(1.12 - 0.06 * carried, 0.78, 1.12);
    if (targetDistance < 8) {
      speed = Math.min(speed, Math.max(0.24, 0.24 * targetDistance));
    }
    if (targetDistance < 0.65) speed = 0;
    if (Math.abs(bestAlpha) > 45) speed = Math.min(speed, 0.68);
    if (Math.abs(bestAlpha) > 68) speed = 0;

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.25) speed = 0;
      else if (bestClear < 1.8) speed = Math.min(speed, 0.28);
      else if (bestClear < 2.6) speed = Math.min(speed, 0.48);
      else if (bestClear < 3.5) speed = Math.min(speed, 0.72);
      else if (bestClear < 4.5) speed = Math.min(speed, 0.92);
    }
    if (raysBlind) speed = Math.min(speed, 0.72);

    const omega = clamp(
      2.0 * bestAlpha * Math.PI / 180, -1.65, 1.65
    );
    return driveWheels(speed, omega);
  }

  // React to a newly reported collision even when the current target changes.
  if (obs.bumped && !mem.prevBumped) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 1.1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
  }
  mem.prevBumped = !!obs.bumped;

  function taskMetrics(task, fromX, fromY) {
    let gx = task.x;
    let gy = task.y;
    let searchExtra = 0;

    if (!task.actual) {
      if (task.searchStarted && task.searchPoints &&
          task.searchIdx < task.searchPoints.length) {
        const p = task.searchPoints[task.searchIdx];
        gx = p.x;
        gy = p.y;
        searchExtra = Math.min(
          105,
          Math.max(0, task.searchPoints.length - task.searchIdx) * 6
        );
      } else if (!task.searchStarted) {
        searchExtra = 82;
      }
    }

    const dOut = dist(fromX, fromY, gx, gy);
    const centerX = task.searchStarted ? task.searchCenterX : task.x;
    const centerY = task.searchStarted ? task.searchCenterY : task.y;
    const dBase = dist(centerX, centerY, mem.baseX, mem.baseY);
    const load = 1 + 0.10 * carried;
    const need = 0.10 +
      finite(mem.ePerM, 0.0008) *
        (dOut + dBase + searchExtra) * 1.75 * load +
      finite(mem.ePerSec, 0.0008) * 8;
    const timeNeed = (dOut + dBase + searchExtra) / 0.85 + 24;
    return {
      dOut: dOut,
      dBase: dBase,
      searchExtra: searchExtra,
      need: need,
      timeNeed: timeNeed
    };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now && task.id !== mem.activeId) {
        continue;
      }
      const m = taskMetrics(task, fromX, fromY);
      const energyLimit = atDock ? 1.08 : battery - 0.025;
      if (m.need > energyLimit) continue;
      if (m.timeNeed + (carried > 0 ? 6 : 10) > timeLeft) continue;

      let value = Math.max(0.15, finite(task.val, 1));
      if (!task.actual) value *= task.kind === "signal" ? 0.68 : 0.78;
      let score = value /
        (38 + m.dOut + 0.78 * m.dBase + 0.48 * m.searchExtra);
      if (task.actual) score *= 1.20;
      if (task.status === 1) score *= 1.07;
      if (task.id === mem.activeId) score *= 1.15;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function spawnScienceTask() {
    if (finite(mem.exploreMade, 0) >= 6) return null;

    let cx = posX;
    let cy = posY;
    let sig = science;
    if (sig < 0.02 && finite(mem.bestSignal, 0) > 0.035) {
      cx = finite(mem.bestSignalX, posX);
      cy = finite(mem.bestSignalY, posY);
      sig = finite(mem.bestSignal, 0);
    }
    if (sig < 0.02) return null;

    for (const task of mem.tasks) {
      if (!task) continue;
      if (dist(cx, cy, task.x, task.y) < 27) return null;
    }

    const task = addTask(
      clamp(cx, 2, mem.mapW - 2),
      clamp(cy, 2, mem.mapH - 2),
      clamp(sig * 3, 0.5, 10),
      "signal"
    );
    buildSearch(task, task.x, task.y);
    mem.exploreMade = finite(mem.exploreMade, 0) + 1;
    return task;
  }

  function sampleCommand() {
    const task = getTask(mem.sampleTaskId);
    if (!task) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    if (carried <= finite(mem.sampleCarryStart, carried) &&
        now - finite(mem.sampleStart, now) > 16 &&
        finite(obs.drilling, 0) < 5.8) {
      task.sampleFailures = finite(task.sampleFailures, 0) + 1;
      task.retryAfter = now + 4;
      if (task.sampleFailures >= 2) task.status = 3;
      else task.status = 0;
      mem.sampling = false;
      mem.sampleTaskId = -1;
      mem.activeId = -1;
      return null;
    }

    const anchorD = dist(
      posX, posY,
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY)
    );
    const visibleClose = siteId === task.id && siteDistance <= 1.48;
    const close = visibleClose || anchorD <= 1.40;

    if (!close && anchorD > 1.75 && finite(obs.drilling, 0) < 0.1) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function tryStartSample(task) {
    if (!task || task.status === 2 || task.status === 3 ||
        carried >= mem.capacity) {
      return null;
    }
    if (finite(task.retryAfter, 0) > now) return null;

    let close = siteId === task.id && siteDistance <= 1.35;
    if (!close && task.actual &&
        dist(posX, posY, task.x, task.y) <= 1.05) {
      close = true;
    }
    if (!close) return null;

    mem.sampling = true;
    mem.sampleTaskId = task.id;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    task.status = 1;
    return sampleCommand();
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual) {
      const sc = tryStartSample(task);
      if (sc) return sc;

      const options = {};
      if (siteId === task.id) {
        options.rel = siteBearing;
        options.distance = siteDistance;
      }
      return navCommand(
        task.x, task.y, "site-" + task.id, options
      );
    }

    if (!task.searchStarted &&
        dist(posX, posY, task.x, task.y) <= 4.5) {
      buildSearch(task, task.x, task.y);
    }

    if (task.searchStarted) {
      let guard = 0;
      while (task.searchIdx < task.searchPoints.length && guard++ < 20) {
        const p = task.searchPoints[task.searchIdx];
        if (dist(posX, posY, p.x, p.y) > 2.3) break;
        task.searchIdx++;
      }
      if (task.searchIdx >= task.searchPoints.length) {
        task.status = 3;
        mem.activeId = -1;
        return null;
      }
      const p = task.searchPoints[task.searchIdx];
      const key = "search-" + task.id + "-" + task.searchIdx;
      return navCommand(p.x, p.y, key, {});
    }

    return navCommand(task.x, task.y, "hint-" + task.id, {});
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  function returnCommand() {
    if (beaconValid && beacon.distance <= 2.0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if (!beaconValid && baseGpsDist <= 1.65) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const options = beaconValid
      ? { rel: beacon.bearing, distance: beacon.distance }
      : {};
    return navCommand(mem.baseX, mem.baseY, "base-return", options);
  }

  // A docked rover unloads first, then charges to the amount needed for its trip.
  if (mem.departing) {
    if (!obs.docked || baseDist > 4.0) {
      mem.departing = false;
    } else if (now - finite(mem.departTime, now) > 25 &&
               dist(posX, posY, mem.departX, mem.departY) < 2.0) {
      mem.departing = false;
    }
  }

  if (mem.returning && obs.docked) {
    mem.returning = false;
    mem.departing = false;
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  if (mem.returning) return returnCommand();

  if (obs.docked && !mem.departing) {
    if (carried > 0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeId);
    if (task && (task.status === 2 || task.status === 3)) task = null;
    if (task) {
      const m = taskMetrics(task, posX, posY);
      if (m.need > 1.08 || m.timeNeed + 5 > timeLeft) {
        if (task.status === 1) task.status = 0;
        mem.activeId = -1;
        task = null;
      }
    }
    if (!task) task = selectTask(posX, posY, true);
    if (!task) {
      spawnScienceTask();
      task = selectTask(posX, posY, true);
    }
    if (!task) {
      mem.activeId = -1;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    const m = taskMetrics(task, posX, posY);
    if (m.timeNeed + 5 > timeLeft || m.need > 1.08) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const chargeGoal = Math.min(
      1.075,
      Math.max(m.need + 0.055, timeLeft < 180 ? m.need + 0.02 : 0.78)
    );
    if (battery + 0.002 < chargeGoal) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    activateTask(task);
    mem.departing = true;
    mem.departTime = now;
    mem.departX = posX;
    mem.departY = posY;
    return controlTask(task) || holdAt(mem.baseX, mem.baseY, false, false);
  }

  if (mem.sampling) {
    const ePerM = finite(mem.ePerM, 0.0008);
    const emergencyReserve = 0.08 +
      ePerM * baseDist * (1.9 + 0.11 * carried) +
      finite(mem.ePerSec, 0.0008) * (8 + 4 * carried);
    const returnTime = baseDist / 0.70 + 18;
    if (battery < Math.max(0.035, emergencyReserve * 0.40) ||
        timeLeft < returnTime + 2) {
      requestReturn();
      return returnCommand();
    }
    const sc = sampleCommand();
    if (sc) return sc;
  }

  const ePerM = finite(mem.ePerM, 0.0008);
  const returnReserve = 0.085 +
    ePerM * baseDist * (1.9 + 0.11 * carried) +
    finite(mem.ePerSec, 0.0008) * (8 + 4 * carried);
  const returnTime = baseDist / 0.70 + 18;
  let mustReturn = false;
  if (carried >= mem.capacity) mustReturn = true;
  if (battery <= returnReserve + 0.025) mustReturn = true;
  if (battery < 0.12) mustReturn = true;
  if (timeLeft < returnTime + (carried > 0 ? 9 : 22)) mustReturn = true;

  if (mustReturn) {
    requestReturn();
    return returnCommand();
  }

  let active = getTask(mem.activeId);
  if (active && (active.status === 2 || active.status === 3)) {
    mem.activeId = -1;
    active = null;
  }
  if (!active) {
    active = selectTask(posX, posY, false);
    if (!active) {
      spawnScienceTask();
      active = selectTask(posX, posY, false);
    }
    if (active) activateTask(active);
  }

  if (!active) {
    if (carried > 0 || battery < 0.72) {
      requestReturn();
      return returnCommand();
    }
    return holdAt(posX, posY, false, false);
  }

  const metrics = taskMetrics(active, posX, posY);
  if (!active.actual &&
      (metrics.need > battery + 0.015 ||
       metrics.timeNeed + 8 > timeLeft)) {
    requestReturn();
    return returnCommand();
  }
  if (active.actual && siteId !== active.id &&
      (metrics.need > battery + 0.05 ||
       metrics.timeNeed + 8 > timeLeft)) {
    requestReturn();
    return returnCommand();
  }

  const command = controlTask(active);
  if (command) return command;

  if (active.status === 3) {
    mem.activeId = -1;
    if (carried > 0) {
      requestReturn();
      return returnCommand();
    }
  }
  return holdAt(posX, posY, false, false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, d) => Number.isFinite(v) ? v : d;
  const wrap = (a) => {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;

  const now = finite(obs.t, 0);
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const solar = Math.max(0, finite(obs.solar, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.1, finite(value, 1)),
      kind: kind || "hint",
      actual: kind === "site",
      status: 0,
      searchStarted: false,
      searchPoints: [],
      searchIdx: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeId = -1;
    mem.sampleTaskId = -1;
    mem.sampling = false;
    mem.returning = false;
    mem.departing = false;
    mem.departTime = -1;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.stuckCount = 0;
    mem.progressKey = "";
    mem.integralL = 0;
    mem.integralR = 0;
    mem.lastNavV = 0;
    mem.lastAvoidAlpha = 0;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.compassBadUntil = -1;
    mem.compassFaults = 0;
    mem.compassStall = 0;

    mem.gpsBad = false;
    mem.gpsBadUntil = -1;
    mem.gpsOdom = 0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.posX = rawX;
    mem.posY = rawY;
    mem.calActive = false;

    mem.ePerM = 0.0011;
    mem.ePerSec = 0.0005;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;

    mem.maxBattery = battery;
    mem.capKnown = false;
    mem.chargeRiseT = now;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.prevCarried = carried;
    mem.exploreMade = 0;
    mem.lastSignalSpawn = -1000;
    mem.bestScience = 0;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 250; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;

      const px = clamp(x, 2, mem.mapW - 2);
      const py = clamp(y, 2, mem.mapH - 2);
      const value = finite(h.estimate, 1);
      let duplicate = null;
      for (const old of mem.tasks) {
        if (dist(px, py, old.x, old.y) < 7) {
          duplicate = old;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, value);
      } else {
        addTask(px, py, value, "hint");
      }
    }

    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
  if (!Number.isFinite(mem.activeId)) mem.activeId = -1;
  if (!Number.isFinite(mem.sampleTaskId)) mem.sampleTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.0011;
  if (!Number.isFinite(mem.ePerSec)) mem.ePerSec = 0.0005;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;

  const dtRaw = now - finite(mem.lastT, now);
  const dt = dtRaw > 0 && dtRaw < 1 ? clamp(dtRaw, 0.04, 0.30) : 0.1;

  // Wheel odometry is the short-term heading reference. Reject implausible compass jumps.
  const rawHeadingDelta = angleDiff(rawHeading, finite(mem.lastRawHeading, rawHeading));
  const wheelYaw = (wr - wl) / 0.6 * dt * 180 / Math.PI;
  const yawMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYaw));
  const compassJump =
    (Math.abs(rawHeadingDelta) > 35 && yawMismatch > 28 + 0.35 * Math.abs(wheelYaw)) ||
    (Math.abs(rawHeadingDelta) > 95 && Math.abs(wheelYaw) < 35);

  if (compassJump) {
    mem.compassBadUntil = now + 3.0;
    mem.compassFaults = finite(mem.compassFaults, 0) + 1;
  } else if (now > finite(mem.compassBadUntil, -1)) {
    mem.compassFaults = Math.max(0, finite(mem.compassFaults, 0) - 0.02);
  }

  if (Math.abs(rawHeadingDelta) < 0.015 && Math.abs(wheelYaw) > 0.8) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(0, finite(mem.compassStall, 0) - 1.5 * dt);
  }

  const predictedHeading = wrap(mem.headingEst + wheelYaw);
  if (compassJump ||
      now < finite(mem.compassBadUntil, -1) ||
      finite(mem.compassStall, 0) > 0.8) {
    mem.headingEst = predictedHeading;
  } else {
    const correctedCompass = wrap(rawHeading - finite(mem.headingBias, 0));
    const err = angleDiff(correctedCompass, predictedHeading);
    mem.headingEst = wrap(predictedHeading + 0.12 * clamp(err, -6, 6));
  }

  // GPS is fused with wheel dead reckoning; detect freezes and large position faults.
  const rawMove = dist(rawX, rawY,
                       finite(mem.lastRawX, rawX),
                       finite(mem.lastRawY, rawY));
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(8, odom * 10 + 3);
  const wasGpsBad = !!mem.gpsBad;

  if (teleport) {
    mem.gpsBad = true;
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsOdom = 0;
  } else {
    const anchorMove = dist(rawX, rawY,
                            finite(mem.gpsAnchorX, rawX),
                            finite(mem.gpsAnchorY, rawY));
    if (anchorMove > 0.55) {
      mem.gpsAnchorX = rawX;
      mem.gpsAnchorY = rawY;
      mem.gpsOdom = 0;
      if (now > finite(mem.gpsBadUntil, -1)) mem.gpsBad = false;
    } else {
      mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
      if (mem.gpsOdom > 2.8) mem.gpsBad = true;
    }
    if (now < finite(mem.gpsBadUntil, -1)) mem.gpsBad = true;
  }

  const headForPosition = mem.headingEst;
  const predX = mem.posX + vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = mem.posY + vAvg * Math.sin(headForPosition * RAD) * dt;
  if (mem.gpsBad || teleport) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.2 ? 0.30 : 0.10;
    if (residual > 10) gain = 0.035;
    else if (residual > 5) gain = 0.10;
    if (wasGpsBad) gain = 0.48;
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  // Estimate compass-to-map bias from sufficiently long straight GPS motion.
  const straight = !mem.gpsBad && !teleport &&
    Math.abs(vAvg) > 0.35 && Math.abs(wr - wl) < 0.42;
  if (straight) {
    const sign = vAvg >= 0 ? 1 : -1;
    if (!mem.calActive || sign !== mem.calSign) {
      mem.calActive = true;
      mem.calSign = sign;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(angleDiff(mem.headingEst, mem.calHead));
      if (turned > 28) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 4.0) {
        let course = Math.atan2(rawY - mem.calY, rawX - mem.calX) * 180 / Math.PI;
        if (sign < 0) course = wrap(course + 180);
        mem.headingEst = wrap(mem.headingEst + 0.38 * angleDiff(course, mem.headingEst));

        if (!compassJump && now > finite(mem.compassBadUntil, -1)) {
          const biasMeasure = wrap(rawHeading - course);
          mem.headingBias = wrap(
            mem.headingBias + 0.18 * angleDiff(biasMeasure, mem.headingBias)
          );
        }
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  mem.posX = clamp(mem.posX, -2, mem.mapW + 2);
  mem.posY = clamp(mem.posY, -2, mem.mapH + 2);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = mem.headingEst;

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  // Learn gross energy use, including observed solar input.
  const oldBattery = finite(mem.lastBattery, battery);
  if (!obs.docked && oldBattery - battery > 0.08) {
    mem.batteryShockUntil = now + 20;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.0011), 0.0022);
    mem.maxBattery = battery;
    mem.capKnown = false;
    mem.chargeRiseT = now;
  }
  mem.lastBattery = battery;

  if (!Number.isFinite(mem.energyT)) {
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }
  if (!obs.docked) {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    mem.energySolar = finite(mem.energySolar, 0) + solar * dt;
  }
  if (now - finite(mem.energyT, now) >= 4.0) {
    const duration = Math.max(0.1, now - finite(mem.energyT, now));
    const grossUse = finite(mem.energyBat, battery) - battery +
                     finite(mem.energySolar, 0);
    if (!obs.docked && now > finite(mem.batteryShockUntil, -1) &&
        grossUse > 0.0002 && grossUse < 0.6) {
      if (finite(mem.energyDist, 0) > 1.2) {
        const measured = clamp(grossUse / mem.energyDist, 0.00025, 0.02);
        mem.ePerM = clamp(0.75 * mem.ePerM + 0.25 * measured, 0.00025, 0.02);
      } else if (duration > 3) {
        const measuredSec = clamp(grossUse / duration, 0.00005, 0.02);
        mem.ePerSec = clamp(0.85 * mem.ePerSec + 0.15 * measuredSec,
                            0.00005, 0.02);
      }
    }
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery) + 0.002) {
      mem.maxBattery = battery;
      mem.chargeRiseT = now;
    }
    if (now - finite(mem.chargeRiseT, now) > 16) mem.capKnown = true;
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let staleRayCount = 0;
  let validRayCount = 0;
  if (rays) {
    for (let i = 0; i < rays.length && i < 9; i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.01 && Math.abs(vAvg) > 0.35 && r < 14.7) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 2.3 && r < 14.7) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  function activateTask(task) {
    if (!task) return;
    const old = getTask(mem.activeId);
    if (old && old.id !== task.id && old.status === 1 && !mem.sampling) {
      old.status = 0;
    }
    mem.activeId = task.id;
    if (task.status !== 2 && task.status !== 3) task.status = 1;
  }

  function buildSearch(task, cx, cy) {
    const offsets = [
      [0, 0],
      [0, -16], [-16, -16], [-16, 0], [-16, 16],
      [0, 16], [16, 16], [16, 0], [16, -16]
    ];
    task.searchPoints = [];
    task.searchIdx = 0;
    task.searchStarted = true;
    for (const o of offsets) {
      const p = {
        x: clamp(cx + o[0], 2, mem.mapW - 2),
        y: clamp(cy + o[1], 2, mem.mapH - 2)
      };
      let duplicate = false;
      for (const q of task.searchPoints) {
        if (dist(p.x, p.y, q.x, q.y) < 1.2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.searchPoints.push(p);
    }
  }

  if (science > finite(mem.bestScience, 0)) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
  }

  let siteId = -1;
  let siteDistance = Infinity;
  let siteBearing = 0;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(siteObs.distance) &&
      Number.isFinite(siteObs.bearing) &&
      siteObs.distance >= 0 && siteObs.distance <= 8.5) {
    siteDistance = siteObs.distance;
    siteBearing = siteObs.bearing;
    const a = (headMap + siteBearing) * RAD;
    const sx = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    const sy = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);

    let match = null;
    let matchDist = Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2) continue;
      const d = dist(sx, sy, task.x, task.y);
      const limit = task.actual ? 14 : 30;
      if (d <= limit && d < matchDist) {
        match = task;
        matchDist = d;
      }
    }
    if (!match) {
      const active = getTask(mem.activeId);
      if (active && !active.actual && active.status !== 2 &&
          dist(posX, posY, active.x, active.y) < 36) {
        match = active;
      }
    }
    if (!match) match = addTask(sx, sy, finite(siteObs.value, 1), "site");

    if (!match.actual) {
      match.x = sx;
      match.y = sy;
      match.searchStarted = false;
      match.searchPoints = [];
      match.searchIdx = 0;
    } else {
      const alpha = siteDistance < 3 ? 0.28 : 0.12;
      match.x = clamp(match.x * (1 - alpha) + sx * alpha, 0, mem.mapW);
      match.y = clamp(match.y * (1 - alpha) + sy * alpha, 0, mem.mapH);
    }
    match.actual = true;
    match.kind = "site";
    if (Number.isFinite(siteObs.value) && siteObs.value > 0) {
      match.val = siteObs.value;
    }
    if (match.status === 3) match.status = 0;
    match.retryAfter = 0;
    siteId = match.id;
    if (!mem.returning && !mem.sampling) activateTask(match);
  }

  // A rising cargo count confirms a completed sample.
  const previousCarried = finite(mem.prevCarried, carried);
  if (carried > previousCarried) {
    let completed = getTask(mem.sampleTaskId);
    if (!completed) completed = getTask(mem.activeId);
    if (!completed) {
      let nearest = null;
      let nearestD = 6;
      for (const task of mem.tasks) {
        if (!task || !task.actual || task.status === 2) continue;
        const d = dist(posX, posY, task.x, task.y);
        if (d < nearestD) {
          nearest = task;
          nearestD = d;
        }
      }
      completed = nearest;
    }
    if (completed) completed.status = 2;
    mem.sampling = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    if (completed && mem.activeId === completed.id) mem.activeId = -1;
  }
  mem.prevCarried = carried;

  if (siteId >= 0 && !mem.returning && !mem.sampling) {
    const visible = getTask(siteId);
    if (visible && visible.status !== 2) activateTask(visible);
  }

  const beacon = obs.beacon;
  const beaconValid = beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 && beacon.distance <= 20.5;
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < rays.length && i < 9; i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) <= 2.3) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * 0.3, -2.4, 2.4);
    const targetR = clamp(v + omega * 0.3, -2.4, 2.4);

    function power(target, current, side) {
      const key = side === 0 ? "integralL" : "integralR";
      let integral = finite(mem[key], 0);
      const error = target - current;
      if (Math.abs(target) < 0.07) {
        integral *= 0.72;
        mem[key] = integral;
        return clamp(-0.52 * current, -1, 1);
      }
      if (target * current < -0.1) integral *= 0.4;
      integral = clamp(integral + 0.055 * error * dt, -0.24, 0.24);
      mem[key] = integral;
      let u = target / 2.65 + 0.23 * error + integral;
      if (Math.abs(target) > 0.16 && Math.abs(u) < 0.16) {
        u = Math.sign(target) * 0.16;
      }
      return clamp(u, -1, 1);
    }

    const slope = clamp(0.10 * Math.sin(finite(obs.pitch, 0) * RAD), -0.10, 0.10);
    mem.lastNavV = v;
    return {
      left: clamp(power(targetL, wl, 0) + slope, -1, 1),
      right: clamp(power(targetR, wr, 1) + slope, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    mem.integralL = finite(mem.integralL, 0) * 0.88;
    mem.integralR = finite(mem.integralR, 0) * 0.88;
    mem.lastNavV = 0;

    const pitch = finite(obs.pitch, 0) * RAD;
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const posU = clamp(0.18 * along, -0.12, 0.12);
    const slopeU = clamp(0.38 * Math.sin(pitch), -0.30, 0.30);
    const left = clamp(-0.76 * wl + slopeU + posU, -0.42, 0.42);
    const right = clamp(-0.76 * wr + slopeU + posU, -0.42, 0.42);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navCommand(gx, gy, key, options) {
    options = options || {};
    let targetDistance = dist(posX, posY, gx, gy);
    let goalRel = wrap(
      Math.atan2(gy - posY, gx - posX) * 180 / Math.PI - headMap
    );
    if (Number.isFinite(options.rel)) goalRel = wrap(options.rel);
    if (Number.isFinite(options.distance)) {
      targetDistance = Math.max(0, options.distance);
    }

    const goalKey = String(key || "goal");
    if (mem.progressKey !== goalKey) {
      mem.progressKey = goalKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.stuckCount = 0;
    } else if (now - finite(mem.progressT, now) >= 8) {
      const improvement = finite(mem.progressD, targetDistance) - targetDistance;
      if (targetDistance > 3 &&
          improvement < 0.55 &&
          finite(mem.lastNavV, 0) > 0.35) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.9;

        if (mem.stuckCount >= 2) {
          const task = getTask(mem.activeId);
          if (task && task.searchStarted &&
              goalKey.indexOf("search-" + task.id + "-") === 0) {
            task.searchIdx = Math.min(task.searchPoints.length, task.searchIdx + 1);
            mem.stuckCount = 0;
            mem.progressKey = "";
          } else if (task && !task.actual) {
            task.status = 3;
            mem.activeId = -1;
            mem.stuckCount = 0;
            mem.progressKey = "";
          } else if (task && task.actual) {
            task.status = 0;
            task.retryAfter = now + 90;
            mem.activeId = -1;
            mem.stuckCount = 0;
            mem.progressKey = "";
          }
        }
      } else if (improvement > 0.8) {
        mem.stuckCount = 0;
      }
      mem.progressT = now;
      mem.progressD = targetDistance;
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.24, finite(mem.escapeSign, 1) * 0.95);
    }

    if (targetDistance < 0.8) return driveWheels(0, 0);

    if (Math.abs(goalRel) > 105) {
      return driveWheels(0, Math.sign(goalRel) * 1.05);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 39, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < rays.length && i < 9; i++) {
          const d = finite(rays[i], NaN);
          if (!Number.isFinite(d) || d <= 0.2 || d >= 14.7 ||
              finite(mem.rayStale[i], 0) > 2.3) continue;

          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const along = d * Math.cos(rel);
          const cross = Math.abs(d * Math.sin(rel));
          if (along <= 0 || along >= 7.5) continue;

          const width = 0.78 + 0.08 * along;
          const safeWidth = width + 0.22;
          if (cross < safeWidth) {
            const severity = (safeWidth - cross) / safeWidth;
            cost += (11 + 3 * Math.max(0, 1 - along / 7.5)) *
                    severity * severity;
            if (along < 1.8) cost += 5 * severity;
            clear = Math.min(clear, along);
          }
        }
      }

      const worldA = (headMap + alpha) * RAD;
      const edgeX = posX + 4.0 * Math.cos(worldA);
      const edgeY = posY + 4.0 * Math.sin(worldA);
      if (edgeX < 2 || edgeX > mem.mapW - 2) cost += 20;
      if (edgeY < 2 || edgeY > mem.mapH - 2) cost += 20;
      if (Number.isFinite(mem.lastAvoidAlpha)) {
        cost += 0.002 * Math.abs(alpha - mem.lastAvoidAlpha);
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(0.84 - 0.035 * carried, 0.64, 0.84);
    if (targetDistance < 5) speed = Math.min(speed, 0.18 + 0.17 * targetDistance);
    if (Math.abs(bestAlpha) > 70) speed = 0;
    else if (Math.abs(bestAlpha) > 55) speed = Math.min(speed, 0.38);
    else speed *= Math.max(0.45, Math.cos(bestAlpha * RAD));

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.15) speed = 0;
      else if (bestClear < 1.8) speed = Math.min(speed, 0.24);
      else if (bestClear < 2.6) speed = Math.min(speed, 0.40);
      else if (bestClear < 3.5) speed = Math.min(speed, 0.58);
      else if (bestClear < 4.5) speed = Math.min(speed, 0.72);
    }
    if (raysBlind) speed = Math.min(speed, 0.62);

    const omega = Math.abs(bestAlpha) > 70
      ? Math.sign(bestAlpha) * 1.0
      : clamp(1.45 * bestAlpha * RAD, -1.2, 1.2);
    return driveWheels(speed, omega);
  }

  function routeLength(task, fromX, fromY) {
    if (task.actual) {
      if (task.id === siteId && Number.isFinite(siteDistance)) return siteDistance;
      return dist(fromX, fromY, task.x, task.y);
    }
    if (!task.searchStarted) {
      return dist(fromX, fromY, task.x, task.y) + 128;
    }
    if (!Array.isArray(task.searchPoints) ||
        task.searchIdx >= task.searchPoints.length) return 0;
    let length = dist(fromX, fromY,
                      task.searchPoints[task.searchIdx].x,
                      task.searchPoints[task.searchIdx].y);
    for (let i = task.searchIdx + 1; i < task.searchPoints.length; i++) {
      length += dist(task.searchPoints[i - 1].x, task.searchPoints[i - 1].y,
                     task.searchPoints[i].x, task.searchPoints[i].y);
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    const route = routeLength(task, fromX, fromY);
    const back = dist(task.x, task.y, mem.baseX, mem.baseY) +
                 (task.actual ? 0 : 20);
    const load = 1 + 0.12 * carried;
    const energy = 0.13 +
      finite(mem.ePerM, 0.0011) * (route * 1.35 + back * 1.50) * load +
      finite(mem.ePerSec, 0.0005) * 10 +
      0.006 * carried;
    const timeNeed = (route + back) / 0.68 + 23;
    return { route: route, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now && task.id !== mem.activeId) continue;

      const m = taskMetrics(task, fromX, fromY);
      if (m.timeNeed + (carried > 0 ? 6 : 10) > timeLeft) continue;
      if (atDock) {
        const available = mem.capKnown
          ? Math.max(0.25, finite(mem.maxBattery, battery) - 0.07)
          : 1.02;
        if (m.energy > available) continue;
      } else if (m.energy > battery - 0.04) {
        continue;
      }

      let value = Math.max(0.15, finite(task.val, 1));
      if (task.actual) value *= 1.18;
      else value *= task.kind === "signal" ? 0.56 : 0.68;

      let score = value / (34 + 0.95 * m.route + 0.76 * m.back);
      if (task.id === mem.activeId) score *= 1.16;
      if (task.status === 1) score *= 1.05;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function spawnScienceTask() {
    if (finite(mem.exploreMade, 0) >= 4 ||
        finite(mem.bestScience, 0) < 0.025 ||
        now - finite(mem.lastSignalSpawn, -1000) < 45) return null;

    const cx = clamp(finite(mem.bestScienceX, posX), 2, mem.mapW - 2);
    const cy = clamp(finite(mem.bestScienceY, posY), 2, mem.mapH - 2);
    for (const task of mem.tasks) {
      if (task && dist(cx, cy, task.x, task.y) < 25) return null;
    }

    const task = addTask(
      cx, cy,
      clamp(finite(mem.bestScience, 0) * 4, 0.5, 8),
      "signal"
    );
    buildSearch(task, cx, cy);
    mem.exploreMade = finite(mem.exploreMade, 0) + 1;
    mem.lastSignalSpawn = now;
    return task;
  }

  function sampleCommand() {
    const task = getTask(mem.sampleTaskId);
    if (!task) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    if (carried <= finite(mem.sampleCarryStart, carried) &&
        now - finite(mem.sampleStart, now) > 22 &&
        finite(obs.drilling, 0) < 5.8) {
      task.sampleFailures = finite(task.sampleFailures, 0) + 1;
      task.retryAfter = now + 20;
      task.status = task.sampleFailures >= 2 ? 3 : 0;
      mem.sampling = false;
      mem.sampleTaskId = -1;
      mem.activeId = -1;
      return null;
    }

    const anchorD = dist(posX, posY,
                         finite(mem.sampleAnchorX, posX),
                         finite(mem.sampleAnchorY, posY));
    const visibleClose = siteId === task.id && siteDistance <= 1.60;
    const coordClose = task.actual && dist(posX, posY, task.x, task.y) <= 1.40;
    const close = visibleClose || coordClose || anchorD <= 1.40;

    if (!close && anchorD > 2.0 && finite(obs.drilling, 0) < 0.1) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function tryStartSample(task) {
    if (!task || task.status === 2 || task.status === 3 ||
        carried >= mem.capacity || finite(task.retryAfter, 0) > now) return null;

    const visibleClose = siteId === task.id && siteDistance <= 1.38;
    const coordClose = task.actual && dist(posX, posY, task.x, task.y) <= 1.05;
    if (!visibleClose && !coordClose) return null;

    mem.sampling = true;
    mem.sampleTaskId = task.id;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    task.status = 1;
    return sampleCommand();
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual) {
      const sample = tryStartSample(task);
      if (sample) return sample;
      const options = {};
      if (siteId === task.id) {
        options.rel = siteBearing;
        options.distance = siteDistance;
      }
      return navCommand(task.x, task.y, "site-" + task.id, options);
    }

    if (!task.searchStarted &&
        dist(posX, posY, task.x, task.y) <= 3.5) {
      buildSearch(task, task.x, task.y);
    }

    if (task.searchStarted) {
      let guard = 0;
      while (task.searchIdx < task.searchPoints.length && guard++ < 12) {
        const p = task.searchPoints[task.searchIdx];
        if (dist(posX, posY, p.x, p.y) > 2.0) break;
        task.searchIdx++;
      }
      if (task.searchIdx >= task.searchPoints.length) {
        task.status = 3;
        task.searchStarted = false;
        mem.activeId = -1;
        return null;
      }
      const p = task.searchPoints[task.searchIdx];
      return navCommand(
        p.x, p.y,
        "search-" + task.id + "-" + task.searchIdx,
        {}
      );
    }

    return navCommand(task.x, task.y, "hint-" + task.id, {});
  }

  if (obs.bumped && !mem.prevBumped && !mem.sampling) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 1.1;
  }
  mem.prevBumped = !!obs.bumped;

  function requestReturn() {
    if (!mem.returning) {
      const old = getTask(mem.activeId);
      if (old && old.status === 1) old.status = 0;
      mem.activeId = -1;
    }
    mem.returning = true;
    mem.departing = false;
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  function returnCommand() {
    if (obs.docked) return holdAt(mem.baseX, mem.baseY, false, false);
    if (beaconValid && beacon.distance <= 1.65) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if (!beaconValid && baseGpsDist <= 1.65) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const options = beaconValid
      ? { rel: beacon.bearing, distance: beacon.distance }
      : {};
    return navCommand(mem.baseX, mem.baseY, "base-return", options);
  }

  if (mem.returning && obs.docked) {
    mem.returning = false;
    mem.departing = false;
    mem.activeId = -1;
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  if (mem.departing && (!obs.docked || baseDist > 4.0)) {
    mem.departing = false;
  }

  if (mem.returning) return returnCommand();

  if (mem.sampling) {
    const reserveNow = 0.12 +
      finite(mem.ePerM, 0.0011) * baseDist * (1.85 + 0.14 * carried) +
      finite(mem.ePerSec, 0.0005) * (12 + 4 * carried);
    const returnTimeNow = baseDist / 0.62 + 18;
    const emergency = battery < Math.max(0.045, reserveNow * 0.43) ||
                      timeLeft < returnTimeNow + 4;
    if (emergency) {
      requestReturn();
      return returnCommand();
    }
    const sample = sampleCommand();
    if (sample) return sample;
  }

  // Docking unloads cargo; select and charge for another feasible trip.
  if (obs.docked && !mem.departing) {
    if (carried > 0) return holdAt(mem.baseX, mem.baseY, false, false);

    let task = getTask(mem.activeId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) task = null;

    if (task) {
      const m = taskMetrics(task, posX, posY);
      const available = mem.capKnown
        ? Math.max(0.25, finite(mem.maxBattery, battery) - 0.07)
        : 1.02;
      if (m.energy > available || m.timeNeed + 8 > timeLeft) {
        if (task.status === 1) task.status = 0;
        mem.activeId = -1;
        task = null;
      }
    }

    if (!task) task = selectTask(posX, posY, true);
    if (!task) {
      spawnScienceTask();
      task = selectTask(posX, posY, true);
    }
    if (!task) {
      mem.activeId = -1;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    const m = taskMetrics(task, posX, posY);
    if (m.timeNeed + 8 > timeLeft) {
      task.status = 0;
      mem.activeId = -1;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    const cap = mem.capKnown
      ? Math.max(0.25, finite(mem.maxBattery, battery))
      : 1.08;
    const chargeGoal = Math.min(cap, m.energy + 0.14);
    if (battery + 0.01 < chargeGoal) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    activateTask(task);
    mem.departing = true;
    mem.departTime = now;
    return controlTask(task) || holdAt(mem.baseX, mem.baseY, false, false);
  }

  const returnReserve = 0.12 +
    finite(mem.ePerM, 0.0011) * baseDist * (1.85 + 0.14 * carried) +
    finite(mem.ePerSec, 0.0005) * (12 + 4 * carried) +
    0.006 * carried;
  const returnTime = baseDist / 0.62 + 18;

  let mustReturn = false;
  if (carried >= mem.capacity) mustReturn = true;
  if (battery < returnReserve + 0.04) mustReturn = true;
  if (battery < 0.09) mustReturn = true;
  if (now < finite(mem.batteryShockUntil, -1) && carried > 0) mustReturn = true;
  if (timeLeft < returnTime + (carried > 0 ? 8 : 22)) mustReturn = true;

  if (mustReturn) {
    requestReturn();
    return returnCommand();
  }

  let active = getTask(mem.activeId);
  if (active && (active.status === 2 || active.status === 3 ||
                 finite(active.retryAfter, 0) > now)) {
    mem.activeId = -1;
    active = null;
  }
  if (!active) {
    active = selectTask(posX, posY, false);
    if (!active) {
      spawnScienceTask();
      active = selectTask(posX, posY, false);
    }
    if (active) activateTask(active);
  }

  if (!active) {
    if (carried > 0 || !obs.docked) {
      requestReturn();
      return returnCommand();
    }
    return holdAt(posX, posY, false, false);
  }

  const metrics = taskMetrics(active, posX, posY);
  if (metrics.energy > battery - 0.04 ||
      metrics.timeNeed + (carried > 0 ? 6 : 10) > timeLeft) {
    requestReturn();
    return returnCommand();
  }

  const command = controlTask(active);
  if (command) return command;

  if (active.status === 3) {
    mem.activeId = -1;
    if (carried > 0) {
      requestReturn();
      return returnCommand();
    }
  }

  return holdAt(posX, posY, false, false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, d) => Number.isFinite(v) ? v : d;
  const wrap = (a) => {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;

  const now = finite(obs.t, 0);
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const solar = Math.max(0, finite(obs.solar, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.1, finite(value, 1)),
      kind: kind || "hint",
      actual: kind === "site",
      status: 0,
      searchStarted: false,
      searchPoints: [],
      searchIdx: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0 || !Array.isArray(mem.tasks)) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  function buildSearch(task, cx, cy) {
    const offsets = [
      [-13, -13], [0, -13], [13, -13],
      [13, 0], [0, 0], [-13, 0],
      [-13, 13], [0, 13], [13, 13]
    ];
    task.searchPoints = [];
    task.searchIdx = 0;
    task.searchStarted = true;
    for (const o of offsets) {
      const p = {
        x: clamp(cx + o[0], 2, mem.mapW - 2),
        y: clamp(cy + o[1], 2, mem.mapH - 2)
      };
      let duplicate = false;
      for (const q of task.searchPoints) {
        if (dist(p.x, p.y, q.x, q.y) < 1.0) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.searchPoints.push(p);
    }
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeId = -1;
    mem.siteId = -1;
    mem.sampleTaskId = -1;
    mem.sampling = false;
    mem.returning = false;
    mem.departing = false;
    mem.departTime = -1;
    mem.baseWaitSince = -1;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.compassBadUntil = -1;
    mem.compassStall = 0;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsOdom = 0;
    mem.gpsBad = false;

    mem.ePerM = 0.0013;
    mem.ePerSec = 0.0004;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;
    mem.maxBattery = battery;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.navKey = "";
    mem.lastAvoidAlpha = 0;
    mem.integralL = 0;
    mem.integralR = 0;
    mem.lastNavV = 0;

    mem.prevCarried = carried;
    mem.prevDelivered = finite(obs.delivered, 0);
    mem.bestScience = science;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;
    mem.signalSpawns = 0;
    mem.lastSignalSpawn = -1000;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 250; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;

      const hx = clamp(x, 2, mem.mapW - 2);
      const hy = clamp(y, 2, mem.mapH - 2);
      const val = finite(h.estimate, 1);
      let duplicate = null;
      for (const old of mem.tasks) {
        if (dist(hx, hy, old.x, old.y) < 8) {
          duplicate = old;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, val);
      } else {
        addTask(hx, hy, val, "hint");
      }
    }

    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.calActive = false;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
  if (!Number.isFinite(mem.activeId)) mem.activeId = -1;
  if (!Number.isFinite(mem.sampleTaskId)) mem.sampleTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.0013;
  if (!Number.isFinite(mem.ePerSec)) mem.ePerSec = 0.0004;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;

  const dtRaw = now - finite(mem.lastT, now);
  const dt = dtRaw > 0 && dtRaw < 1 ? clamp(dtRaw, 0.04, 0.30) : 0.1;

  // Use wheel yaw for short-term motion, while rejecting sudden compass faults.
  const rawHeadingDelta = angleDiff(
    rawHeading,
    finite(mem.lastRawHeading, rawHeading)
  );
  const wheelYawDeg = (wr - wl) / 0.6 * dt * 180 / Math.PI;
  const predHeading = wrap(mem.headingEst + wheelYawDeg);
  const compassMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYawDeg));
  const compassJump =
    Math.abs(rawHeadingDelta) > 38 &&
    compassMismatch > 28 + 0.35 * Math.abs(wheelYawDeg);

  if (compassJump) {
    mem.compassBadUntil = now + 2.0;
    mem.compassStall = 0;
  }

  if (Math.abs(rawHeadingDelta) < 0.012 && Math.abs(wheelYawDeg) > 0.8) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(
      0,
      finite(mem.compassStall, 0) - 1.4 * dt
    );
  }

  if (now < finite(mem.compassBadUntil, -1) ||
      finite(mem.compassStall, 0) > 0.8) {
    mem.headingEst = predHeading;
  } else {
    const err = angleDiff(rawHeading, predHeading);
    const weight = Math.abs(wheelYawDeg) > 5 ? 0.38 : 0.58;
    mem.headingEst = wrap(
      predHeading + weight * clamp(err, -14, 14)
    );
  }

  // GPS is filtered against wheel odometry and ignored during a freeze/teleport.
  const rawMove = dist(
    rawX, rawY,
    finite(mem.lastRawX, rawX),
    finite(mem.lastRawY, rawY)
  );
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(12, odom * 12 + 5);
  const gpsAnchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );

  if (gpsAnchorMove > 1.0) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsOdom = 0;
    if (now > finite(mem.gpsBadUntil, -1)) mem.gpsBad = false;
  } else {
    mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
    if (mem.gpsOdom > 2.8) mem.gpsBad = true;
  }
  if (teleport) {
    mem.gpsBad = true;
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsOdom = 0;
  }
  if (now < finite(mem.gpsBadUntil, -1)) mem.gpsBad = true;

  const headForPosition = wrap(mem.headingEst - mem.headingBias);
  const predX = mem.posX + vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = mem.posY + vAvg * Math.sin(headForPosition * RAD) * dt;

  if (mem.gpsBad || teleport) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.25 ? 0.24 : 0.09;
    if (residual > 10) gain = 0.035;
    else if (residual > 5) gain = 0.08;
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  // Learn the compass-to-map offset from long, nearly straight GPS motion.
  const straight = !mem.gpsBad && !teleport &&
    Math.abs(vAvg) > 0.45 && Math.abs(wr - wl) < 0.22;
  if (straight) {
    const sign = vAvg >= 0 ? 1 : -1;
    if (!mem.calActive || sign !== mem.calSign) {
      mem.calActive = true;
      mem.calSign = sign;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(angleDiff(mem.headingEst, mem.calHead));
      if (turned > 22) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 5.5) {
        let course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        if (sign < 0) course = wrap(course + 180);
        const measuredBias = angleDiff(mem.headingEst, course);
        mem.headingBias = wrap(
          mem.headingBias +
          0.16 * angleDiff(measuredBias, mem.headingBias)
        );
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  mem.posX = clamp(mem.posX, -2, mem.mapW + 2);
  mem.posY = clamp(mem.posY, -2, mem.mapH + 2);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = wrap(mem.headingEst - mem.headingBias);

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  // Learn energy use from battery change, solar input, and measured travel.
  const priorBattery = finite(mem.lastBattery, battery);
  if (priorBattery - battery > 0.18 && dt < 0.6) {
    mem.batteryShockUntil = now + 25;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.0013), 0.0025);
    mem.maxBattery = battery;
  }
  mem.lastBattery = battery;

  if (!Number.isFinite(mem.energyT)) {
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }
  if (!obs.docked) {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    mem.energySolar = finite(mem.energySolar, 0) + solar * dt;
  }
  if (now - finite(mem.energyT, now) >= 4.5) {
    const duration = Math.max(0.1, now - mem.energyT);
    const grossUse = finite(mem.energyBat, battery) - battery +
                     finite(mem.energySolar, 0);
    if (!obs.docked && now > finite(mem.batteryShockUntil, -1) &&
        grossUse > 0.0002 && grossUse < 0.55) {
      if (mem.energyDist > 2.0) {
        const measured = clamp(grossUse / mem.energyDist, 0.00035, 0.02);
        mem.ePerM = clamp(
          0.78 * mem.ePerM + 0.22 * measured,
          0.0004, 0.02
        );
      } else if (duration > 3.5) {
        const measuredSec = clamp(grossUse / duration, 0.00005, 0.02);
        mem.ePerSec = clamp(
          0.85 * mem.ePerSec + 0.15 * measuredSec,
          0.00005, 0.02
        );
      }
    }
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySolar = 0;
  }

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery) + 0.002) {
      mem.maxBattery = battery;
    }
  }

  // Identify stale range beams so a stuck sensor is not treated as a real wall.
  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let validRayCount = 0;
  let staleRayCount = 0;
  if (rays) {
    for (let i = 0; i < rays.length && i < 9; i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.01 && Math.abs(vAvg) > 0.35 &&
          r < 14.7) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 2.2 && r < 14.7) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  if (science > finite(mem.bestScience, 0) + 0.002) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
  }

  // Convert a local site bearing into a rough map location and associate it
  // with the nearest plausible hint/task. The bearing itself is used directly
  // for steering, so this coordinate is only for memory and planning.
  let siteValid = !!(obs.site &&
    Number.isFinite(obs.site.distance) &&
    Number.isFinite(obs.site.bearing) &&
    obs.site.distance >= 0 &&
    obs.site.distance <= 8.5);
  let siteDistance = siteValid ? obs.site.distance : Infinity;
  let siteBearing = siteValid ? obs.site.bearing : 0;
  let siteId = -1;
  let siteX = posX;
  let siteY = posY;

  if (siteValid) {
    const siteAngle = (headMap + siteBearing) * RAD;
    siteX = clamp(posX + siteDistance * Math.cos(siteAngle), 0, mem.mapW);
    siteY = clamp(posY + siteDistance * Math.sin(siteAngle), 0, mem.mapH);

    let match = null;
    const active = getTask(mem.activeId);
    if (active && active.status !== 2 &&
        dist(siteX, siteY, active.x, active.y) < 34) {
      match = active;
    }
    if (!match) {
      let nearest = Infinity;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const d = dist(siteX, siteY, task.x, task.y);
        const limit = task.actual ? 12 : 27;
        if (d < limit && d < nearest) {
          nearest = d;
          match = task;
        }
      }
    }
    if (!match) {
      match = addTask(
        siteX, siteY,
        finite(obs.site.value, 1),
        "site"
      );
    }

    if (match.status === 3 && finite(match.sampleFailures, 0) < 2) {
      match.status = 0;
    }
    if (match.retryAfter <= now || match.sampleFailures === 0) {
      if (match.actual) {
        const a = siteDistance < 3 ? 0.24 : 0.10;
        match.x = clamp(match.x * (1 - a) + siteX * a, 0, mem.mapW);
        match.y = clamp(match.y * (1 - a) + siteY * a, 0, mem.mapH);
      } else {
        match.x = siteX;
        match.y = siteY;
      }
      match.actual = true;
      match.kind = "site";
      match.searchStarted = false;
      match.searchPoints = [];
      match.searchIdx = 0;
      if (Number.isFinite(obs.site.value) && obs.site.value > 0) {
        match.val = obs.site.value;
      }
      if (match.status !== 2) match.status = 1;
    }
    siteId = match.id;
  }
  mem.siteId = siteId;

  // A rising cargo count is definitive confirmation that the sample succeeded.
  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    let completed = getTask(mem.sampleTaskId);
    if (!completed) completed = getTask(siteId);
    if (!completed) completed = getTask(mem.activeId);
    if (completed) {
      completed.status = 2;
      completed.sampleFailures = 0;
      for (const task of mem.tasks) {
        if (task && task.kind === "hint" && task.status !== 2 &&
            dist(task.x, task.y, completed.x, completed.y) < 24) {
          task.status = 2;
        }
      }
    }
    mem.sampling = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    if (completed && mem.activeId === completed.id) mem.activeId = -1;
  }
  mem.prevCarried = carried;
  mem.prevDelivered = finite(obs.delivered, finite(mem.prevDelivered, 0));

  const beacon = obs.beacon;
  const beaconValid = !!(beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 &&
    beacon.distance <= 20.5);
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < rays.length && i < 9; i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) <= 2.2) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function motorPower(target, current, side) {
    const key = side === 0 ? "integralL" : "integralR";
    const oldTargetKey = side === 0 ? "oldTargetL" : "oldTargetR";
    let integral = finite(mem[key], 0);
    const previousTarget = finite(mem[oldTargetKey], target);
    if (target * previousTarget < -0.05) integral *= 0.35;
    mem[oldTargetKey] = target;

    if (Math.abs(target) < 0.045) {
      integral *= 0.72;
      mem[key] = integral;
      return clamp(-0.72 * current + integral, -1, 1);
    }

    const error = target - current;
    integral = clamp(integral + 0.07 * error * dt, -0.22, 0.22);
    mem[key] = integral;
    let u = target / 3.0 + 0.31 * error + integral;
    if (Math.abs(target) > 0.16 && Math.abs(u) < 0.14) {
      u = Math.sign(target) * 0.14;
    }
    return clamp(u, -1, 1);
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * 0.3, -1.7, 1.7);
    const targetR = clamp(v + omega * 0.3, -1.7, 1.7);
    const pitch = finite(obs.pitch, 0) * RAD;
    const slopeAssist = clamp(0.10 * Math.sin(pitch), -0.10, 0.10);
    const left = clamp(
      motorPower(targetL, wl, 0) + slopeAssist, -1, 1
    );
    const right = clamp(
      motorPower(targetR, wr, 1) + slopeAssist, -1, 1
    );
    mem.lastNavV = v;
    return { left: left, right: right, drill: false };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    const pitch = finite(obs.pitch, 0) * RAD;
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const positionAssist = clamp(0.09 * along, -0.12, 0.12);
    const slopeHold = clamp(0.42 * Math.sin(pitch), -0.30, 0.30);
    const left = clamp(-0.78 * wl + slopeHold + positionAssist, -0.46, 0.46);
    const right = clamp(-0.78 * wr + slopeHold + positionAssist, -0.46, 0.46);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.12;
    mem.lastNavV = 0;
    mem.integralL = finite(mem.integralL, 0) * 0.85;
    mem.integralR = finite(mem.integralR, 0) * 0.85;
    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navDrive(goalRel, targetDistance, key, baseSpeed) {
    goalRel = wrap(goalRel);
    targetDistance = Math.max(0, targetDistance);
    const goalKey = String(key || "goal");

    if (mem.navKey !== goalKey) {
      mem.navKey = goalKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.stuckCount = 0;
    } else if (now - finite(mem.progressT, now) >= 8) {
      const improvement = finite(mem.progressD, targetDistance) -
                         targetDistance;
      if (targetDistance > 4 &&
          improvement < 0.55 &&
          finite(mem.lastNavV, 0) > 0.30) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.85;

        if (mem.stuckCount >= 2) {
          const task = getTask(mem.activeId);
          if (task && task.searchStarted &&
              goalKey.indexOf("search-" + task.id + "-") === 0) {
            task.searchIdx = Math.min(
              task.searchPoints.length,
              task.searchIdx + 1
            );
            mem.stuckCount = 0;
            mem.navKey = "";
          } else if (task && !task.actual &&
                     goalKey.indexOf("base-return") !== 0) {
            task.status = 3;
            mem.activeId = -1;
            mem.stuckCount = 0;
            mem.navKey = "";
          } else if (task && task.actual &&
                     goalKey.indexOf("base-return") !== 0) {
            task.retryAfter = now + 55;
            task.status = 0;
            mem.activeId = -1;
            mem.stuckCount = 0;
            mem.navKey = "";
          }
        }
      } else if (improvement > 0.8) {
        mem.stuckCount = 0;
      }
      mem.progressT = now;
      mem.progressD = targetDistance;
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.25, finite(mem.escapeSign, 1) * 1.0);
    }

    if (targetDistance < 0.55) {
      return driveWheels(0, 0);
    }

    if (Math.abs(goalRel) > 105) {
      return driveWheels(0, Math.sign(goalRel) * 1.15);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 34, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < rays.length && i < 9; i++) {
          const range = finite(rays[i], NaN);
          if (!Number.isFinite(range) || range <= 0.15 || range >= 14.7 ||
              finite(mem.rayStale[i], 0) > 2.2) {
            continue;
          }
          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const along = range * Math.cos(rel);
          const cross = Math.abs(range * Math.sin(rel));
          if (along <= 0 || along >= 6.5) continue;

          const width = 0.72 + 0.075 * along;
          const safeWidth = width + 0.28;
          if (cross < safeWidth) {
            const severity = (safeWidth - cross) / safeWidth;
            cost += (13 + 5 * Math.max(0, 1 - along / 6.5)) *
                    severity * severity;
            if (along < 1.6) cost += 5 * severity;
            clear = Math.min(clear, along);
          }
        }
      }

      const worldA = (headMap + alpha) * RAD;
      const edgeX = posX + 4.0 * Math.cos(worldA);
      const edgeY = posY + 4.0 * Math.sin(worldA);
      if (edgeX < 3 || edgeX > mem.mapW - 3) cost += 22;
      if (edgeY < 3 || edgeY > mem.mapH - 3) cost += 22;
      cost += 0.002 * Math.abs(alpha - finite(mem.lastAvoidAlpha, alpha));

      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = finite(baseSpeed, 0.86);
    if (targetDistance < 5) {
      speed = Math.min(speed, 0.15 + 0.15 * targetDistance);
    }
    if (targetDistance < 1.4) speed = Math.min(speed, 0.22);
    if (Math.abs(bestAlpha) > 58) speed = Math.min(speed, 0.35);
    else speed *= Math.max(0.45, Math.cos(bestAlpha * RAD));

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.0) speed = Math.min(speed, 0.10);
      else if (bestClear < 1.5) speed = Math.min(speed, 0.20);
      else if (bestClear < 2.2) speed = Math.min(speed, 0.36);
      else if (bestClear < 3.2) speed = Math.min(speed, 0.56);
      else if (bestClear < 4.2) speed = Math.min(speed, 0.72);
    }
    if (raysBlind) speed = Math.min(speed, 0.66);

    const error = bestAlpha * RAD;
    let v = speed * Math.max(0, Math.cos(error));
    if (Math.abs(bestAlpha) > 58) v = 0;
    const omega = clamp(2.0 * error, -1.25, 1.25);
    return driveWheels(v, omega);
  }

  function navToPoint(gx, gy, key, speed) {
    const dx = gx - posX;
    const dy = gy - posY;
    const distance = Math.hypot(dx, dy);
    const bearing = Math.atan2(dy, dx) / RAD;
    const rel = wrap(bearing - headMap);
    return navDrive(rel, distance, key, speed);
  }

  function routeRemaining(task, fromX, fromY) {
    if (task.actual) {
      if (task.id === siteId && siteValid) return siteDistance;
      return dist(fromX, fromY, task.x, task.y);
    }
    if (!task.searchStarted) {
      return dist(fromX, fromY, task.x, task.y) + 104;
    }
    if (!Array.isArray(task.searchPoints) ||
        task.searchIdx >= task.searchPoints.length) {
      return 0;
    }
    let length = dist(
      fromX, fromY,
      task.searchPoints[task.searchIdx].x,
      task.searchPoints[task.searchIdx].y
    );
    for (let i = task.searchIdx + 1; i < task.searchPoints.length; i++) {
      length += dist(
        task.searchPoints[i - 1].x,
        task.searchPoints[i - 1].y,
        task.searchPoints[i].x,
        task.searchPoints[i].y
      );
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    const out = routeRemaining(task, fromX, fromY);
    const back = dist(task.x, task.y, mem.baseX, mem.baseY);
    const load = 1 + 0.16 * carried;
    const energy = 0.12 +
      finite(mem.ePerM, 0.0013) * 1.55 * (out + back) * load +
      finite(mem.ePerSec, 0.0004) * 12;
    const timeNeed =
      (1.35 * out + 1.50 * back) / 0.78 + 25;
    return { out: out, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    const available = atDock
      ? Math.max(0, finite(mem.maxBattery, battery) - 0.025)
      : battery - 0.075;

    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now) continue;

      const m = taskMetrics(task, fromX, fromY);
      if (m.energy > available) continue;
      if (m.timeNeed + 28 > timeLeft) continue;

      let value = Math.max(0.15, finite(task.val, 1));
      if (!task.actual) {
        value *= task.kind === "signal" ? 0.62 : 0.82;
      } else {
        value *= 1.16;
      }
      let score = value / (36 + m.out + 0.76 * m.back);
      if (task.id === mem.activeId) score *= 1.14;
      if (task.status === 1) score *= 1.04;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function spawnScienceTask() {
    if (finite(mem.signalSpawns, 0) >= 4 ||
        now - finite(mem.lastSignalSpawn, -1000) < 70) {
      return null;
    }

    let sig = science;
    let cx = posX;
    let cy = posY;
    if (finite(mem.bestScience, 0) > sig) {
      sig = mem.bestScience;
      cx = finite(mem.bestScienceX, posX);
      cy = finite(mem.bestScienceY, posY);
    }
    if (sig < 0.025) return null;

    for (const task of mem.tasks) {
      if (task && task.status !== 2 &&
          dist(cx, cy, task.x, task.y) < 24) {
        return null;
      }
    }

    const task = addTask(
      clamp(cx, 2, mem.mapW - 2),
      clamp(cy, 2, mem.mapH - 2),
      clamp(sig * 7, 0.7, 9),
      "signal"
    );
    mem.signalSpawns = finite(mem.signalSpawns, 0) + 1;
    mem.lastSignalSpawn = now;
    return task;
  }

  function activateTask(task) {
    if (!task) return;
    const old = getTask(mem.activeId);
    if (old && old.id !== task.id && old.status === 1 && !mem.sampling) {
      old.status = 0;
    }
    mem.activeId = task.id;
    if (task.status !== 2 && task.status !== 3) task.status = 1;
  }

  function startSample(task) {
    if (!task || task.status === 2 || carried >= mem.capacity ||
        finite(task.retryAfter, 0) > now) {
      return false;
    }
    mem.sampling = true;
    mem.sampleTaskId = task.id;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    mem.sampleArmed = true;
    task.status = 1;
    return true;
  }

  function sampleCommand() {
    const task = getTask(mem.sampleTaskId);
    if (!task) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    if (carried <= finite(mem.sampleCarryStart, carried) &&
        now - finite(mem.sampleStart, now) > 25 &&
        finite(obs.drilling, 0) < 5.8) {
      task.sampleFailures = finite(task.sampleFailures, 0) + 1;
      task.retryAfter = now + (task.sampleFailures >= 2 ? 60 : 22);
      task.status = task.sampleFailures >= 3 ? 3 : 0;
      mem.sampling = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      if (mem.activeId === task.id) mem.activeId = -1;
      return null;
    }

    const anchorD = dist(
      posX, posY,
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY)
    );
    if (anchorD > 2.0 && finite(obs.drilling, 0) < 0.1) {
      mem.sampling = false;
      mem.sampleTaskId = -1;
      return null;
    }

    let close = !!mem.sampleArmed && anchorD < 1.25;
    if (siteValid && siteId === task.id && siteDistance <= 1.55) close = true;
    if (task.actual &&
        dist(posX, posY, task.x, task.y) <= 1.35) close = true;
    if (anchorD > 1.55) close = false;

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual) {
      const d = dist(posX, posY, task.x, task.y);
      if (d <= 1.20 && startSample(task)) return sampleCommand();
      return navToPoint(task.x, task.y, "actual-" + task.id, 0.78);
    }

    if (!task.searchStarted && dist(posX, posY, task.x, task.y) <= 6.0) {
      buildSearch(task, task.x, task.y);
    }

    if (task.searchStarted) {
      let guard = 0;
      while (task.searchIdx < task.searchPoints.length && guard++ < 12) {
        const p = task.searchPoints[task.searchIdx];
        if (dist(posX, posY, p.x, p.y) > 2.2) break;
        task.searchIdx++;
      }
      if (task.searchIdx >= task.searchPoints.length) {
        task.status = 3;
        mem.activeId = -1;
        return null;
      }
      const p = task.searchPoints[task.searchIdx];
      return navToPoint(
        p.x, p.y,
        "search-" + task.id + "-" + task.searchIdx,
        0.84
      );
    }

    return navToPoint(task.x, task.y, "hint-" + task.id, 0.86);
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    if (mem.sampling) {
      const task = getTask(mem.sampleTaskId);
      if (task && task.status !== 2) task.status = 0;
    }
    mem.sampling = false;
    mem.sampleTaskId = -1;
  }

  function returnCommand() {
    if (obs.docked) {
      mem.baseWaitSince = -1;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (beaconValid && beacon.distance <= 2.2) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (now - mem.baseWaitSince < 3.0 || beacon.distance < 0.7) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
    } else if (!beaconValid && baseGpsDist <= 1.8) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (now - mem.baseWaitSince < 3.0 || baseGpsDist < 0.7) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
    } else {
      mem.baseWaitSince = -1;
    }

    if (beaconValid) {
      return navDrive(
        beacon.bearing,
        beacon.distance,
        "base-return",
        0.72
      );
    }
    return navToPoint(mem.baseX, mem.baseY, "base-return", 0.72);
  }

  if (obs.bumped && !mem.prevBumped && !mem.sampling && !mem.returning) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 0.9;
  }
  mem.prevBumped = !!obs.bumped;

  if (mem.departing &&
      (!obs.docked || baseDist > 3.6 ||
       (now - finite(mem.departTime, now) > 35 && baseDist < 3.0))) {
    mem.departing = false;
  }

  if (mem.returning && obs.docked) {
    mem.returning = false;
    mem.departing = false;
    mem.sampling = false;
    mem.sampleTaskId = -1;
    mem.baseWaitSince = -1;
  }

  if (mem.returning) return returnCommand();

  // A docked rover unloads automatically and fast-charges while held still.
  if (obs.docked && !mem.departing) {
    if (carried > 0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      task = null;
    }
    if (task) {
      const m = taskMetrics(task, posX, posY);
      if (m.energy > finite(mem.maxBattery, battery) - 0.02 ||
          m.timeNeed + 28 > timeLeft) {
        if (task.status === 1) task.status = 0;
        mem.activeId = -1;
        task = null;
      }
    }
    if (!task) task = selectTask(posX, posY, true);
    if (!task) {
      spawnScienceTask();
      task = selectTask(posX, posY, true);
    }
    if (!task) {
      mem.activeId = -1;
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    const m = taskMetrics(task, posX, posY);
    if (m.timeNeed + 28 > timeLeft ||
        m.energy > finite(mem.maxBattery, battery) - 0.02) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    const chargeGoal = Math.min(
      finite(mem.maxBattery, battery),
      Math.max(0.70, m.energy + 0.07)
    );
    if (battery + 0.012 < chargeGoal) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    activateTask(task);
    mem.departing = true;
    mem.departTime = now;
  }

  const returnReserve = 0.12 +
    finite(mem.ePerM, 0.0013) * 2.15 * baseDist *
      (1 + 0.17 * carried) +
    finite(mem.ePerSec, 0.0004) * 12 +
    0.006 * carried;
  const returnTime = 30 + 1.75 * baseDist;

  if (!obs.docked) {
    let mustReturn = false;
    if (carried >= mem.capacity) mustReturn = true;
    if (battery < returnReserve + 0.075) mustReturn = true;
    if (battery < 0.065) mustReturn = true;
    if (timeLeft < returnTime + (carried > 0 ? 12 : 35)) mustReturn = true;
    if (now < finite(mem.batteryShockUntil, -1) && carried > 0) {
      mustReturn = true;
    }
    if (mustReturn) {
      requestReturn();
      return returnCommand();
    }
  }

  if (mem.sampling) {
    const cmd = sampleCommand();
    if (cmd) return cmd;
  }

  // Approach every observed unsampled site using its local relative bearing.
  const siteTask = getTask(siteId);
  const siteIgnored = !!(siteTask &&
    finite(siteTask.retryAfter, 0) > now &&
    finite(siteTask.sampleFailures, 0) > 0);
  if (siteValid && !siteIgnored && !mem.returning) {
    if (siteDistance <= 1.25 && siteTask && startSample(siteTask)) {
      return sampleCommand();
    }
    if (siteDistance <= 1.25 && !siteTask) {
      const temp = addTask(
        siteX, siteY,
        finite(obs.site.value, 1),
        "site"
      );
      mem.siteId = temp.id;
      if (startSample(temp)) return sampleCommand();
    }

    let speed = 0.78;
    if (siteDistance < 4) speed = Math.min(speed, 0.12 + 0.18 * siteDistance);
    if (siteDistance < 2.4) speed = Math.min(speed, 0.14 + 0.10 * siteDistance);
    return navDrive(
      siteBearing,
      siteDistance,
      "site-" + siteId,
      speed
    );
  }

  let active = getTask(mem.activeId);
  if (active && (active.status === 2 || active.status === 3 ||
                 finite(active.retryAfter, 0) > now)) {
    mem.activeId = -1;
    active = null;
  }

  if (active) {
    const m = taskMetrics(active, posX, posY);
    if (m.energy > battery - 0.07 || m.timeNeed + 28 > timeLeft) {
      if (active.status === 1) active.status = 0;
      mem.activeId = -1;
      active = null;
    }
  }

  if (!active) {
    active = selectTask(posX, posY, false);
    if (!active) {
      spawnScienceTask();
      active = selectTask(posX, posY, false);
    }
    if (active) activateTask(active);
  }

  if (!active) {
    requestReturn();
    return returnCommand();
  }

  // If the site bearing sensor drops out at the final approach, its learned
  // map location is still accurate enough for a conservative sample attempt.
  if (active.actual &&
      dist(posX, posY, active.x, active.y) <= 1.20 &&
      startSample(active)) {
    return sampleCommand();
  }

  const command = controlTask(active);
  if (command) return command;

  if (active.status === 3) {
    mem.activeId = -1;
    return holdAt(posX, posY, false, false);
  }

  return holdAt(posX, posY, false, false);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, fallback) => Number.isFinite(v) ? v : fallback;
  const wrap = (a) => {
    if (!Number.isFinite(a)) return 0;
    return ((a + 180) % 360 + 360) % 360 - 180;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;
  const WHEEL_BASE = 0.6;

  const now = Math.max(0, finite(obs.t, 0));
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const solar = Math.max(0, finite(obs.solar, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    if (!Array.isArray(mem.tasks)) mem.tasks = [];
    if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.2, finite(value, 1)),
      kind: kind || "hint",
      status: 0,
      scanStarted: false,
      scanPts: [],
      scanIdx: 0
    };
    mem.tasks.push(task);
    return task;
  }

  function makeExplorePoints() {
    const out = [];
    const dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];
    let gx = 0;
    let gy = 0;
    let dir = 0;
    let segmentLen = 1;
    let stepsAtLen = 0;
    let turnsAtLen = 0;
    const step = 12;
    const maxCells = Math.ceil(Math.max(mem.mapW, mem.mapH) / step) + 3;
    const maxCount = Math.min(1800, 4 * maxCells * maxCells);

    for (let i = 0; i < maxCount && out.length < 1500; i++) {
      gx += dirs[dir][0];
      gy += dirs[dir][1];
      const px = clamp(mem.baseX + gx * step, 5, mem.mapW - 5);
      const py = clamp(mem.baseY + gy * step, 5, mem.mapH - 5);
      if (!out.length ||
          dist(px, py, out[out.length - 1].x, out[out.length - 1].y) > 5) {
        out.push({ x: px, y: py });
      }

      stepsAtLen++;
      if (stepsAtLen >= segmentLen) {
        stepsAtLen = 0;
        dir = (dir + 1) % 4;
        turnsAtLen++;
        if (turnsAtLen >= 2) {
          turnsAtLen = 0;
          segmentLen++;
        }
      }
      if (Math.abs(gx) > maxCells && Math.abs(gy) > maxCells) break;
    }
    if (!out.length) out.push({ x: mem.baseX, y: mem.baseY });
    return out;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.currentTaskId = -1;
    mem.sampleTaskId = -1;
    mem.sampleActive = false;
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;
    mem.departTime = -1;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.biasCount = 0;
    mem.compassBadUntil = -1;
    mem.compassStall = 0;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
    mem.gpsBadUntil = -1;

    mem.ePerM = 0.0012;
    mem.ePerSec = 0.00018;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySeconds = 0;
    mem.energySolar = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;
    mem.maxBattery = battery;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.navKey = "";
    mem.navStallFlag = false;
    mem.lastAvoidAlpha = 0;
    mem.integralL = 0;
    mem.integralR = 0;
    mem.oldTargetL = 0;
    mem.oldTargetR = 0;
    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;

    mem.prevCarried = carried;
    mem.prevDelivered = finite(obs.delivered, 0);
    mem.bestScience = 0;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;
    mem.signalSpawns = 0;
    mem.lastSignalSpawn = -1000;

    mem.lastSiteX = rawX;
    mem.lastSiteY = rawY;
    mem.lastSiteUntil = -1;
    mem.sampleRetryUntil = -1;
    mem.exploreIdx = 0;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(40, mem.mapW);
    mem.mapH = Math.max(40, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 300; i++) {
      const h = hints[i] || {};
      const hx = finite(h.x, NaN);
      const hy = finite(h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;

      const x = clamp(hx, 5, mem.mapW - 5);
      const y = clamp(hy, 5, mem.mapH - 5);
      const value = finite(h.estimate, 1);
      let duplicate = null;
      for (const old of mem.tasks) {
        if (dist(x, y, old.x, old.y) < 9) {
          duplicate = old;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, value);
      } else {
        addTask(x, y, value, "hint");
      }
    }

    mem.explorePoints = makeExplorePoints();
    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.calActive = false;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Number.isFinite(mem.currentTaskId)) mem.currentTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.0012;
  if (!Number.isFinite(mem.ePerSec)) mem.ePerSec = 0.00018;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;
  if (!Array.isArray(mem.explorePoints) || !mem.explorePoints.length) {
    mem.explorePoints = makeExplorePoints();
  }

  const dtRaw = now - finite(mem.lastT, now);
  const dt = dtRaw > 0 && dtRaw < 2 ? clamp(dtRaw, 0.04, 0.30) : 0.1;

  // Integrate wheel yaw and reject large, implausible compass changes.
  const rawHeadingDelta = angleDiff(
    rawHeading,
    finite(mem.lastRawHeading, rawHeading)
  );
  const wheelYawDeg = (wr - wl) / WHEEL_BASE * dt / RAD;
  const predictedHeading = wrap(mem.headingEst + wheelYawDeg);
  const yawMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYawDeg));
  const compassJump =
    (Math.abs(rawHeadingDelta) > 42 &&
      yawMismatch > 30 + 0.45 * Math.abs(wheelYawDeg)) ||
    (Math.abs(rawHeadingDelta) > 105 && Math.abs(wheelYawDeg) < 28);

  if (compassJump) {
    mem.compassBadUntil = now + 2.5;
    mem.compassStall = 0;
  }

  if (Math.abs(rawHeadingDelta) < 0.015 && Math.abs(wheelYawDeg) > 1.2) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(
      0,
      finite(mem.compassStall, 0) - 1.3 * dt
    );
  }

  if (now < finite(mem.compassBadUntil, -1) ||
      finite(mem.compassStall, 0) > 0.8) {
    mem.headingEst = predictedHeading;
  } else {
    const correctedCompass = wrap(rawHeading - finite(mem.headingBias, 0));
    const err = angleDiff(correctedCompass, predictedHeading);
    if (Math.abs(err) < 75) {
      mem.headingEst = wrap(
        predictedHeading + 0.10 * clamp(err, -18, 18)
      );
    } else {
      mem.headingEst = predictedHeading;
      mem.compassBadUntil = now + 1.0;
    }
  }

  // Detect GPS freezes and large position jumps; use wheel odometry between GPS fixes.
  const rawMove = dist(
    rawX, rawY,
    finite(mem.lastRawX, rawX),
    finite(mem.lastRawY, rawY)
  );
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(15, odom * 12 + 5);

  const anchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );
  if (anchorMove > 1.8) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
  } else {
    mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
    if (now - finite(mem.gpsAnchorT, now) > 4.0 &&
        mem.gpsOdom > 4.0 &&
        Math.abs(vAvg) > 0.25 &&
        !obs.bumped) {
      mem.gpsFrozen = true;
    }
  }

  if (teleport) {
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  const gpsBad = !!mem.gpsFrozen ||
    teleport ||
    now < finite(mem.gpsBadUntil, -1);

  const headForPosition = wrap(mem.headingEst - finite(mem.headingBias, 0));
  const predX = mem.posX + vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = mem.posY + vAvg * Math.sin(headForPosition * RAD) * dt;
  if (gpsBad) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gpsGain = Math.abs(vAvg) > 0.22 ? 0.065 : 0.018;
    if (residual > 12) gpsGain = 0.01;
    else if (residual > 6) gpsGain = 0.03;
    mem.posX = predX + gpsGain * (rawX - predX);
    mem.posY = predY + gpsGain * (rawY - predY);
  }

  // Estimate compass bias from long, nearly straight GPS motion.
  const straight =
    !gpsBad &&
    !teleport &&
    finite(mem.lastCmdV, 0) > 0.32 &&
    Math.abs(finite(mem.lastCmdOmega, 0)) < 0.28 &&
    vAvg > 0.18 &&
    !compassJump;

  if (straight) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(
        angleDiff(mem.headingEst, finite(mem.calHead, mem.headingEst))
      );
      if (turned > 24) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 8.0) {
        const course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        const measuredBias = wrap(rawHeading - course);
        if (finite(mem.biasCount, 0) < 1) {
          mem.headingBias = measuredBias;
        } else {
          mem.headingBias = wrap(
            mem.headingBias +
            0.25 * angleDiff(measuredBias, mem.headingBias)
          );
        }
        mem.biasCount = finite(mem.biasCount, 0) + 1;
        mem.headingEst = wrap(
          mem.headingEst + 0.42 * angleDiff(course, mem.headingEst)
        );
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  mem.posX = clamp(mem.posX, -3, mem.mapW + 3);
  mem.posY = clamp(mem.posY, -3, mem.mapH + 3);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = wrap(mem.headingEst);

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  // Learn gross energy use, including measured solar input.
  const previousBattery = finite(mem.lastBattery, battery);
  if (previousBattery - battery > 0.10 && dt < 0.5) {
    mem.batteryShockUntil = now + 25;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.0012), 0.0022);
    mem.maxBattery = Math.min(finite(mem.maxBattery, battery), battery);
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySeconds = 0;
    mem.energySolar = 0;
  }
  mem.lastBattery = battery;

  if (!obs.docked) {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    mem.energySeconds = finite(mem.energySeconds, 0) + dt;
    mem.energySolar = finite(mem.energySolar, 0) + solar * dt;
  }

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery)) mem.maxBattery = battery;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySeconds = 0;
    mem.energySolar = 0;
  } else if (now - finite(mem.energyT, now) >= 8.0) {
    const duration = Math.max(0.1, now - finite(mem.energyT, now));
    const grossUse =
      finite(mem.energyBat, battery) - battery +
      finite(mem.energySolar, 0);

    if (now > finite(mem.batteryShockUntil, -1) &&
        grossUse > 0.0005 &&
        grossUse < 0.6) {
      if (finite(mem.energyDist, 0) > 2.5) {
        const measured = clamp(
          grossUse / mem.energyDist,
          0.00025,
          0.02
        );
        if (measured > mem.ePerM) {
          mem.ePerM = clamp(0.72 * mem.ePerM + 0.28 * measured,
                            0.0003, 0.02);
        } else {
          mem.ePerM = clamp(0.94 * mem.ePerM + 0.06 * measured,
                            0.0003, 0.02);
        }
      } else if (duration > 6) {
        const measuredSec = clamp(grossUse / duration, 0.00002, 0.01);
        mem.ePerSec = clamp(
          0.85 * mem.ePerSec + 0.15 * measuredSec,
          0.00002,
          0.01
        );
      }
    }

    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.energySeconds = 0;
    mem.energySolar = 0;
  }

  // Track range beams that appear to have failed or stuck.
  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let validRayCount = 0;
  let staleRayCount = 0;
  if (rays) {
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.01 &&
          Math.abs(vAvg) > 0.4 &&
          r < 14.8) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 2.5 && r < 14.8) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  function buildScan(task) {
    const offsets = [
      [0, 0],
      [-15, -15], [-5, -15], [5, -15], [15, -15],
      [15, -5], [5, -5], [-5, -5], [-15, -5],
      [-15, 5], [-5, 5], [5, 5], [15, 5],
      [15, 15], [5, 15], [-5, 15], [-15, 15]
    ];
    task.scanPts = [];
    task.scanIdx = 0;
    task.scanStarted = true;

    for (const o of offsets) {
      const p = {
        x: clamp(task.x + o[0], 5, mem.mapW - 5),
        y: clamp(task.y + o[1], 5, mem.mapH - 5)
      };
      let duplicate = false;
      for (const q of task.scanPts) {
        if (dist(p.x, p.y, q.x, q.y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.scanPts.push(p);
    }
  }

  function markSampled(siteX, siteY, id) {
    let markedId = -1;
    const byId = getTask(id);
    if (byId && dist(siteX, siteY, byId.x, byId.y) < 38) {
      byId.status = 2;
      markedId = byId.id;
    }

    let nearest = null;
    let nearestD = 24;
    for (const task of mem.tasks) {
      if (!task || task.status === 2) continue;
      const d = dist(siteX, siteY, task.x, task.y);
      if (d < nearestD) {
        nearestD = d;
        nearest = task;
      }
    }
    if (nearest) {
      nearest.status = 2;
      markedId = nearest.id;
    }

    for (const task of mem.tasks) {
      if (task && task.status !== 2 &&
          dist(siteX, siteY, task.x, task.y) < 7) {
        task.status = 2;
        markedId = task.id;
      }
    }

    if (mem.currentTaskId === markedId) mem.currentTaskId = -1;
    mem.lastSiteUntil = -1;
  }

  // A rising cargo count confirms a completed sample.
  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    const sx = finite(mem.sampleSiteX, posX);
    const sy = finite(mem.sampleSiteY, posY);
    const sampleId = finite(mem.sampleTaskId, -1);
    markSampled(sx, sy, sampleId);
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    mem.sampleFailures = 0;
  }
  mem.prevCarried = carried;

  if (science > finite(mem.bestScience, 0) + 0.008) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
  }

  function maybeSpawnScienceTask() {
    if (finite(mem.signalSpawns, 0) >= 6 ||
        finite(mem.bestScience, 0) < 0.025 ||
        now - finite(mem.lastSignalSpawn, -1000) < 35) {
      return;
    }

    const x = clamp(finite(mem.bestScienceX, posX), 5, mem.mapW - 5);
    const y = clamp(finite(mem.bestScienceY, posY), 5, mem.mapH - 5);
    for (const task of mem.tasks) {
      if (task && task.status !== 2 &&
          dist(x, y, task.x, task.y) < 20) return;
    }

    addTask(
      x,
      y,
      clamp(finite(mem.bestScience, 0) * 7, 1, 12),
      "signal"
    );
    mem.signalSpawns = finite(mem.signalSpawns, 0) + 1;
    mem.lastSignalSpawn = now;
  }
  maybeSpawnScienceTask();

  const siteObs = obs.site;
  const siteValid = !!(
    siteObs &&
    Number.isFinite(siteObs.distance) &&
    Number.isFinite(siteObs.bearing) &&
    siteObs.distance >= 0 &&
    siteObs.distance <= 8.5
  );
  const siteDistance = siteValid ? siteObs.distance : Infinity;
  const siteBearing = siteValid ? wrap(siteObs.bearing) : 0;
  let siteX = posX;
  let siteY = posY;
  if (siteValid) {
    const a = (headMap + siteBearing) * RAD;
    siteX = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    siteY = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);
    mem.lastSiteX = siteX;
    mem.lastSiteY = siteY;
    mem.lastSiteUntil = now + 5;
  }

  const beacon = obs.beacon;
  const beaconValid = !!(
    beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 &&
    beacon.distance <= 20.5
  );
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) < 2.5) {
          score += r >= 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1.2) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function motorPower(target, current, side) {
    const key = side === 0 ? "integralL" : "integralR";
    const targetKey = side === 0 ? "oldTargetL" : "oldTargetR";
    let integral = finite(mem[key], 0);
    const previousTarget = finite(mem[targetKey], target);

    if (target * previousTarget < -0.05) integral *= 0.25;
    mem[targetKey] = target;

    if (Math.abs(target) < 0.075) {
      integral *= 0.65;
      mem[key] = integral;
      return clamp(-0.9 * current + integral, -1, 1);
    }

    const error = target - current;
    integral = clamp(integral + 0.18 * error * dt, -0.32, 0.32);
    mem[key] = integral;

    let u = Math.sign(target) * 0.15 +
      target / 2.75 +
      0.55 * error +
      integral;

    if (Math.abs(target) > 0.12 && Math.abs(u) < 0.18) {
      u = Math.sign(target) * 0.18;
    }
    return clamp(u, -1, 1);
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * WHEEL_BASE * 0.5, -1.35, 1.35);
    const targetR = clamp(v + omega * WHEEL_BASE * 0.5, -1.35, 1.35);
    const slopeAssist = clamp(
      0.08 * Math.sin(finite(obs.pitch, 0) * RAD),
      -0.08,
      0.08
    );
    mem.lastCmdV = v;
    mem.lastCmdOmega = omega;
    return {
      left: clamp(motorPower(targetL, wl, 0) + slopeAssist, -1, 1),
      right: clamp(motorPower(targetR, wr, 1) + slopeAssist, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    const pitch = finite(obs.pitch, 0) * RAD;
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const slopeHold = clamp(0.62 * Math.sin(pitch), -0.40, 0.40);
    const positionHold = clamp(0.13 * along, -0.15, 0.15);
    const left = clamp(-0.95 * wl + slopeHold + positionHold, -0.55, 0.55);
    const right = clamp(-0.95 * wr + slopeHold + positionHold, -0.55, 0.55);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;
    mem.integralL = finite(mem.integralL, 0) * 0.8;
    mem.integralR = finite(mem.integralR, 0) * 0.8;
    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navDrive(goalRel, targetDistance, key, baseSpeed, gx, gy) {
    goalRel = wrap(goalRel);
    targetDistance = Math.max(0, targetDistance);
    const navKey = String(key || "goal");

    if (mem.navKey !== navKey) {
      mem.navKey = navKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
      mem.stuckCount = 0;
      mem.navStallFlag = false;
    } else if (now - finite(mem.progressT, now) >= 12) {
      const distanceImprovement =
        finite(mem.progressD, targetDistance) - targetDistance;
      const angleImprovement =
        finite(mem.progressA, Math.abs(goalRel)) - Math.abs(goalRel);
      const tryingToMove =
        finite(mem.lastCmdV, 0) > 0.25 ||
        Math.abs(finite(mem.lastCmdOmega, 0)) > 0.35;

      if (targetDistance > 4 &&
          distanceImprovement < 0.8 &&
          angleImprovement < 8 &&
          tryingToMove) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.9;
        if (mem.stuckCount >= 2) mem.navStallFlag = true;
      } else if (distanceImprovement > 1.0 || angleImprovement > 12) {
        mem.stuckCount = 0;
        mem.navStallFlag = false;
      }

      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
    }

    if (obs.bumped && !mem.prevBumped && !mem.sampleActive) {
      mem.escapeSign = chooseEscapeSign();
      mem.escapeUntil = now + 0.85;
    }
    mem.prevBumped = !!obs.bumped;

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.28, finite(mem.escapeSign, 1) * 1.05);
    }

    if (targetDistance < 0.55) return driveWheels(0, 0);

    if (Math.abs(goalRel) > 108) {
      return driveWheels(0, Math.sign(goalRel) * 1.05);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 38, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < Math.min(9, rays.length); i++) {
          const range = finite(rays[i], NaN);
          if (!Number.isFinite(range) ||
              range < 0 ||
              range >= 14.8 ||
              finite(mem.rayStale[i], 0) > 2.5) continue;

          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const d = Math.max(0.1, range);
          const along = d * Math.cos(rel);
          const cross = Math.abs(d * Math.sin(rel));
          if (along <= 0 || along >= 6.2) continue;

          const safeWidth = 0.88 + 0.055 * along;
          if (cross < safeWidth) {
            const severity = (safeWidth - cross) / safeWidth;
            const obstacleWeight =
              along < 1.6 ? 23 :
              along < 3.0 ? 16 :
              10;
            cost += obstacleWeight * severity * severity;
            if (along < 1.3) cost += 8 * severity;
            clear = Math.min(clear, along);
          }
        }
      }

      if (Number.isFinite(gx) && Number.isFinite(gy)) {
        const worldA = (headMap + alpha) * RAD;
        const edgeX = posX + 3.5 * Math.cos(worldA);
        const edgeY = posY + 3.5 * Math.sin(worldA);
        if (edgeX < 2 || edgeX > mem.mapW - 2) cost += 10;
        if (edgeY < 2 || edgeY > mem.mapH - 2) cost += 10;
      }

      cost += 0.0015 * Math.abs(alpha - finite(mem.lastAvoidAlpha, alpha));
      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(finite(baseSpeed, 0.76), 0.12, 0.82);
    if (targetDistance < 5) {
      speed = Math.min(speed, 0.10 + 0.15 * targetDistance);
    }
    if (Math.abs(bestAlpha) > 65) speed = 0;
    else speed *= Math.max(0.35, Math.cos(bestAlpha * RAD));

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.0) speed = Math.min(speed, 0.12);
      else if (bestClear < 1.6) speed = Math.min(speed, 0.20);
      else if (bestClear < 2.4) speed = Math.min(speed, 0.34);
      else if (bestClear < 3.5) speed = Math.min(speed, 0.52);
      else if (bestClear < 4.5) speed = Math.min(speed, 0.67);
    }
    if (raysBlind) speed = Math.min(speed, 0.60);

    const errRad = bestAlpha * RAD;
    const v = Math.abs(bestAlpha) > 65
      ? 0
      : speed * Math.max(0, Math.cos(errRad));
    const omega = clamp(2.25 * errRad, -1.3, 1.3);
    return driveWheels(v, omega);
  }

  function navToPoint(gx, gy, key, speed) {
    const dx = gx - posX;
    const dy = gy - posY;
    const d = Math.hypot(dx, dy);
    const bearingDeg = Math.atan2(dy, dx) / RAD;
    const rel = wrap(bearingDeg - headMap);
    return navDrive(rel, d, key, speed, gx, gy);
  }

  function navRelative(rel, d, key, speed) {
    return navDrive(rel, d, key, speed);
  }

  function remainingRoute(task, fromX, fromY) {
    if (!task.scanStarted) {
      return dist(fromX, fromY, task.x, task.y) + 75;
    }
    if (!Array.isArray(task.scanPts) || task.scanIdx >= task.scanPts.length) {
      return 0;
    }
    let length = dist(
      fromX, fromY,
      task.scanPts[task.scanIdx].x,
      task.scanPts[task.scanIdx].y
    );
    for (let i = task.scanIdx + 1; i < task.scanPts.length; i++) {
      length += dist(
        task.scanPts[i - 1].x,
        task.scanPts[i - 1].y,
        task.scanPts[i].x,
        task.scanPts[i].y
      );
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    const out = remainingRoute(task, fromX, fromY);
    const back = dist(task.x, task.y, mem.baseX, mem.baseY) + 22;
    const load = 1 + 0.13 * carried;
    const energy =
      0.09 +
      finite(mem.ePerM, 0.0012) *
        (1.25 * out + 1.50 * back) * load +
      finite(mem.ePerSec, 0.00018) *
        (10 + 0.04 * (out + back));
    const timeNeed = (out + back) / 0.62 + 42;
    return { out: out, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    const available = atDock
      ? Math.max(0, finite(mem.maxBattery, battery) - 0.035)
      : battery - 0.055;

    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;

      const m = taskMetrics(task, fromX, fromY);
      if (m.energy > available) continue;
      if (m.timeNeed + 12 > timeLeft) continue;

      let value = clamp(finite(task.val, 1), 0.3, 60);
      if (task.kind === "signal") value *= 0.82;
      let score = value / (34 + m.out + 0.72 * m.back);
      if (task.id === mem.currentTaskId) score *= 1.18;
      if (task.status === 1) score *= 1.06;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function fallbackPoint() {
    const pts = mem.explorePoints;
    if (!Array.isArray(pts) || !pts.length) {
      return { x: clamp(mem.baseX + 12, 5, mem.mapW - 5), y: mem.baseY };
    }
    let guard = 0;
    while (guard++ < 10) {
      const p = pts[mem.exploreIdx % pts.length];
      if (dist(posX, posY, p.x, p.y) > 4.0) return p;
      mem.exploreIdx = (mem.exploreIdx + 1) % pts.length;
    }
    return pts[mem.exploreIdx % pts.length];
  }

  function fallbackEnergy(p) {
    const out = dist(posX, posY, p.x, p.y);
    const back = dist(p.x, p.y, mem.baseX, mem.baseY);
    return 0.07 +
      finite(mem.ePerM, 0.0012) *
        (1.35 * out + 1.60 * back) *
        (1 + 0.13 * carried) +
      finite(mem.ePerSec, 0.00018) * 12;
  }

  function beginSample(taskId, sx, sy, initialDistance) {
    if (carried >= mem.capacity) return false;
    mem.sampleActive = true;
    mem.sampleTaskId = Number.isFinite(taskId) ? taskId : -1;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleSiteX = finite(sx, posX);
    mem.sampleSiteY = finite(sy, posY);
    mem.sampleInitialDistance = clamp(finite(initialDistance, 1.2), 0, 1.5);
    mem.sampleStart = now;
    mem.sampleFailures = finite(mem.sampleFailures, 0);
    const task = getTask(mem.sampleTaskId);
    if (task && task.status !== 2) task.status = 1;
    return true;
  }

  function sampleCommand() {
    const anchorD = dist(
      posX,
      posY,
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY)
    );
    const drilling = Math.max(0, finite(obs.drilling, 0));

    if (carried <= finite(mem.prevCarried, carried) &&
        now - finite(mem.sampleStart, now) > 19 &&
        drilling < 5.8) {
      mem.sampleFailures = finite(mem.sampleFailures, 0) + 1;
      mem.sampleRetryUntil = now + 4;
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      if (mem.sampleFailures >= 3) {
        const task = getTask(mem.currentTaskId);
        if (task && task.status === 1) task.status = 0;
      }
      return null;
    }

    if (anchorD > 1.25 && drilling < 0.1) {
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      return null;
    }

    const close =
      finite(mem.sampleInitialDistance, 1.2) <= 1.5 &&
      anchorD <= 1.0;
    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function taskCommand(task) {
    if (!task.scanStarted) buildScan(task);

    let guard = 0;
    while (task.scanIdx < task.scanPts.length && guard++ < 20) {
      const p = task.scanPts[task.scanIdx];
      if (dist(posX, posY, p.x, p.y) > 3.0) break;
      task.scanIdx++;
    }

    if (task.scanIdx >= task.scanPts.length) {
      task.status = 3;
      if (mem.currentTaskId === task.id) mem.currentTaskId = -1;
      return null;
    }

    const p = task.scanPts[task.scanIdx];
    const cmd = navToPoint(
      p.x,
      p.y,
      "scan-" + task.id + "-" + task.scanIdx,
      0.78
    );

    if (mem.navStallFlag && finite(mem.stuckCount, 0) >= 2) {
      task.scanIdx++;
      mem.navKey = "";
      mem.stuckCount = 0;
      mem.navStallFlag = false;
    }
    return cmd;
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    mem.baseWaitSince = -1;
    if (mem.sampleActive) {
      const task = getTask(mem.sampleTaskId);
      if (task && task.status !== 2) task.status = 1;
    }
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
  }

  function returnCommand() {
    if (obs.docked) return holdAt(mem.baseX, mem.baseY, false, false);

    if (beaconValid) {
      if (beacon.distance <= 2.4) {
        if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
        if (beacon.distance < 0.75 ||
            now - mem.baseWaitSince < 2.5) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        return navRelative(
          beacon.bearing,
          beacon.distance,
          "base-return",
          0.28
        );
      }
      mem.baseWaitSince = -1;
      return navRelative(
        beacon.bearing,
        beacon.distance,
        "base-return",
        0.74
      );
    }

    if (baseGpsDist <= 2.4) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (baseGpsDist < 0.75 ||
          now - mem.baseWaitSince < 2.5) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      return navToPoint(mem.baseX, mem.baseY, "base-return", 0.28);
    }

    mem.baseWaitSince = -1;
    return navToPoint(mem.baseX, mem.baseY, "base-return", 0.74);
  }

  if (mem.returning && obs.docked) {
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
  }

  if (mem.departing && (!obs.docked || baseDist > 4.0)) {
    mem.departing = false;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped && !mem.sampleActive) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 0.85;
  }
  mem.prevBumped = bumped;

  if (mem.returning) return returnCommand();

  const returnReserve =
    0.09 +
    finite(mem.ePerM, 0.0012) *
      baseDist * (1.65 + 0.17 * carried) +
    finite(mem.ePerSec, 0.00018) * (10 + 0.05 * baseDist) +
    0.012 * carried;
  const returnTime = 30 + baseDist / 0.50 + 2 * carried;

  if (!obs.docked) {
    const isSampling = !!mem.sampleActive;
    const batteryMargin = isSampling ? 0.02 : (carried > 0 ? 0.055 : 0.085);
    const timeMargin = isSampling ? 10 : (carried > 0 ? 12 : 24);
    const mustReturn =
      carried >= mem.capacity ||
      battery < returnReserve + batteryMargin ||
      battery < 0.075 ||
      timeLeft < returnTime + timeMargin ||
      (now < finite(mem.batteryShockUntil, -1) && carried > 0);

    if (mustReturn) {
      requestReturn();
      return returnCommand();
    }
  }

  if (mem.sampleActive) {
    const cmd = sampleCommand();
    if (cmd) return cmd;
  }

  // Use the local bearing directly for reliable close-range site approach.
  if (!mem.returning && carried < mem.capacity && siteValid) {
    if (siteDistance <= 1.34 &&
        now >= finite(mem.sampleRetryUntil, -1)) {
      const activeTask = getTask(mem.currentTaskId);
      const taskId = activeTask ? activeTask.id : -1;
      beginSample(taskId, siteX, siteY, siteDistance);
      return sampleCommand() || holdAt(posX, posY, false, false);
    }

    const speed = siteDistance < 4
      ? clamp(0.12 + 0.22 * (siteDistance - 1.0), 0.12, 0.70)
      : 0.76;
    return navRelative(
      siteBearing,
      siteDistance,
      "visible-site",
      speed
    );
  }

  // Briefly continue toward a recently seen site if its range beam drops out.
  if (!mem.returning &&
      carried < mem.capacity &&
      now < finite(mem.lastSiteUntil, -1)) {
    const d = dist(posX, posY, mem.lastSiteX, mem.lastSiteY);
    if (d <= 1.25 && now >= finite(mem.sampleRetryUntil, -1)) {
      const activeTask = getTask(mem.currentTaskId);
      beginSample(
        activeTask ? activeTask.id : -1,
        mem.lastSiteX,
        mem.lastSiteY,
        d
      );
      return sampleCommand() || holdAt(posX, posY, false, false);
    }
    return navToPoint(
      mem.lastSiteX,
      mem.lastSiteY,
      "last-seen-site",
      d < 4 ? 0.30 : 0.58
    );
  }

  if (obs.docked && carried > 0) {
    return holdAt(mem.baseX, mem.baseY, false, false);
  }

  // Continue an assigned hint scan where possible; otherwise choose a feasible task.
  for (let tries = 0; tries < 5; tries++) {
    let task = getTask(mem.currentTaskId);
    if (task && (task.status === 2 || task.status === 3)) {
      mem.currentTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, !!obs.docked);
      if (task) {
        mem.currentTaskId = task.id;
        task.status = 1;
        if (!task.scanStarted) buildScan(task);
      }
    }

    if (task) {
      const metrics = taskMetrics(task, posX, posY);
      const available = obs.docked
        ? Math.max(0, finite(mem.maxBattery, battery) - 0.035)
        : battery - 0.055;

      if (metrics.energy > available ||
          metrics.timeNeed + 12 > timeLeft) {
        if (obs.docked) {
          task.status = 0;
          mem.currentTaskId = -1;
          continue;
        }
        requestReturn();
        return returnCommand();
      }

      if (obs.docked && !mem.departing) {
        const chargeGoal = Math.min(
          finite(mem.maxBattery, battery),
          metrics.energy + 0.045
        );
        if (battery + 0.012 < chargeGoal) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        mem.departing = true;
        mem.departTime = now;
      }

      const cmd = taskCommand(task);
      if (cmd) return cmd;
      if (task.status === 3) {
        mem.currentTaskId = -1;
        continue;
      }
    }

    break;
  }

  // No feasible hint remains: continue a local expanding coverage path instead of idling.
  const p = fallbackPoint();
  const fbNeed = fallbackEnergy(p);

  if (obs.docked && !mem.departing) {
    const chargeGoal = Math.min(
      finite(mem.maxBattery, battery),
      fbNeed + 0.035
    );
    if (battery + 0.012 < chargeGoal) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    mem.departing = true;
    mem.departTime = now;
  } else if (!obs.docked && fbNeed > battery - 0.055) {
    requestReturn();
    return returnCommand();
  }

  if (dist(posX, posY, p.x, p.y) <= 4.0) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    return driveWheels(0, 0);
  }

  const exploreCmd = navToPoint(
    p.x,
    p.y,
    "explore-" + mem.exploreIdx,
    0.76
  );

  if (mem.navStallFlag && finite(mem.stuckCount, 0) >= 2) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    mem.navKey = "";
    mem.stuckCount = 0;
    mem.navStallFlag = false;
  }

  return exploreCmd;
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, d) => Number.isFinite(v) ? v : d;
  const wrap = (a) => {
    if (!Number.isFinite(a)) return 0;
    return ((a + 180) % 360 + 360) % 360 - 180;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;
  const WHEEL_BASE = 0.6;

  const now = Math.max(0, finite(obs.t, 0));
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    if (!Array.isArray(mem.tasks)) mem.tasks = [];
    if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.2, finite(value, 1)),
      kind: kind || "hint",
      status: 0,
      actual: false,
      siteX: null,
      siteY: null,
      scanStarted: false,
      scanPoints: [],
      scanIdx: 0,
      scanRadius: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeTaskId = -1;
    mem.sampleTaskId = -1;
    mem.sampleActive = false;
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.biasCount = 0;
    mem.compassBadUntil = -1;
    mem.compassStall = 0;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
    mem.gpsBadUntil = -1;

    mem.ePerM = 0.00145;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;
    mem.maxBattery = battery;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.navKey = "";
    mem.navBlockedKey = "";
    mem.progressT = now;
    mem.progressD = 0;
    mem.progressA = 0;
    mem.stuckCount = 0;
    mem.lastAvoidAlpha = 0;
    mem.integralL = 0;
    mem.integralR = 0;
    mem.oldTargetL = 0;
    mem.oldTargetR = 0;
    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;

    mem.prevCarried = carried;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    mem.sampleRetryUntil = -1;
    mem.lastSampleUntil = -1;
    mem.lastSampleX = rawX;
    mem.lastSampleY = rawY;

    mem.bestScience = 0;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;
    mem.bestScienceT = now;
    mem.signalSpawns = 0;
    mem.signalSpawnedPeak = 0;

    mem.exploreIdx = 0;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 300; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      const hx = clamp(x, 2.5, mem.mapW - 2.5);
      const hy = clamp(y, 2.5, mem.mapH - 2.5);
      const val = finite(h.estimate, 1);

      let duplicate = null;
      for (const task of mem.tasks) {
        if (dist(hx, hy, task.x, task.y) < 9) {
          duplicate = task;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, val);
      } else {
        addTask(hx, hy, val, "hint");
      }
    }

    mem.explorePoints = [];
    for (let radius = 18; radius <= 180; radius += 18) {
      for (let j = 0; j < 8; j++) {
        const a = j * Math.PI / 4;
        const p = {
          x: clamp(mem.baseX + radius * Math.cos(a), 3, mem.mapW - 3),
          y: clamp(mem.baseY + radius * Math.sin(a), 3, mem.mapH - 3)
        };
        let duplicate = false;
        for (const q of mem.explorePoints) {
          if (dist(p.x, p.y, q.x, q.y) < 5) {
            duplicate = true;
            break;
          }
        }
        if (!duplicate) mem.explorePoints.push(p);
      }
    }
    if (!mem.explorePoints.length) {
      mem.explorePoints.push({
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      });
    }

    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.calActive = false;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Array.isArray(mem.explorePoints) || !mem.explorePoints.length) {
    mem.explorePoints = [{
      x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
      y: clamp(mem.baseY, 3, mem.mapH - 3)
    }];
  }
  if (!Number.isFinite(mem.activeTaskId)) mem.activeTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.00145;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;

  let dtRaw = now - finite(mem.lastT, now);
  let dt = dtRaw > 0 ? clamp(dtRaw, 0.025, 0.25) : 0.1;

  const rawHeadingDelta = angleDiff(
    rawHeading,
    finite(mem.lastRawHeading, rawHeading)
  );
  const wheelYawDeg = (wr - wl) / WHEEL_BASE * dt / RAD;
  const predictedHeading = wrap(finite(mem.headingEst, rawHeading) + wheelYawDeg);
  const yawMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYawDeg));

  const compassJump =
    (Math.abs(rawHeadingDelta) > 48 && yawMismatch > 36) ||
    (Math.abs(rawHeadingDelta) > 125 && Math.abs(wheelYawDeg) < 48);

  if (compassJump) {
    mem.compassBadUntil = now + 1.4;
    mem.compassStall = 0;
  }

  if (Math.abs(rawHeadingDelta) < 0.025 && Math.abs(wheelYawDeg) > 1.4) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(0, finite(mem.compassStall, 0) - 1.2 * dt);
  }

  let compassTrusted =
    now >= finite(mem.compassBadUntil, -1) &&
    finite(mem.compassStall, 0) < 0.9 &&
    !compassJump;

  if (compassTrusted) {
    const err = angleDiff(rawHeading, predictedHeading);
    if (Math.abs(err) < 80) {
      mem.headingEst = wrap(
        predictedHeading + clamp(0.16 * err, -6, 6)
      );
    } else {
      mem.headingEst = predictedHeading;
      mem.compassBadUntil = now + 1.0;
      compassTrusted = false;
    }
  } else {
    mem.headingEst = predictedHeading;
  }

  const rawMove = dist(
    rawX, rawY,
    finite(mem.lastRawX, rawX),
    finite(mem.lastRawY, rawY)
  );
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(18, odom * 15 + 8);

  let anchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );

  if (anchorMove > 0.9) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
  } else {
    mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
    if (now - finite(mem.gpsAnchorT, now) > 3.2 &&
        mem.gpsOdom > 2.5 &&
        Math.abs(vAvg) > 0.18 &&
        !obs.bumped) {
      mem.gpsFrozen = true;
    }
  }

  if (teleport) {
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  if (mem.gpsFrozen && anchorMove > 1.4) {
    mem.gpsFrozen = false;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  const gpsBad = !!mem.gpsFrozen ||
    teleport ||
    now < finite(mem.gpsBadUntil, -1);

  const headForPosition = wrap(mem.headingEst - finite(mem.headingBias, 0));
  const predX = finite(mem.posX, rawX) +
    vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = finite(mem.posY, rawY) +
    vAvg * Math.sin(headForPosition * RAD) * dt;

  if (gpsBad) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.2 ? 0.36 : 0.20;
    if (residual > 16) gain = 0.015;
    else if (residual > 7) gain = 0.07;
    if (obs.docked) gain = Math.max(gain, 0.45);
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  const straight =
    !gpsBad &&
    !teleport &&
    compassTrusted &&
    finite(mem.lastCmdV, 0) > 0.28 &&
    Math.abs(finite(mem.lastCmdOmega, 0)) < 0.24 &&
    vAvg > 0.18;

  if (straight) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(
        angleDiff(mem.headingEst, finite(mem.calHead, mem.headingEst))
      );
      if (turned > 25) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 5.0) {
        const course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        const measuredBias = angleDiff(mem.headingEst, course);
        if (finite(mem.biasCount, 0) < 1) {
          mem.headingBias = measuredBias;
        } else {
          mem.headingBias = wrap(
            mem.headingBias +
            0.18 * angleDiff(measuredBias, mem.headingBias)
          );
        }
        mem.biasCount = finite(mem.biasCount, 0) + 1;
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  if (!gpsBad && !compassTrusted && Math.abs(vAvg) > 0.3 &&
      Math.abs(finite(mem.lastCmdOmega, 0)) < 0.2) {
    const gx = rawX - finite(mem.lastRawX, rawX);
    const gy = rawY - finite(mem.lastRawY, rawY);
    if (Math.hypot(gx, gy) > 0.05) {
      const course = Math.atan2(gy, gx) / RAD;
      const expected = wrap(course + finite(mem.headingBias, 0));
      mem.headingEst = wrap(mem.headingEst + 0.10 * angleDiff(expected, mem.headingEst));
    }
  }

  mem.posX = clamp(mem.posX, -3, mem.mapW + 3);
  mem.posY = clamp(mem.posY, -3, mem.mapH + 3);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = wrap(mem.headingEst - finite(mem.headingBias, 0));

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  const previousBattery = finite(mem.lastBattery, battery);
  if (previousBattery - battery > 0.14 && dt < 0.6) {
    mem.batteryShockUntil = now + 30;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.00145), 0.0024);
    mem.maxBattery = Math.min(finite(mem.maxBattery, battery), battery);
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  }
  mem.lastBattery = battery;

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery)) mem.maxBattery = battery;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  } else {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    if (now - finite(mem.energyT, now) >= 8) {
      const netUse = finite(mem.energyBat, battery) - battery;
      if (netUse > 0.004 && finite(mem.energyDist, 0) > 2.0) {
        const measured = clamp(netUse / mem.energyDist, 0.0003, 0.02);
        if (measured > mem.ePerM) {
          mem.ePerM = clamp(0.75 * mem.ePerM + 0.25 * measured, 0.0004, 0.02);
        } else {
          mem.ePerM = clamp(0.97 * mem.ePerM + 0.03 * measured, 0.0004, 0.02);
        }
      }
      mem.energyT = now;
      mem.energyBat = battery;
      mem.energyDist = 0;
    }
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let validRayCount = 0;
  let staleRayCount = 0;

  if (rays) {
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.005 &&
          Math.abs(vAvg) > 0.4 &&
          r < 14.8) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 3.5 && r < 14.8) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  if (science > finite(mem.bestScience, 0) + 0.015) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
    mem.bestScienceT = now;
  }

  const peakScience = finite(mem.bestScience, 0);
  const peakFell = science < peakScience - Math.max(0.035, peakScience * 0.12);
  const peakOld = now - finite(mem.bestScienceT, now) > 30;
  if (peakScience > 0.10 &&
      peakScience > finite(mem.signalSpawnedPeak, 0) + 0.04 &&
      finite(mem.signalSpawns, 0) < 4 &&
      (peakFell || peakOld)) {
    let nearTask = false;
    for (const task of mem.tasks) {
      if (task && dist(
        finite(mem.bestScienceX, posX),
        finite(mem.bestScienceY, posY),
        task.x, task.y
      ) < 19) {
        nearTask = true;
        break;
      }
    }
    if (!nearTask) {
      const t = addTask(
        clamp(finite(mem.bestScienceX, posX), 2.5, mem.mapW - 2.5),
        clamp(finite(mem.bestScienceY, posY), 2.5, mem.mapH - 2.5),
        clamp(peakScience * 11, 1, 15),
        "signal"
      );
      t.scanRadius = 11.5;
      mem.signalSpawns = finite(mem.signalSpawns, 0) + 1;
    }
    mem.signalSpawnedPeak = peakScience;
  }

  let siteValid = !!(
    obs.site &&
    Number.isFinite(obs.site.distance) &&
    Number.isFinite(obs.site.bearing) &&
    obs.site.distance >= 0 &&
    obs.site.distance <= 9
  );
  let siteDistance = siteValid ? obs.site.distance : Infinity;
  let siteBearing = siteValid ? wrap(obs.site.bearing) : 0;
  let siteX = posX;
  let siteY = posY;
  let siteTaskId = -1;

  if (siteValid) {
    const a = (headMap + siteBearing) * RAD;
    siteX = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    siteY = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);

    if (now < finite(mem.lastSampleUntil, -1) &&
        dist(siteX, siteY,
             finite(mem.lastSampleX, siteX),
             finite(mem.lastSampleY, siteY)) < 4) {
      siteValid = false;
      siteDistance = Infinity;
    }
  }

  if (siteValid) {
    let match = null;
    const active = getTask(mem.activeTaskId);
    if (active && active.status !== 2) {
      const ax = Number.isFinite(active.siteX) ? active.siteX : active.x;
      const ay = Number.isFinite(active.siteY) ? active.siteY : active.y;
      if (dist(siteX, siteY, ax, ay) < 36) match = active;
    }

    if (!match) {
      let nearest = Infinity;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const tx = Number.isFinite(task.siteX) ? task.siteX : task.x;
        const ty = Number.isFinite(task.siteY) ? task.siteY : task.y;
        const d = dist(siteX, siteY, tx, ty);
        const limit = task.actual ? 14 : 29;
        if (d < limit && d < nearest) {
          nearest = d;
          match = task;
        }
      }
    }

    if (!match) {
      match = addTask(
        siteX, siteY,
        finite(obs.site.value, 1),
        "site"
      );
    }

    if (match.status === 3) match.status = 0;
    match.actual = true;
    if (!Number.isFinite(match.siteX)) {
      match.siteX = siteX;
      match.siteY = siteY;
    } else {
      match.siteX = 0.30 * match.siteX + 0.70 * siteX;
      match.siteY = 0.30 * match.siteY + 0.70 * siteY;
    }
    if (Number.isFinite(obs.site.value) && obs.site.value > 0) {
      match.val = Math.max(match.val, obs.site.value);
    }
    match.status = 1;
    siteTaskId = match.id;
    mem.activeTaskId = match.id;
  }

  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    const sx = finite(mem.sampleSiteX, posX);
    const sy = finite(mem.sampleSiteY, posY);
    let completed = getTask(mem.sampleTaskId);

    if (!completed) {
      let nearest = 25;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const d = dist(sx, sy, task.x, task.y);
        if (d < nearest) {
          nearest = d;
          completed = task;
        }
      }
    }

    if (completed) completed.status = 2;

    let nearestHint = null;
    let nearestHintD = 24;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.id === (completed ? completed.id : -1)) {
        continue;
      }
      const d = dist(sx, sy, task.x, task.y);
      if (d < nearestHintD) {
        nearestHintD = d;
        nearestHint = task;
      }
    }
    if (nearestHint) nearestHint.status = 2;

    for (const task of mem.tasks) {
      if (task && task.status !== 2 && dist(sx, sy, task.x, task.y) < 7) {
        task.status = 2;
      }
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleUntil = now + 1.5;
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    if (completed && mem.activeTaskId === completed.id) mem.activeTaskId = -1;
  }
  mem.prevCarried = carried;

  const beacon = obs.beacon;
  const beaconValid = !!(
    beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 &&
    beacon.distance <= 20.8
  );
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function ensureScan(task, fromX, fromY) {
    if (!task || task.actual) return;
    if (task.scanStarted &&
        Array.isArray(task.scanPoints) &&
        task.scanPoints.length > 0) return;

    const radius = task.kind === "signal"
      ? finite(task.scanRadius, 11.5)
      : 18.5;
    task.scanRadius = radius;
    task.scanPoints = [];
    task.scanIdx = 0;
    task.scanStarted = true;

    const center = {
      x: clamp(task.x, 2.5, mem.mapW - 2.5),
      y: clamp(task.y, 2.5, mem.mapH - 2.5)
    };
    task.scanPoints.push(center);

    const fromAngle = Math.atan2(fromY - task.y, fromX - task.x) / RAD;
    let start = Math.round(fromAngle / 45);
    start = ((start % 8) + 8) % 8;

    for (let j = 0; j < 8; j++) {
      const angle = (start + j) * Math.PI / 4;
      const p = {
        x: clamp(task.x + radius * Math.cos(angle), 2.5, mem.mapW - 2.5),
        y: clamp(task.y + radius * Math.sin(angle), 2.5, mem.mapH - 2.5)
      };
      let duplicate = false;
      for (const q of task.scanPoints) {
        if (dist(p.x, p.y, q.x, q.y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.scanPoints.push(p);
    }
  }

  function remainingScan(task, fromX, fromY) {
    if (!task.scanStarted || !Array.isArray(task.scanPoints)) {
      return dist(fromX, fromY, task.x, task.y) +
        (task.kind === "signal" ? 75 : 122);
    }
    if (task.scanIdx >= task.scanPoints.length) return 0;
    let length = dist(
      fromX, fromY,
      task.scanPoints[task.scanIdx].x,
      task.scanPoints[task.scanIdx].y
    );
    for (let i = task.scanIdx + 1; i < task.scanPoints.length; i++) {
      length += dist(
        task.scanPoints[i - 1].x,
        task.scanPoints[i - 1].y,
        task.scanPoints[i].x,
        task.scanPoints[i].y
      );
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    let out;
    let back;
    if (task.actual && Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      out = dist(fromX, fromY, task.siteX, task.siteY);
      back = dist(task.siteX, task.siteY, mem.baseX, mem.baseY);
    } else {
      out = remainingScan(task, fromX, fromY);
      const radius = task.scanStarted
        ? finite(task.scanRadius, task.kind === "signal" ? 11.5 : 18.5)
        : (task.kind === "signal" ? 11.5 : 18.5);
      back = dist(task.x, task.y, mem.baseX, mem.baseY) + radius;
    }

    const load = 1 + 0.16 * carried;
    const energy =
      0.11 +
      finite(mem.ePerM, 0.00145) * 1.50 * (out + back) * load +
      0.025 * (carried + 1);
    const timeNeed = (out + back) / 0.62 + 22;
    return { out: out, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    const available = atDock
      ? Math.max(battery, finite(mem.maxBattery, battery))
      : battery;

    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now) continue;

      if (!task.actual) ensureScan(task, fromX, fromY);
      const m = taskMetrics(task, fromX, fromY);
      if (m.energy > available - 0.035) continue;
      if (m.timeNeed + 12 > timeLeft) continue;

      let value = clamp(finite(task.val, 1), 0.3, 100);
      if (task.kind === "signal") value *= 0.95;
      if (task.actual) value *= 1.16;

      let score = value / (30 + m.out + 0.72 * m.back);
      if (task.id === mem.activeTaskId) score *= 1.18;
      if (task.status === 1) score *= 1.05;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) < 3.5) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1.0) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function motorPower(target, current, side) {
    const ikey = side === 0 ? "integralL" : "integralR";
    const tkey = side === 0 ? "oldTargetL" : "oldTargetR";
    let integral = finite(mem[ikey], 0);
    const oldTarget = finite(mem[tkey], target);

    if (target * oldTarget < -0.05) integral *= 0.25;
    mem[tkey] = target;

    if (Math.abs(target) < 0.035) {
      integral *= 0.65;
      mem[ikey] = integral;
      return clamp(-0.82 * current + integral, -1, 1);
    }

    const error = target - current;
    integral = clamp(integral + 0.10 * error * dt, -0.30, 0.30);
    mem[ikey] = integral;

    let u = 0.25 * target +
      0.12 * Math.sign(target) +
      0.42 * error +
      integral;
    if (Math.abs(target) > 0.12 && Math.abs(u) < 0.12) {
      u = Math.sign(target) * 0.12;
    }
    return clamp(u, -1, 1);
  }

  function slopeAssist() {
    const pitch = finite(obs.pitch, 0) * RAD;
    return clamp(0.16 * Math.sin(pitch), -0.14, 0.14);
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const targetR = clamp(v + omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const slope = slopeAssist();
    mem.lastCmdV = v;
    mem.lastCmdOmega = omega;
    return {
      left: clamp(motorPower(targetL, wl, 0) + slope, -1, 1),
      right: clamp(motorPower(targetR, wr, 1) + slope, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const correction = clamp(0.035 * along, -0.06, 0.06);
    const slope = slopeAssist();
    const left = clamp(-0.82 * wl + slope + correction, -0.45, 0.45);
    const right = clamp(-0.82 * wr + slope + correction, -0.45, 0.45);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;

    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;
    mem.integralL = finite(mem.integralL, 0) * 0.8;
    mem.integralR = finite(mem.integralR, 0) * 0.8;

    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navDrive(goalRel, targetDistance, key, baseSpeed,
                    worldX, worldY, stopRadius) {
    goalRel = wrap(goalRel);
    targetDistance = Math.max(0, finite(targetDistance, 0));
    stopRadius = Math.max(0, finite(stopRadius, 2.4));
    const navKey = String(key || "nav");

    if (mem.navKey !== navKey) {
      mem.navKey = navKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
      mem.stuckCount = 0;
      mem.navBlockedKey = "";
    } else if (now - finite(mem.progressT, now) >= 10) {
      const distanceImprovement =
        finite(mem.progressD, targetDistance) - targetDistance;
      const angleImprovement =
        finite(mem.progressA, Math.abs(goalRel)) - Math.abs(goalRel);
      const trying =
        Math.abs(finite(mem.lastCmdV, 0)) > 0.20 ||
        Math.abs(finite(mem.lastCmdOmega, 0)) > 0.30;

      if (targetDistance > stopRadius + 3 &&
          distanceImprovement < 0.65 &&
          angleImprovement < 8 &&
          trying) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.75;
        if (mem.stuckCount >= 3 &&
            (navKey.indexOf("scan:") === 0 ||
             navKey.indexOf("explore:") === 0)) {
          mem.navBlockedKey = navKey;
        }
      } else if (distanceImprovement > 0.9 || angleImprovement > 12) {
        mem.stuckCount = 0;
      }

      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.23, finite(mem.escapeSign, 1) * 0.85);
    }

    if (targetDistance <= stopRadius) return driveWheels(0, 0);

    if (Math.abs(goalRel) > 115) {
      return driveWheels(0, Math.sign(goalRel) * 0.95);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 32, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < Math.min(9, rays.length); i++) {
          const range = finite(rays[i], NaN);
          if (!Number.isFinite(range) ||
              range < 0 ||
              range >= 14.8 ||
              finite(mem.rayStale[i], 0) > 3.5) continue;

          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const d = Math.max(0.15, range);
          const along = d * Math.cos(rel);
          const cross = Math.abs(d * Math.sin(rel));

          if (along > 0 && along < 5.5) {
            const safeWidth = 0.78 + 0.07 * along;
            if (cross < safeWidth) {
              const severity = (safeWidth - cross) / safeWidth;
              const weight = along < 1.25 ? 38 :
                (along < 2.5 ? 23 : 11);
              cost += weight * severity * severity;
              if (along < 0.9) cost += 12 * severity;
              clear = Math.min(clear, along);
            }
          }
        }
      }

      if (Number.isFinite(worldX) && Number.isFinite(worldY)) {
        const worldA = (headMap + alpha) * RAD;
        const edgeX = posX + 3.0 * Math.cos(worldA);
        const edgeY = posY + 3.0 * Math.sin(worldA);
        if (edgeX < 2 || edgeX > mem.mapW - 2) cost += 16;
        if (edgeY < 2 || edgeY > mem.mapH - 2) cost += 16;
      }

      cost += 0.002 * Math.abs(alpha - finite(mem.lastAvoidAlpha, alpha));
      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(finite(baseSpeed, 0.70), 0.12, 0.82);
    if (targetDistance < 7) {
      speed = Math.min(speed, 0.18 + 0.11 * targetDistance);
    }
    if (Math.abs(bestAlpha) > 55) speed = 0;
    else if (Math.abs(bestAlpha) > 38) speed = Math.min(speed, 0.32);

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.0) speed = Math.min(speed, 0.10);
      else if (bestClear < 1.5) speed = Math.min(speed, 0.18);
      else if (bestClear < 2.3) speed = Math.min(speed, 0.30);
      else if (bestClear < 3.4) speed = Math.min(speed, 0.48);
      else if (bestClear < 4.4) speed = Math.min(speed, 0.64);
    }
    if (raysBlind) speed = Math.min(speed, 0.58);

    const alphaRad = bestAlpha * RAD;
    const v = Math.abs(bestAlpha) > 55
      ? 0
      : speed * Math.max(0, Math.cos(alphaRad));
    const omega = clamp(2.0 * alphaRad, -1.15, 1.15);
    return driveWheels(v, omega);
  }

  function navToWorld(gx, gy, key, speed, stopRadius) {
    const dx = gx - posX;
    const dy = gy - posY;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / RAD : headMap;
    return navDrive(
      wrap(bearing - headMap),
      d,
      key,
      speed,
      gx,
      gy,
      stopRadius
    );
  }

  function navRelative(rel, d, key, speed, stopRadius) {
    return navDrive(rel, d, key, speed, NaN, NaN, stopRadius);
  }

  function beginSample(taskId, sx, sy, initialDistance) {
    if (carried >= mem.capacity) return false;
    mem.sampleActive = true;
    mem.sampleTaskId = Number.isFinite(taskId) ? taskId : -1;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleSiteX = finite(sx, posX);
    mem.sampleSiteY = finite(sy, posY);
    mem.sampleInitialDistance = clamp(finite(initialDistance, 1.2), 0, 1.5);
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    mem.sampleLastT = now;
    mem.sampleMove = 0;

    const task = getTask(mem.sampleTaskId);
    if (task && task.status !== 2) task.status = 1;
    return true;
  }

  function sampleCommand(currentSiteDistance) {
    if (!mem.sampleActive) return driveWheels(0, 0);

    if (now > finite(mem.sampleLastT, now)) {
      mem.sampleMove = finite(mem.sampleMove, 0) + Math.abs(vAvg) * dt;
      mem.sampleLastT = now;
    }

    const drilling = Math.max(0, finite(obs.drilling, 0));
    const elapsed = now - finite(mem.sampleStart, now);

    if (carried > finite(mem.sampleCarryStart, carried)) {
      return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, false, false);
    }

    if ((elapsed > 20 && drilling < 5.8) || elapsed > 26 ||
        (mem.sampleMove > 1.8 && drilling < 0.2)) {
      const task = getTask(mem.sampleTaskId);
      if (task) {
        task.sampleFailures = finite(task.sampleFailures, 0) + 1;
        task.retryAfter = now + (task.sampleFailures >= 3 ? 18 : 5);
      }
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      mem.sampleRetryUntil = now + 5;
      return driveWheels(0, 0);
    }

    let close = finite(mem.sampleInitialDistance, 1.5) <= 1.45;
    if (Number.isFinite(currentSiteDistance)) {
      close = currentSiteDistance <= 1.5;
    }
    if (mem.sampleMove > 1.0 && drilling < 0.2) close = false;

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual &&
        Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      const d = dist(posX, posY, task.siteX, task.siteY);
      if (d < 1.0 &&
          carried < mem.capacity &&
          now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(task.id, task.siteX, task.siteY, d)) {
          return sampleCommand(Infinity);
        }
      }
      return navToWorld(
        task.siteX, task.siteY,
        "actual:" + task.id,
        d < 5 ? 0.42 : 0.58,
        0.65
      );
    }

    ensureScan(task, posX, posY);
    let guard = 0;
    while (task.scanIdx < task.scanPoints.length && guard++ < 12) {
      const p = task.scanPoints[task.scanIdx];
      if (dist(posX, posY, p.x, p.y) > 2.7) break;
      task.scanIdx++;
    }

    if (task.scanIdx >= task.scanPoints.length) {
      task.status = 3;
      if (mem.activeTaskId === task.id) mem.activeTaskId = -1;
      return null;
    }

    const p = task.scanPoints[task.scanIdx];
    const key = "scan:" + task.id + ":" + task.scanIdx;
    const cmd = navToWorld(p.x, p.y, key, 0.72, 2.4);

    if (mem.navBlockedKey === key) {
      task.scanIdx++;
      mem.navBlockedKey = "";
      mem.navKey = "";
      mem.stuckCount = 0;
      return driveWheels(0, 0);
    }
    return cmd;
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    mem.baseWaitSince = -1;
    if (mem.sampleActive) {
      const task = getTask(mem.sampleTaskId);
      if (task && task.status !== 2) task.status = 1;
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
    }
  }

  function returnCommand() {
    if (obs.docked) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (beaconValid) {
      const d = beacon.distance;
      if (d <= 2.7) {
        if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
        if (d < 0.75 || now - mem.baseWaitSince < 2.5) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        return navRelative(beacon.bearing, d, "return", 0.22, 0.65);
      }
      mem.baseWaitSince = -1;
      return navRelative(beacon.bearing, d, "return", 0.72, 2.7);
    }

    if (baseGpsDist <= 2.7) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (baseGpsDist < 0.75 || now - mem.baseWaitSince < 2.5) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      return navToWorld(
        mem.baseX, mem.baseY, "return", 0.22, 0.65
      );
    }
    mem.baseWaitSince = -1;
    return navToWorld(mem.baseX, mem.baseY, "return", 0.72, 2.7);
  }

  function fallbackPoint() {
    const pts = mem.explorePoints;
    if (!Array.isArray(pts) || !pts.length) {
      return {
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      };
    }
    let guard = 0;
    while (guard++ < pts.length) {
      const idx = ((mem.exploreIdx % pts.length) + pts.length) % pts.length;
      const p = pts[idx];
      if (dist(posX, posY, p.x, p.y) > 3.5) return p;
      mem.exploreIdx = (idx + 1) % pts.length;
    }
    return pts[mem.exploreIdx % pts.length];
  }

  function fallbackMetrics(p, fromX, fromY) {
    const out = dist(fromX, fromY, p.x, p.y);
    const back = dist(p.x, p.y, mem.baseX, mem.baseY);
    const energy =
      0.10 +
      finite(mem.ePerM, 0.00145) * 1.45 * (out + back) *
        (1 + 0.16 * carried) +
      0.015;
    const timeNeed = (out + back) / 0.65 + 18;
    return { energy: energy, timeNeed: timeNeed };
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped && !mem.sampleActive) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 0.75;
  }
  mem.prevBumped = bumped;

  if (mem.departing && !obs.docked && baseDist > 4) {
    mem.departing = false;
  }

  if (obs.docked && mem.returning) {
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;
    mem.escapeUntil = -1;
  }

  if (mem.returning) return returnCommand();

  if (mem.sampleActive) {
    if (battery < 0.035 && carried > 0) {
      requestReturn();
      return returnCommand();
    }
    return sampleCommand(siteValid ? siteDistance : Infinity);
  }

  const returnReserve =
    0.11 +
    finite(mem.ePerM, 0.00145) *
      1.85 * baseDist * (1 + 0.18 * carried) +
    0.022 * carried;
  const returnTime = 24 + baseDist / 0.48;

  if (!obs.docked) {
    const mustReturn =
      carried >= mem.capacity ||
      carried >= Math.min(3, mem.capacity) ||
      battery < returnReserve + 0.075 ||
      battery < 0.065 ||
      timeLeft < returnTime + (carried > 0 ? 12 : 70) ||
      (now < finite(mem.batteryShockUntil, -1) && carried > 0);

    if (mustReturn) {
      requestReturn();
      return returnCommand();
    }
  }

  if (siteValid && carried < mem.capacity) {
    if (obs.docked && battery < 0.18) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (siteDistance <= 1.35) {
      if (now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(
          siteTaskId,
          siteX,
          siteY,
          siteDistance
        )) {
          return sampleCommand(siteDistance);
        }
      } else {
        return holdAt(posX, posY, false, false);
      }
    }

    if (obs.docked) mem.departing = true;
    const speed = siteDistance < 4
      ? clamp(0.14 + 0.17 * (siteDistance - 1.0), 0.16, 0.62)
      : 0.70;
    return navRelative(
      siteBearing,
      siteDistance,
      "site:" + siteTaskId,
      speed,
      0.65
    );
  }

  if (obs.docked && !mem.departing) {
    if (carried > 0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      if (task.status === 1 && task.status !== 2) task.status = 0;
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, true);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task && !task.actual) ensureScan(task, posX, posY);

    if (task) {
      const m = taskMetrics(task, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (m.energy <= maxBat - 0.025 &&
          m.timeNeed + 10 <= timeLeft) {
        const chargeGoal = Math.min(maxBat, m.energy + 0.035);
        if (battery + 0.012 < chargeGoal) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        mem.activeTaskId = task.id;
        task.status = 1;
        mem.departing = true;
      } else {
        if (task.status === 1) task.status = 0;
        mem.activeTaskId = -1;
        task = null;
      }
    }

    if (!task) {
      const p = fallbackPoint();
      const fm = fallbackMetrics(p, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (fm.energy > maxBat - 0.025 ||
          fm.timeNeed + 10 > timeLeft) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      const chargeGoal = Math.min(maxBat, fm.energy + 0.03);
      if (battery + 0.012 < chargeGoal) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      mem.departing = true;
    }
  }

  for (let tries = 0; tries < 5; tries++) {
    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, false);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task) {
      if (!task.actual) ensureScan(task, posX, posY);
      const m = taskMetrics(task, posX, posY);

      if (m.energy > battery - 0.04 ||
          m.timeNeed + (carried > 0 ? 12 : 25) > timeLeft) {
        requestReturn();
        return returnCommand();
      }

      const cmd = controlTask(task);
      if (cmd) return cmd;
      if (task.status === 3) {
        mem.activeTaskId = -1;
        continue;
      }
    }
    break;
  }

  if (carried > 0) {
    requestReturn();
    return returnCommand();
  }

  const p = fallbackPoint();
  const fm = fallbackMetrics(p, posX, posY);
  if (!obs.docked &&
      (fm.energy > battery - 0.04 ||
       fm.timeNeed + 35 > timeLeft)) {
    requestReturn();
    return returnCommand();
  }

  if (obs.docked && !mem.departing) {
    const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
    if (fm.energy > maxBat - 0.025 ||
        fm.timeNeed + 10 > timeLeft) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if (battery + 0.012 < Math.min(maxBat, fm.energy + 0.03)) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    mem.departing = true;
  }

  const dExplore = dist(posX, posY, p.x, p.y);
  if (dExplore <= 2.6) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  const exploreKey = "explore:" + mem.exploreIdx;
  const exploreCmd = navToWorld(
    p.x, p.y, exploreKey, 0.68, 2.4
  );
  if (mem.navBlockedKey === exploreKey) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    mem.navBlockedKey = "";
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  return exploreCmd;
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, d) => Number.isFinite(v) ? v : d;
  const wrap = (a) => {
    if (!Number.isFinite(a)) return 0;
    return ((a + 180) % 360 + 360) % 360 - 180;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;
  const WHEEL_BASE = 0.6;

  const now = Math.max(0, finite(obs.t, 0));
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    if (!Array.isArray(mem.tasks)) mem.tasks = [];
    if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.2, finite(value, 1)),
      kind: kind || "hint",
      status: 0,
      actual: false,
      siteX: null,
      siteY: null,
      scanStarted: false,
      scanPoints: [],
      scanIdx: 0,
      scanRadius: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeTaskId = -1;
    mem.sampleTaskId = -1;
    mem.sampleActive = false;
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.biasCount = 0;
    mem.compassBadUntil = -1;
    mem.compassStall = 0;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
    mem.gpsBadUntil = -1;

    mem.ePerM = 0.00145;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;
    mem.maxBattery = battery;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.navKey = "";
    mem.navBlockedKey = "";
    mem.progressT = now;
    mem.progressD = 0;
    mem.progressA = 0;
    mem.stuckCount = 0;
    mem.lastAvoidAlpha = 0;
    mem.integralL = 0;
    mem.integralR = 0;
    mem.oldTargetL = 0;
    mem.oldTargetR = 0;
    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;

    mem.prevCarried = carried;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    mem.sampleRetryUntil = -1;
    mem.lastSampleUntil = -1;
    mem.lastSampleX = rawX;
    mem.lastSampleY = rawY;

    mem.bestScience = 0;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;
    mem.bestScienceT = now;
    mem.signalSpawns = 0;
    mem.signalSpawnedPeak = 0;

    mem.exploreIdx = 0;
    mem.endgameIdx = 0;
    mem.endgameTarget = null;
    mem.endgameTargetIdx = -1;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 300; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      const hx = clamp(x, 2.5, mem.mapW - 2.5);
      const hy = clamp(y, 2.5, mem.mapH - 2.5);
      const val = finite(h.estimate, 1);

      let duplicate = null;
      for (const task of mem.tasks) {
        if (dist(hx, hy, task.x, task.y) < 9) {
          duplicate = task;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, val);
      } else {
        addTask(hx, hy, val, "hint");
      }
    }

    mem.explorePoints = [];
    for (let radius = 18; radius <= 180; radius += 18) {
      for (let j = 0; j < 8; j++) {
        const a = j * Math.PI / 4;
        const p = {
          x: clamp(mem.baseX + radius * Math.cos(a), 3, mem.mapW - 3),
          y: clamp(mem.baseY + radius * Math.sin(a), 3, mem.mapH - 3)
        };
        let duplicate = false;
        for (const q of mem.explorePoints) {
          if (dist(p.x, p.y, q.x, q.y) < 5) {
            duplicate = true;
            break;
          }
        }
        if (!duplicate) mem.explorePoints.push(p);
      }
    }
    if (!mem.explorePoints.length) {
      mem.explorePoints.push({
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      });
    }

    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.calActive = false;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Array.isArray(mem.explorePoints) || !mem.explorePoints.length) {
    mem.explorePoints = [{
      x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
      y: clamp(mem.baseY, 3, mem.mapH - 3)
    }];
  }
  if (!Number.isFinite(mem.activeTaskId)) mem.activeTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.00145;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;
  if (!Number.isFinite(mem.endgameIdx)) mem.endgameIdx = 0;

  let dtRaw = now - finite(mem.lastT, now);
  let dt = dtRaw > 0 ? clamp(dtRaw, 0.025, 0.25) : 0.1;

  const rawHeadingDelta = angleDiff(
    rawHeading,
    finite(mem.lastRawHeading, rawHeading)
  );
  const wheelYawDeg = (wr - wl) / WHEEL_BASE * dt / RAD;
  const predictedHeading = wrap(finite(mem.headingEst, rawHeading) + wheelYawDeg);
  const yawMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYawDeg));

  const compassJump =
    (Math.abs(rawHeadingDelta) > 48 && yawMismatch > 36) ||
    (Math.abs(rawHeadingDelta) > 125 && Math.abs(wheelYawDeg) < 48);

  if (compassJump) {
    mem.compassBadUntil = now + 1.4;
    mem.compassStall = 0;
  }

  if (Math.abs(rawHeadingDelta) < 0.025 && Math.abs(wheelYawDeg) > 1.4) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(0, finite(mem.compassStall, 0) - 1.2 * dt);
  }

  let compassTrusted =
    now >= finite(mem.compassBadUntil, -1) &&
    finite(mem.compassStall, 0) < 0.9 &&
    !compassJump;

  if (compassTrusted) {
    const err = angleDiff(rawHeading, predictedHeading);
    if (Math.abs(err) < 80) {
      mem.headingEst = wrap(
        predictedHeading + clamp(0.16 * err, -6, 6)
      );
    } else {
      mem.headingEst = predictedHeading;
      mem.compassBadUntil = now + 1.0;
      compassTrusted = false;
    }
  } else {
    mem.headingEst = predictedHeading;
  }

  const rawMove = dist(
    rawX, rawY,
    finite(mem.lastRawX, rawX),
    finite(mem.lastRawY, rawY)
  );
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(18, odom * 15 + 8);

  let anchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );

  if (anchorMove > 0.9) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
  } else {
    mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
    if (now - finite(mem.gpsAnchorT, now) > 3.2 &&
        mem.gpsOdom > 2.5 &&
        Math.abs(vAvg) > 0.18 &&
        !obs.bumped) {
      mem.gpsFrozen = true;
    }
  }

  if (teleport) {
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  if (mem.gpsFrozen && anchorMove > 1.4) {
    mem.gpsFrozen = false;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  const gpsBad = !!mem.gpsFrozen ||
    teleport ||
    now < finite(mem.gpsBadUntil, -1);

  const headForPosition = wrap(mem.headingEst - finite(mem.headingBias, 0));
  const predX = finite(mem.posX, rawX) +
    vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = finite(mem.posY, rawY) +
    vAvg * Math.sin(headForPosition * RAD) * dt;

  if (gpsBad) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.2 ? 0.36 : 0.20;
    if (residual > 16) gain = 0.015;
    else if (residual > 7) gain = 0.07;
    if (obs.docked) gain = Math.max(gain, 0.45);
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  const straight =
    !gpsBad &&
    !teleport &&
    compassTrusted &&
    finite(mem.lastCmdV, 0) > 0.28 &&
    Math.abs(finite(mem.lastCmdOmega, 0)) < 0.24 &&
    vAvg > 0.18;

  if (straight) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(
        angleDiff(mem.headingEst, finite(mem.calHead, mem.headingEst))
      );
      if (turned > 25) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 5.0) {
        const course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        const measuredBias = angleDiff(mem.headingEst, course);
        if (finite(mem.biasCount, 0) < 1) {
          mem.headingBias = measuredBias;
        } else {
          mem.headingBias = wrap(
            mem.headingBias +
            0.18 * angleDiff(measuredBias, mem.headingBias)
          );
        }
        mem.biasCount = finite(mem.biasCount, 0) + 1;
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  if (!gpsBad && !compassTrusted && Math.abs(vAvg) > 0.3 &&
      Math.abs(finite(mem.lastCmdOmega, 0)) < 0.2) {
    const gx = rawX - finite(mem.lastRawX, rawX);
    const gy = rawY - finite(mem.lastRawY, rawY);
    if (Math.hypot(gx, gy) > 0.05) {
      const course = Math.atan2(gy, gx) / RAD;
      const expected = wrap(course + finite(mem.headingBias, 0));
      mem.headingEst = wrap(
        mem.headingEst + 0.10 * angleDiff(expected, mem.headingEst)
      );
    }
  }

  mem.posX = clamp(mem.posX, -3, mem.mapW + 3);
  mem.posY = clamp(mem.posY, -3, mem.mapH + 3);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = wrap(mem.headingEst - finite(mem.headingBias, 0));

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  const previousBattery = finite(mem.lastBattery, battery);
  if (previousBattery - battery > 0.14 && dt < 0.6) {
    mem.batteryShockUntil = now + 30;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.00145), 0.0024);
    mem.maxBattery = Math.min(finite(mem.maxBattery, battery), battery);
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  }
  mem.lastBattery = battery;

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery)) mem.maxBattery = battery;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  } else {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    if (now - finite(mem.energyT, now) >= 8) {
      const netUse = finite(mem.energyBat, battery) - battery;
      if (netUse > 0.004 && finite(mem.energyDist, 0) > 2.0) {
        const measured = clamp(netUse / mem.energyDist, 0.0003, 0.02);
        if (measured > mem.ePerM) {
          mem.ePerM = clamp(
            0.75 * mem.ePerM + 0.25 * measured,
            0.0004,
            0.02
          );
        } else {
          mem.ePerM = clamp(
            0.97 * mem.ePerM + 0.03 * measured,
            0.0004,
            0.02
          );
        }
      }
      mem.energyT = now;
      mem.energyBat = battery;
      mem.energyDist = 0;
    }
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let validRayCount = 0;
  let staleRayCount = 0;

  if (rays) {
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.005 &&
          Math.abs(vAvg) > 0.4 &&
          r < 14.8) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 3.5 && r < 14.8) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  if (science > finite(mem.bestScience, 0) + 0.015) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
    mem.bestScienceT = now;
  }

  const peakScience = finite(mem.bestScience, 0);
  const peakFell = science < peakScience - Math.max(0.035, peakScience * 0.12);
  const peakOld = now - finite(mem.bestScienceT, now) > 30;
  if (peakScience > 0.10 &&
      peakScience > finite(mem.signalSpawnedPeak, 0) + 0.04 &&
      finite(mem.signalSpawns, 0) < 4 &&
      (peakFell || peakOld)) {
    let nearTask = false;
    for (const task of mem.tasks) {
      if (task && dist(
        finite(mem.bestScienceX, posX),
        finite(mem.bestScienceY, posY),
        task.x, task.y
      ) < 19) {
        nearTask = true;
        break;
      }
    }
    if (!nearTask) {
      const t = addTask(
        clamp(finite(mem.bestScienceX, posX), 2.5, mem.mapW - 2.5),
        clamp(finite(mem.bestScienceY, posY), 2.5, mem.mapH - 2.5),
        clamp(peakScience * 11, 1, 15),
        "signal"
      );
      t.scanRadius = 11.5;
      mem.signalSpawns = finite(mem.signalSpawns, 0) + 1;
    }
    mem.signalSpawnedPeak = peakScience;
  }

  let siteValid = !!(
    obs.site &&
    Number.isFinite(obs.site.distance) &&
    Number.isFinite(obs.site.bearing) &&
    obs.site.distance >= 0 &&
    obs.site.distance <= 9
  );
  let siteDistance = siteValid ? obs.site.distance : Infinity;
  let siteBearing = siteValid ? wrap(obs.site.bearing) : 0;
  let siteX = posX;
  let siteY = posY;
  let siteTaskId = -1;

  if (siteValid) {
    const a = (headMap + siteBearing) * RAD;
    siteX = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    siteY = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);

    if (now < finite(mem.lastSampleUntil, -1) &&
        dist(siteX, siteY,
             finite(mem.lastSampleX, siteX),
             finite(mem.lastSampleY, siteY)) < 4) {
      siteValid = false;
      siteDistance = Infinity;
    }
  }

  if (siteValid) {
    let match = null;
    const active = getTask(mem.activeTaskId);
    if (active && active.status !== 2) {
      const ax = Number.isFinite(active.siteX) ? active.siteX : active.x;
      const ay = Number.isFinite(active.siteY) ? active.siteY : active.y;
      if (dist(siteX, siteY, ax, ay) < 36) match = active;
    }

    if (!match) {
      let nearest = Infinity;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const tx = Number.isFinite(task.siteX) ? task.siteX : task.x;
        const ty = Number.isFinite(task.siteY) ? task.siteY : task.y;
        const d = dist(siteX, siteY, tx, ty);
        const limit = task.actual ? 14 : 29;
        if (d < limit && d < nearest) {
          nearest = d;
          match = task;
        }
      }
    }

    if (!match) {
      match = addTask(
        siteX, siteY,
        finite(obs.site.value, 1),
        "site"
      );
    }

    if (match.status === 3) match.status = 0;
    match.actual = true;
    if (!Number.isFinite(match.siteX)) {
      match.siteX = siteX;
      match.siteY = siteY;
    } else {
      match.siteX = 0.30 * match.siteX + 0.70 * siteX;
      match.siteY = 0.30 * match.siteY + 0.70 * siteY;
    }
    if (Number.isFinite(obs.site.value) && obs.site.value > 0) {
      match.val = Math.max(match.val, obs.site.value);
    }
    match.status = 1;
    siteTaskId = match.id;
    mem.activeTaskId = match.id;
  }

  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    const sx = finite(mem.sampleSiteX, posX);
    const sy = finite(mem.sampleSiteY, posY);
    let completed = getTask(mem.sampleTaskId);

    if (!completed) {
      let nearest = 25;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const d = dist(sx, sy, task.x, task.y);
        if (d < nearest) {
          nearest = d;
          completed = task;
        }
      }
    }

    if (completed) completed.status = 2;

    let nearestHint = null;
    let nearestHintD = 24;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.id === (completed ? completed.id : -1)) {
        continue;
      }
      const d = dist(sx, sy, task.x, task.y);
      if (d < nearestHintD) {
        nearestHintD = d;
        nearestHint = task;
      }
    }
    if (nearestHint) nearestHint.status = 2;

    for (const task of mem.tasks) {
      if (task && task.status !== 2 && dist(sx, sy, task.x, task.y) < 7) {
        task.status = 2;
      }
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleUntil = now + 1.5;
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    if (completed && mem.activeTaskId === completed.id) mem.activeTaskId = -1;
  }
  mem.prevCarried = carried;

  const beacon = obs.beacon;
  const beaconValid = !!(
    beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 &&
    beacon.distance <= 20.8
  );
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function ensureScan(task, fromX, fromY) {
    if (!task || task.actual) return;
    if (task.scanStarted &&
        Array.isArray(task.scanPoints) &&
        task.scanPoints.length > 0) return;

    const radius = task.kind === "signal"
      ? finite(task.scanRadius, 11.5)
      : 18.5;
    task.scanRadius = radius;
    task.scanPoints = [];
    task.scanIdx = 0;

    task.scanStarted = true;
    task.scanPoints.push({
      x: clamp(task.x, 2.5, mem.mapW - 2.5),
      y: clamp(task.y, 2.5, mem.mapH - 2.5)
    });

    const fromAngle = Math.atan2(fromY - task.y, fromX - task.x) / RAD;
    let start = Math.round(fromAngle / 45);
    start = ((start % 8) + 8) % 8;

    for (let j = 0; j < 8; j++) {
      const angle = (start + j) * Math.PI / 4;
      const p = {
        x: clamp(task.x + radius * Math.cos(angle), 2.5, mem.mapW - 2.5),
        y: clamp(task.y + radius * Math.sin(angle), 2.5, mem.mapH - 2.5)
      };
      let duplicate = false;
      for (const q of task.scanPoints) {
        if (dist(p.x, p.y, q.x, q.y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.scanPoints.push(p);
    }
  }

  function remainingScan(task, fromX, fromY) {
    if (!task.scanStarted || !Array.isArray(task.scanPoints)) {
      return dist(fromX, fromY, task.x, task.y) +
        (task.kind === "signal" ? 75 : 122);
    }
    if (task.scanIdx >= task.scanPoints.length) return 0;
    let length = dist(
      fromX, fromY,
      task.scanPoints[task.scanIdx].x,
      task.scanPoints[task.scanIdx].y
    );
    for (let i = task.scanIdx + 1; i < task.scanPoints.length; i++) {
      length += dist(
        task.scanPoints[i - 1].x,
        task.scanPoints[i - 1].y,
        task.scanPoints[i].x,
        task.scanPoints[i].y
      );
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    let out;
    let back;
    if (task.actual && Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      out = dist(fromX, fromY, task.siteX, task.siteY);
      back = dist(task.siteX, task.siteY, mem.baseX, mem.baseY);
    } else {
      out = remainingScan(task, fromX, fromY);
      const radius = task.scanStarted
        ? finite(task.scanRadius, task.kind === "signal" ? 11.5 : 18.5)
        : (task.kind === "signal" ? 11.5 : 18.5);
      back = dist(task.x, task.y, mem.baseX, mem.baseY) + radius;
    }

    const load = 1 + 0.16 * carried;
    const energy =
      0.11 +
      finite(mem.ePerM, 0.00145) * 1.50 * (out + back) * load +
      0.025 * (carried + 1);
    const timeNeed = (out + back) / 0.62 + 22;
    return { out: out, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    const available = atDock
      ? Math.max(battery, finite(mem.maxBattery, battery))
      : battery;

    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now) continue;

      if (!task.actual) ensureScan(task, fromX, fromY);
      const m = taskMetrics(task, fromX, fromY);
      if (m.energy > available - 0.035) continue;
      if (m.timeNeed + 12 > timeLeft) continue;

      let value = clamp(finite(task.val, 1), 0.3, 100);
      if (task.kind === "signal") value *= 0.95;
      if (task.actual) value *= 1.16;

      let score = value / (30 + m.out + 0.72 * m.back);
      if (task.id === mem.activeTaskId) score *= 1.18;
      if (task.status === 1) score *= 1.05;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) < 3.5) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1.0) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function motorPower(target, current, side) {
    const ikey = side === 0 ? "integralL" : "integralR";
    const tkey = side === 0 ? "oldTargetL" : "oldTargetR";
    let integral = finite(mem[ikey], 0);
    const oldTarget = finite(mem[tkey], target);

    if (target * oldTarget < -0.05) integral *= 0.25;
    mem[tkey] = target;

    if (Math.abs(target) < 0.035) {
      integral *= 0.65;
      mem[ikey] = integral;
      return clamp(-0.82 * current + integral, -1, 1);
    }

    const error = target - current;
    integral = clamp(integral + 0.10 * error * dt, -0.30, 0.30);
    mem[ikey] = integral;

    let u = 0.25 * target +
      0.12 * Math.sign(target) +
      0.42 * error +
      integral;
    if (Math.abs(target) > 0.12 && Math.abs(u) < 0.12) {
      u = Math.sign(target) * 0.12;
    }
    return clamp(u, -1, 1);
  }

  function slopeAssist() {
    const pitch = finite(obs.pitch, 0) * RAD;
    return clamp(0.16 * Math.sin(pitch), -0.14, 0.14);
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const targetR = clamp(v + omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const slope = slopeAssist();
    mem.lastCmdV = v;
    mem.lastCmdOmega = omega;
    return {
      left: clamp(motorPower(targetL, wl, 0) + slope, -1, 1),
      right: clamp(motorPower(targetR, wr, 1) + slope, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const correction = clamp(0.035 * along, -0.06, 0.06);
    const slope = slopeAssist();
    const left = clamp(-0.82 * wl + slope + correction, -0.45, 0.45);
    const right = clamp(-0.82 * wr + slope + correction, -0.45, 0.45);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;

    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;
    mem.integralL = finite(mem.integralL, 0) * 0.8;
    mem.integralR = finite(mem.integralR, 0) * 0.8;

    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navDrive(goalRel, targetDistance, key, baseSpeed,
                    worldX, worldY, stopRadius) {
    goalRel = wrap(goalRel);
    targetDistance = Math.max(0, finite(targetDistance, 0));
    stopRadius = Math.max(0, finite(stopRadius, 2.4));
    const navKey = String(key || "nav");

    if (mem.navKey !== navKey) {
      mem.navKey = navKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
      mem.stuckCount = 0;
      mem.navBlockedKey = "";
    } else if (now - finite(mem.progressT, now) >= 10) {
      const distanceImprovement =
        finite(mem.progressD, targetDistance) - targetDistance;
      const angleImprovement =
        finite(mem.progressA, Math.abs(goalRel)) - Math.abs(goalRel);
      const trying =
        Math.abs(finite(mem.lastCmdV, 0)) > 0.20 ||
        Math.abs(finite(mem.lastCmdOmega, 0)) > 0.30;

      if (targetDistance > stopRadius + 3 &&
          distanceImprovement < 0.65 &&
          angleImprovement < 8 &&
          trying) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.75;
        if (mem.stuckCount >= 3 &&
            (navKey.indexOf("scan:") === 0 ||
             navKey.indexOf("explore:") === 0)) {
          mem.navBlockedKey = navKey;
        }
      } else if (distanceImprovement > 0.9 || angleImprovement > 12) {
        mem.stuckCount = 0;
      }

      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.23, finite(mem.escapeSign, 1) * 0.85);
    }

    if (targetDistance <= stopRadius) return driveWheels(0, 0);

    if (Math.abs(goalRel) > 115) {
      return driveWheels(0, Math.sign(goalRel) * 0.95);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 32, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < Math.min(9, rays.length); i++) {
          const range = finite(rays[i], NaN);
          if (!Number.isFinite(range) ||
              range < 0 ||
              range >= 14.8 ||
              finite(mem.rayStale[i], 0) > 3.5) continue;

          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const d = Math.max(0.15, range);
          const along = d * Math.cos(rel);
          const cross = Math.abs(d * Math.sin(rel));

          if (along > 0 && along < 5.5) {
            const safeWidth = 0.78 + 0.07 * along;
            if (cross < safeWidth) {
              const severity = (safeWidth - cross) / safeWidth;
              const weight = along < 1.25 ? 38 :
                (along < 2.5 ? 23 : 11);
              cost += weight * severity * severity;
              if (along < 0.9) cost += 12 * severity;
              clear = Math.min(clear, along);
            }
          }
        }
      }

      if (Number.isFinite(worldX) && Number.isFinite(worldY)) {
        const worldA = (headMap + alpha) * RAD;
        const edgeX = posX + 3.0 * Math.cos(worldA);
        const edgeY = posY + 3.0 * Math.sin(worldA);
        if (edgeX < 2 || edgeX > mem.mapW - 2) cost += 16;
        if (edgeY < 2 || edgeY > mem.mapH - 2) cost += 16;
      }

      cost += 0.002 * Math.abs(alpha - finite(mem.lastAvoidAlpha, alpha));
      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(finite(baseSpeed, 0.70), 0.12, 0.82);
    if (targetDistance < 7) {
      speed = Math.min(speed, 0.18 + 0.11 * targetDistance);
    }
    if (Math.abs(bestAlpha) > 55) speed = 0;
    else if (Math.abs(bestAlpha) > 38) speed = Math.min(speed, 0.32);

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.0) speed = Math.min(speed, 0.10);
      else if (bestClear < 1.5) speed = Math.min(speed, 0.18);
      else if (bestClear < 2.3) speed = Math.min(speed, 0.30);
      else if (bestClear < 3.4) speed = Math.min(speed, 0.48);
      else if (bestClear < 4.4) speed = Math.min(speed, 0.64);
    }
    if (raysBlind) speed = Math.min(speed, 0.58);

    const alphaRad = bestAlpha * RAD;
    const v = Math.abs(bestAlpha) > 55
      ? 0
      : speed * Math.max(0, Math.cos(alphaRad));
    const omega = clamp(2.0 * alphaRad, -1.15, 1.15);
    return driveWheels(v, omega);
  }

  function navToWorld(gx, gy, key, speed, stopRadius) {
    const dx = gx - posX;
    const dy = gy - posY;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / RAD : headMap;
    return navDrive(
      wrap(bearing - headMap),
      d,
      key,
      speed,
      gx,
      gy,
      stopRadius
    );
  }

  function navRelative(rel, d, key, speed, stopRadius) {
    return navDrive(rel, d, key, speed, NaN, NaN, stopRadius);
  }

  function beginSample(taskId, sx, sy, initialDistance) {
    if (carried >= mem.capacity) return false;
    mem.sampleActive = true;
    mem.sampleTaskId = Number.isFinite(taskId) ? taskId : -1;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleSiteX = finite(sx, posX);
    mem.sampleSiteY = finite(sy, posY);
    mem.sampleInitialDistance = clamp(finite(initialDistance, 1.2), 0, 1.5);
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    mem.sampleLastT = now;
    mem.sampleMove = 0;

    const task = getTask(mem.sampleTaskId);
    if (task && task.status !== 2) task.status = 1;
    return true;
  }

  function sampleCommand(currentSiteDistance) {
    if (!mem.sampleActive) return driveWheels(0, 0);

    if (now > finite(mem.sampleLastT, now)) {
      mem.sampleMove = finite(mem.sampleMove, 0) + Math.abs(vAvg) * dt;
      mem.sampleLastT = now;
    }

    const drilling = Math.max(0, finite(obs.drilling, 0));
    const elapsed = now - finite(mem.sampleStart, now);

    if (carried > finite(mem.sampleCarryStart, carried)) {
      return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, false, false);
    }

    if ((elapsed > 20 && drilling < 5.8) || elapsed > 26 ||
        (mem.sampleMove > 1.8 && drilling < 0.2)) {
      const task = getTask(mem.sampleTaskId);
      if (task) {
        task.sampleFailures = finite(task.sampleFailures, 0) + 1;
        task.retryAfter = now + (task.sampleFailures >= 3 ? 18 : 5);
      }
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      mem.sampleRetryUntil = now + 5;
      return driveWheels(0, 0);
    }

    let close = finite(mem.sampleInitialDistance, 1.5) <= 1.45;
    if (Number.isFinite(currentSiteDistance)) {
      close = currentSiteDistance <= 1.5;
    }
    if (mem.sampleMove > 1.0 && drilling < 0.2) close = false;

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual &&
        Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      const d = dist(posX, posY, task.siteX, task.siteY);
      if (d < 1.0 &&
          carried < mem.capacity &&
          now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(task.id, task.siteX, task.siteY, d)) {
          return sampleCommand(Infinity);
        }
      }
      return navToWorld(
        task.siteX, task.siteY,
        "actual:" + task.id,
        d < 5 ? 0.42 : 0.58,
        0.65
      );
    }

    ensureScan(task, posX, posY);
    let guard = 0;
    while (task.scanIdx < task.scanPoints.length && guard++ < 12) {
      const p = task.scanPoints[task.scanIdx];
      if (dist(posX, posY, p.x, p.y) > 2.7) break;
      task.scanIdx++;
    }

    if (task.scanIdx >= task.scanPoints.length) {
      task.status = 3;
      if (mem.activeTaskId === task.id) mem.activeTaskId = -1;
      return null;
    }

    const p = task.scanPoints[task.scanIdx];
    const key = "scan:" + task.id + ":" + task.scanIdx;
    const cmd = navToWorld(p.x, p.y, key, 0.72, 2.4);

    if (mem.navBlockedKey === key) {
      task.scanIdx++;
      mem.navBlockedKey = "";
      mem.navKey = "";
      mem.stuckCount = 0;
      return driveWheels(0, 0);
    }
    return cmd;
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    mem.baseWaitSince = -1;
    if (mem.sampleActive) {
      const task = getTask(mem.sampleTaskId);
      if (task && task.status !== 2) task.status = 1;
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
    }
  }

  function returnCommand() {
    if (obs.docked) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (beaconValid) {
      const d = beacon.distance;
      if (d <= 2.7) {
        if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
        if (d < 0.75 || now - mem.baseWaitSince < 2.5) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        return navRelative(beacon.bearing, d, "return", 0.22, 0.65);
      }
      mem.baseWaitSince = -1;
      return navRelative(beacon.bearing, d, "return", 0.72, 2.7);
    }

    if (baseGpsDist <= 2.7) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (baseGpsDist < 0.75 || now - mem.baseWaitSince < 2.5) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      return navToWorld(
        mem.baseX, mem.baseY, "return", 0.22, 0.65
      );
    }
    mem.baseWaitSince = -1;
    return navToWorld(mem.baseX, mem.baseY, "return", 0.72, 2.7);
  }

  function fallbackPoint() {
    if (timeLeft < 180) {
      const idx = Math.max(0, Math.floor(finite(mem.endgameIdx, 0)));
      if (!mem.endgameTarget || mem.endgameTargetIdx !== idx) {
        const radius = clamp((timeLeft - 32) / 3.0, 5, 19);
        const angle = (((idx % 8) * 45) + 22.5) * RAD;
        mem.endgameTarget = {
          x: clamp(mem.baseX + radius * Math.cos(angle), 3, mem.mapW - 3),
          y: clamp(mem.baseY + radius * Math.sin(angle), 3, mem.mapH - 3)
        };
        mem.endgameTargetIdx = idx;
      }
      return mem.endgameTarget;
    }

    const pts = mem.explorePoints;
    if (!Array.isArray(pts) || !pts.length) {
      return {
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      };
    }
    let guard = 0;
    while (guard++ < pts.length) {
      const idx = ((mem.exploreIdx % pts.length) + pts.length) % pts.length;
      const p = pts[idx];
      if (dist(posX, posY, p.x, p.y) > 3.5) return p;
      mem.exploreIdx = (idx + 1) % pts.length;
    }
    return pts[mem.exploreIdx % pts.length];
  }

  function fallbackMetrics(p, fromX, fromY) {
    const out = dist(fromX, fromY, p.x, p.y);
    const back = dist(p.x, p.y, mem.baseX, mem.baseY);
    const energy =
      0.10 +
      finite(mem.ePerM, 0.00145) * 1.45 * (out + back) *
        (1 + 0.16 * carried) +
      0.015;
    const timeNeed = (out + back) / 0.65 + 18;
    return { energy: energy, timeNeed: timeNeed };
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped && !mem.sampleActive) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 0.75;
  }
  mem.prevBumped = bumped;

  if (mem.departing && !obs.docked && baseDist > 4) {
    mem.departing = false;
  }

  if (obs.docked && mem.returning) {
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;
    mem.escapeUntil = -1;
  }

  if (mem.returning) return returnCommand();

  if (mem.sampleActive) {
    if (battery < 0.035 && carried > 0) {
      requestReturn();
      return returnCommand();
    }
    return sampleCommand(siteValid ? siteDistance : Infinity);
  }

  const returnReserve =
    0.11 +
    finite(mem.ePerM, 0.00145) *
      1.85 * baseDist * (1 + 0.18 * carried) +
    0.022 * carried;
  const returnTime = 24 + baseDist / 0.48;

  if (!obs.docked) {
    const mustReturn =
      carried >= mem.capacity ||
      battery < returnReserve + 0.075 ||
      battery < 0.065 ||
      timeLeft < returnTime +
        (carried > 0 ? 12 : (timeLeft < 180 ? 8 : 70)) ||
      (now < finite(mem.batteryShockUntil, -1) && carried > 0);

    if (mustReturn) {
      requestReturn();
      return returnCommand();
    }
  }

  if (siteValid && carried < mem.capacity) {
    if (obs.docked && battery < 0.18) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (siteDistance <= 1.35) {
      if (now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(
          siteTaskId,
          siteX,
          siteY,
          siteDistance
        )) {
          return sampleCommand(siteDistance);
        }
      } else {
        return holdAt(posX, posY, false, false);
      }
    }

    if (obs.docked) mem.departing = true;
    const speed = siteDistance < 4
      ? clamp(0.14 + 0.17 * (siteDistance - 1.0), 0.16, 0.62)
      : 0.70;
    return navRelative(
      siteBearing,
      siteDistance,
      "site:" + siteTaskId,
      speed,
      0.65
    );
  }

  if (obs.docked && !mem.departing) {
    if (carried > 0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      if (task.status === 1 && task.status !== 2) task.status = 0;
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, true);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task && !task.actual) ensureScan(task, posX, posY);

    if (task) {
      const m = taskMetrics(task, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (m.energy <= maxBat - 0.025 &&
          m.timeNeed + 10 <= timeLeft) {
        const chargeGoal = Math.min(maxBat, m.energy + 0.035);
        if (battery + 0.012 < chargeGoal) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        mem.activeTaskId = task.id;
        task.status = 1;
        mem.departing = true;
      } else {
        if (task.status === 1) task.status = 0;
        mem.activeTaskId = -1;
        task = null;
      }
    }

    if (!task) {
      const p = fallbackPoint();
      const fm = fallbackMetrics(p, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (fm.energy > maxBat - 0.025 ||
          fm.timeNeed + 10 > timeLeft) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      const chargeGoal = Math.min(maxBat, fm.energy + 0.03);
      if (battery + 0.012 < chargeGoal) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      mem.departing = true;
    }
  }

  for (let tries = 0; tries < 5; tries++) {
    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, false);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task) {
      if (!task.actual) ensureScan(task, posX, posY);
      const m = taskMetrics(task, posX, posY);

      if (m.energy > battery - 0.04 ||
          m.timeNeed + (carried > 0 ? 12 : 25) > timeLeft) {
        requestReturn();
        return returnCommand();
      }

      const cmd = controlTask(task);
      if (cmd) return cmd;
      if (task.status === 3) {
        mem.activeTaskId = -1;
        continue;
      }
    }
    break;
  }

  const p = fallbackPoint();
  const fm = fallbackMetrics(p, posX, posY);
  if (!obs.docked &&
      (fm.energy > battery - 0.04 ||
       fm.timeNeed + (timeLeft < 180 ? 12 : 35) > timeLeft)) {
    requestReturn();
    return returnCommand();
  }

  if (obs.docked && !mem.departing) {
    const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
    if (fm.energy > maxBat - 0.025 ||
        fm.timeNeed + 10 > timeLeft) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if (battery + 0.012 < Math.min(maxBat, fm.energy + 0.03)) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    mem.departing = true;
  }

  const dExplore = dist(posX, posY, p.x, p.y);
  if (dExplore <= 2.6) {
    if (timeLeft < 180) {
      mem.endgameIdx = Math.floor(finite(mem.endgameIdx, 0)) + 1;
      mem.endgameTarget = null;
      mem.endgameTargetIdx = -1;
    } else {
      mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    }
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  const exploreKey = timeLeft < 180
    ? "endgame:" + mem.endgameIdx
    : "explore:" + mem.exploreIdx;
  const exploreCmd = navToWorld(
    p.x, p.y, exploreKey, 0.68, 2.4
  );

  if (mem.navBlockedKey === exploreKey) {
    if (timeLeft < 180) {
      mem.endgameIdx = Math.floor(finite(mem.endgameIdx, 0)) + 1;
      mem.endgameTarget = null;
      mem.endgameTargetIdx = -1;
    } else {
      mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    }
    mem.navBlockedKey = "";
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  return exploreCmd;
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = (v, d) => Number.isFinite(v) ? v : d;
  const wrap = (a) => {
    if (!Number.isFinite(a)) return 0;
    return ((a + 180) % 360 + 360) % 360 - 180;
  };
  const angleDiff = (a, b) => wrap(a - b);
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const RAD = Math.PI / 180;
  const WHEEL_BASE = 0.6;

  const now = Math.max(0, finite(obs.t, 0));
  const rawX = finite(obs.x, 0);
  const rawY = finite(obs.y, 0);
  const rawHeading = wrap(finite(obs.heading, 0));
  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const vAvg = (wl + wr) * 0.5;
  const battery = Math.max(0, finite(obs.battery, 0));
  const carried = Math.max(0, finite(obs.carried, 0));
  const timeLeft = Math.max(0, finite(obs.timeLeft, 1200 - now));
  const science = Math.max(0, finite(obs.science, 0));

  function addTask(x, y, value, kind) {
    if (!Array.isArray(mem.tasks)) mem.tasks = [];
    if (!Number.isFinite(mem.nextId)) mem.nextId = 1;
    const task = {
      id: mem.nextId++,
      x: x,
      y: y,
      val: Math.max(0.2, finite(value, 1)),
      kind: kind || "hint",
      status: 0,
      actual: false,
      siteX: null,
      siteY: null,
      scanStarted: false,
      scanPoints: [],
      scanIdx: 0,
      scanRadius: 0,
      retryAfter: 0,
      sampleFailures: 0
    };
    mem.tasks.push(task);
    return task;
  }

  if (!mem.initialized) {
    mem.tasks = [];
    mem.nextId = 1;
    mem.activeTaskId = -1;
    mem.sampleTaskId = -1;
    mem.sampleActive = false;
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;

    mem.headingEst = rawHeading;
    mem.headingBias = 0;
    mem.biasCount = 0;
    mem.compassBadUntil = -1;
    mem.compassStall = 0;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
    mem.gpsBadUntil = -1;

    mem.ePerM = 0.00145;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
    mem.lastBattery = battery;
    mem.batteryShockUntil = -1;
    mem.maxBattery = battery;

    mem.rayLast = [];
    mem.rayStale = [];
    mem.prevBumped = false;
    mem.escapeUntil = -1;
    mem.escapeSign = 1;
    mem.escapeCount = 0;
    mem.navKey = "";
    mem.navBlockedKey = "";
    mem.progressT = now;
    mem.progressD = 0;
    mem.progressA = 0;
    mem.stuckCount = 0;
    mem.lastAvoidAlpha = 0;
    mem.integralL = 0;
    mem.integralR = 0;
    mem.oldTargetL = 0;
    mem.oldTargetR = 0;
    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;

    mem.prevCarried = carried;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    mem.sampleRetryUntil = -1;
    mem.lastSampleUntil = -1;
    mem.lastSampleX = rawX;
    mem.lastSampleY = rawY;

    mem.bestScience = 0;
    mem.bestScienceX = rawX;
    mem.bestScienceY = rawY;
    mem.bestScienceT = now;
    mem.signalSpawns = 0;
    mem.signalSpawnedPeak = 0;

    mem.exploreIdx = 0;

    const mission = obs.mission || {};
    const base = mission.base || {};
    mem.baseX = finite(base.x, rawX);
    mem.baseY = finite(base.y, rawY);

    const size = mission.size;
    if (size && typeof size === "object") {
      mem.mapW = finite(size.width, finite(size.x, 400));
      mem.mapH = finite(size.height, finite(size.y, mem.mapW));
    } else {
      mem.mapW = finite(size, 400);
      mem.mapH = finite(size, 400);
    }
    mem.mapW = Math.max(20, mem.mapW);
    mem.mapH = Math.max(20, mem.mapH);
    mem.capacity = Math.max(1, finite(mission.capacity, 5));

    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length && i < 300; i++) {
      const h = hints[i] || {};
      const x = finite(h.x, NaN);
      const y = finite(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      const hx = clamp(x, 2.5, mem.mapW - 2.5);
      const hy = clamp(y, 2.5, mem.mapH - 2.5);
      const val = finite(h.estimate, 1);

      let duplicate = null;
      for (const task of mem.tasks) {
        if (dist(hx, hy, task.x, task.y) < 9) {
          duplicate = task;
          break;
        }
      }
      if (duplicate) {
        duplicate.val = Math.max(duplicate.val, val);
      } else {
        addTask(hx, hy, val, "hint");
      }
    }

    mem.explorePoints = [];
    for (let radius = 18; radius <= 180; radius += 18) {
      for (let j = 0; j < 8; j++) {
        const a = j * Math.PI / 4;
        const p = {
          x: clamp(mem.baseX + radius * Math.cos(a), 3, mem.mapW - 3),
          y: clamp(mem.baseY + radius * Math.sin(a), 3, mem.mapH - 3)
        };
        let duplicate = false;
        for (const q of mem.explorePoints) {
          if (dist(p.x, p.y, q.x, q.y) < 5) {
            duplicate = true;
            break;
          }
        }
        if (!duplicate) mem.explorePoints.push(p);
      }
    }
    if (!mem.explorePoints.length) {
      mem.explorePoints.push({
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      });
    }

    mem.lastT = now;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.lastRawHeading = rawHeading;
    mem.calActive = false;
    mem.initialized = true;
  }

  if (!Array.isArray(mem.tasks)) mem.tasks = [];
  if (!Array.isArray(mem.explorePoints) || !mem.explorePoints.length) {
    mem.explorePoints = [{
      x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
      y: clamp(mem.baseY, 3, mem.mapH - 3)
    }];
  }
  if (!Number.isFinite(mem.activeTaskId)) mem.activeTaskId = -1;
  if (!Number.isFinite(mem.posX)) mem.posX = rawX;
  if (!Number.isFinite(mem.posY)) mem.posY = rawY;
  if (!Number.isFinite(mem.headingEst)) mem.headingEst = rawHeading;
  if (!Number.isFinite(mem.headingBias)) mem.headingBias = 0;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.00145;
  if (!Number.isFinite(mem.maxBattery)) mem.maxBattery = battery;

  let dtRaw = now - finite(mem.lastT, now);
  let dt = dtRaw > 0 ? clamp(dtRaw, 0.025, 0.25) : 0.1;

  const rawHeadingDelta = angleDiff(
    rawHeading,
    finite(mem.lastRawHeading, rawHeading)
  );
  const wheelYawDeg = (wr - wl) / WHEEL_BASE * dt / RAD;
  const predictedHeading = wrap(finite(mem.headingEst, rawHeading) + wheelYawDeg);
  const yawMismatch = Math.abs(angleDiff(rawHeadingDelta, wheelYawDeg));

  const compassJump =
    (Math.abs(rawHeadingDelta) > 48 && yawMismatch > 36) ||
    (Math.abs(rawHeadingDelta) > 125 && Math.abs(wheelYawDeg) < 48);

  if (compassJump) {
    mem.compassBadUntil = now + 1.4;
    mem.compassStall = 0;
  }

  if (Math.abs(rawHeadingDelta) < 0.025 && Math.abs(wheelYawDeg) > 1.4) {
    mem.compassStall = finite(mem.compassStall, 0) + dt;
  } else {
    mem.compassStall = Math.max(0, finite(mem.compassStall, 0) - 1.2 * dt);
  }

  let compassTrusted =
    now >= finite(mem.compassBadUntil, -1) &&
    finite(mem.compassStall, 0) < 0.9 &&
    !compassJump;

  if (compassTrusted) {
    const err = angleDiff(rawHeading, predictedHeading);
    if (Math.abs(err) < 80) {
      mem.headingEst = wrap(
        predictedHeading + clamp(0.16 * err, -6, 6)
      );
    } else {
      mem.headingEst = predictedHeading;
      mem.compassBadUntil = now + 1.0;
      compassTrusted = false;
    }
  } else {
    mem.headingEst = predictedHeading;
  }

  const rawMove = dist(
    rawX, rawY,
    finite(mem.lastRawX, rawX),
    finite(mem.lastRawY, rawY)
  );
  const odom = Math.abs(vAvg) * dt;
  const teleport = rawMove > Math.max(18, odom * 15 + 8);

  let anchorMove = dist(
    rawX, rawY,
    finite(mem.gpsAnchorX, rawX),
    finite(mem.gpsAnchorY, rawY)
  );

  if (anchorMove > 0.9) {
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
    mem.gpsFrozen = false;
  } else {
    mem.gpsOdom = finite(mem.gpsOdom, 0) + odom;
    if (now - finite(mem.gpsAnchorT, now) > 3.2 &&
        mem.gpsOdom > 2.5 &&
        Math.abs(vAvg) > 0.18 &&
        !obs.bumped) {
      mem.gpsFrozen = true;
    }
  }

  if (teleport) {
    mem.gpsBadUntil = now + 2.0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  if (mem.gpsFrozen && anchorMove > 1.4) {
    mem.gpsFrozen = false;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsAnchorT = now;
    mem.gpsOdom = 0;
  }

  const gpsBad = !!mem.gpsFrozen ||
    teleport ||
    now < finite(mem.gpsBadUntil, -1);

  const headForPosition = wrap(mem.headingEst - finite(mem.headingBias, 0));
  const predX = finite(mem.posX, rawX) +
    vAvg * Math.cos(headForPosition * RAD) * dt;
  const predY = finite(mem.posY, rawY) +
    vAvg * Math.sin(headForPosition * RAD) * dt;

  if (gpsBad) {
    mem.posX = predX;
    mem.posY = predY;
  } else {
    const residual = dist(rawX, rawY, predX, predY);
    let gain = Math.abs(vAvg) > 0.2 ? 0.36 : 0.20;
    if (residual > 16) gain = 0.015;
    else if (residual > 7) gain = 0.07;
    if (obs.docked) gain = Math.max(gain, 0.45);
    mem.posX = predX + gain * (rawX - predX);
    mem.posY = predY + gain * (rawY - predY);
  }

  const straight =
    !gpsBad &&
    !teleport &&
    compassTrusted &&
    finite(mem.lastCmdV, 0) > 0.28 &&
    Math.abs(finite(mem.lastCmdOmega, 0)) < 0.24 &&
    vAvg > 0.18;

  if (straight) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calHead = mem.headingEst;
    } else {
      const moved = dist(rawX, rawY, mem.calX, mem.calY);
      const turned = Math.abs(
        angleDiff(mem.headingEst, finite(mem.calHead, mem.headingEst))
      );
      if (turned > 25) {
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      } else if (moved > 5.0) {
        const course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        const measuredBias = angleDiff(mem.headingEst, course);
        if (finite(mem.biasCount, 0) < 1) {
          mem.headingBias = measuredBias;
        } else {
          mem.headingBias = wrap(
            mem.headingBias +
            0.18 * angleDiff(measuredBias, mem.headingBias)
          );
        }
        mem.biasCount = finite(mem.biasCount, 0) + 1;
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calHead = mem.headingEst;
      }
    }
  } else {
    mem.calActive = false;
  }

  if (!gpsBad && !compassTrusted && Math.abs(vAvg) > 0.3 &&
      Math.abs(finite(mem.lastCmdOmega, 0)) < 0.2) {
    const gx = rawX - finite(mem.lastRawX, rawX);
    const gy = rawY - finite(mem.lastRawY, rawY);
    if (Math.hypot(gx, gy) > 0.05) {
      const course = Math.atan2(gy, gx) / RAD;
      const expected = wrap(course + finite(mem.headingBias, 0));
      mem.headingEst = wrap(mem.headingEst + 0.10 * angleDiff(expected, mem.headingEst));
    }
  }

  mem.posX = clamp(mem.posX, -3, mem.mapW + 3);
  mem.posY = clamp(mem.posY, -3, mem.mapH + 3);
  const posX = mem.posX;
  const posY = mem.posY;
  const headMap = wrap(mem.headingEst - finite(mem.headingBias, 0));

  mem.lastT = now;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawHeading = rawHeading;

  const previousBattery = finite(mem.lastBattery, battery);
  if (previousBattery - battery > 0.14 && dt < 0.6) {
    mem.batteryShockUntil = now + 30;
    mem.ePerM = Math.max(finite(mem.ePerM, 0.00145), 0.0024);
    mem.maxBattery = Math.min(finite(mem.maxBattery, battery), battery);
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  }
  mem.lastBattery = battery;

  if (obs.docked) {
    if (battery > finite(mem.maxBattery, battery)) mem.maxBattery = battery;
    mem.energyT = now;
    mem.energyBat = battery;
    mem.energyDist = 0;
  } else {
    mem.energyDist = finite(mem.energyDist, 0) + Math.abs(vAvg) * dt;
    if (now - finite(mem.energyT, now) >= 8) {
      const netUse = finite(mem.energyBat, battery) - battery;
      if (netUse > 0.004 && finite(mem.energyDist, 0) > 2.0) {
        const measured = clamp(netUse / mem.energyDist, 0.0003, 0.02);
        if (measured > mem.ePerM) {
          mem.ePerM = clamp(0.75 * mem.ePerM + 0.25 * measured, 0.0004, 0.02);
        } else {
          mem.ePerM = clamp(0.97 * mem.ePerM + 0.03 * measured, 0.0004, 0.02);
        }
      }
      mem.energyT = now;
      mem.energyBat = battery;
      mem.energyDist = 0;
    }
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : null;
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [];
  let validRayCount = 0;
  let staleRayCount = 0;

  if (rays) {
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const r = finite(rays[i], NaN);
      const old = finite(mem.rayLast[i], NaN);
      if (Number.isFinite(r)) validRayCount++;
      if (Number.isFinite(r) && Number.isFinite(old) &&
          Math.abs(r - old) < 0.005 &&
          Math.abs(vAvg) > 0.4 &&
          r < 14.8) {
        mem.rayStale[i] = finite(mem.rayStale[i], 0) + dt;
      } else {
        mem.rayStale[i] = 0;
      }
      mem.rayLast[i] = r;
      if (finite(mem.rayStale[i], 0) > 3.5 && r < 14.8) staleRayCount++;
    }
  }
  const raysBlind = !rays || validRayCount < 5 || staleRayCount >= 6;

  function getTask(id) {
    if (!Number.isFinite(id) || id < 0) return null;
    for (const task of mem.tasks) {
      if (task && task.id === id) return task;
    }
    return null;
  }

  if (science > finite(mem.bestScience, 0) + 0.015) {
    mem.bestScience = science;
    mem.bestScienceX = posX;
    mem.bestScienceY = posY;
    mem.bestScienceT = now;
  }

  const peakScience = finite(mem.bestScience, 0);
  const peakFell = science < peakScience - Math.max(0.035, peakScience * 0.12);
  const peakOld = now - finite(mem.bestScienceT, now) > 30;
  if (peakScience > 0.10 &&
      peakScience > finite(mem.signalSpawnedPeak, 0) + 0.04 &&
      finite(mem.signalSpawns, 0) < 4 &&
      (peakFell || peakOld)) {
    let nearTask = false;
    for (const task of mem.tasks) {
      if (task && dist(
        finite(mem.bestScienceX, posX),
        finite(mem.bestScienceY, posY),
        task.x, task.y
      ) < 19) {
        nearTask = true;
        break;
      }
    }
    if (!nearTask) {
      const t = addTask(
        clamp(finite(mem.bestScienceX, posX), 2.5, mem.mapW - 2.5),
        clamp(finite(mem.bestScienceY, posY), 2.5, mem.mapH - 2.5),
        clamp(peakScience * 11, 1, 15),
        "signal"
      );
      t.scanRadius = 11.5;
      mem.signalSpawns = finite(mem.signalSpawns, 0) + 1;
    }
    mem.signalSpawnedPeak = peakScience;
  }

  let siteValid = !!(
    obs.site &&
    Number.isFinite(obs.site.distance) &&
    Number.isFinite(obs.site.bearing) &&
    obs.site.distance >= 0 &&
    obs.site.distance <= 9
  );
  let siteDistance = siteValid ? obs.site.distance : Infinity;
  let siteBearing = siteValid ? wrap(obs.site.bearing) : 0;
  let siteX = posX;
  let siteY = posY;
  let siteTaskId = -1;

  if (siteValid) {
    const a = (headMap + siteBearing) * RAD;
    siteX = clamp(posX + siteDistance * Math.cos(a), 0, mem.mapW);
    siteY = clamp(posY + siteDistance * Math.sin(a), 0, mem.mapH);

    if (now < finite(mem.lastSampleUntil, -1) &&
        dist(siteX, siteY,
             finite(mem.lastSampleX, siteX),
             finite(mem.lastSampleY, siteY)) < 4) {
      siteValid = false;
      siteDistance = Infinity;
    }
  }

  if (siteValid) {
    let match = null;
    const active = getTask(mem.activeTaskId);
    if (active && active.status !== 2) {
      const ax = Number.isFinite(active.siteX) ? active.siteX : active.x;
      const ay = Number.isFinite(active.siteY) ? active.siteY : active.y;
      if (dist(siteX, siteY, ax, ay) < 36) match = active;
    }

    if (!match) {
      let nearest = Infinity;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const tx = Number.isFinite(task.siteX) ? task.siteX : task.x;
        const ty = Number.isFinite(task.siteY) ? task.siteY : task.y;
        const d = dist(siteX, siteY, tx, ty);
        const limit = task.actual ? 14 : 29;
        if (d < limit && d < nearest) {
          nearest = d;
          match = task;
        }
      }
    }

    if (!match) {
      match = addTask(
        siteX, siteY,
        finite(obs.site.value, 1),
        "site"
      );
    }

    if (match.status === 3) match.status = 0;
    match.actual = true;
    if (!Number.isFinite(match.siteX)) {
      match.siteX = siteX;
      match.siteY = siteY;
    } else {
      match.siteX = 0.30 * match.siteX + 0.70 * siteX;
      match.siteY = 0.30 * match.siteY + 0.70 * siteY;
    }
    if (Number.isFinite(obs.site.value) && obs.site.value > 0) {
      match.val = Math.max(match.val, obs.site.value);
    }
    match.status = 1;
    siteTaskId = match.id;
    mem.activeTaskId = match.id;
  }

  const oldCarried = finite(mem.prevCarried, carried);
  if (carried > oldCarried) {
    const sx = finite(mem.sampleSiteX, posX);
    const sy = finite(mem.sampleSiteY, posY);
    let completed = getTask(mem.sampleTaskId);

    if (!completed) {
      let nearest = 25;
      for (const task of mem.tasks) {
        if (!task || task.status === 2) continue;
        const d = dist(sx, sy, task.x, task.y);
        if (d < nearest) {
          nearest = d;
          completed = task;
        }
      }
    }

    if (completed) completed.status = 2;

    let nearestHint = null;
    let nearestHintD = 24;
    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.id === (completed ? completed.id : -1)) {
        continue;
      }
      const d = dist(sx, sy, task.x, task.y);
      if (d < nearestHintD) {
        nearestHintD = d;
        nearestHint = task;
      }
    }
    if (nearestHint) nearestHint.status = 2;

    for (const task of mem.tasks) {
      if (task && task.status !== 2 && dist(sx, sy, task.x, task.y) < 7) {
        task.status = 2;
      }
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleUntil = now + 1.5;
    mem.sampleActive = false;
    mem.sampleTaskId = -1;
    mem.sampleStart = -1;
    mem.sampleMove = 0;
    if (completed && mem.activeTaskId === completed.id) mem.activeTaskId = -1;
  }
  mem.prevCarried = carried;

  const beacon = obs.beacon;
  const beaconValid = !!(
    beacon &&
    Number.isFinite(beacon.distance) &&
    Number.isFinite(beacon.bearing) &&
    beacon.distance >= 0 &&
    beacon.distance <= 20.8
  );
  const baseGpsDist = dist(posX, posY, mem.baseX, mem.baseY);
  const baseDist = beaconValid ? beacon.distance : baseGpsDist;

  function ensureScan(task, fromX, fromY) {
    if (!task || task.actual) return;
    if (task.scanStarted &&
        Array.isArray(task.scanPoints) &&
        task.scanPoints.length > 0) return;

    const radius = task.kind === "signal"
      ? finite(task.scanRadius, 11.5)
      : 18.5;
    task.scanRadius = radius;
    task.scanPoints = [];
    task.scanIdx = 0;
    task.scanStarted = true;

    const center = {
      x: clamp(task.x, 2.5, mem.mapW - 2.5),
      y: clamp(task.y, 2.5, mem.mapH - 2.5)
    };
    task.scanPoints.push(center);

    const fromAngle = Math.atan2(fromY - task.y, fromX - task.x) / RAD;
    let start = Math.round(fromAngle / 45);
    start = ((start % 8) + 8) % 8;

    for (let j = 0; j < 8; j++) {
      const angle = (start + j) * Math.PI / 4;
      const p = {
        x: clamp(task.x + radius * Math.cos(angle), 2.5, mem.mapW - 2.5),
        y: clamp(task.y + radius * Math.sin(angle), 2.5, mem.mapH - 2.5)
      };
      let duplicate = false;
      for (const q of task.scanPoints) {
        if (dist(p.x, p.y, q.x, q.y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) task.scanPoints.push(p);
    }
  }

  function remainingScan(task, fromX, fromY) {
    if (!task.scanStarted || !Array.isArray(task.scanPoints)) {
      return dist(fromX, fromY, task.x, task.y) +
        (task.kind === "signal" ? 75 : 122);
    }
    if (task.scanIdx >= task.scanPoints.length) return 0;
    let length = dist(
      fromX, fromY,
      task.scanPoints[task.scanIdx].x,
      task.scanPoints[task.scanIdx].y
    );
    for (let i = task.scanIdx + 1; i < task.scanPoints.length; i++) {
      length += dist(
        task.scanPoints[i - 1].x,
        task.scanPoints[i - 1].y,
        task.scanPoints[i].x,
        task.scanPoints[i].y
      );
    }
    return length;
  }

  function taskMetrics(task, fromX, fromY) {
    let out;
    let back;
    if (task.actual && Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      out = dist(fromX, fromY, task.siteX, task.siteY);
      back = dist(task.siteX, task.siteY, mem.baseX, mem.baseY);
    } else {
      out = remainingScan(task, fromX, fromY);
      const radius = task.scanStarted
        ? finite(task.scanRadius, task.kind === "signal" ? 11.5 : 18.5)
        : (task.kind === "signal" ? 11.5 : 18.5);
      back = dist(task.x, task.y, mem.baseX, mem.baseY) + radius;
    }

    const load = 1 + 0.16 * carried;
    const energy =
      0.11 +
      finite(mem.ePerM, 0.00145) * 1.50 * (out + back) * load +
      0.025 * (carried + 1);
    const timeNeed = (out + back) / 0.62 + 22;
    return { out: out, back: back, energy: energy, timeNeed: timeNeed };
  }

  function selectTask(fromX, fromY, atDock) {
    let best = null;
    let bestScore = -Infinity;
    const available = atDock
      ? Math.max(battery, finite(mem.maxBattery, battery))
      : battery;

    for (const task of mem.tasks) {
      if (!task || task.status === 2 || task.status === 3) continue;
      if (finite(task.retryAfter, 0) > now) continue;

      if (!task.actual) ensureScan(task, fromX, fromY);
      const m = taskMetrics(task, fromX, fromY);
      if (m.energy > available - 0.035) continue;
      if (m.timeNeed + 12 > timeLeft) continue;

      let value = clamp(finite(task.val, 1), 0.3, 100);
      if (task.kind === "signal") value *= 0.95;
      if (task.actual) value *= 1.16;

      let score = value / (30 + m.out + 0.72 * m.back);
      if (task.id === mem.activeTaskId) score *= 1.18;
      if (task.status === 1) score *= 1.05;
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    return best;
  }

  function sideOpenScore(sign) {
    if (!rays) return 0;
    let score = 0;
    for (let i = 0; i < Math.min(9, rays.length); i++) {
      const beta = -80 + 20 * i;
      if ((sign > 0 && beta > 0) || (sign < 0 && beta < 0)) {
        const r = finite(rays[i], 0);
        if (finite(mem.rayStale[i], 0) < 3.5) {
          score += r > 0 ? Math.min(12, r) : 0;
        }
      }
    }
    return score;
  }

  function chooseEscapeSign() {
    const left = sideOpenScore(1);
    const right = sideOpenScore(-1);
    if (Math.abs(left - right) > 1.0) return left > right ? 1 : -1;
    mem.escapeCount = finite(mem.escapeCount, 0) + 1;
    return mem.escapeCount % 2 === 0 ? 1 : -1;
  }

  function motorPower(target, current, side) {
    const ikey = side === 0 ? "integralL" : "integralR";
    const tkey = side === 0 ? "oldTargetL" : "oldTargetR";
    let integral = finite(mem[ikey], 0);
    const oldTarget = finite(mem[tkey], target);

    if (target * oldTarget < -0.05) integral *= 0.25;
    mem[tkey] = target;

    if (Math.abs(target) < 0.035) {
      integral *= 0.65;
      mem[ikey] = integral;
      return clamp(-0.82 * current + integral, -1, 1);
    }

    const error = target - current;
    integral = clamp(integral + 0.10 * error * dt, -0.30, 0.30);
    mem[ikey] = integral;

    let u = 0.25 * target +
      0.12 * Math.sign(target) +
      0.42 * error +
      integral;
    if (Math.abs(target) > 0.12 && Math.abs(u) < 0.12) {
      u = Math.sign(target) * 0.12;
    }
    return clamp(u, -1, 1);
  }

  function slopeAssist() {
    const pitch = finite(obs.pitch, 0) * RAD;
    return clamp(0.16 * Math.sin(pitch), -0.14, 0.14);
  }

  function driveWheels(v, omega) {
    const targetL = clamp(v - omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const targetR = clamp(v + omega * WHEEL_BASE * 0.5, -1.15, 1.15);
    const slope = slopeAssist();
    mem.lastCmdV = v;
    mem.lastCmdOmega = omega;
    return {
      left: clamp(motorPower(targetL, wl, 0) + slope, -1, 1),
      right: clamp(motorPower(targetR, wr, 1) + slope, -1, 1),
      drill: false
    };
  }

  function holdAt(anchorX, anchorY, wantDrill, closeEnough) {
    let along = 0;
    if (Number.isFinite(anchorX) && Number.isFinite(anchorY)) {
      const dx = anchorX - posX;
      const dy = anchorY - posY;
      along = dx * Math.cos(headMap * RAD) + dy * Math.sin(headMap * RAD);
    }
    const correction = clamp(0.035 * along, -0.06, 0.06);
    const slope = slopeAssist();
    const left = clamp(-0.82 * wl + slope + correction, -0.45, 0.45);
    const right = clamp(-0.82 * wr + slope + correction, -0.45, 0.45);
    const stationary = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;

    mem.lastCmdV = 0;
    mem.lastCmdOmega = 0;
    mem.integralL = finite(mem.integralL, 0) * 0.8;
    mem.integralR = finite(mem.integralR, 0) * 0.8;

    return {
      left: left,
      right: right,
      drill: !!wantDrill && !!closeEnough && stationary
    };
  }

  function navDrive(goalRel, targetDistance, key, baseSpeed,
                    worldX, worldY, stopRadius) {
    goalRel = wrap(goalRel);
    targetDistance = Math.max(0, finite(targetDistance, 0));
    stopRadius = Math.max(0, finite(stopRadius, 2.4));
    const navKey = String(key || "nav");

    if (mem.navKey !== navKey) {
      mem.navKey = navKey;
      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
      mem.stuckCount = 0;
      mem.navBlockedKey = "";
    } else if (now - finite(mem.progressT, now) >= 10) {
      const distanceImprovement =
        finite(mem.progressD, targetDistance) - targetDistance;
      const angleImprovement =
        finite(mem.progressA, Math.abs(goalRel)) - Math.abs(goalRel);
      const trying =
        Math.abs(finite(mem.lastCmdV, 0)) > 0.20 ||
        Math.abs(finite(mem.lastCmdOmega, 0)) > 0.30;

      if (targetDistance > stopRadius + 3 &&
          distanceImprovement < 0.65 &&
          angleImprovement < 8 &&
          trying) {
        mem.stuckCount = finite(mem.stuckCount, 0) + 1;
        mem.escapeSign = chooseEscapeSign();
        mem.escapeUntil = now + 0.75;
        if (mem.stuckCount >= 3 &&
            (navKey.indexOf("scan:") === 0 ||
             navKey.indexOf("explore:") === 0)) {
          mem.navBlockedKey = navKey;
        }
      } else if (distanceImprovement > 0.9 || angleImprovement > 12) {
        mem.stuckCount = 0;
      }

      mem.progressT = now;
      mem.progressD = targetDistance;
      mem.progressA = Math.abs(goalRel);
    }

    if (now < finite(mem.escapeUntil, -1)) {
      return driveWheels(-0.23, finite(mem.escapeSign, 1) * 0.85);
    }

    if (targetDistance <= stopRadius) return driveWheels(0, 0);

    if (Math.abs(goalRel) > 115) {
      return driveWheels(0, Math.sign(goalRel) * 0.95);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    if (Math.abs(goalRel) <= 80) candidates.push(goalRel);

    let bestAlpha = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestClear = Infinity;

    for (const alpha of candidates) {
      let cost = Math.pow(angleDiff(goalRel, alpha) / 32, 2);
      let clear = Infinity;

      if (rays) {
        for (let i = 0; i < Math.min(9, rays.length); i++) {
          const range = finite(rays[i], NaN);
          if (!Number.isFinite(range) ||
              range < 0 ||
              range >= 14.8 ||
              finite(mem.rayStale[i], 0) > 3.5) continue;

          const beta = -80 + 20 * i;
          const rel = (beta - alpha) * RAD;
          const d = Math.max(0.15, range);
          const along = d * Math.cos(rel);
          const cross = Math.abs(d * Math.sin(rel));

          if (along > 0 && along < 5.5) {
            const safeWidth = 0.78 + 0.07 * along;
            if (cross < safeWidth) {
              const severity = (safeWidth - cross) / safeWidth;
              const weight = along < 1.25 ? 38 :
                (along < 2.5 ? 23 : 11);
              cost += weight * severity * severity;
              if (along < 0.9) cost += 12 * severity;
              clear = Math.min(clear, along);
            }
          }
        }
      }

      if (Number.isFinite(worldX) && Number.isFinite(worldY)) {
        const worldA = (headMap + alpha) * RAD;
        const edgeX = posX + 3.0 * Math.cos(worldA);
        const edgeY = posY + 3.0 * Math.sin(worldA);
        if (edgeX < 2 || edgeX > mem.mapW - 2) cost += 16;
        if (edgeY < 2 || edgeY > mem.mapH - 2) cost += 16;
      }

      cost += 0.002 * Math.abs(alpha - finite(mem.lastAvoidAlpha, alpha));
      if (cost < bestCost) {
        bestCost = cost;
        bestAlpha = alpha;
        bestClear = clear;
      }
    }

    mem.lastAvoidAlpha = bestAlpha;

    let speed = clamp(finite(baseSpeed, 0.70), 0.12, 0.82);
    if (targetDistance < 7) {
      speed = Math.min(speed, 0.18 + 0.11 * targetDistance);
    }
    if (Math.abs(bestAlpha) > 55) speed = 0;
    else if (Math.abs(bestAlpha) > 38) speed = Math.min(speed, 0.32);

    if (Number.isFinite(bestClear)) {
      if (bestClear < 1.0) speed = Math.min(speed, 0.10);
      else if (bestClear < 1.5) speed = Math.min(speed, 0.18);
      else if (bestClear < 2.3) speed = Math.min(speed, 0.30);
      else if (bestClear < 3.4) speed = Math.min(speed, 0.48);
      else if (bestClear < 4.4) speed = Math.min(speed, 0.64);
    }
    if (raysBlind) speed = Math.min(speed, 0.58);

    const alphaRad = bestAlpha * RAD;
    const v = Math.abs(bestAlpha) > 55
      ? 0
      : speed * Math.max(0, Math.cos(alphaRad));
    const omega = clamp(2.0 * alphaRad, -1.15, 1.15);
    return driveWheels(v, omega);
  }

  function navToWorld(gx, gy, key, speed, stopRadius) {
    const dx = gx - posX;
    const dy = gy - posY;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / RAD : headMap;
    return navDrive(
      wrap(bearing - headMap),
      d,
      key,
      speed,
      gx,
      gy,
      stopRadius
    );
  }

  function navRelative(rel, d, key, speed, stopRadius) {
    return navDrive(rel, d, key, speed, NaN, NaN, stopRadius);
  }

  function beginSample(taskId, sx, sy, initialDistance) {
    if (carried >= mem.capacity) return false;
    mem.sampleActive = true;
    mem.sampleTaskId = Number.isFinite(taskId) ? taskId : -1;
    mem.sampleAnchorX = posX;
    mem.sampleAnchorY = posY;
    mem.sampleSiteX = finite(sx, posX);
    mem.sampleSiteY = finite(sy, posY);
    mem.sampleInitialDistance = clamp(finite(initialDistance, 1.2), 0, 1.5);
    mem.sampleCarryStart = carried;
    mem.sampleStart = now;
    mem.sampleLastT = now;
    mem.sampleMove = 0;

    const task = getTask(mem.sampleTaskId);
    if (task && task.status !== 2) task.status = 1;
    return true;
  }

  function sampleCommand(currentSiteDistance) {
    if (!mem.sampleActive) return driveWheels(0, 0);

    if (now > finite(mem.sampleLastT, now)) {
      mem.sampleMove = finite(mem.sampleMove, 0) + Math.abs(vAvg) * dt;
      mem.sampleLastT = now;
    }

    const drilling = Math.max(0, finite(obs.drilling, 0));
    const elapsed = now - finite(mem.sampleStart, now);

    if (carried > finite(mem.sampleCarryStart, carried)) {
      return holdAt(mem.sampleAnchorX, mem.sampleAnchorY, false, false);
    }

    if ((elapsed > 20 && drilling < 5.8) || elapsed > 26 ||
        (mem.sampleMove > 1.8 && drilling < 0.2)) {
      const task = getTask(mem.sampleTaskId);
      if (task) {
        task.sampleFailures = finite(task.sampleFailures, 0) + 1;
        task.retryAfter = now + (task.sampleFailures >= 3 ? 18 : 5);
      }
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
      mem.sampleRetryUntil = now + 5;
      return driveWheels(0, 0);
    }

    let close = finite(mem.sampleInitialDistance, 1.5) <= 1.45;
    if (Number.isFinite(currentSiteDistance)) {
      close = currentSiteDistance <= 1.5;
    }
    if (mem.sampleMove > 1.0 && drilling < 0.2) close = false;

    return holdAt(
      finite(mem.sampleAnchorX, posX),
      finite(mem.sampleAnchorY, posY),
      true,
      close
    );
  }

  function controlTask(task) {
    if (!task || task.status === 2 || task.status === 3) return null;

    if (task.actual &&
        Number.isFinite(task.siteX) &&
        Number.isFinite(task.siteY)) {
      const d = dist(posX, posY, task.siteX, task.siteY);
      if (d < 1.0 &&
          carried < mem.capacity &&
          now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(task.id, task.siteX, task.siteY, d)) {
          return sampleCommand(Infinity);
        }
      }
      return navToWorld(
        task.siteX, task.siteY,
        "actual:" + task.id,
        d < 5 ? 0.42 : 0.58,
        0.65
      );
    }

    ensureScan(task, posX, posY);
    let guard = 0;
    while (task.scanIdx < task.scanPoints.length && guard++ < 12) {
      const p = task.scanPoints[task.scanIdx];
      if (dist(posX, posY, p.x, p.y) > 2.7) break;
      task.scanIdx++;
    }

    if (task.scanIdx >= task.scanPoints.length) {
      task.status = 3;
      if (mem.activeTaskId === task.id) mem.activeTaskId = -1;
      return null;
    }

    const p = task.scanPoints[task.scanIdx];
    const key = "scan:" + task.id + ":" + task.scanIdx;
    const cmd = navToWorld(p.x, p.y, key, 0.72, 2.4);

    if (mem.navBlockedKey === key) {
      task.scanIdx++;
      mem.navBlockedKey = "";
      mem.navKey = "";
      mem.stuckCount = 0;
      return driveWheels(0, 0);
    }
    return cmd;
  }

  function requestReturn() {
    mem.returning = true;
    mem.departing = false;
    mem.baseWaitSince = -1;
    if (mem.sampleActive) {
      const task = getTask(mem.sampleTaskId);
      if (task && task.status !== 2) task.status = 1;
      mem.sampleActive = false;
      mem.sampleTaskId = -1;
      mem.sampleStart = -1;
    }
  }

  function returnCommand() {
    if (obs.docked) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (beaconValid) {
      const d = beacon.distance;
      if (d <= 2.7) {
        if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
        if (d < 0.75 || now - mem.baseWaitSince < 2.5) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        return navRelative(beacon.bearing, d, "return", 0.22, 0.65);
      }
      mem.baseWaitSince = -1;
      return navRelative(beacon.bearing, d, "return", 0.72, 2.7);
    }

    if (baseGpsDist <= 2.7) {
      if (mem.baseWaitSince < 0) mem.baseWaitSince = now;
      if (baseGpsDist < 0.75 || now - mem.baseWaitSince < 2.5) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      return navToWorld(
        mem.baseX, mem.baseY, "return", 0.22, 0.65
      );
    }
    mem.baseWaitSince = -1;
    return navToWorld(mem.baseX, mem.baseY, "return", 0.72, 2.7);
  }

  function fallbackPoint() {
    const pts = mem.explorePoints;
    if (!Array.isArray(pts) || !pts.length) {
      return {
        x: clamp(mem.baseX + 18, 3, mem.mapW - 3),
        y: clamp(mem.baseY, 3, mem.mapH - 3)
      };
    }
    let guard = 0;
    while (guard++ < pts.length) {
      const idx = ((mem.exploreIdx % pts.length) + pts.length) % pts.length;
      const p = pts[idx];
      if (dist(posX, posY, p.x, p.y) > 3.5) return p;
      mem.exploreIdx = (idx + 1) % pts.length;
    }
    return pts[mem.exploreIdx % pts.length];
  }

  function fallbackMetrics(p, fromX, fromY) {
    const out = dist(fromX, fromY, p.x, p.y);
    const back = dist(p.x, p.y, mem.baseX, mem.baseY);
    const energy =
      0.10 +
      finite(mem.ePerM, 0.00145) * 1.45 * (out + back) *
        (1 + 0.16 * carried) +
      0.015;
    const timeNeed = (out + back) / 0.65 + 18;
    return { energy: energy, timeNeed: timeNeed };
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped && !mem.sampleActive) {
    mem.escapeSign = chooseEscapeSign();
    mem.escapeUntil = now + 0.75;
  }
  mem.prevBumped = bumped;

  if (mem.departing && !obs.docked && baseDist > 4) {
    mem.departing = false;
  }

  if (obs.docked && mem.returning) {
    mem.returning = false;
    mem.departing = false;
    mem.baseWaitSince = -1;
    mem.escapeUntil = -1;
  }

  if (mem.returning) return returnCommand();

  if (mem.sampleActive) {
    if (battery < 0.035 && carried > 0) {
      requestReturn();
      return returnCommand();
    }
    return sampleCommand(siteValid ? siteDistance : Infinity);
  }

  const returnReserve =
    0.11 +
    finite(mem.ePerM, 0.00145) *
      1.85 * baseDist * (1 + 0.18 * carried) +
    0.022 * carried;
  const returnTime = 24 + baseDist / 0.48;

  if (!obs.docked) {
    const mustReturn =
      carried >= mem.capacity ||
      carried >= Math.min(3, mem.capacity) ||
      battery < returnReserve + 0.075 ||
      battery < 0.065 ||
      timeLeft < returnTime + (carried > 0 ? 12 : 70) ||
      (now < finite(mem.batteryShockUntil, -1) && carried > 0);

    if (mustReturn) {
      requestReturn();
      return returnCommand();
    }
  }

  if (siteValid && carried < mem.capacity) {
    if (obs.docked && battery < 0.18) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    if (siteDistance <= 1.35) {
      if (now >= finite(mem.sampleRetryUntil, -1)) {
        if (beginSample(
          siteTaskId,
          siteX,
          siteY,
          siteDistance
        )) {
          return sampleCommand(siteDistance);
        }
      } else {
        return holdAt(posX, posY, false, false);
      }
    }

    if (obs.docked) mem.departing = true;
    const speed = siteDistance < 4
      ? clamp(0.14 + 0.17 * (siteDistance - 1.0), 0.16, 0.62)
      : 0.70;
    return navRelative(
      siteBearing,
      siteDistance,
      "site:" + siteTaskId,
      speed,
      0.65
    );
  }

  if (obs.docked && !mem.departing) {
    if (carried > 0) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }

    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      if (task.status === 1 && task.status !== 2) task.status = 0;
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, true);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task && !task.actual) ensureScan(task, posX, posY);

    if (task) {
      const m = taskMetrics(task, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (m.energy <= maxBat - 0.025 &&
          m.timeNeed + 10 <= timeLeft) {
        const chargeGoal = Math.min(maxBat, m.energy + 0.035);
        if (battery + 0.012 < chargeGoal) {
          return holdAt(mem.baseX, mem.baseY, false, false);
        }
        mem.activeTaskId = task.id;
        task.status = 1;
        mem.departing = true;
      } else {
        if (task.status === 1) task.status = 0;
        mem.activeTaskId = -1;
        task = null;
      }
    }

    if (!task) {
      const p = fallbackPoint();
      const fm = fallbackMetrics(p, posX, posY);
      const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
      if (fm.energy > maxBat - 0.025 ||
          fm.timeNeed + 10 > timeLeft) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      const chargeGoal = Math.min(maxBat, fm.energy + 0.03);
      if (battery + 0.012 < chargeGoal) {
        return holdAt(mem.baseX, mem.baseY, false, false);
      }
      mem.departing = true;
    }
  }

  for (let tries = 0; tries < 5; tries++) {
    let task = getTask(mem.activeTaskId);
    if (task && (task.status === 2 || task.status === 3 ||
                 finite(task.retryAfter, 0) > now)) {
      mem.activeTaskId = -1;
      task = null;
    }

    if (!task) {
      task = selectTask(posX, posY, false);
      if (task) {
        mem.activeTaskId = task.id;
        task.status = 1;
      }
    }

    if (task) {
      if (!task.actual) ensureScan(task, posX, posY);
      const m = taskMetrics(task, posX, posY);

      if (m.energy > battery - 0.04 ||
          m.timeNeed + (carried > 0 ? 12 : 25) > timeLeft) {
        requestReturn();
        return returnCommand();
      }

      const cmd = controlTask(task);
      if (cmd) return cmd;
      if (task.status === 3) {
        mem.activeTaskId = -1;
        continue;
      }
    }
    break;
  }

  if (carried > 0) {
    requestReturn();
    return returnCommand();
  }

  const p = fallbackPoint();
  const fm = fallbackMetrics(p, posX, posY);
  if (!obs.docked &&
      (fm.energy > battery - 0.04 ||
       fm.timeNeed + 35 > timeLeft)) {
    requestReturn();
    return returnCommand();
  }

  if (obs.docked && !mem.departing) {
    const maxBat = Math.max(battery, finite(mem.maxBattery, battery));
    if (fm.energy > maxBat - 0.025 ||
        fm.timeNeed + 10 > timeLeft) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    if (battery + 0.012 < Math.min(maxBat, fm.energy + 0.03)) {
      return holdAt(mem.baseX, mem.baseY, false, false);
    }
    mem.departing = true;
  }

  const dExplore = dist(posX, posY, p.x, p.y);
  if (dExplore <= 2.6) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  const exploreKey = "explore:" + mem.exploreIdx;
  const exploreCmd = navToWorld(
    p.x, p.y, exploreKey, 0.68, 2.4
  );
  if (mem.navBlockedKey === exploreKey) {
    mem.exploreIdx = (mem.exploreIdx + 1) % mem.explorePoints.length;
    mem.navBlockedKey = "";
    mem.navKey = "";
    return driveWheels(0, 0);
  }

  return exploreCmd;
}

const DEG = Math.PI / 180;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const DX = [1, -1, 0, 0, 1, 1, -1, -1];
const DY = [0, 0, 1, -1, 1, -1, 1, -1];

function clamp(v, a, b) {
  return v < a ? a : (v > b ? b : v);
}
function wrapRad(a) {
  a = a % (2 * Math.PI);
  if (a > Math.PI) a -= 2 * Math.PI;
  if (a < -Math.PI) a += 2 * Math.PI;
  return a;
}
function wrapDeg(a) {
  a = a % 360;
  if (a > 180) a -= 360;
  if (a < -180) a += 360;
  return a;
}

function initMission(obs, mem) {
  mem.init = true;
  const M = obs.mission || {};
  mem.size = Number(M.size) || 400;
  mem.missionSeconds = Number(M.seconds) || 1200;
  const b = M.base || { x: obs.x, y: obs.y };
  mem.base = { x: Number(b.x) || 0, y: Number(b.y) || 0 };
  mem.capacity = Number(M.capacity) || 5;

  const hs = Array.isArray(M.hints) ? M.hints : [];
  mem.hints = [];
  for (let i = 0; i < hs.length; i++) {
    const h = hs[i] || {};
    let x = Number(h.x);
    let y = Number(h.y);
    let v = Number(h.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    if (!isFinite(v) || v <= 0) v = 1;
    mem.hints.push({
      id: mem.hints.length,
      x: x,
      y: y,
      v: v,
      status: 0,
      seen: false,
      pseudo: false
    });
  }
  mem.maxHintVal = 1;
  for (let i = 0; i < mem.hints.length; i++) {
    if (mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;
  }

  mem.res = 2;
  mem.gw = Math.ceil(mem.size / mem.res) + 2;
  mem.gh = mem.gw;
  const n = mem.gw * mem.gh;
  mem.obsCnt = new Uint8Array(n);
  mem.freeCnt = new Uint8Array(n);
  mem.dist = new Int16Array(n);
  mem.par = new Int32Array(n);
  mem.queue = new Int32Array(n);

  mem.path = [];
  mem.pathIndex = 0;
  mem.pathGoal = null;
  mem.pathDirty = true;
  mem.lastPlan = -100;

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.approachSite = null;
  mem.approachId = -1;
  mem.visibleSite = null;
  mem.sites = [];
  mem.nextSiteId = 1;
  mem.drill = null;
  mem.lastSample = null;
  mem.sampledCount = 0;

  mem.pos = { x: Number(obs.x) || 0, y: Number(obs.y) || 0 };
  mem.od = { x: mem.pos.x, y: mem.pos.y };
  mem.lastX = Number(obs.x) || 0;
  mem.lastY = Number(obs.y) || 0;
  mem.head = Number(obs.heading) || 0;
  mem.lastObsHeading = mem.head;
  mem.bias = 0;
  mem.calib = { x: mem.pos.x, y: mem.pos.y };
  mem.staleCount = 0;
  mem.gpsStale = false;
  mem.gpsWasStale = false;
  mem.lastT = Number(obs.t) || 0;
  mem.dt = 0.1;
  mem.groundDist = 0;
  mem.speedWheel = 0;
  mem.omega = 0;

  mem.lastBatt = isFinite(obs.battery) ? obs.battery : 1;
  mem.drainMove = 0.0015;
  mem.drainIdle = 0.0003;
  mem.epm = 0.0012;
  mem.epmSamples = 0;
  mem.lastCarried = obs.carried || 0;
  mem.lastDelivered = obs.delivered || 0;

  mem.wheelL = { i: 0, prevT: 0 };
  mem.wheelR = { i: 0, prevT: 0 };
  mem.lastLeft = 0;
  mem.lastRight = 0;

  mem.recoverUntil = -1;
  mem.recoverBackUntil = -1;
  mem.recoverTurn = 1;
  mem.noMoveTime = 0;

  mem.rayStuck = new Int16Array(9);
  mem.lastRay = new Float32Array(9);
  for (let i = 0; i < 9; i++) mem.lastRay[i] = 15;

  mem.sciMax = 1e-9;
  mem.unhintedSearches = 0;
  mem.roamCount = 0;
  mem.randomSeed = (Math.floor(Math.abs(mem.pos.x * 1000 + mem.pos.y * 97 + mem.lastT * 13)) + 12345) >>> 0;
}

function updateSensors(obs, mem) {
  let dt = Number(obs.t) - mem.lastT;
  if (!(dt > 0) || dt > 1.5) dt = 0.1;
  if (dt < 0.02) dt = 0.02;
  mem.dt = dt;

  let x = Number(obs.x);
  let y = Number(obs.y);
  if (!isFinite(x)) x = mem.pos.x;
  if (!isFinite(y)) y = mem.pos.y;

  const dxg = x - mem.lastX;
  const dyg = y - mem.lastY;
  let gd = Math.hypot(dxg, dyg);
  if (!isFinite(gd)) gd = 0;
  mem.groundDist = gd;
  mem.lastX = x;
  mem.lastY = y;

  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  const vW = (wl + wr) / 2;
  const omega = (wr - wl) / 0.6;
  mem.speedWheel = vW;
  mem.omega = omega;

  if (gd < 0.015 && Math.abs(vW) > 0.16) mem.staleCount++;
  else mem.staleCount = 0;
  const stale = mem.staleCount > 5;
  mem.gpsStale = stale;

  const pred = wrapDeg(mem.head + omega * (180 / Math.PI) * dt);
  let hObs = Number(obs.heading);
  if (!isFinite(hObs)) hObs = pred;

  const hdiff = wrapDeg(hObs - pred);
  let jump = false;
  if (Math.abs(hdiff) > 55 && Math.abs(omega) < 1.0) jump = true;
  const hRaw = jump ? pred : hObs;

  if (!mem.calib) mem.calib = { x: x, y: y };
  if (!stale && Math.abs(vW) > 0.35 && Math.abs(wr - wl) < 1.1) {
    const cd = Math.hypot(x - mem.calib.x, y - mem.calib.y);
    if (cd > 4.0) {
      let dir = Math.atan2(y - mem.calib.y, x - mem.calib.x) * (180 / Math.PI);
      if (vW < 0) dir = wrapDeg(dir + 180);
      const b = wrapDeg(hObs - dir);
      if (Math.abs(b) < 75) {
        mem.bias = wrapDeg(mem.bias * 0.86 + b * 0.14);
      }
      mem.calib = { x: x, y: y };
    }
  }

  const headMeas = wrapDeg(hRaw - mem.bias);
  let headTrue;
  if (jump) {
    headTrue = pred;
  } else {
    headTrue = wrapDeg(pred + wrapDeg(headMeas - pred) * 0.45);
  }

  if (stale) {
    mem.od.x += vW * Math.cos(headTrue * DEG) * dt;
    mem.od.y += vW * Math.sin(headTrue * DEG) * dt;
    mem.pos.x = mem.od.x;
    mem.pos.y = mem.od.y;
  } else {
    const dx = x - mem.pos.x;
    const dy = y - mem.pos.y;
    const dd = Math.hypot(dx, dy);
    let alpha = 0.45;
    if (mem.gpsWasStale || dd > 12) alpha = 0.65;
    if (dd > 40) alpha = 1.0;
    mem.pos.x += dx * alpha;
    mem.pos.y += dy * alpha;
    mem.od.x = mem.pos.x;
    mem.od.y = mem.pos.y;
  }

  mem.gpsWasStale = stale;
  mem.head = wrapDeg(headTrue);
  mem.lastObsHeading = hObs;
  mem.lastT = Number(obs.t) || mem.lastT;
}

function markFree(mem, x, y) {
  if (!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x / mem.res);
  const iy = Math.round(y / mem.res);
  if (ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gw) return;
  const idx = iy * mem.gw + ix;
  const v = mem.freeCnt[idx];
  if (v < 255) mem.freeCnt[idx] = v + 1;
}

function markObs(mem, x, y) {
  if (!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x / mem.res);
  const iy = Math.round(y / mem.res);
  if (ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gw) return;
  const idx = iy * mem.gw + ix;
  const old = mem.obsCnt[idx];
  if (old < 255) {
    const nv = old + 1;
    mem.obsCnt[idx] = nv;
    if (old < 2 && nv >= 2) mem.pathDirty = true;
  }
}

function updateGrid(obs, mem) {
  const rays = obs.rays || [];
  const wr = Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0);
  for (let i = 0; i < 9; i++) {
    let r = Number(rays[i]);
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;

    if (Math.abs(r - mem.lastRay[i]) < 0.0005 && wr > 0.1) {
      if (mem.rayStuck[i] < 30000) mem.rayStuck[i]++;
    } else {
      mem.rayStuck[i] = 0;
    }
    mem.lastRay[i] = r;

    if (mem.rayStuck[i] > 25) continue;

    const rel = ANG[i] * DEG;
    const ang = mem.head * DEG + rel;
    const maxd = Math.min(r, 15);
    const step = 1.25;

    for (let d = 0.6; d < maxd - 0.6; d += step) {
      markFree(mem, mem.pos.x + Math.cos(ang) * d, mem.pos.y + Math.sin(ang) * d);
    }

    if (r > 0.1 && r < 14.75) {
      markObs(mem, mem.pos.x + Math.cos(ang) * r, mem.pos.y + Math.sin(ang) * r);
    }
  }
}

function updateSites(obs, mem) {
  mem.visibleSite = null;
  const os = obs.site;
  if (os) {
    const dist = Math.max(0, Number(os.distance) || 0);
    const bearing = Number(os.bearing) || 0;
    let val = Number(os.value);
    if (!isFinite(val) || val < 0) val = 1;
    const ang = mem.head * DEG + bearing * DEG;
    const sx = mem.pos.x + Math.cos(ang) * dist;
    const sy = mem.pos.y + Math.sin(ang) * dist;

    let s = null;
    let bestD = 16;
    for (let i = 0; i < mem.sites.length; i++) {
      const q = mem.sites[i];
      if (q.sampled) continue;
      const d2 = (q.x - sx) * (q.x - sx) + (q.y - sy) * (q.y - sy);
      if (d2 < bestD) {
        bestD = d2;
        s = q;
      }
    }

    if (!s) {
      s = {
        id: mem.nextSiteId++,
        x: sx,
        y: sy,
        value: val,
        sampled: false,
        ignoreUntil: 0,
        lastSeen: obs.t || 0
      };
      mem.sites.push(s);
    } else {
      s.x += (sx - s.x) * 0.25;
      s.y += (sy - s.y) * 0.25;
      s.value = val;
      s.lastSeen = obs.t || 0;
    }

    mem.visibleSite = {
      id: s.id,
      x: s.x,
      y: s.y,
      value: s.value,
      distance: dist,
      bearing: bearing
    };

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status >= 2) continue;
      const dd = Math.hypot(h.x - s.x, h.y - s.y);
      if (dd < 30) h.seen = true;
    }
  }

  const sci = Number(obs.science);
  if (isFinite(sci) && sci > mem.sciMax) mem.sciMax = sci;
}

function updateEnergy(obs, mem) {
  const batt = Number(obs.battery);
  if (!isFinite(batt)) return;
  const dt = mem.dt;
  const solar = Number(obs.solar) || 0;
  const delta = batt - mem.lastBatt;
  let consumed = solar * dt - delta;
  if (!isFinite(consumed) || consumed < 0) consumed = 0;

  const v = Math.abs((Number(obs.wheelLeft) || 0) + (Number(obs.wheelRight) || 0)) / 2;
  if (!obs.drilling && v > 0.25) {
    const rate = consumed / dt;
    if (rate > 0 && rate < 0.05) {
      mem.drainMove = clamp(mem.drainMove * 0.97 + rate * 0.03, 0.0001, 0.04);
    }
    const gd = mem.groundDist;
    if (gd > 0.03) {
      const ep = consumed / gd;
      if (ep > 0.00005 && ep < 0.05) {
        mem.epm = clamp(mem.epm * 0.95 + ep * 0.05, 0.0004, 0.025);
        mem.epmSamples++;
      }
    }
  } else if (obs.drilling) {
    const rate = consumed / dt;
    if (rate > 0 && rate < 0.05) mem.drainMove = clamp(mem.drainMove * 0.995 + rate * 0.005, 0.0001, 0.04);
  }

  mem.lastBatt = batt;
}

function returnRequirementFor(mem, obs, dist) {
  const epm = Math.max(0.0007, mem.epm || 0.0012);
  const load = 1 + 0.08 * (obs.carried || 0);
  return dist * 1.70 * epm * load + 0.09;
}

function cellBlocked(mem, ix, iy) {
  if (ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gh) return true;
  const wx = ix * mem.res;
  const wy = iy * mem.res;
  if (wx < 0.6 || wx > mem.size - 0.6 || wy < 0.6 || wy > mem.size - 0.6) return true;
  const idx = iy * mem.gw + ix;
  const o = mem.obsCnt[idx];
  const f = mem.freeCnt[idx];
  if (o >= 2 && o > f) return true;
  if (o >= 1 && f === 0) return true;
  return false;
}

function nearestFree(mem, ix, iy, maxR) {
  for (let r = 0; r <= maxR; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const nx = ix + dx;
        const ny = iy + dy;
        if (!cellBlocked(mem, nx, ny)) return ny * mem.gw + nx;
      }
    }
  }
  return -1;
}

function planPath(mem, gx, gy) {
  const gw = mem.gw;
  const n = gw * mem.gh;

  gx = clamp(gx, 1, mem.size - 1);
  gy = clamp(gy, 1, mem.size - 1);

  const sx = Math.round(mem.pos.x / mem.res);
  const sy = Math.round(mem.pos.y / mem.res);
  const gxi = Math.round(gx / mem.res);
  const gyi = Math.round(gy / mem.res);

  const start = nearestFree(mem, sx, sy, 5);
  if (start < 0) {
    mem.path = [];
    return;
  }
  let goal = nearestFree(mem, gxi, gyi, 8);
  if (goal < 0) goal = start;

  const dist = mem.dist;
  const par = mem.par;
  const q = mem.queue;
  dist.fill(32767);
  par.fill(-1);

  let qh = 0;
  let qt = 0;
  dist[goal] = 0;
  q[qt++] = goal;
  let found = false;

  while (qh < qt) {
    const cur = q[qh++];
    if (cur === start) {
      found = true;
      break;
    }
    const cx = cur % gw;
    const cy = (cur / gw) | 0;
    const nd = dist[cur] + 1;
    if (nd >= 32767) continue;

    for (let k = 0; k < 8; k++) {
      const nx = cx + DX[k];
      const ny = cy + DY[k];
      if (nx < 0 || ny < 0 || nx >= gw || ny >= mem.gh) continue;
      const ni = ny * gw + nx;
      if (dist[ni] !== 32767) continue;
      if (cellBlocked(mem, nx, ny)) continue;
      if (k >= 4) {
        if (cellBlocked(mem, cx + DX[k], cy) || cellBlocked(mem, cx, cy + DY[k])) continue;
      }
      dist[ni] = nd;
      par[ni] = cur;
      q[qt++] = ni;
      if (qt >= n) break;
    }
  }

  if (found || dist[start] !== 32767) {
    const arr = [];
    let cur = start;
    let reached = false;
    let guard = 0;
    while (cur !== -1 && guard++ < 5000) {
      arr.push(cur);
      if (cur === goal) {
        reached = true;
        break;
      }
      cur = par[cur];
    }
    if (reached) {
      mem.path = arr;
      mem.pathIndex = 0;
      mem.pathGoal = { x: gx, y: gy };
      return;
    }
  }

  dist.fill(32767);
  par.fill(-1);
  qh = 0;
  qt = 0;
  dist[start] = 0;
  q[qt++] = start;

  let best = start;
  let bestScore = 1e100;

  while (qh < qt) {
    const cur = q[qh++];
    const cx = cur % gw;
    const cy = (cur / gw) | 0;

    if (cur !== start) {
      const dx = cx * mem.res - gx;
      const dy = cy * mem.res - gy;
      const score = dx * dx + dy * dy;
      if (score < bestScore) {
        bestScore = score;
        best = cur;
      }
    }

    const nd = dist[cur] + 1;
    for (let k = 0; k < 8; k++) {
      const nx = cx + DX[k];
      const ny = cy + DY[k];
      if (nx < 0 || ny < 0 || nx >= gw || ny >= mem.gh) continue;
      const ni = ny * gw + nx;
      if (dist[ni] !== 32767) continue;
      if (cellBlocked(mem, nx, ny)) continue;
      if (k >= 4) {
        if (cellBlocked(mem, cx + DX[k], cy) || cellBlocked(mem, cx, cy + DY[k])) continue;
      }
      dist[ni] = nd;
      par[ni] = cur;
      q[qt++] = ni;
      if (qt >= n) break;
    }
  }

  if (best === start) {
    mem.path = [];
    mem.pathGoal = { x: gx, y: gy };
    return;
  }

  const chain = [];
  let cur = best;
  let guard = 0;
  while (cur !== -1 && guard++ < 5000) {
    chain.push(cur);
    if (cur === start) break;
    cur = par[cur];
  }

  if (chain.length && chain[chain.length - 1] === start) {
    chain.reverse();
    mem.path = chain;
  } else {
    mem.path = [];
  }
  mem.pathGoal = { x: gx, y: gy };
  mem.pathIndex = 0;
}

function ensurePathTo(obs, mem, gx, gy) {
  let need = false;
  if (!mem.path || mem.path.length < 2) need = true;
  else if (!mem.pathGoal || Math.hypot(mem.pathGoal.x - gx, mem.pathGoal.y - gy) > 3) need = true;
  else if (mem.pathDirty) need = true;
  else if (obs.t - mem.lastPlan > 2.5) need = true;

  if (need) {
    if (mem.pathDirty && mem.path && mem.path.length > 1 && obs.t - mem.lastPlan < 0.45) return;
    planPath(mem, gx, gy);
    mem.lastPlan = obs.t;
    mem.pathDirty = false;
  }
}

function getPathWaypoint(mem) {
  const p = mem.path;
  if (!p || p.length === 0) return null;
  const gw = mem.gw;
  let idx = mem.pathIndex || 0;

  while (idx < p.length - 1) {
    const id = p[idx];
    const x = (id % gw) * mem.res;
    const y = ((id / gw) | 0) * mem.res;
    if (Math.hypot(x - mem.pos.x, y - mem.pos.y) < 1.3) idx++;
    else break;
  }

  let chosen = idx;
  for (let k = idx; k < p.length; k++) {
    const id = p[k];
    const x = (id % gw) * mem.res;
    const y = ((id / gw) | 0) * mem.res;
    const d = Math.hypot(x - mem.pos.x, y - mem.pos.y);
    chosen = k;
    if (d > 2.8) break;
  }

  mem.pathIndex = idx;
  const id = p[chosen];
  const x = (id % gw) * mem.res;
  const y = ((id / gw) | 0) * mem.res;

  if (chosen === p.length - 1 && Math.hypot(x - mem.pos.x, y - mem.pos.y) < 0.3) return null;
  return { x: x, y: y };
}

function wheelControl(meas, target, st, dt) {
  const err = target - meas;

  if (Math.abs(target) < 0.15 && Math.abs(st.prevT) > 0.3) {
    st.i *= 0.25;
  }
  st.prevT = target;

  st.i += err * dt * 0.45;
  st.i = clamp(st.i, -0.55, 0.55);

  let u = target / 3.0 + 0.22 * err + st.i;

  if (Math.abs(target) < 0.02 && Math.abs(meas) < 0.03) {
    st.i *= Math.exp(-1.5 * dt);
  }

  if (Math.abs(u) < 0.045 && (Math.abs(target) > 0.025 || Math.abs(err) > 0.025)) {
    let sgn;
    if (u !== 0) sgn = Math.sign(u);
    else if (err !== 0) sgn = Math.sign(err);
    else sgn = Math.sign(target);
    u = sgn * 0.045;
  }

  return clamp(u, -1, 1);
}

function brakeCmd(obs, mem) {
  return {
    left: wheelControl(obs.wheelLeft || 0, 0, mem.wheelL, mem.dt),
    right: wheelControl(obs.wheelRight || 0, 0, mem.wheelR, mem.dt),
    drill: false
  };
}

function motion(obs, mem, err, vdes, opt) {
  opt = opt || {};
  const head = mem.head * DEG;
  let desiredAbs = head + err;

  let vx = Math.cos(desiredAbs);
  let vy = Math.sin(desiredAbs);

  const edge = 3.0;
  if (mem.pos.x < edge) vx += (edge - mem.pos.x) * 0.5;
  if (mem.pos.x > mem.size - edge) vx -= (mem.pos.x - (mem.size - edge)) * 0.5;
  if (mem.pos.y < edge) vy += (edge - mem.pos.y) * 0.5;
  if (mem.pos.y > mem.size - edge) vy -= (mem.pos.y - (mem.size - edge)) * 0.5;

  const rays = obs.rays || [];
  let repX = 0;
  let repY = 0;
  let front = 15;
  let sideL = 0;
  let sideR = 0;

  for (let i = 0; i < 9; i++) {
    let r = Number(rays[i]);
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;

    if (i >= 3 && i <= 5 && r < front) front = r;
    if (i >= 5) sideL += r;
    if (i <= 3) sideR += r;

    if (r < 5.5) {
      const rel = ANG[i] * DEG;
      const away = head + rel + Math.PI;
      let w = (5.5 - r) / 5.5;
      if (i === 4) w *= 1.8;
      else if (i >= 3 && i <= 5) w *= 1.4;
      repX += Math.cos(away) * w;
      repY += Math.sin(away) * w;
    }
  }

  vx += repX * 0.9;
  vy += repY * 0.9;

  if (Math.hypot(vx, vy) > 0.08) {
    desiredAbs = Math.atan2(vy, vx);
  }
  err = wrapRad(desiredAbs - head);

  if (front < 3.2) {
    if (sideL > sideR + 2.5) err = Math.max(err, 0.55);
    else if (sideR > sideL + 2.5) err = Math.min(err, -0.55);
    else err = (sideL >= sideR ? 1 : -1) * 1.0;
  }

  if (front < 1.1) {
    err = (sideL > sideR ? 1 : -1) * 1.2;
    vdes = Math.min(vdes, 0.08);
  }

  let vcap = 2.8;
  if (front < 8) vcap = Math.max(0, (front - 0.8) * 0.55);

  const edgeDist = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
  if (edgeDist < 3.5) vcap = Math.min(vcap, Math.max(0, (edgeDist - 0.7) * 0.7));

  if (obs.battery < 0.15) vcap = Math.min(vcap, 0.9);
  if (obs.battery < 0.05) vcap = Math.min(vcap, 0.45);
  if (obs.carried > 0) vcap *= Math.max(0.75, 1 - 0.035 * obs.carried);

  if (vdes > vcap) vdes = vcap;
  if (vdes < 0) vdes = 0;
  if (Math.abs(err) > 1.25) vdes = 0;

  let omega = clamp(err * 2.2, -2.4, 2.4);
  if (opt.noTurn) omega = 0;

  let vL = vdes - omega * 0.3;
  let vR = vdes + omega * 0.3;
  vL = clamp(vL, -3, 3);
  vR = clamp(vR, -3, 3);

  return {
    left: wheelControl(obs.wheelLeft || 0, vL, mem.wheelL, mem.dt),
    right: wheelControl(obs.wheelRight || 0, vR, mem.wheelR, mem.dt),
    drill: false
  };
}

function driveTo(obs, mem, gx, gy, opt) {
  opt = opt || {};
  const dGoal = Math.hypot(gx - mem.pos.x, gy - mem.pos.y);

  if (dGoal < 0.35) return brakeCmd(obs, mem);

  let wp = { x: gx, y: gy };
  if (!opt.direct && dGoal > 3.5) {
    ensurePathTo(obs, mem, gx, gy);
    const p = getPathWaypoint(mem);
    if (p) wp = p;
  }

  const desired = Math.atan2(wp.y - mem.pos.y, wp.x - mem.pos.x);
  let err = wrapRad(desired - mem.head * DEG);

  let speed = opt.speed !== undefined ? opt.speed : 1.8;
  const stopDist = opt.stopDist !== undefined ? opt.stopDist : 0.5;

  if (dGoal < 3.0) {
    const f = clamp((dGoal - stopDist) / 2.5, 0, 1);
    speed *= f;
  }

  if (speed <= 0.02) return brakeCmd(obs, mem);
  return motion(obs, mem, err, speed, opt);
}

function findSiteById(mem, id) {
  for (let i = 0; i < mem.sites.length; i++) {
    if (mem.sites[i].id === id) return mem.sites[i];
  }
  return null;
}

function shouldAcceptSite(obs, mem, vis) {
  if (!vis) return false;
  if (obs.carried >= mem.capacity) return false;
  if (!(vis.value > 0)) return false;
  if (mem.mode === 'approach') return true;
  if (mem.mode === 'search') return true;
  if (mem.task && mem.task.type === 'site' && mem.task.id === vis.id) return true;
  if (mem.mode === 'return') return false;

  const maxv = mem.maxHintVal || 1;
  if (obs.carried < Math.min(2, mem.capacity - 1)) return true;
  if (vis.value >= Math.max(0.02 * maxv, 0.05)) return true;

  const bd = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
  if (bd < 35) return true;
  if (obs.carried < mem.capacity - 1 && vis.value >= 0.01 * maxv) return true;
  return false;
}

function beginSearch(obs, mem, h) {
  const R = 14;
  const pts = [{ x: h.x, y: h.y }];
  const startAng = Math.atan2(mem.pos.y - h.y, mem.pos.x - h.x);

  for (let k = 1; k <= 16; k++) {
    const a = startAng + k * 2 * Math.PI / 16;
    pts.push({
      x: clamp(h.x + Math.cos(a) * R, 1, mem.size - 1),
      y: clamp(h.y + Math.sin(a) * R, 1, mem.size - 1)
    });
  }

  mem.search = {
    hintId: h.id,
    cx: h.x,
    cy: h.y,
    points: pts,
    idx: 0,
    startT: obs.t,
    travel: 0,
    lastX: mem.pos.x,
    lastY: mem.pos.y,
    centerChecked: false
  };
  h.status = 1;
  mem.mode = 'search';
  mem.path = [];
  mem.pathDirty = true;
}

function chooseTask(obs, mem) {
  const bdNow = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
  const atBase = obs.docked || bdNow < 4;
  const epm = Math.max(0.0007, mem.epm || 0.0012);
  const cands = [];

  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.status !== 0) continue;
    const d = Math.hypot(h.x - mem.pos.x, h.y - mem.pos.y);
    const dret = Math.hypot(h.x - mem.base.x, h.y - mem.base.y);
    const maxReq = (Math.max(d, dret) * 2.4 + 35) * epm * (1 + 0.08 * (obs.carried || 0)) + 0.1;
    if (atBase && maxReq > 0.97) continue;

    const hp = 28 + (h.pseudo ? 10 : 0);
    const travel = d + 0.55 * dret + hp + 20;
    let score = Math.pow(Math.max(0.001, h.v), 1.08) / (travel + 20);
    if (h.pseudo) score *= 0.8;
    if (obs.carried >= mem.capacity - 1) {
      score *= 1 + 2 * (h.v / Math.max(1, mem.maxHintVal));
    }
    cands.push({
      type: 'hint',
      id: h.id,
      x: h.x,
      y: h.y,
      v: h.v,
      d: d,
      dret: dret,
      score: score
    });
  }

  for (let i = 0; i < mem.sites.length; i++) {
    const s = mem.sites[i];
    if (s.sampled) continue;
    if ((s.ignoreUntil || 0) > obs.t) continue;
    const d = Math.hypot(s.x - mem.pos.x, s.y - mem.pos.y);
    const dret = Math.hypot(s.x - mem.base.x, s.y - mem.base.y);
    const maxReq = (Math.max(d, dret) * 2.4 + 25) * epm * (1 + 0.08 * (obs.carried || 0)) + 0.08;
    if (atBase && maxReq > 0.97) continue;

    const travel = d + 0.55 * dret + 10;
    let score = Math.pow(Math.max(0.001, s.value), 1.1) / (travel + 20);
    if (obs.carried >= mem.capacity - 1) {
      score *= 1 + 2 * (s.value / Math.max(1, mem.maxHintVal));
    }
    cands.push({
      type: 'site',
      id: s.id,
      x: s.x,
      y: s.y,
      v: s.value,
      d: d,
      dret: dret,
      score: score
    });
  }

  let best = null;
  for (let i = 0; i < cands.length; i++) {
    const c = cands[i];
    const load = 1 + 0.08 * (obs.carried || 0);
    const req = (c.d * 1.5 + c.dret * 1.5) * epm * load + 0.08;
    if (!atBase && obs.battery < req && c.d > 5) continue;

    const timeNeed = (c.d + c.dret * 1.3) / 1.1 + 18 + (c.type === 'hint' ? 22 : 0);
    if (obs.timeLeft < timeNeed) continue;
    if (atBase && obs.timeLeft < (c.d * 2.0) / 1.0 + 25) continue;

    if (!best || c.score > best.score) best = c;
  }

  if (!best) {
    if (obs.carried > 0) {
      mem.task = null;
      mem.mode = 'return';
      return false;
    }

    if (!atBase && obs.battery < 0.24) {
      mem.task = null;
      mem.mode = 'return';
      return false;
    }

    const sci = Number(obs.science) || 0;
    if (obs.timeLeft > 80 && obs.battery > 0.35 && (mem.unhintedSearches || 0) < 3 && sci > 1e-8) {
      const hx = mem.pos.x;
      const hy = mem.pos.y;
      const h = {
        id: mem.hints.length,
        x: hx,
        y: hy,
        v: 1,
        status: 0,
        seen: false,
        pseudo: true
      };
      mem.hints.push(h);
      mem.unhintedSearches++;
      mem.task = {
        type: 'hint',
        id: h.id,
        x: hx,
        y: hy,
        v: 1,
        startT: obs.t
      };
      mem.mode = 'travel';
      mem.search = null;
      mem.path = [];
      mem.pathDirty = true;
      return true;
    }

    if (obs.timeLeft > 80 && obs.battery > 0.40 && (mem.roamCount || 0) < 8) {
      mem.roamCount++;
      const seed = mem.randomSeed + mem.roamCount * 1013904223;
      const frac = ((Math.sin(seed * 0.0001) * 43758.5453) % 1 + 1) % 1;
      const ang = frac * 2 * Math.PI;
      const rad = 70 + 110 * frac;
      const tx = clamp(mem.pos.x + Math.cos(ang) * rad, 6, mem.size - 6);
      const ty = clamp(mem.pos.y + Math.sin(ang) * rad, 6, mem.size - 6);
      mem.task = {
        type: 'roam',
        id: -1,
        x: tx,
        y: ty,
        v: 0.1,
        startT: obs.t
      };
      mem.mode = 'travel';
      mem.search = null;
      mem.path = [];
      mem.pathDirty = true;
      return true;
    }

    mem.task = null;
    mem.mode = atBase ? 'charge' : 'return';
    return false;
  }

  mem.task = {
    type: best.type,
    id: best.id,
    x: best.x,
    y: best.y,
    v: best.v,
    startT: obs.t
  };
  mem.mode = 'travel';
  mem.search = null;
  mem.path = [];
  mem.pathIndex = 0;
  mem.pathGoal = null;
  mem.pathDirty = true;
  return true;
}

function doTravel(obs, mem) {
  const task = mem.task;
  if (!task) {
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }

  if (task.type === 'hint') {
    if (task.id < 0 || task.id >= mem.hints.length) {
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs, mem);
    }
    const h = mem.hints[task.id];
    if (!h || h.status >= 2) {
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs, mem);
    }

    const d = Math.hypot(h.x - mem.pos.x, h.y - mem.pos.y);
    if (d < 2.8) {
      beginSearch(obs, mem, h);
      return doSearch(obs, mem);
    }

    if (obs.t - task.startT > 350 && d > 15) {
      h.status = 3;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs, mem);
    }

    return driveTo(obs, mem, h.x, h.y, { speed: 1.85 });
  }

  if (task.type === 'site') {
    const s = findSiteById(mem, task.id);
    if (!s || s.sampled) {
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs, mem);
    }

    const d = Math.hypot(s.x - mem.pos.x, s.y - mem.pos.y);
    if (d < 4) {
      if (!obs.site) {
        s.ignoreUntil = obs.t + 45;
        mem.task = null;
        mem.mode = 'idle';
        return brakeCmd(obs, mem);
      }
    }

    if (obs.t - task.startT > 350 && d > 20) {
      s.ignoreUntil = obs.t + 60;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs, mem);
    }

    return driveTo(obs, mem, s.x, s.y, { speed: 1.8 });
  }

  if (task.type === 'roam') {
    const d = Math.hypot(task.x - mem.pos.x, task.y - mem.pos.y);
    if (d < 4 || obs.t - task.startT > 130) {
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs, mem);
    }
    return driveTo(obs, mem, task.x, task.y, { speed: 1.65 });
  }

  mem.task = null;
  mem.mode = 'idle';
  return brakeCmd(obs, mem);
}

function doSearch(obs, mem) {
  const S = mem.search;
  if (!S) {
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }
  if (S.hintId < 0 || S.hintId >= mem.hints.length) {
    mem.search = null;
    mem.task = null;
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }
  const h = mem.hints[S.hintId];
  if (!h) {
    mem.search = null;
    mem.task = null;
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }

  const moved = Math.hypot(mem.pos.x - S.lastX, mem.pos.y - S.lastY);
  S.travel += moved;
  S.lastX = mem.pos.x;
  S.lastY = mem.pos.y;

  if (obs.t - S.startT > 78 || S.travel > 210) {
    h.status = 2;
    mem.search = null;
    mem.task = null;
    mem.mode = 'idle';
    mem.path = [];
    return brakeCmd(obs, mem);
  }

  const d0 = Math.hypot(S.cx - mem.pos.x, S.cy - mem.pos.y);
  if (!S.centerChecked && d0 < 2.5) {
    S.centerChecked = true;
    const sci = Number(obs.science) || 0;
    if (sci < 1e-9 && !obs.site) {
      h.status = 2;
      mem.search = null;
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs, mem);
    }
  }

  while (S.idx < S.points.length) {
    const p = S.points[S.idx];
    const d = Math.hypot(p.x - mem.pos.x, p.y - mem.pos.y);
    if (d < 1.4) S.idx++;
    else break;
  }

  if (S.idx >= S.points.length) {
    h.status = 2;
    mem.search = null;
    mem.task = null;
    mem.mode = 'idle';
    mem.path = [];
    return brakeCmd(obs, mem);
  }

  const p = S.points[S.idx];
  return driveTo(obs, mem, p.x, p.y, { speed: 1.30 });
}

function doApproach(obs, mem) {
  const vis = mem.visibleSite;
  const os = obs.site;

  if (!vis || !os) {
    if (mem.approachSite) {
      const s = findSiteById(mem, mem.approachSite.id);
      if (s && !s.sampled) {
        mem.mode = 'travel';
        mem.task = {
          type: 'site',
          id: s.id,
          x: s.x,
          y: s.y,
          v: s.value,
          startT: obs.t
        };
        return doTravel(obs, mem);
      }
    }
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }

  const dist = os.distance;
  const maxWheel = Math.max(Math.abs(obs.wheelLeft || 0), Math.abs(obs.wheelRight || 0));
  const still = maxWheel < 0.13;

  if (dist < 1.42) {
    if (!still) return brakeCmd(obs, mem);

    const bd = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
    const req = returnRequirementFor(mem, obs, bd);
    const safeTime = obs.timeLeft > bd / 1.1 + 16;
    const safeBatt = obs.battery > req + 0.045;

    if (obs.carried < mem.capacity && safeTime && safeBatt) {
      mem.mode = 'drill';
      mem.drill = {
        id: vis.id,
        value: vis.value,
        x: vis.x,
        y: vis.y,
        beforeCarried: obs.carried || 0,
        startT: obs.t,
        started: true,
        holdX: mem.pos.x,
        holdY: mem.pos.y
      };
      return handleDrill(obs, mem);
    }

    const s = findSiteById(mem, vis.id);
    if (s && !s.sampled) s.ignoreUntil = obs.t + 45;
    mem.mode = obs.carried > 0 ? 'return' : 'idle';
    mem.task = null;
    return brakeCmd(obs, mem);
  }

  let speed = (dist - 0.6) * 0.55;
  speed = clamp(speed, 0, 1.15);

  let err = os.bearing * DEG;
  return motion(obs, mem, err, speed, {});
}

function handleDrill(obs, mem) {
  const d = mem.drill;
  if (!d) {
    mem.mode = 'idle';
    return brakeCmd(obs, mem);
  }

  if ((obs.carried || 0) > d.beforeCarried) {
    const oldTask = mem.task;

    let s = findSiteById(mem, d.id);
    if (s) {
      s.sampled = true;
    } else {
      for (let i = 0; i < mem.sites.length; i++) {
        const q = mem.sites[i];
        if (!q.sampled && Math.hypot(q.x - d.x, q.y - d.y) < 4) {
          q.sampled = true;
          break;
        }
      }
    }

    let nearestH = null;
    let nhd = 1e100;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status >= 2) continue;
      const dd = (h.x - d.x) * (h.x - d.x) + (h.y - d.y) * (h.y - d.y);
      if (dd < nhd) {
        nhd = dd;
        nearestH = h;
      }
    }
    if (nearestH && nhd < 35 * 35) nearestH.status = 2;

    let keepTask = null;
    if (oldTask && oldTask.type === 'hint' && oldTask.id >= 0 && oldTask.id < mem.hints.length) {
      const h = mem.hints[oldTask.id];
      if (h && h.status !== 2) {
        const dd = (h.x - d.x) * (h.x - d.x) + (h.y - d.y) * (h.y - d.y);
        if (dd > 35 * 35) keepTask = oldTask;
        else h.status = 2;
      }
    }

    mem.lastSample = {
      value: d.value,
      x: d.x,
      y: d.y,
      t: obs.t
    };
    mem.sampledCount++;
    mem.drill = null;
    mem.search = null;

    if ((obs.carried || 0) >= mem.capacity) {
      mem.task = null;
      mem.mode = 'return';
      mem.path = [];
      mem.pathDirty = true;
    } else if (keepTask) {
      mem.task = keepTask;
      mem.mode = 'travel';
      mem.path = [];
      mem.pathDirty = true;
    } else {
      mem.task = null;
      mem.mode = 'idle';
    }

    return { left: 0, right: 0, drill: false };
  }

  const bd = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
  const req = returnRequirementFor(mem, obs, bd);
  const drilling = Number(obs.drilling) || 0;
  const drillRemain = Math.max(0, 6 - drilling);
  const timeNeed = bd / 1.1 + drillRemain + 5;
  const timeShort = obs.timeLeft < timeNeed;
  const low = obs.battery < req + 0.015;

  const siteDist = obs.site ? obs.site.distance : 99;

  if (!d.started) {
    const maxWheel = Math.max(Math.abs(obs.wheelLeft || 0), Math.abs(obs.wheelRight || 0));
    if (obs.site && siteDist < 1.45 && maxWheel < 0.13 && !low && !timeShort) {
      d.started = true;
    } else if ((low || timeShort) && drilling < 5.5) {
      d.abort = true;
    }
  }

  if (d.started) {
    if ((low && drilling < 5.7) || (timeShort && drilling < 5.7)) d.abort = true;
    if (obs.site && siteDist > 1.75 && drilling < 0.2) d.abort = true;
    if (obs.t - d.startT > 18 && drilling < 5.9 && (obs.carried || 0) <= d.beforeCarried) {
      if (!obs.site || siteDist > 1.6 || drilling === 0) d.abort = true;
    }
  }

  if (d.abort) {
    if (low || timeShort) {
      mem.mode = 'return';
    } else {
      mem.mode = 'idle';
    }
    mem.task = null;
    mem.search = null;
    mem.drill = null;
    mem.path = [];
    return brakeCmd(obs, mem);
  }

  let targetL = 0;
  let targetR = 0;

  if (d.started) {
    const ex = d.holdX - mem.pos.x;
    const ey = d.holdY - mem.pos.y;
    const de = Math.hypot(ex, ey);
    if (de > 0.80 && drilling < 5.95) {
      let ang = Math.atan2(ey, ex) - mem.head * DEG;
      let v = Math.min(0.08, de * 0.10);
      let turn = clamp(wrapRad(ang) * 1.2, -0.12, 0.12);
      if (Math.abs(turn) > 0.8) v = 0;
      targetL = v - turn * 0.3;
      targetR = v + turn * 0.3;
    }
  }

  return {
    left: wheelControl(obs.wheelLeft || 0, targetL, mem.wheelL, mem.dt),
    right: wheelControl(obs.wheelRight || 0, targetR, mem.wheelR, mem.dt),
    drill: !!d.started && !d.abort
  };
}

function doReturn(obs, mem) {
  const bdGPS = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
  let dist = bdGPS;
  let err = null;

  if (obs.beacon && isFinite(obs.beacon.distance) && obs.beacon.distance < 20) {
    dist = Number(obs.beacon.distance) || bdGPS;
    err = (Number(obs.beacon.bearing) || 0) * DEG;
  }

  if (dist < 1.15) {
    return brakeCmd(obs, mem);
  }

  if (dist < 5.0) {
    if (err === null) {
      const da = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x);
      err = wrapRad(da - mem.head * DEG);
    }
    const v = clamp((dist - 0.9) * 0.55, 0, 0.95);
    if (v <= 0.02) return brakeCmd(obs, mem);
    return motion(obs, mem, err, v, {});
  }

  if (err !== null) {
    const v = dist > 10 ? 1.55 : 1.0;
    return motion(obs, mem, err, v, {});
  }

  return driveTo(obs, mem, mem.base.x, mem.base.y, { speed: 1.75, stopDist: 1.0 });
}

function handleDocked(obs, mem) {
  if (obs.carried > 0) {
    return { left: 0, right: 0, drill: false };
  }

  if (mem.mode === 'return' || mem.mode === 'charge') {
    mem.task = null;
    mem.search = null;
    mem.drill = null;
    mem.mode = 'charge';
  }

  if (obs.timeLeft < 8) {
    mem.mode = 'charge';
    return { left: 0, right: 0, drill: false };
  }

  let valid = false;
  if (mem.task) {
    if (mem.task.type === 'hint') {
      const h = mem.hints[mem.task.id];
      if (h && h.status < 2) valid = true;
    } else if (mem.task.type === 'site') {
      const s = findSiteById(mem, mem.task.id);
      if (s && !s.sampled) valid = true;
    } else if (mem.task.type === 'roam') {
      valid = true;
    }
  }

  if (!valid) {
    mem.task = null;
    mem.mode = 'idle';
    chooseTask(obs, mem);
  }

  if (!mem.task) {
    mem.mode = 'charge';
    return { left: 0, right: 0, drill: false };
  }

  const task = mem.task;
  const d = Math.hypot(task.x - mem.base.x, task.y - mem.base.y);
  const epm = Math.max(0.0007, mem.epm || 0.0012);
  const extra = task.type === 'hint' ? 30 : (task.type === 'roam' ? 10 : 10);
  const req = (2.0 * d + extra) * epm * (1 + 0.08 * (obs.carried || 0)) + 0.12;

  if (req > 0.99) {
    mem.task = null;
    mem.mode = 'charge';
    return { left: 0, right: 0, drill: false };
  }

  const timeForTrip = (2.6 * d) / 1.0 + 60;
  const shouldCharge = (obs.battery < req + 0.10) || (obs.battery < 0.22 && obs.timeLeft > 150);

  if (shouldCharge && obs.timeLeft > timeForTrip) {
    mem.mode = 'charge';
    return { left: 0, right: 0, drill: false };
  }

  if (obs.timeLeft < (d * 2.0) / 1.0 + 20) {
    mem.task = null;
    mem.mode = 'charge';
    return { left: 0, right: 0, drill: false };
  }

  mem.mode = 'travel';
  mem.path = [];
  mem.pathGoal = null;
  mem.pathDirty = true;
  return doTravel(obs, mem);
}

function doRecovery(obs, mem) {
  let v = 0;
  const turn = mem.recoverTurn || 1;

  if (obs.t < mem.recoverBackUntil) {
    v = -0.65;
  }

  let w;
  if (v === 0) w = turn * 1.35;
  else w = turn * 0.18;

  let vL = v - w * 0.3;
  let vR = v + w * 0.3;
  vL = clamp(vL, -2, 2);
  vR = clamp(vR, -2, 2);

  const left = wheelControl(obs.wheelLeft || 0, vL, mem.wheelL, mem.dt);
  const right = wheelControl(obs.wheelRight || 0, vR, mem.wheelR, mem.dt);

  if (obs.t >= mem.recoverUntil) {
    mem.pathDirty = true;
    mem.noMoveTime = 0;
  }

  return { left: left, right: right, drill: false };
}

function act(obs, mem) {
  if (!mem.init) initMission(obs, mem);

  updateSensors(obs, mem);
  updateGrid(obs, mem);
  updateSites(obs, mem);
  updateEnergy(obs, mem);

  if ((obs.carried || 0) < (mem.lastCarried || 0)) {
    mem.lastDelivered = obs.delivered || mem.lastDelivered;
  }
  mem.lastCarried = obs.carried || 0;

  if (obs.bumped) {
    const bx = mem.pos.x + Math.cos(mem.head * DEG) * 0.9;
    const by = mem.pos.y + Math.sin(mem.head * DEG) * 0.9;
    markObs(mem, bx, by);
    mem.pathDirty = true;
  }

  if (mem.mode !== 'drill' && mem.mode !== 'charge' && mem.mode !== 'idle') {
    const want = Math.max(Math.abs(mem.lastLeft || 0), Math.abs(mem.lastRight || 0));
    const turning = Math.abs((obs.wheelRight || 0) - (obs.wheelLeft || 0)) > 0.15;

    if (want > 0.25 && mem.groundDist < 0.005 && !turning) mem.noMoveTime += mem.dt;
    else mem.noMoveTime = 0;

    if (obs.bumped) {
      mem.recoverUntil = obs.t + 1.8;
      mem.recoverBackUntil = obs.t + 0.9;
      const l = (obs.rays && (obs.rays[6] || 0) + (obs.rays[7] || 0) + (obs.rays[8] || 0)) || 0;
      const r = (obs.rays && (obs.rays[0] || 0) + (obs.rays[1] || 0) + (obs.rays[2] || 0)) || 0;
      mem.recoverTurn = l > r ? 1 : -1;
      mem.noMoveTime = 0;
    } else if (mem.noMoveTime > 2.2) {
      mem.recoverUntil = obs.t + 1.8;
      mem.recoverBackUntil = obs.t + 0.8;
      const rays = obs.rays || [];
      const l = (rays[5] || 15) + (rays[6] || 15) + (rays[7] || 15) + (rays[8] || 15);
      const r = (rays[0] || 15) + (rays[1] || 15) + (rays[2] || 15) + (rays[3] || 15);
      mem.recoverTurn = l > r ? 1 : -1;
      mem.noMoveTime = 0;
    }
  }

  if (mem.mode !== 'drill' && mem.recoverUntil > obs.t) {
    const res = doRecovery(obs, mem);
    mem.lastLeft = res.left;
    mem.lastRight = res.right;
    return res;
  }

  if (mem.mode === 'drill') {
    const res = handleDrill(obs, mem);
    mem.lastLeft = res.left;
    mem.lastRight = res.right;
    return res;
  }

  if (obs.docked) {
    const res = handleDocked(obs, mem);
    mem.lastLeft = res.left;
    mem.lastRight = res.right;
    return res;
  }

  if (mem.mode === 'charge') {
    mem.mode = 'return';
    mem.path = [];
    mem.pathDirty = true;
  }

  const bd = Math.hypot(mem.pos.x - mem.base.x, mem.pos.y - mem.base.y);
  const req = returnRequirementFor(mem, obs, bd);
  const timeNeed = bd / 1.15 + 14 + ((obs.carried || 0) > 0 ? 6 : 0);
  const batteryCrit = obs.battery < req + ((obs.carried || 0) > 0 ? 0.05 : 0.02);
  const timeCrit = obs.timeLeft < timeNeed + ((obs.carried || 0) > 0 ? 8 : 0);

  if (mem.mode !== 'return' && mem.mode !== 'approach' && mem.mode !== 'drill' && (obs.carried || 0) > 0 && bd < 8 && !mem.visibleSite) {
    if (mem.search) {
      const h = mem.hints[mem.search.hintId];
      if (h && h.status === 1) h.status = 0;
    }
    mem.search = null;
    mem.mode = 'return';
    mem.path = [];
    mem.pathDirty = true;
  }

  if (((obs.carried || 0) >= mem.capacity || batteryCrit || timeCrit) && mem.mode !== 'return') {
    if (mem.search) {
      const h = mem.hints[mem.search.hintId];
      if (h && h.status === 1) h.status = 0;
    }
    mem.search = null;
    mem.task = null;
    mem.mode = 'return';
    mem.path = [];
    mem.pathGoal = null;
    mem.pathDirty = true;
  }

  if (mem.mode !== 'return' && obs.site && (obs.carried || 0) < mem.capacity) {
    const vis = mem.visibleSite;
    if (vis) {
      if (shouldAcceptSite(obs, mem, vis)) {
        if (mem.mode !== 'approach' || mem.approachId !== vis.id) {
          mem.mode = 'approach';
          mem.approachId = vis.id;
          mem.approachSite = {
            id: vis.id,
            x: vis.x,
            y: vis.y,
            value: vis.value
          };
        }
      } else {
        const s = findSiteById(mem, vis.id);
        if (s && !s.sampled) s.ignoreUntil = obs.t + 45;
      }
    }
  }

  if ((mem.mode === 'idle' || !mem.task) && mem.mode !== 'approach') {
    if ((obs.carried || 0) > 0 && bd < 12) {
      mem.mode = 'return';
      mem.path = [];
      mem.pathGoal = null;
      mem.pathDirty = true;
    } else {
      chooseTask(obs, mem);
    }
  }

  let res;

  if (mem.mode === 'return') {
    res = doReturn(obs, mem);
  } else if (mem.mode === 'travel') {
    res = doTravel(obs, mem);
  } else if (mem.mode === 'search') {
    res = doSearch(obs, mem);
  } else if (mem.mode === 'approach') {
    res = doApproach(obs, mem);
  } else if (mem.mode === 'charge') {
    res = handleDocked(obs, mem);
  } else {
    if (!mem.task) {
      chooseTask(obs, mem);
      if (mem.mode === 'travel') res = doTravel(obs, mem);
      else res = brakeCmd(obs, mem);
    } else {
      res = brakeCmd(obs, mem);
    }
  }

  mem.lastLeft = res.left;
  mem.lastRight = res.right;
  return res;
}

const PI = Math.PI;
const TWO_PI = 2 * PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const WB = 0.6;
const RAYR = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];
const DX8 = [1,0,-1,0,1,1,-1,-1];
const DY8 = [0,1,0,-1,1,-1,1,-1];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % TWO_PI;
  if(a > PI) a -= TWO_PI;
  if(a < -PI) a += TWO_PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function sgn(v){ return v<0?-1:(v>0?1:0); }

function initMission(obs,mem){
  mem.init = true;
  mem.tick = 0;
  mem.t = Number(obs.t) || 0;
  mem.dt = 0.1;
  const M = obs.mission || {};
  mem.size = Number(M.size) || 400;
  mem.seconds = Number(M.seconds) || 1200;
  mem.cap = Math.max(1, Math.floor(Number(M.capacity) || 5));
  const b = M.base || {x:Number(obs.x)||0,y:Number(obs.y)||0};
  mem.base = {x:clamp(Number(b.x)||0,0,mem.size), y:clamp(Number(b.y)||0,0,mem.size)};

  const hs = Array.isArray(M.hints) ? M.hints : [];
  mem.hints = [];
  mem.maxHintVal = 1;
  for(let i=0;i<hs.length;i++){
    const h = hs[i] || {};
    let x = Number(h.x), y = Number(h.y), v = Number(h.estimate);
    if(!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x,0,mem.size); y = clamp(y,0,mem.size);
    if(!isFinite(v) || v <= 0) v = 0.1;
    mem.hints.push({id:mem.hints.length,x:x,y:y,v:v,status:0,pseudo:false});
  }
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;

  mem.res = 2;
  mem.gw = Math.ceil(mem.size / mem.res) + 2;
  mem.gh = mem.gw;
  mem.n = mem.gw * mem.gh;
  mem.obsCount = new Uint8Array(mem.n);
  mem.freeCount = new Uint8Array(mem.n);
  mem.dist = new Int32Array(mem.n);
  mem.par = new Int32Array(mem.n);
  mem.q = new Int32Array(mem.n);

  mem.pos = {x:clamp(Number(obs.x)||0,0.2,mem.size-0.2), y:clamp(Number(obs.y)||0,0.2,mem.size-0.2)};
  mem.od = {x:mem.pos.x,y:mem.pos.y};
  mem.lastGpsX = mem.pos.x;
  mem.lastGpsY = mem.pos.y;
  mem.lastGpsNewT = mem.t;
  mem.gpsIntervalAvg = 0.5;
  mem.gpsStillT = 0;
  mem.gpsStale = false;
  mem.gpsWasStale = false;
  mem.gpsNew = false;
  mem.gpsBad = 0;
  mem.lastGpsMoved = 0;

  mem.head = (Number(obs.heading)||0) * D2R;
  mem.lastRawDeg = Number(obs.heading)||0;
  mem.rawLast2 = mem.head;
  mem.bias = 0;
  mem.compassBad = 0;
  mem.compassGood = 0;
  mem.headStuck = 0;
  mem.slip = 1;

  mem.path = [];
  mem.pathIdx = 0;
  mem.pathGoal = null;
  mem.pathDirty = true;
  mem.lastPlan = -999;

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.drill = null;
  mem.approach = null;
  mem.sites = [];
  mem.nextSiteId = 1;
  mem.visibleSite = null;

  mem.lastBatt = isFinite(Number(obs.battery)) ? Number(obs.battery) : 1;
  mem.epmBase = 0.0015;
  mem.loadBeta = 0.12;
  mem.drillRate = 0.006;
  mem.dockWait = 0;
  mem.chargeRate = 0;
  mem.skipTask = null;
  mem.skipUntil = 0;

  mem.ctlL = {i:0,prev:0};
  mem.ctlR = {i:0,prev:0};
  mem.wantV = 0;
  mem.stallT = 0;

  mem.recoverUntil = -1;
  mem.recoverBackUntil = -1;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.goodT = 0;

  mem.rayLast = new Float32Array(9);
  mem.rayStuck = new Int16Array(9);
  for(let i=0;i<9;i++){ mem.rayLast[i]=15; mem.rayStuck[i]=0; }

  mem.sciMax = 0;
  mem.pseudoSearches = 0;
  mem.roams = 0;
  mem.sampledCount = 0;
  mem.rng = (Math.floor(Math.abs(mem.pos.x*1000 + mem.pos.y*137 + mem.t*19)) + 1234567) >>> 0;
}

function updateSensors(obs,mem){
  let t = Number(obs.t);
  if(!isFinite(t)) t = mem.t + 0.1;
  let dt = t - mem.t;
  if(!(dt > 0) || dt > 1.0) dt = 0.1;
  if(dt < 0.01) dt = 0.1;
  mem.dt = dt;
  mem.t = t;

  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const v = (wl + wr) / 2;
  const yawRate = (wr - wl) / WB;

  let rawDeg = Number(obs.heading);
  if(!isFinite(rawDeg)) rawDeg = mem.lastRawDeg;
  mem.lastRawDeg = rawDeg;
  const raw = rawDeg * D2R;

  const pred = wrap(mem.head + yawRate * dt);
  const expRaw = pred + mem.bias;
  const diff = wrap(raw - expRaw);
  let jump = false;
  if(Math.abs(diff) > 1.15 && Math.abs(yawRate) < 1.0){
    jump = true;
    mem.compassBad = Math.min(80, (mem.compassBad||0)+1);
    mem.compassGood = 0;
  } else {
    mem.compassGood = (mem.compassGood||0)+1;
    mem.compassBad = Math.max(0, (mem.compassBad||0)-0.35);
    if(mem.compassGood > 10) mem.compassBad = 0;
  }

  if(Math.abs(raw - (mem.rawLast2||raw)) < 0.0001 && Math.abs(yawRate) > 0.15){
    mem.headStuck = (mem.headStuck||0)+1;
  } else {
    mem.headStuck = 0;
  }
  mem.rawLast2 = raw;

  const meas = wrap(raw - mem.bias);
  let head;
  if(jump || mem.compassBad > 12 || mem.headStuck > 12){
    head = pred;
  } else {
    head = wrap(pred + wrap(meas - pred) * 0.55);
  }
  mem.head = wrap(head);

  const odx = mem.od.x + v * Math.cos(mem.head) * dt;
  const ody = mem.od.y + v * Math.sin(mem.head) * dt;

  let gx = Number(obs.x), gy = Number(obs.y);
  if(!isFinite(gx)) gx = mem.lastGpsX;
  if(!isFinite(gy)) gy = mem.lastGpsY;
  const gdx = gx - mem.lastGpsX;
  const gdy = gy - mem.lastGpsY;
  const gmove = hyp(gdx,gdy);
  mem.gpsNew = gmove > 0.003;
  mem.lastGpsMoved = gmove;

  if(mem.gpsNew){
    const interval = t - (mem.lastGpsNewT || t);
    if(interval > 0.03 && interval < 20){
      mem.gpsIntervalAvg = mem.gpsIntervalAvg * 0.8 + interval * 0.2;
    }
    mem.lastGpsNewT = t;
  }

  if(Math.abs(v) > 0.03 && gmove < 0.002) mem.gpsStillT += dt;
  else if(gmove > 0.002 || Math.abs(v) < 0.03) mem.gpsStillT = 0;
  const stale = mem.gpsStillT > 1.8;
  mem.gpsStale = stale;

  if(mem.gpsNew && Math.abs(v) > 0.25 && Math.abs(wr-wl) < 0.6 && !jump){
    let course = Math.atan2(gdy,gdx);
    if(v < 0) course = wrap(course + PI);
    const mb = wrap(raw - course);
    const bd = wrap(mb - mem.bias);
    if(Math.abs(bd) < 0.85){
      mem.bias = wrap(mem.bias + bd * 0.06);
    }
  }

  let px = odx, py = ody;
  if(!stale){
    const errx = gx - odx;
    const erry = gy - ody;
    const err = hyp(errx,erry);
    if(mem.gpsWasStale){
      if(err < 80){
        px = gx; py = gy;
      } else {
        px = odx + errx * 0.5;
        py = ody + erry * 0.5;
      }
      mem.gpsBad = 0;
    } else if(mem.gpsNew || Math.abs(v) < 0.05){
      if(err > 70 && (mem.gpsBad||0) < 3){
        mem.gpsBad = (mem.gpsBad||0)+1;
        px = odx; py = ody;
      } else {
        mem.gpsBad = 0;
        const alpha = (Math.abs(v) < 0.05) ? 0.5 : 0.35;
        px = odx + errx * alpha;
        py = ody + erry * alpha;
      }
    }
  } else {
    mem.gpsBad = 0;
  }

  mem.pos.x = clamp(px,0.2,mem.size-0.2);
  mem.pos.y = clamp(py,0.2,mem.size-0.2);
  mem.od.x = mem.pos.x;
  mem.od.y = mem.pos.y;
  mem.gpsWasStale = stale;

  if(mem.gpsNew && Math.abs(v) > 0.2){
    const dtg = Math.max(0.05, t - (mem.lastGpsT || (t-0.1)));
    if(dtg < 10){
      const ratio = gmove / (Math.abs(v) * dtg);
      mem.slip = mem.slip * 0.85 + clamp(ratio,0,2) * 0.15;
    }
    mem.lastGpsT = t;
  }
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;
}

function markFree(mem,x,y){
  if(!isFinite(x)||!isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gh) return;
  const idx = iy*mem.gw + ix;
  if(mem.obsCount[idx] >= 200) return;
  const f = mem.freeCount[idx];
  if(f < 250) mem.freeCount[idx] = f + 1;
}

function markObstacle(mem,x,y,strength){
  if(!isFinite(x)||!isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gh) return;
  const idx = iy*mem.gw + ix;
  const o = mem.obsCount[idx];
  const add = strength || 1;
  if(o < 255) mem.obsCount[idx] = Math.min(255, o + add);
}

function markHard(mem,x,y){
  if(!isFinite(x)||!isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix < 0 || iy < 0 || ix >= mem.gw || iy >= mem.gh) return;
  const idx = iy*mem.gw + ix;
  mem.obsCount[idx] = 255;
  mem.freeCount[idx] = 0;
  for(let dx=-1;dx<=1;dx++){
    for(let dy=-1;dy<=1;dy++){
      if(dx===0 && dy===0) continue;
      const nx=ix+dx, ny=iy+dy;
      if(nx<0||ny<0||nx>=mem.gw||ny>=mem.gh) continue;
      const ni=ny*mem.gw+nx;
      if(mem.obsCount[ni] < 245) mem.obsCount[ni] = mem.obsCount[ni] + 3;
    }
  }
}

function updateGrid(obs,mem){
  const rays = obs.rays || [];
  const moving = Math.abs(Number(obs.wheelLeft)||0) + Math.abs(Number(obs.wheelRight)||0) > 0.18;
  for(let i=0;i<9;i++){
    let r = Number(rays[i]);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    const last = mem.rayLast[i];
    if(Math.abs(r-last) < 0.0005 && moving) mem.rayStuck[i] = Math.min(30000, mem.rayStuck[i]+1);
    else mem.rayStuck[i] = 0;
    mem.rayLast[i] = r;

    if(mem.rayStuck[i] > 45) continue;

    const ang = mem.head + RAYR[i];
    const ca = Math.cos(ang), sa = Math.sin(ang);
    const maxd = Math.min(r,14.8);
    for(let d=0.7; d<maxd-0.25; d+=1.2){
      markFree(mem, mem.pos.x + ca*d, mem.pos.y + sa*d);
    }
    if(r < 14.5 && r > 0.2){
      const strength = (r < 1.5) ? 3 : 1;
      markObstacle(mem, mem.pos.x + ca*r, mem.pos.y + sa*r, strength);
    }
  }
  markFree(mem,mem.pos.x,mem.pos.y);
}

function updateSites(obs,mem){
  mem.visibleSite = null;
  const os = obs.site;
  if(os){
    let dist = Number(os.distance);
    let bearing = Number(os.bearing);
    let val = Number(os.value);
    if(!isFinite(dist) || dist < 0) dist = 0;
    if(!isFinite(bearing)) bearing = 0;
    if(!isFinite(val) || val < 0) val = 0;
    const ang = mem.head + bearing * D2R;
    const sx = mem.pos.x + Math.cos(ang) * dist;
    const sy = mem.pos.y + Math.sin(ang) * dist;

    let best = null;
    let bestD = 25;
    for(let i=0;i<mem.sites.length;i++){
      const s = mem.sites[i];
      if(s.sampled) continue;
      const dx = s.x - sx, dy = s.y - sy;
      const d2 = dx*dx + dy*dy;
      if(d2 < bestD){ bestD = d2; best = s; }
    }
    if(!best){
      if(mem.sites.length < 200){
        best = {id:mem.nextSiteId++, x:sx, y:sy, value:val, sampled:false, lastSeen:mem.t, ignoreUntil:0};
        mem.sites.push(best);
      }
    } else {
      best.x += (sx - best.x) * 0.28;
      best.y += (sy - best.y) * 0.28;
      best.value = val;
      best.lastSeen = mem.t;
      best.sampled = false;
    }
    if(best){
      mem.visibleSite = {id:best.id,x:best.x,y:best.y,value:best.value,rawDist:dist,rawBearing:bearing};
    }
  }

  const sci = Number(obs.science);
  if(isFinite(sci) && sci > mem.sciMax) mem.sciMax = sci;
}

function updateEnergy(obs,mem){
  const batt = Number(obs.battery);
  if(!isFinite(batt)) return;
  const dt = mem.dt;
  const solar = Number(obs.solar) || 0;
  let cons = (mem.lastBatt - batt) + solar * dt;
  if(!isFinite(cons) || cons < 0) cons = 0;

  const carried = obs.carried || 0;
  const load = 1 + mem.loadBeta * carried;
  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const wheelDist = Math.abs((wl+wr)/2) * dt;

  if(!obs.drilling && wheelDist > 0.005){
    const r = (cons / wheelDist) / load;
    if(r > 0 && r < 0.2){
      mem.epmBase = mem.epmBase * 0.97 + r * 0.03;
      mem.epmBase = clamp(mem.epmBase,0.00025,0.05);
    }
  }

  if(obs.drilling && cons > 0){
    const rate = cons / dt;
    if(rate > 0 && rate < 0.2) mem.drillRate = mem.drillRate * 0.9 + rate * 0.1;
  }

  if(obs.docked && batt > mem.lastBatt){
    const rate = (batt - mem.lastBatt) / dt;
    if(rate > 0) mem.chargeRate = mem.chargeRate * 0.7 + rate * 0.3;
  }
  mem.lastBatt = batt;
}

function returnBatteryNeed(mem,obs,dist,carried){
  const load = 1 + mem.loadBeta * carried;
  let b = dist * mem.epmBase * load * 1.8 + 0.05;
  if(mem.mode === 'drill'){
    const rem = Math.max(0, 6 - (Number(obs.drilling)||0));
    b += rem * mem.drillRate;
  }
  return b;
}

function taskMetrics(mem,obs,task){
  const sd = (task.type === 'hint') ? 24 : (task.type === 'roam' ? 10 : 4);
  const d1 = hyp(task.x - mem.pos.x, task.y - mem.pos.y);
  const d2 = hyp(task.x - mem.base.x, task.y - mem.base.y);
  const sample = (task.type === 'hint' || task.type === 'site') ? 1 : 0;
  const load = 1 + mem.loadBeta * ((obs.carried||0) + sample);
  const dist = d1 + d2 + sd;
  const batt = dist * mem.epmBase * load * 2.0 + 0.07 + sample * 6 * mem.drillRate;
  const time = (d1 + d2 + sd) / 0.9 + 10 + sample * 8 + (task.type === 'hint' ? 12 : 0);
  return {dist:dist,batt:batt,time:time};
}

function cellBlocked(mem,ix,iy){
  if(ix < 1 || iy < 1 || ix >= mem.gw-1 || iy >= mem.gh-1) return true;
  const wx = ix * mem.res;
  const wy = iy * mem.res;
  if(wx < 0.7 || wx > mem.size-0.7 || wy < 0.7 || wy > mem.size-0.7) return true;
  const idx = iy*mem.gw + ix;
  const o = mem.obsCount[idx];
  if(o >= 200) return true;
  const f = mem.freeCount[idx];
  if(o >= 2 && o >= f) return true;
  return false;
}

function blockedWorld(mem,x,y){
  if(x < 0.5 || x > mem.size-0.5 || y < 0.5 || y > mem.size-0.5) return true;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  return cellBlocked(mem,ix,iy);
}

function findFreeNear(mem,cx,cy,maxR){
  if(!cellBlocked(mem,cx,cy)) return cy*mem.gw + cx;
  for(let r=1;r<=maxR;r++){
    for(let dx=-r;dx<=r;dx++){
      for(let dy=-r;dy<=r;dy++){
        if(Math.max(Math.abs(dx),Math.abs(dy)) !== r) continue;
        const nx = cx + dx;
        const ny = cy + dy;
        if(!cellBlocked(mem,nx,ny)) return ny*mem.gw + nx;
      }
    }
  }
  return -1;
}

function planPath(mem,gx,gy,t){
  const gw = mem.gw;
  const n = mem.n;
  let sx = Math.round(mem.pos.x / mem.res);
  let sy = Math.round(mem.pos.y / mem.res);
  let gxi = Math.round(gx / mem.res);
  let gyi = Math.round(gy / mem.res);
  sx = clamp(sx,1,gw-2);
  sy = clamp(sy,1,mem.gh-2);
  gxi = clamp(gxi,1,gw-2);
  gyi = clamp(gyi,1,mem.gh-2);

  const start = findFreeNear(mem,sx,sy,7);
  if(start < 0){ mem.path=[]; mem.pathGoal={x:gx,y:gy}; mem.lastPlan=t; return false; }
  let goal = findFreeNear(mem,gxi,gyi,10);
  if(goal < 0) goal = start;
  if(start === goal){
    mem.path = [start];
    mem.pathIdx = 0;
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = t;
    return true;
  }

  const dist = mem.dist;
  const par = mem.par;
  const q = mem.q;
  for(let i=0;i<n;i++) dist[i] = -1;
  let qh = 0, qt = 0;
  dist[start] = 0;
  par[start] = -1;
  q[qt++] = start;
  let found = false;
  let best = start;
  let bestD = 1e100;
  const gxCell = goal % gw;
  const gyCell = (goal / gw) | 0;

  while(qh < qt && qh < n){
    const cur = q[qh++];
    const cx = cur % gw;
    const cy = (cur / gw) | 0;
    if(cur === goal){ found = true; break; }
    const ddx = cx - gxCell;
    const ddy = cy - gyCell;
    const dd = ddx*ddx + ddy*ddy;
    if(dd < bestD){ bestD = dd; best = cur; }
    const nd = dist[cur] + 1;

    for(let k=0;k<8;k++){
      const nx = cx + DX8[k];
      const ny = cy + DY8[k];
      if(nx < 1 || ny < 1 || nx >= gw-1 || ny >= mem.gh-1) continue;
      const ni = ny*gw + nx;
      if(dist[ni] !== -1) continue;
      if(cellBlocked(mem,nx,ny)) continue;
      if(k >= 4){
        if(cellBlocked(mem,cx+DX8[k],cy) || cellBlocked(mem,cx,cy+DY8[k])) continue;
      }
      dist[ni] = nd;
      par[ni] = cur;
      q[qt++] = ni;
      if(qt >= n) break;
    }
  }

  const end = found ? goal : best;
  const arr = [];
  let cur = end;
  let guard = 0;
  while(cur !== -1 && guard++ < n+10){
    arr.push(cur);
    if(cur === start) break;
    cur = par[cur];
  }
  if(arr.length === 0 || arr[arr.length-1] !== start){
    mem.path = [];
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = t;
    return false;
  }
  arr.reverse();
  mem.path = arr;
  mem.pathIdx = 0;
  mem.pathGoal = {x:gx,y:gy};
  mem.lastPlan = t;
  return true;
}

function ensurePath(obs,mem,gx,gy,t){
  let need = false;
  if(!mem.path || mem.path.length < 1) need = true;
  else if(!mem.pathGoal || hyp(mem.pathGoal.x-gx,mem.pathGoal.y-gy) > 2.5) need = true;
  else if(mem.pathDirty) need = true;
  else if(t - mem.lastPlan > 2.2) need = true;
  if(need && t - mem.lastPlan > 0.25){
    planPath(mem,gx,gy,t);
    mem.pathDirty = false;
  }
}

function getWaypoint(mem){
  const p = mem.path;
  if(!p || p.length === 0) return null;
  const gw = mem.gw;
  let idx = mem.pathIdx || 0;
  const px = mem.pos.x;
  const py = mem.pos.y;
  while(idx < p.length-1){
    const id = p[idx];
    const x = (id % gw) * mem.res;
    const y = ((id / gw) | 0) * mem.res;
    if(hyp(x-px,y-py) < 1.6) idx++;
    else break;
  }
  mem.pathIdx = idx;

  let chosen = idx;
  for(let k=idx;k<p.length && k<idx+8;k++){
    const id = p[k];
    const x = (id % gw) * mem.res;
    const y = ((id / gw) | 0) * mem.res;
    const d = hyp(x-px,y-py);
    chosen = k;
    if(d > 3.0) break;
  }
  const id = p[chosen];
  return {x:(id % gw)*mem.res, y:((id / gw)|0)*mem.res};
}

function clearLine(mem,x1,y1,x2,y2){
  const dx = x2-x1, dy = y2-y1;
  const d = hyp(dx,dy);
  if(d < 0.05) return true;
  const n = Math.ceil(d / 1.0);
  for(let i=1;i<n;i++){
    const f = i/n;
    if(blockedWorld(mem,x1+dx*f,y1+dy*f)) return false;
  }
  return true;
}

function wheelCmd(target,meas,st,dt){
  target = clamp(target,-3.2,3.2);
  const zero = Math.abs(target) < 0.02;
  if(st.prev !== undefined && st.prev * target < 0 && Math.abs(target) > 0.1) st.i *= 0.25;
  st.prev = target;

  const err = target - meas;
  const kp = zero ? 1.1 : 0.34;
  const ki = zero ? 1.0 : 0.55;
  st.i += err * dt * ki;
  st.i = clamp(st.i,-0.9,0.9);
  let u = target/3.0 + kp*err + st.i;

  if(u > 1){
    u = 1;
    if(err > 0) st.i -= err * dt * ki;
  } else if(u < -1){
    u = -1;
    if(err < 0) st.i -= err * dt * ki;
  }

  if(zero && Math.abs(meas) < 0.03) st.i *= Math.exp(-dt*2.0);
  if(Math.abs(target) > 0.03 && Math.abs(u) < 0.05) u = (target > 0 ? 0.05 : -0.05);
  return clamp(u,-1,1);
}

function brakeCmd(obs,mem){
  mem.wantV = 0;
  return {
    left:wheelCmd(0,Number(obs.wheelLeft)||0,mem.ctlL,mem.dt),
    right:wheelCmd(0,Number(obs.wheelRight)||0,mem.ctlR,mem.dt),
    drill:false
  };
}

function steerToBearing(obs,mem,desired,vdes,opt){
  opt = opt || {};
  const rays = obs.rays || [];
  const head = mem.head;
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let front = 15;
  let leftOpen = 0, rightOpen = 0;

  for(let i=0;i<9;i++){
    let r = Number(rays[i]);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i >= 3 && i <= 5 && r < front) front = r;
    if(i > 4) leftOpen += Math.min(r,8);
    else if(i < 4) rightOpen += Math.min(r,8);

    if(r < 6.0){
      const ang = head + RAYR[i];
      let w = (6.0-r)/6.0;
      if(i === 4) w *= 2.2;
      else if(i >= 3 && i <= 5) w *= 1.6;
      else w *= 0.7;
      if(r < 1.5) w *= 2.0;
      vx -= Math.cos(ang) * w * 1.35;
      vy -= Math.sin(ang) * w * 1.35;
    }
  }

  const m = 6.0;
  if(mem.pos.x < m) vx += (m-mem.pos.x)/m * 2.2;
  if(mem.pos.x > mem.size-m) vx -= (mem.pos.x-(mem.size-m))/m * 2.2;
  if(mem.pos.y < m) vy += (m-mem.pos.y)/m * 2.2;
  if(mem.pos.y > mem.size-m) vy -= (mem.pos.y-(mem.size-m))/m * 2.2;

  if(hyp(vx,vy) > 0.05) desired = Math.atan2(vy,vx);
  let err = wrap(desired - head);
  let w;

  if(front < 1.3){
    vdes = 0;
    const turn = (leftOpen >= rightOpen ? 1 : -1);
    w = turn * 1.2;
  } else {
    if(front < 8){
      const cap = Math.max(0,(front-0.9)*0.7);
      if(vdes > cap) vdes = cap;
    }
    if(front < 1.8 && Math.abs(err) < 0.7) vdes = Math.min(vdes,0.15);

    const maxw = 1.8;
    w = clamp(err*2.3,-maxw,maxw);
    if(Math.abs(err) > 1.0){
      vdes = 0;
      w = clamp((err > 0 ? 1 : -1) * (1.0 + 0.5*Math.abs(err)), -maxw, maxw);
    } else {
      vdes *= Math.max(0.1, 1 - Math.abs(err)*0.55);
    }
  }

  let cap = 3.0;
  if(obs.battery < 0.12) cap = 0.8;
  else if(obs.battery < 0.22) cap = 1.3;
  const carried = obs.carried || 0;
  if(carried > 0) cap *= Math.max(0.72,1-0.035*carried);
  if(mem.slip < 0.65) cap *= 0.8;
  if(vdes > cap) vdes = cap;
  if(vdes < -1.5) vdes = -1.5;

  let vL = vdes - w * 0.3;
  let vR = vdes + w * 0.3;
  vL = clamp(vL,-3.2,3.2);
  vR = clamp(vR,-3.2,3.2);

  mem.wantV = vdes;
  return {
    left:wheelCmd(vL,Number(obs.wheelLeft)||0,mem.ctlL,mem.dt),
    right:wheelCmd(vR,Number(obs.wheelRight)||0,mem.ctlR,mem.dt),
    drill:false
  };
}

function navigate(obs,mem,gx,gy,opt){
  opt = opt || {};
  const dx = gx - mem.pos.x;
  const dy = gy - mem.pos.y;
  const d = hyp(dx,dy);
  const arrive = opt.arrive !== undefined ? opt.arrive : 0.8;
  if(d <= arrive){
    return brakeCmd(obs,mem);
  }

  let targetX = gx;
  let targetY = gy;
  let direct = opt.direct || false;
  const directDist = opt.directDist !== undefined ? opt.directDist : 5;

  if(!direct && d > directDist){
    if(d < 12 && clearLine(mem,mem.pos.x,mem.pos.y,gx,gy)){
      direct = true;
    } else {
      ensurePath(obs,mem,gx,gy,mem.t);
      const wp = getWaypoint(mem);
      if(wp && hyp(wp.x-mem.pos.x,wp.y-mem.pos.y) > 0.4){
        targetX = wp.x;
        targetY = wp.y;
      } else {
        direct = true;
      }
    }
  }

  const bearing = Math.atan2(targetY-mem.pos.y,targetX-mem.pos.x);
  let speed = opt.speed !== undefined ? opt.speed : 1.8;
  const slow = opt.slow !== undefined ? opt.slow : 5.0;
  if(d < slow){
    const f = clamp((d-arrive)/Math.max(0.4,slow-arrive),0.15,1);
    speed *= f;
  }
  return steerToBearing(obs,mem,bearing,speed,opt);
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++) if(mem.sites[i].id === id) return mem.sites[i];
  return null;
}

function findSiteNear(mem,x,y){
  let best = null, bd = 25;
  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    const dx = s.x-x, dy = s.y-y;
    const d2 = dx*dx+dy*dy;
    if(d2 < bd){ bd = d2; best = s; }
  }
  return best;
}

function markNearestHintDone(mem,x,y){
  let best = -1;
  let bd = 35*35;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x, dy = h.y-y;
    const d2 = dx*dx+dy*dy;
    if(d2 < bd){ bd = d2; best = i; }
  }
  if(best >= 0) mem.hints[best].status = 2;
}

function acceptSite(obs,mem,vis){
  if(!vis) return false;
  const carried = obs.carried || 0;
  if(carried >= mem.cap) return false;
  if(!(vis.value > 0)) return false;
  if(carried < mem.cap-1) return true;
  const maxv = Math.max(0.000001,mem.maxHintVal);
  if(vis.value >= 0.04*maxv) return true;
  if((obs.timeLeft||0) < 260) return true;
  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  if(bd < 40) return true;
  return false;
}

function cancelActive(mem){
  if(mem.search){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status === 1) h.status = 0;
    mem.search = null;
  }
  mem.task = null;
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
}

function beginSearch(obs,mem,h){
  const pts = [];
  const maxR = 20;
  const pitch = 8;
  const dth = 0.18;
  const thMax = TWO_PI * maxR / pitch;
  pts.push({x:clamp(h.x,1.5,mem.size-1.5), y:clamp(h.y,1.5,mem.size-1.5)});
  for(let th=0.1; th<=thMax; th+=dth){
    const r = pitch * th / TWO_PI;
    if(r < 0.6) continue;
    const x = clamp(h.x + Math.cos(th)*r,1.5,mem.size-1.5);
    const y = clamp(h.y + Math.sin(th)*r,1.5,mem.size-1.5);
    pts.push({x:x,y:y});
  }
  mem.search = {
    hintId:h.id,
    cx:h.x,
    cy:h.y,
    pts:pts,
    idx:0,
    startT:obs.t,
    lastX:mem.pos.x,
    lastY:mem.pos.y,
    travel:0,
    checked:false,
    ptStart:obs.t,
    lastDist:undefined
  };
  h.status = 1;
  mem.mode = 'search';
  mem.task = null;
  mem.path = [];
  mem.pathDirty = true;
  return true;
}

function finishSearch(mem,done){
  if(mem.search){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status === 1) h.status = done ? 2 : 0;
  }
  mem.search = null;
  mem.task = null;
  mem.mode = 'idle';
  mem.path = [];
  mem.pathDirty = true;
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){ mem.mode = 'idle'; return brakeCmd(obs,mem); }
  const h = mem.hints[S.hintId];
  if(!h || h.status >= 2){ finishSearch(mem,true); return brakeCmd(obs,mem); }

  const step = hyp(mem.pos.x-S.lastX,mem.pos.y-S.lastY);
  S.travel += step;
  S.lastX = mem.pos.x;
  S.lastY = mem.pos.y;

  if(!S.checked && hyp(mem.pos.x-S.cx,mem.pos.y-S.cy) < 2.2){
    S.checked = true;
    const sci = Number(obs.science)||0;
    if(sci <= 0 && !obs.site){
      finishSearch(mem,true);
      return brakeCmd(obs,mem);
    }
  }

  if(obs.t - S.startT > 115 || S.travel > 220){
    finishSearch(mem,true);
    return brakeCmd(obs,mem);
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    const d = hyp(p.x-mem.pos.x,p.y-mem.pos.y);
    if(d < 1.5){
      S.idx++;
      S.ptStart = obs.t;
      S.lastDist = undefined;
      mem.path = [];
      mem.pathDirty = true;
    } else break;
  }

  if(S.idx >= S.pts.length){
    finishSearch(mem,true);
    return brakeCmd(obs,mem);
  }

  const p = S.pts[S.idx];
  const d = hyp(p.x-mem.pos.x,p.y-mem.pos.y);
  if(!S.ptStart) S.ptStart = obs.t;
  if(S.lastDist === undefined) S.lastDist = d;

  let skip = false;
  if(obs.t - S.ptStart > 18){
    if(d > 2.0 || (S.lastDist - d) < 0.2) skip = true;
  }
  if(obs.t - S.ptStart > 30) skip = true;
  if(skip){
    S.idx++;
    S.ptStart = obs.t;
    S.lastDist = undefined;
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }
  S.lastDist = d;

  let speed = 1.5;
  if(obs.battery < 0.25) speed = 1.0;
  if((obs.carried||0) > 0) speed = 1.35;
  return navigate(obs,mem,p.x,p.y,{speed:speed,arrive:1.2,slow:5.0});
}

function doTravel(obs,mem){
  const task = mem.task;
  if(!task){ mem.mode='idle'; return brakeCmd(obs,mem); }

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.task = null; mem.mode='idle'; return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.task = null; mem.mode='idle'; return brakeCmd(obs,mem);
    }
    const d = hyp(h.x-mem.pos.x,h.y-mem.pos.y);
    if(d < 2.6){
      beginSearch(obs,mem,h);
      return doSearch(obs,mem);
    }
    const sci = Number(obs.science)||0;
    if(d < 15 && sci <= 0 && !obs.site){
      h.status = 2;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs,mem);
    }
    if(obs.t - task.startT > 250 && d > 8){
      h.status = 2;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs,mem);
    }
    let speed = 2.1;
    if((obs.carried||0) > 0) speed = 1.9;
    if(obs.battery < 0.25) speed = 1.4;
    return navigate(obs,mem,h.x,h.y,{speed:speed,arrive:2.4,slow:8.0});
  }

  if(task.type === 'site'){
    const s = findSiteById(mem,task.id);
    if(!s || s.sampled){
      mem.task = null; mem.mode='idle'; return brakeCmd(obs,mem);
    }
    const d = hyp(s.x-mem.pos.x,s.y-mem.pos.y);
    if(d < 2.5){
      s.ignoreUntil = obs.t + 60;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs,mem);
    }
    if(obs.t - task.startT > 220 && d > 10){
      s.ignoreUntil = obs.t + 80;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs,mem);
    }
    let speed = 1.9;
    if((obs.carried||0) > 0) speed = 1.7;
    return navigate(obs,mem,s.x,s.y,{speed:speed,arrive:1.6,slow:6.0});
  }

  if(task.type === 'roam'){
    const d = hyp(task.x-mem.pos.x,task.y-mem.pos.y);
    if(d < 4 || obs.t - task.startT > 160){
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      return brakeCmd(obs,mem);
    }
    return navigate(obs,mem,task.x,task.y,{speed:1.7,arrive:3.0,slow:7.0});
  }

  mem.task = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function doApproach(obs,mem){
  if(!mem.approach){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const app = mem.approach;
  const os = obs.site;
  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const maxWheel = Math.max(Math.abs(wl),Math.abs(wr));

  if(os){
    const dist = Number(os.distance)||0;
    const bearing = Number(os.bearing)||0;
    const ang = mem.head + bearing * D2R;
    const sx = mem.pos.x + Math.cos(ang) * dist;
    const sy = mem.pos.y + Math.sin(ang) * dist;
    if(hyp(sx-app.x,sy-app.y) > 5){
      app.x = sx;
      app.y = sy;
      app.value = Number(os.value)||0;
      app.startT = obs.t;
    } else {
      app.x += (sx-app.x)*0.28;
      app.y += (sy-app.y)*0.28;
      app.value = Number(os.value)||0;
      app.lastSeen = obs.t;
    }

    if(dist < 1.45){
      if(maxWheel < 0.15){
        const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
        const need = returnBatteryNeed(mem,obs,bd,obs.carried||0);
        const safeB = obs.battery > need + 6*mem.drillRate + 0.02;
        const safeT = obs.timeLeft > bd/0.85 + 8 + 6;
        if(safeB && safeT && (obs.carried||0) < mem.cap){
          mem.mode = 'drill';
          mem.drill = {
            x:mem.pos.x,
            y:mem.pos.y,
            sx:app.x,
            sy:app.y,
            value:app.value,
            before:obs.carried||0,
            startT:obs.t,
            started:false,
            abort:false
          };
          mem.approach = null;
          return handleDrill(obs,mem);
        } else {
          if(mem.visibleSite){
            const s = findSiteById(mem,mem.visibleSite.id);
            if(s) s.ignoreUntil = obs.t + 90;
          }
          mem.approach = null;
          mem.mode = ((obs.carried||0) > 0 || obs.battery < need+0.05) ? 'return' : 'idle';
          mem.path = [];
          mem.pathDirty = true;
          return brakeCmd(obs,mem);
        }
      } else {
        return brakeCmd(obs,mem);
      }
    }

    let speed = clamp((dist-1.2)*0.45,0.04,0.85);
    const desired = mem.head + bearing * D2R;
    return steerToBearing(obs,mem,desired,speed,{});
  }

  const dx = app.x - mem.pos.x;
  const dy = app.y - mem.pos.y;
  const d = hyp(dx,dy);
  if(d < 0.8){
    mem.approach = null;
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  if(obs.t - app.startT > 25){
    mem.approach = null;
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  let speed = clamp((d-0.3)*0.5,0.08,0.8);
  return steerToBearing(obs,mem,Math.atan2(dy,dx),speed,{});
}

function handleDrill(obs,mem){
  const d = mem.drill;
  if(!d){ mem.mode='idle'; return brakeCmd(obs,mem); }
  const carried = obs.carried || 0;

  if(carried > d.before){
    for(let i=0;i<mem.sites.length;i++){
      const s = mem.sites[i];
      if(s.sampled) continue;
      const dx1 = s.x - d.sx, dy1 = s.y - d.sy;
      const dx2 = s.x - d.x, dy2 = s.y - d.y;
      if(dx1*dx1+dy1*dy1 < 20 || dx2*dx2+dy2*dy2 < 20) s.sampled = true;
    }
    markNearestHintDone(mem,d.sx,d.sy);

    mem.drill = null;
    mem.approach = null;
    mem.search = null;
    mem.task = null;
    mem.sampledCount++;
    mem.path = [];
    mem.pathDirty = true;

    if(carried >= mem.cap){
      mem.mode = 'return';
    } else {
      const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
      const need = returnBatteryNeed(mem,obs,bd,carried);
      const timeNeed = bd/0.85 + 12;
      mem.mode = (obs.battery < need + 0.03 || obs.timeLeft < timeNeed + 8) ? 'return' : 'idle';
    }
    return brakeCmd(obs,mem);
  }

  const drilling = Number(obs.drilling)||0;
  const os = obs.site;
  const siteDist = os ? (Number(os.distance)||99) : 99;
  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const maxWheel = Math.max(Math.abs(wl),Math.abs(wr));

  if(!d.started){
    if(os && siteDist < 1.55 && maxWheel < 0.15) d.started = true;
    else if(os && siteDist < 1.60 && maxWheel < 0.20) d.started = true;
    else if(!os && drilling > 0) d.started = true;
  }

  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const need = returnBatteryNeed(mem,obs,bd,carried);
  const remain = Math.max(0,6-drilling);
  const safeB = obs.battery > need + remain*mem.drillRate + 0.01;
  const safeT = obs.timeLeft > bd/0.85 + remain + 6;

  if(d.started && ((!safeB && drilling < 5.7) || (!safeT && drilling < 5.7))) d.abort = true;
  if(d.started && os && siteDist > 1.8 && drilling < 0.2) d.abort = true;
  if(d.started && os && siteDist > 2.2) d.abort = true;
  if(!d.started && obs.t - d.startT > 8) d.abort = true;
  if(d.started && obs.t - d.startT > 20 && drilling < 5.8 && carried <= d.before) d.abort = true;

  if(d.abort){
    const s = findSiteNear(mem,d.sx,d.sy);
    if(s) s.ignoreUntil = obs.t + 60;
    mem.drill = null;
    mem.approach = null;
    mem.mode = ((carried > 0) || obs.battery < need+0.05 || obs.timeLeft < bd/0.8+12) ? 'return' : 'idle';
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }

  let targetL = 0;
  let targetR = 0;
  if(d.started && drilling < 5.9){
    const dx = d.x - mem.pos.x;
    const dy = d.y - mem.pos.y;
    const de = hyp(dx,dy);
    if(de > 0.5){
      const desired = Math.atan2(dy,dx);
      const err = wrap(desired - mem.head);
      const v = clamp(de*0.3,0,0.08);
      const w = clamp(err*1.5,-0.15,0.15);
      targetL = v - w*0.3;
      targetR = v + w*0.3;
    }
  }

  mem.wantV = 0;
  return {
    left:wheelCmd(targetL,Number(obs.wheelLeft)||0,mem.ctlL,mem.dt),
    right:wheelCmd(targetR,Number(obs.wheelRight)||0,mem.ctlR,mem.dt),
    drill: d.started && !d.abort
  };
}

function doReturn(obs,mem){
  const bdGPS = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  let d = bdGPS;
  let desired = Math.atan2(mem.base.y-mem.pos.y,mem.base.x-mem.pos.x);

  const beacon = obs.beacon;
  if(beacon && isFinite(Number(beacon.distance)) && isFinite(Number(beacon.bearing))){
    const bdist = Number(beacon.distance);
    const bbearing = Number(beacon.bearing);
    const gpsAng = desired;
    const beaconAng = wrap(mem.head + bbearing*D2R);
    const diff = Math.abs(wrap(beaconAng - gpsAng));
    if(bdist < 20 && (diff < 1.0 || mem.gpsStale || bdist < 5)){
      d = bdist;
      desired = mem.head + bbearing*D2R;
    }
  }

  if(d < 3.0){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  let speed = 1.8;
  if((obs.carried||0) > 0) speed = 1.7;
  if(obs.battery < 0.20) speed = 1.1;
  if(bdGPS > 0 && obs.battery < returnBatteryNeed(mem,obs,bdGPS,obs.carried||0) + 0.10) speed = Math.min(speed,1.2);
  if(d < 8) speed = Math.min(speed,0.9);
  if(d < 5) speed = Math.min(speed,0.55);
  return steerToBearing(obs,mem,desired,speed,{});
}

function startRecovery(obs,mem,isBump){
  mem.recoverUntil = obs.t + 1.6;
  mem.recoverBackUntil = obs.t + 0.8;
  const rays = obs.rays || [];
  let left = 0, right = 0;
  for(let i=0;i<9;i++){
    let r = Number(rays[i]);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i > 4) left += Math.min(r,10);
    else if(i < 4) right += Math.min(r,10);
  }
  if(Math.abs(left-right) < 0.01) mem.recoverTurn = (mem.recoverTurn === 1 ? -1 : 1);
  else mem.recoverTurn = (left >= right ? 1 : -1);

  const bx = mem.pos.x + Math.cos(mem.head) * (isBump ? 0.8 : 0.9);
  const by = mem.pos.y + Math.sin(mem.head) * (isBump ? 0.8 : 0.9);
  markHard(mem,bx,by);
  mem.path = [];
  mem.pathDirty = true;
  mem.stallT = 0;
  mem.ctlL.i = 0;
  mem.ctlR.i = 0;
  mem.recoverCount = (mem.recoverCount||0) + 1;

  if(mem.recoverCount > 3){
    if(mem.search){
      const h = mem.hints[mem.search.hintId];
      if(h) h.status = 2;
      mem.search = null;
    }
    if(mem.task && mem.task.type === 'hint'){
      const h = mem.hints[mem.task.id];
      if(h) h.status = 2;
    }
    if(mem.task && mem.task.type === 'site'){
      const s = findSiteById(mem,mem.task.id);
      if(s) s.ignoreUntil = obs.t + 90;
    }
    mem.task = null;
    mem.approach = null;
    mem.mode = 'idle';
    mem.recoverCount = 0;
  }
}

function doRecovery(obs,mem){
  let v = 0;
  let w = 0;
  if(obs.t < mem.recoverBackUntil){
    v = -0.45;
    w = mem.recoverTurn * 0.40;
  } else {
    v = 0;
    w = mem.recoverTurn * 1.20;
  }
  let vL = clamp(v - w*0.3,-1.2,1.2);
  let vR = clamp(v + w*0.3,-1.2,1.2);
  mem.wantV = v;
  return {
    left:wheelCmd(vL,Number(obs.wheelLeft)||0,mem.ctlL,mem.dt),
    right:wheelCmd(vR,Number(obs.wheelRight)||0,mem.ctlR,mem.dt),
    drill:false
  };
}

function chooseTask(obs,mem){
  if(mem.skipTask && obs.t > mem.skipUntil){ mem.skipTask = null; mem.skipUntil = 0; }
  const carried = obs.carried || 0;
  const atBase = !!obs.docked || hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y) < 3.5;
  let activeHints = 0;
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].status === 0) activeHints++;

  if(carried >= mem.cap){
    mem.mode = 'return';
    mem.task = null;
    mem.search = null;
    mem.path = [];
    mem.pathDirty = true;
    return false;
  }

  let best = null;
  let bestScore = -1e100;
  const maxv = Math.max(0.000001,mem.maxHintVal);

  function consider(task,value,isSite,isPseudo){
    const key = task.type + ':' + task.id;
    if(mem.skipTask === key && obs.t < mem.skipUntil) return;
    const met = taskMetrics(mem,obs,task);
    if(met.batt > 1.18) return;
    if(met.time > (obs.timeLeft||0) - 4) return;
    if(!atBase && met.batt > (obs.battery||0) - 0.03) return;

    const d1 = hyp(task.x-mem.pos.x,task.y-mem.pos.y);
    const d2 = hyp(task.x-mem.base.x,task.y-mem.base.y);
    const sd = (task.type === 'hint') ? 24 : (task.type === 'roam' ? 10 : 4);
    let score = Math.pow(Math.max(0.001,value),1.10) / (d1 + 0.48*d2 + sd + 30);
    if(carried >= mem.cap-1) score *= 1 + 2.0*(value/maxv);
    if((obs.timeLeft||0) < 320) score *= 1 + 0.9*(value/maxv);
    if(isSite) score *= 1.15;
    if(isPseudo) score *= 0.75;
    if(score > bestScore){
      bestScore = score;
      best = {task:task,value:value};
    }
  }

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    const task = {type:'hint',id:h.id,x:h.x,y:h.y,v:h.v,startT:obs.t};
    consider(task,h.v,false,h.pseudo);
  }

  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(s.ignoreUntil && s.ignoreUntil > obs.t) continue;
    const task = {type:'site',id:s.id,x:s.x,y:s.y,v:s.value,startT:obs.t};
    consider(task,s.value,true,false);
  }

  if(best){
    mem.task = best.task;
    mem.mode = 'travel';
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathDirty = true;
    return true;
  }

  if(carried > 0){
    mem.mode = 'return';
    mem.task = null;
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathDirty = true;
    return false;
  }

  const sci = Number(obs.science)||0;
  if(sci > 1e-12 && mem.pseudoSearches < 3 && (obs.timeLeft||0) > 80 && (obs.battery||0) > 0.35){
    const h = {
      id:mem.hints.length,
      x:mem.pos.x,
      y:mem.pos.y,
      v:Math.max(0.1,mem.maxHintVal*0.45),
      status:0,
      pseudo:true
    };
    mem.hints.push(h);
    mem.pseudoSearches++;
    mem.task = {type:'hint',id:h.id,x:h.x,y:h.y,v:h.v,startT:obs.t};
    mem.mode = 'travel';
    mem.path = [];
    mem.pathDirty = true;
    return true;
  }

  if(activeHints === 0 && mem.roams < 2 && (obs.timeLeft||0) > 150 && (obs.battery||0) > 0.60){
    mem.roams++;
    const seed = (mem.rng + mem.roams*1013904223) >>> 0;
    mem.rng = seed;
    const frac = ((Math.sin(seed*0.000001)*10000)%1 + 1)%1;
    const ang = frac * TWO_PI;
    const rad = 60 + 90*frac;
    const tx = clamp(mem.pos.x + Math.cos(ang)*rad,6,mem.size-6);
    const ty = clamp(mem.pos.y + Math.sin(ang)*rad,6,mem.size-6);
    mem.task = {type:'roam',id:-1,x:tx,y:ty,v:0.5,startT:obs.t};
    mem.mode = 'travel';
    mem.path = [];
    mem.pathDirty = true;
    return true;
  }

  if(atBase){
    mem.mode = 'idle';
    return false;
  }

  mem.mode = 'return';
  mem.task = null;
  mem.path = [];
  mem.pathDirty = true;
  return false;
}

function handleDocked(obs,mem){
  if((obs.carried||0) > 0){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }
  if((obs.timeLeft||0) < 5){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }
  if(mem.mode === 'return') mem.mode = 'idle';

  if(mem.visibleSite && acceptSite(obs,mem,mem.visibleSite)){
    if(mem.search){
      const h = mem.hints[mem.search.hintId];
      if(h && h.status === 1) h.status = 0;
    }
    mem.search = null;
    mem.task = null;
    mem.path = [];
    mem.pathDirty = true;
    mem.mode = 'approach';
    mem.approach = {
      x:mem.visibleSite.x,
      y:mem.visibleSite.y,
      value:mem.visibleSite.value,
      startT:obs.t,
      lastSeen:obs.t
    };
    return doApproach(obs,mem);
  }

  if(mem.task && mem.task.type === 'hint'){
    const h = mem.hints[mem.task.id];
    if(!h || h.status >= 2) mem.task = null;
  } else if(mem.task && mem.task.type === 'site'){
    const s = findSiteById(mem,mem.task.id);
    if(!s || s.sampled) mem.task = null;
  }

  if(!mem.task) chooseTask(obs,mem);
  if(!mem.task){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  let met = taskMetrics(mem,obs,mem.task);
  if(met.batt > 1.18){
    mem.skipTask = mem.task.type + ':' + mem.task.id;
    mem.skipUntil = obs.t + 120;
    mem.task = null;
    mem.mode = 'idle';
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  if((obs.battery||0) < met.batt + 0.03){
    mem.dockWait = (mem.dockWait||0) + mem.dt;
    const timeShort = (obs.timeLeft||0) < met.time + 10;
    if(timeShort && (obs.battery||0) > 0.35){
      mem.dockWait = 0;
    } else if(mem.dockWait > 50 && (obs.battery||0) < met.batt*0.8 && (obs.timeLeft||0) > 150){
      mem.skipTask = mem.task.type + ':' + mem.task.id;
      mem.skipUntil = obs.t + 90;
      mem.task = null;
      mem.mode = 'idle';
      mem.dockWait = 0;
      chooseTask(obs,mem);
      if(!mem.task){ mem.wantV = 0; return brakeCmd(obs,mem); }
      met = taskMetrics(mem,obs,mem.task);
      if((obs.battery||0) < met.batt + 0.03){
        mem.wantV = 0;
        return brakeCmd(obs,mem);
      }
    } else {
      mem.wantV = 0;
      return brakeCmd(obs,mem);
    }
  }

  mem.dockWait = 0;
  mem.mode = 'travel';
  mem.search = null;
  mem.path = [];
  mem.pathDirty = true;
  return doTravel(obs,mem);
}

function act(obs,mem){
  if(!mem.init) initMission(obs,mem);

  updateSensors(obs,mem);
  updateGrid(obs,mem);
  updateSites(obs,mem);
  updateEnergy(obs,mem);

  mem.tick = (mem.tick||0) + 1;
  if(mem.tick === 1){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  if(mem.gpsNew && mem.lastGpsMoved > 0.02){
    mem.goodT = (mem.goodT||0) + mem.dt;
    if(mem.goodT > 1.0) mem.recoverCount = 0;
  } else {
    mem.goodT = 0;
  }

  if(mem.mode === 'drill'){
    return handleDrill(obs,mem);
  }

  if(obs.docked){
    return handleDocked(obs,mem);
  }

  if(mem.recoverUntil > mem.t){
    return doRecovery(obs,mem);
  }

  if(obs.bumped){
    startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const measSpeed = Math.abs((wl + wr)/2);
  const want = Math.abs(mem.wantV||0);
  if(want > 0.4 && measSpeed < Math.max(0.05,want*0.15) && Math.abs(wl-wr) < 0.2){
    mem.stallT = (mem.stallT||0) + mem.dt;
    if(mem.stallT > 1.5){
      mem.stallT = 0;
      startRecovery(obs,mem,false);
      return doRecovery(obs,mem);
    }
  } else {
    mem.stallT = 0;
  }

  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const carried = obs.carried || 0;
  const needB = returnBatteryNeed(mem,obs,bd,carried);
  const needT = bd/0.85 + 12;

  if(carried > 0 && bd < 4 && mem.mode !== 'return' && mem.mode !== 'drill' && mem.mode !== 'approach'){
    cancelActive(mem);
    mem.mode = 'return';
  }

  let critical = false;
  if(carried > 0){
    if(carried >= mem.cap || (obs.battery||0) < needB + 0.04 || (obs.timeLeft||0) < needT + 8) critical = true;
  }
  if(bd > 5 && (obs.battery||0) < needB + 0.02) critical = true;

  if(critical && mem.mode !== 'return' && mem.mode !== 'drill'){
    cancelActive(mem);
    mem.mode = 'return';
  }

  const vis = mem.visibleSite;
  if(vis && mem.mode !== 'drill' && mem.mode !== 'return'){
    if(acceptSite(obs,mem,vis)){
      if(mem.mode !== 'approach'){
        cancelActive(mem);
        mem.mode = 'approach';
        mem.approach = {
          x:vis.x,
          y:vis.y,
          value:vis.value,
          startT:obs.t,
          lastSeen:obs.t
        };
      } else if(mem.approach){
        if(hyp(vis.x-mem.approach.x,vis.y-mem.approach.y) > 4){
          mem.approach.x = vis.x;
          mem.approach.y = vis.y;
          mem.approach.value = vis.value;
          mem.approach.startT = obs.t;
        } else {
          mem.approach.x += (vis.x-mem.approach.x)*0.25;
          mem.approach.y += (vis.y-mem.approach.y)*0.25;
          mem.approach.value = vis.value;
          mem.approach.lastSeen = obs.t;
        }
      }
    } else if(vis.id){
      const s = findSiteById(mem,vis.id);
      if(s && s.ignoreUntil < obs.t) s.ignoreUntil = obs.t + 45;
    }
  }

  let res;
  if(mem.mode === 'return'){
    res = doReturn(obs,mem);
  } else if(mem.mode === 'approach'){
    res = doApproach(obs,mem);
  } else if(mem.mode === 'search'){
    res = doSearch(obs,mem);
  } else if(mem.mode === 'travel'){
    res = doTravel(obs,mem);
  } else {
    if(!mem.task) chooseTask(obs,mem);
    if(mem.mode === 'travel') res = doTravel(obs,mem);
    else if(mem.mode === 'search') res = doSearch(obs,mem);
    else if(mem.mode === 'approach') res = doApproach(obs,mem);
    else if(mem.mode === 'return') res = doReturn(obs,mem);
    else res = brakeCmd(obs,mem);
  }

  return res;
}

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const RAY_ANG = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];
const DX8 = [1,0,-1,0,1,1,-1,-1];
const DY8 = [0,1,0,-1,1,-1,1,-1];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % (2*PI);
  if(a > PI) a -= 2*PI;
  if(a < -PI) a += 2*PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function fin(v,d){ return (typeof v === 'number' && isFinite(v)) ? v : d; }

function initMission(obs,mem){
  mem.init = true;
  mem.tick = 0;
  mem.t = fin(obs.t,0);
  mem.dt = 0.1;
  const M = obs.mission || {};
  mem.size = fin(M.size,400);
  const base = M.base || {x:fin(obs.x,0), y:fin(obs.y,0)};
  mem.base = {x:fin(base.x,fin(obs.x,0)), y:fin(base.y,fin(obs.y,0))};
  mem.cap = Math.max(1, Math.floor(fin(M.capacity,5)));
  mem.hints = [];
  const hs = Array.isArray(M.hints) ? M.hints : [];
  for(let i=0;i<hs.length;i++){
    const h = hs[i] || {};
    let x = fin(h.x,NaN), y = fin(h.y,NaN), v = fin(h.estimate,0.1);
    if(!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x,0,mem.size);
    y = clamp(y,0,mem.size);
    if(!(v > 0)) v = 0.1;
    mem.hints.push({id:mem.hints.length,x:x,y:y,v:v,status:0,pseudo:false});
  }
  mem.maxHintVal = 1;
  for(let i=0;i<mem.hints.length;i++) mem.maxHintVal = Math.max(mem.maxHintVal, mem.hints[i].v);

  mem.res = 2;
  mem.gw = Math.ceil(mem.size / mem.res) + 2;
  mem.gh = mem.gw;
  mem.n = mem.gw * mem.gh;
  mem.obsc = new Uint8Array(mem.n);
  mem.freec = new Uint8Array(mem.n);
  mem.dist = new Int32Array(mem.n);
  mem.par = new Int32Array(mem.n);
  mem.q = new Int32Array(mem.n);

  mem.pos = {x:clamp(fin(obs.x,0),0.3,mem.size-0.3), y:clamp(fin(obs.y,0),0.3,mem.size-0.3)};
  mem.lastGX = fin(obs.x,mem.pos.x);
  mem.lastGY = fin(obs.y,mem.pos.y);
  mem.gpsStaleT = 0;

  mem.head = fin(obs.heading,0) * D2R;
  mem.rawHead = mem.head;
  mem.headPred = mem.head;
  mem.bias = 0;

  mem.wheelL = fin(obs.wheelLeft,0);
  mem.wheelR = fin(obs.wheelRight,0);
  mem.maxWheel = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  mem.vMeas = (mem.wheelL+mem.wheelR)/2;
  mem.yawMeas = (mem.wheelR-mem.wheelL)/0.6;

  mem.ctlL = {i:0,prev:0};
  mem.ctlR = {i:0,prev:0};

  mem.lastBatt = fin(obs.battery,1);
  mem.maxBattSeen = mem.lastBatt;
  mem.epm = 0.0018;
  mem.dockT = 0;
  mem.dockLastBatt = mem.lastBatt;
  mem.dockNoGainT = 0;
  mem.dockStartBatt = mem.lastBatt;

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.drill = null;
  mem.approach = null;
  mem.path = [];
  mem.pathIdx = 0;
  mem.pathGoal = null;
  mem.pathDirty = true;
  mem.lastPlan = -999;

  mem.wantV = 0;
  mem.stallT = 0;
  mem.recoverUntil = -1;
  mem.recoverBackUntil = -1;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.goodMoveT = 0;

  mem.sciMax = 0;
  mem.pseudoSearches = 0;
  mem.roamCount = 0;
  mem.rng = (Math.floor(Math.abs(mem.pos.x*1000 + mem.pos.y*137 + mem.t*19)) + 1234567) >>> 0;

  mem.ignoreX = 0;
  mem.ignoreY = 0;
  mem.ignoreUntil = -1;
  mem.sampled = [];
  mem.lastCarried = fin(obs.carried,0);
  mem.lastDelivered = fin(obs.delivered,0);
  mem.returnAfter = 1;
}

function updateSensors(obs,mem){
  let t = fin(obs.t,mem.t+0.1);
  let dt = t - mem.t;
  if(!(dt>0) || dt>1.5) dt = 0.1;
  if(dt<0.02) dt = 0.02;
  mem.dt = dt;
  mem.t = t;

  const wl = fin(obs.wheelLeft,0);
  const wr = fin(obs.wheelRight,0);
  const v = (wl+wr)/2;
  const yaw = (wr-wl)/0.6;
  mem.wheelL = wl;
  mem.wheelR = wr;
  mem.vMeas = v;
  mem.yawMeas = yaw;
  mem.maxWheel = Math.max(Math.abs(wl),Math.abs(wr));

  const raw = fin(obs.heading, mem.rawHead*R2D) * D2R;
  let pred = wrap(mem.head + yaw*dt);
  let meas = wrap(raw - mem.bias);
  let diff = wrap(meas - pred);
  let jump = Math.abs(diff) > 55*D2R && Math.abs(yaw) < 1.2;
  let head;
  if(jump){
    head = pred;
  } else {
    head = wrap(pred + wrap(meas - pred) * 0.6);
  }
  mem.head = head;
  mem.rawHead = raw;
  mem.headPred = pred;

  const gx = fin(obs.x,mem.lastGX);
  const gy = fin(obs.y,mem.lastGY);
  const moveGPS = hyp(gx-mem.lastGX, gy-mem.lastGY);
  if(moveGPS > 0.01){
    mem.gpsStaleT = 0;
  } else if(Math.abs(v) > 0.08){
    mem.gpsStaleT += dt;
  } else {
    mem.gpsStaleT = 0;
  }
  const stale = mem.gpsStaleT > 1.2;

  if(stale){
    mem.pos.x += v * Math.cos(mem.head) * dt;
    mem.pos.y += v * Math.sin(mem.head) * dt;
  } else {
    const dx = gx - mem.pos.x;
    const dy = gy - mem.pos.y;
    const d = hyp(dx,dy);
    const alpha = d > 5 ? 1.0 : 0.45;
    mem.pos.x += dx * alpha;
    mem.pos.y += dy * alpha;
  }
  mem.pos.x = clamp(mem.pos.x,0.3,mem.size-0.3);
  mem.pos.y = clamp(mem.pos.y,0.3,mem.size-0.3);

  if(!stale && Math.abs(v) > 0.25 && Math.abs(wr-wl) < 0.4){
    const gdx = gx - mem.lastGX;
    const gdy = gy - mem.lastGY;
    if(hyp(gdx,gdy) > 0.06){
      let course = Math.atan2(gdy,gdx);
      if(v < 0) course = wrap(course + PI);
      const bm = wrap(raw - course);
      if(Math.abs(bm) < 70*D2R){
        mem.bias = wrap(mem.bias*0.98 + bm*0.02);
      }
    }
  }

  const batt = fin(obs.battery,mem.lastBatt);
  if(batt > mem.maxBattSeen) mem.maxBattSeen = batt;
  const solar = fin(obs.solar,0);
  const consumed = (mem.lastBatt - batt) + solar*dt;
  if(moveGPS > 0.02 && !obs.docked && !obs.drilling){
    const load = 1 + 0.08*fin(obs.carried,0);
    const r = consumed / (moveGPS * load);
    if(r > 0.0001 && r < 0.05){
      mem.epm = mem.epm*0.98 + r*0.02;
      mem.epm = clamp(mem.epm,0.0004,0.02);
    }
  }
  mem.lastBatt = batt;
  mem.lastGX = gx;
  mem.lastGY = gy;
  mem.lastCarried = fin(obs.carried,0);
  mem.lastDelivered = fin(obs.delivered,0);
}

function markFree(mem,x,y){
  if(!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<0 || iy<0 || ix>=mem.gw || iy>=mem.gh) return;
  const idx = iy*mem.gw + ix;
  const f = mem.freec[idx];
  if(f < 255) mem.freec[idx] = f+1;
}

function markObs(mem,x,y,strength){
  if(!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<0 || iy<0 || ix>=mem.gw || iy>=mem.gh) return;
  const idx = iy*mem.gw + ix;
  const o = mem.obsc[idx];
  const add = strength || 1;
  if(o + add >= 255) mem.obsc[idx] = 255;
  else mem.obsc[idx] = o + add;
}

function updateGrid(obs,mem){
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(r < 0) r = 15;
    if(r > 15) r = 15;
    const ang = mem.head + RAY_ANG[i];
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const maxd = Math.min(r,14.5);
    for(let d=0.6; d<maxd; d+=1.0){
      markFree(mem, mem.pos.x + ca*d, mem.pos.y + sa*d);
    }
    if(r > 0.3 && r < 14.5){
      markObs(mem, mem.pos.x + ca*r, mem.pos.y + sa*r, 1);
    }
  }
  markFree(mem,mem.pos.x,mem.pos.y);
}

function cellBlocked(mem,ix,iy){
  if(ix < 1 || iy < 1 || ix >= mem.gw-1 || iy >= mem.gh-1) return true;
  const wx = ix * mem.res;
  const wy = iy * mem.res;
  if(wx < 0.8 || wx > mem.size-0.8 || wy < 0.8 || wy > mem.size-0.8) return true;
  const idx = iy*mem.gw + ix;
  const o = mem.obsc[idx];
  const f = mem.freec[idx];
  if(o >= 3 && o > f + 1) return true;
  if(o >= 2 && f < 2) return true;
  return false;
}

function nearestFree(mem,cx,cy,maxR){
  if(!cellBlocked(mem,cx,cy)) return cy*mem.gw + cx;
  for(let r=1;r<=maxR;r++){
    for(let dx=-r;dx<=r;dx++){
      for(let dy=-r;dy<=r;dy++){
        if(Math.max(Math.abs(dx),Math.abs(dy)) !== r) continue;
        const nx = cx+dx;
        const ny = cy+dy;
        if(!cellBlocked(mem,nx,ny)) return ny*mem.gw + nx;
      }
    }
  }
  return -1;
}

function planPath(mem,gx,gy){
  const gw = mem.gw;
  const n = mem.n;
  let sx = Math.round(mem.pos.x/mem.res);
  let sy = Math.round(mem.pos.y/mem.res);
  let gxi = Math.round(gx/mem.res);
  let gyi = Math.round(gy/mem.res);
  sx = clamp(sx,1,gw-2);
  sy = clamp(sy,1,mem.gh-2);
  gxi = clamp(gxi,1,gw-2);
  gyi = clamp(gyi,1,mem.gh-2);

  const start = nearestFree(mem,sx,sy,6);
  let goal = nearestFree(mem,gxi,gyi,9);
  if(start < 0){
    mem.path = [];
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = mem.t;
    return false;
  }
  if(goal < 0) goal = start;
  if(start === goal){
    mem.path = [start];
    mem.pathIdx = 0;
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = mem.t;
    return true;
  }

  mem.dist.fill(-1);
  mem.par.fill(-1);
  let qh = 0;
  let qt = 0;
  mem.dist[start] = 0;
  mem.par[start] = -1;
  mem.q[qt++] = start;
  let found = false;
  let best = start;
  let bestD = 1e100;
  const gxc = goal % gw;
  const gyc = (goal / gw) | 0;

  while(qh < qt && qh < n){
    const cur = mem.q[qh++];
    const cx = cur % gw;
    const cy = (cur / gw) | 0;
    const ddx = cx - gxc;
    const ddy = cy - gyc;
    const dd = ddx*ddx + ddy*ddy;
    if(dd < bestD){
      bestD = dd;
      best = cur;
    }
    if(cur === goal){
      found = true;
      break;
    }
    const nd = mem.dist[cur] + 1;
    for(let k=0;k<8;k++){
      const nx = cx + DX8[k];
      const ny = cy + DY8[k];
      if(nx < 1 || ny < 1 || nx >= gw-1 || ny >= mem.gh-1) continue;
      const ni = ny*gw + nx;
      if(mem.dist[ni] !== -1) continue;
      if(cellBlocked(mem,nx,ny)) continue;
      if(k >= 4){
        if(cellBlocked(mem,cx+DX8[k],cy) || cellBlocked(mem,cx,cy+DY8[k])) continue;
      }
      mem.dist[ni] = nd;
      mem.par[ni] = cur;
      mem.q[qt++] = ni;
      if(qt >= n) break;
    }
  }

  const end = found ? goal : best;
  const arr = [];
  let cur = end;
  let guard = 0;
  while(cur !== -1 && guard++ < n+10){
    arr.push(cur);
    if(cur === start) break;
    cur = mem.par[cur];
  }
  if(arr.length === 0 || arr[arr.length-1] !== start){
    mem.path = [];
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = mem.t;
    return false;
  }
  arr.reverse();
  mem.path = arr;
  mem.pathIdx = 0;
  mem.pathGoal = {x:gx,y:gy};
  mem.lastPlan = mem.t;
  return true;
}

function ensurePath(mem,gx,gy){
  let need = false;
  if(!mem.path || mem.path.length < 1) need = true;
  else if(!mem.pathGoal || hyp(mem.pathGoal.x-gx,mem.pathGoal.y-gy) > 2.5) need = true;
  else if(mem.pathDirty) need = true;
  else if(mem.t - mem.lastPlan > 2.0) need = true;
  if(need && mem.t - mem.lastPlan > 0.3){
    planPath(mem,gx,gy);
    mem.pathDirty = false;
  }
}

function getWaypoint(mem,gx,gy){
  if(!mem.path || mem.path.length === 0) return {x:gx,y:gy};
  const gw = mem.gw;
  let idx = mem.pathIdx || 0;
  while(idx < mem.path.length-1){
    const id = mem.path[idx];
    const x = (id % gw)*mem.res;
    const y = ((id / gw)|0)*mem.res;
    if(hyp(x-mem.pos.x,y-mem.pos.y) < 1.2) idx++;
    else break;
  }
  mem.pathIdx = idx;
  let chosen = idx;
  for(let k=idx;k<mem.path.length && k<idx+10;k++){
    const id = mem.path[k];
    const x = (id % gw)*mem.res;
    const y = ((id / gw)|0)*mem.res;
    const d = hyp(x-mem.pos.x,y-mem.pos.y);
    chosen = k;
    if(d > 3.0) break;
  }
  let id = mem.path[chosen];
  let wx = (id % gw)*mem.res;
  let wy = ((id / gw)|0)*mem.res;
  if(hyp(wx-mem.pos.x,wy-mem.pos.y) < 0.25 && chosen < mem.path.length-1){
    chosen++;
    id = mem.path[chosen];
    wx = (id % gw)*mem.res;
    wy = ((id / gw)|0)*mem.res;
  }
  return {x:wx,y:wy};
}

function wheelControl(target,meas,st,dt){
  target = clamp(target,-2.4,2.4);
  if(st.prev !== undefined && st.prev * target < -0.01) st.i *= 0.25;
  st.prev = target;
  const err = target - meas;
  const ff = clamp(target/3.0,-1,1);
  let raw = ff + 0.75*err + st.i;
  let u = clamp(raw,-1,1);
  if(raw !== u) st.i += (u - raw)*0.15;
  st.i += err*dt*1.1;
  st.i = clamp(st.i,-0.85,0.85);
  if(Math.abs(target) > 0.03 && Math.abs(u) < 0.04){
    u = target > 0 ? 0.04 : -0.04;
  }
  if(Math.abs(target) < 0.02 && Math.abs(meas) < 0.02){
    st.i *= Math.exp(-dt*2.0);
  }
  return clamp(u,-1,1);
}

function brakeCmd(obs,mem){
  mem.wantV = 0;
  return {
    left:wheelControl(0,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(0,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays = obs.rays || [];
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let front = 15;
  let leftOpen = 0;
  let rightOpen = 0;

  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(r < 0) r = 15;
    if(r > 15) r = 15;
    if(i >= 3 && i <= 5 && r < front) front = r;
    if(i > 4) leftOpen += Math.min(r,8);
    else if(i < 4) rightOpen += Math.min(r,8);

    if(r < 5.0){
      const ang = mem.head + RAY_ANG[i];
      let w = (5.0-r)/5.0;
      if(i === 4) w *= 1.8;
      else if(i >= 3 && i <= 5) w *= 1.35;
      else w *= 0.65;
      vx -= Math.cos(ang)*w*1.3;
      vy -= Math.sin(ang)*w*1.3;
    }
  }

  const margin = 4.0;
  if(mem.pos.x < margin) vx += (margin-mem.pos.x)/margin * 2.2;
  if(mem.pos.x > mem.size-margin) vx -= (mem.pos.x-(mem.size-margin))/margin * 2.2;
  if(mem.pos.y < margin) vy += (margin-mem.pos.y)/margin * 2.2;
  if(mem.pos.y > mem.size-margin) vy -= (mem.pos.y-(mem.size-margin))/margin * 2.2;

  if(hyp(vx,vy) > 0.05) desired = Math.atan2(vy,vx);
  let err = wrap(desired - mem.head);

  let speed = speedLimit;
  if(front < 4.2){
    speed = Math.min(speed, Math.max(0.04, (front-0.55)*0.28));
  }
  if(front < 1.15){
    speed = 0;
    const turn = leftOpen >= rightOpen ? 1 : -1;
    err = turn * 1.2;
  } else if(Math.abs(err) > 1.1){
    speed = 0;
  } else if(Math.abs(err) > 0.55){
    speed = Math.min(speed, Math.max(0.08, speedLimit*0.45));
  }

  speed = clamp(speed,0,0.9);
  let w = clamp(err*2.4,-2.0,2.0);
  let v = speed;
  if(speed < 0.02){
    v = 0;
    if(Math.abs(err) > 0.25) w = clamp(err*2.4,-1.7,1.7);
    else w = 0;
  }
  let L = v - w*0.3;
  let R = v + w*0.3;
  L = clamp(L,-2.2,2.2);
  R = clamp(R,-2.2,2.2);

  mem.wantV = v;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveTo(obs,mem,gx,gy,speed,arrive){
  const d = hyp(gx-mem.pos.x, gy-mem.pos.y);
  if(d <= arrive) return brakeCmd(obs,mem);

  let tx = gx;
  let ty = gy;
  if(d > 4.0){
    ensurePath(mem,gx,gy);
    const wp = getWaypoint(mem,gx,gy);
    const dwp = hyp(wp.x-mem.pos.x, wp.y-mem.pos.y);
    if(mem.path && mem.path.length > 1 && dwp > 0.3){
      tx = wp.x;
      ty = wp.y;
    }
  }

  let desired = Math.atan2(ty-mem.pos.y, tx-mem.pos.x);
  let sp = speed;
  if(d < 5.0){
    sp = Math.min(sp, Math.max(0.12, d*0.28));
  }
  return driveHeading(obs,mem,desired,sp);
}

function cancelSearch(mem,done){
  if(mem.search){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status === 1) h.status = done ? 2 : 0;
  }
  mem.search = null;
}

function makeRing(cx,cy,r,space,phase,size){
  const arr = [];
  const n = Math.max(6, Math.ceil(2*PI*r/space));
  for(let k=0;k<n;k++){
    const a = phase + k*2*PI/n;
    arr.push({
      x:clamp(cx + Math.cos(a)*r, 2.0, size-2.0),
      y:clamp(cy + Math.sin(a)*r, 2.0, size-2.0)
    });
  }
  return arr;
}

function beginSearch(obs,mem,h){
  const pts = [{x:clamp(h.x,2,mem.size-2), y:clamp(h.y,2,mem.size-2)}];
  const ring1 = makeRing(h.x,h.y,10,7.5,0.3,mem.size);
  for(let i=0;i<ring1.length;i++) pts.push(ring1[i]);
  mem.search = {
    hintId:h.id,
    cx:h.x,
    cy:h.y,
    pts:pts,
    idx:0,
    stage:0,
    startT:mem.t,
    ptT:mem.t,
    lastX:mem.pos.x,
    lastY:mem.pos.y,
    travel:0,
    centerChecked:false
  };
  h.status = 1;
  mem.mode = 'search';
  mem.task = null;
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
}

function finishSearch(mem){
  if(mem.search){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status === 1) h.status = 2;
  }
  mem.search = null;
  mem.mode = 'idle';
  mem.task = null;
  mem.path = [];
  mem.pathDirty = true;
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const h = mem.hints[S.hintId];
  if(!h || h.status >= 2){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  const moved = hyp(mem.pos.x-S.lastX, mem.pos.y-S.lastY);
  S.travel += moved;
  S.lastX = mem.pos.x;
  S.lastY = mem.pos.y;

  if(!S.centerChecked && hyp(mem.pos.x-S.cx, mem.pos.y-S.cy) < 2.5){
    S.centerChecked = true;
    if((fin(obs.science,0) <= 0.0000001) && !obs.site){
      finishSearch(mem);
      return brakeCmd(obs,mem);
    }
  }

  if(mem.t - S.startT > 225 || S.travel > 230){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    if(hyp(p.x-mem.pos.x,p.y-mem.pos.y) < 1.35){
      S.idx++;
      S.ptT = mem.t;
      mem.path = [];
      mem.pathDirty = true;
    } else {
      break;
    }
  }

  if(S.idx >= S.pts.length){
    if(S.stage === 0){
      const expand = h.v >= 0.08*mem.maxHintVal || fin(obs.science,0) > Math.max(0.005, mem.sciMax*0.08);
      if(expand && mem.t - S.startT < 190){
        const ring2 = makeRing(h.x,h.y,18,8.0,1.1,mem.size);
        for(let i=0;i<ring2.length;i++) S.pts.push(ring2[i]);
        S.stage = 1;
        S.ptT = mem.t;
      } else {
        finishSearch(mem);
        return brakeCmd(obs,mem);
      }
    } else {
      finishSearch(mem);
      return brakeCmd(obs,mem);
    }
  }

  if(mem.t - S.ptT > 30){
    S.idx++;
    S.ptT = mem.t;
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }

  if(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    return driveTo(obs,mem,p.x,p.y,0.85,1.15);
  }
  return brakeCmd(obs,mem);
}

function startRecovery(obs,mem,isBump){
  mem.recoverUntil = mem.t + 1.8;
  mem.recoverBackUntil = mem.t + 0.7;
  const rays = obs.rays || [];
  let l = 0;
  let r = 0;
  for(let i=0;i<9;i++){
    let val = fin(rays[i],15);
    if(val < 0) val = 15;
    if(i > 4) l += Math.min(val,10);
    else if(i < 4) r += Math.min(val,10);
  }
  if(Math.abs(l-r) < 0.05) mem.recoverTurn = (mem.recoverTurn === 1 ? -1 : 1);
  else mem.recoverTurn = l >= r ? 1 : -1;

  markObs(mem, mem.pos.x + Math.cos(mem.head)*0.85, mem.pos.y + Math.sin(mem.head)*0.85, 4);
  mem.path = [];
  mem.pathDirty = true;
  mem.wantV = 0;
  mem.stallT = 0;
  mem.recoverCount = (mem.recoverCount || 0) + 1;

  if(mem.recoverCount > 3){
    if(mem.search){
      const h = mem.hints[mem.search.hintId];
      if(h) h.status = 2;
    }
    if(mem.task && mem.task.type === 'hint'){
      const h = mem.hints[mem.task.id];
      if(h) h.status = 2;
    }
    mem.task = null;
    mem.search = null;
    mem.approach = null;
    mem.mode = 'idle';
    mem.recoverCount = 0;
  }
}

function doRecovery(obs,mem){
  let v = 0;
  let w = mem.recoverTurn * 1.2;
  if(mem.t < mem.recoverBackUntil) v = -0.35;
  let L = clamp(v - w*0.3,-0.85,0.85);
  let R = clamp(v + w*0.3,-0.85,0.85);
  mem.wantV = v;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function markNearestHintDone(mem,x,y){
  let best = -1;
  let bd = 35*35;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x;
    const dy = h.y-y;
    const d2 = dx*dx+dy*dy;
    if(d2 < bd){
      bd = d2;
      best = i;
    }
  }
  if(best >= 0) mem.hints[best].status = 2;
}

function startDrill(obs,mem,value,sx,sy){
  mem.mode = 'drill';
  mem.drill = {
    x:mem.pos.x,
    y:mem.pos.y,
    sx:sx,
    sy:sy,
    value:value,
    before:fin(obs.carried,0),
    startT:mem.t
  };
  mem.approach = null;
  mem.search = null;
  mem.wantV = 0;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  const D = mem.drill;
  if(D){
    mem.ignoreX = D.sx;
    mem.ignoreY = D.sy;
    mem.ignoreUntil = mem.t + 20;
  }
  mem.drill = null;
  mem.approach = null;
  mem.mode = (fin(obs.carried,0) > 0) ? 'return' : 'idle';
  mem.task = null;
  mem.path = [];
  mem.pathDirty = true;
  mem.wantV = 0;
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D = mem.drill;
  if(!D){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried > D.before){
    markNearestHintDone(mem,D.sx,D.sy);
    mem.sampled.push({x:D.sx,y:D.sy,value:D.value,t:mem.t});
    mem.drill = null;
    mem.approach = null;
    mem.search = null;
    mem.mode = 'idle';
    mem.task = null;
    mem.path = [];
    mem.pathDirty = true;
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  const drilling = fin(obs.drilling,0);
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  const needE = bd*mem.epm*(1+0.08*carried)*1.8 + 0.05;
  const timeNeed = bd/0.75 + 8 + Math.max(0,6-drilling);
  if(drilling < 5.6 && (fin(obs.battery,0) < needE + 0.03 || fin(obs.timeLeft,1200) < timeNeed + 5)){
    return abortDrill(obs,mem);
  }
  if(mem.t - D.startT > 13 && carried <= D.before){
    return abortDrill(obs,mem);
  }
  if(obs.site && fin(obs.site.distance,0) > 2.0 && drilling < 5.8){
    return abortDrill(obs,mem);
  }

  let targetL = 0;
  let targetR = 0;
  const dx = D.x - mem.pos.x;
  const dy = D.y - mem.pos.y;
  const dd = hyp(dx,dy);
  if(dd > 0.35 && drilling < 5.9){
    const err = wrap(Math.atan2(dy,dx) - mem.head);
    const v = Math.min(0.08, dd*0.15);
    const w = clamp(err*1.5,-0.15,0.15);
    targetL = v - w*0.3;
    targetR = v + w*0.3;
  }

  mem.wantV = 0;
  return {
    left:wheelControl(targetL,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(targetR,mem.wheelR,mem.ctlR,mem.dt),
    drill:true
  };
}

function doApproach(obs,mem){
  const app = mem.approach;
  if(!app){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  const os = obs.site;
  if(os){
    const d = fin(os.distance,0);
    const bear = fin(os.bearing,0) * D2R;
    const ang = mem.head + bear;
    const sx = mem.pos.x + Math.cos(ang)*d;
    const sy = mem.pos.y + Math.sin(ang)*d;

    if(hyp(sx-app.x,sy-app.y) > 6){
      app.x = sx;
      app.y = sy;
    } else {
      app.x += (sx-app.x)*0.3;
      app.y += (sy-app.y)*0.3;
    }
    app.value = fin(os.value,app.value);
    app.lastSeen = mem.t;
    app.startT = Math.min(app.startT, mem.t - 1);

    if(d < 1.55){
      if(mem.maxWheel < 0.12){
        return startDrill(obs,mem,app.value,app.x,app.y);
      }
      return brakeCmd(obs,mem);
    }

    let speed = clamp((d-1.15)*0.5,0.08,0.75);
    if(d < 2.5) speed = Math.min(speed,0.16);
    if(d < 4.0) speed = Math.min(speed,0.35);
    return driveHeading(obs,mem,mem.head + bear,speed);
  }

  const dx = app.x - mem.pos.x;
  const dy = app.y - mem.pos.y;
  const d = hyp(dx,dy);
  if(d < 1.8 || mem.t - app.startT > 35){
    mem.ignoreX = app.x;
    mem.ignoreY = app.y;
    mem.ignoreUntil = mem.t + 12;
    mem.approach = null;
    mem.mode = 'idle';
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }
  let speed = clamp(d*0.25,0.08,0.55);
  return driveHeading(obs,mem,Math.atan2(dy,dx),speed);
}

function doTravel(obs,mem){
  const task = mem.task;
  if(!task){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }

    const d = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    if(d < 4.0){
      beginSearch(obs,mem,h);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 300 && d > 10){
      h.status = 2;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
    return driveTo(obs,mem,h.x,h.y,0.9,3.4);
  }

  mem.task = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function doReturn(obs,mem){
  const bdGPS = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  let d = bdGPS;
  let desired = Math.atan2(mem.base.y-mem.pos.y, mem.base.x-mem.pos.x);

  const beacon = obs.beacon;
  if(beacon && isFinite(Number(beacon.distance)) && isFinite(Number(beacon.bearing))){
    const bdist = Number(beacon.distance);
    const bbear = Number(beacon.bearing) * D2R;
    if(bdist < 20 && (bdist < bdGPS + 8 || bdGPS < 25)){
      d = bdist;
      desired = mem.head + bbear;
    }
  }

  if(d < 2.4){
    return brakeCmd(obs,mem);
  }
  let speed = 0.9;
  if(d < 6.0) speed = Math.min(speed, Math.max(0.15,(d-1.1)*0.32));
  return driveHeading(obs,mem,desired,speed);
}

function handleDocked(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried > 0){
    mem.dockT = 0;
    mem.dockNoGainT = 0;
    mem.mode = 'idle';
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  const batt = fin(obs.battery,0);
  const capTarget = Math.min(0.98, Math.max(0.72, mem.maxBattSeen*0.92));
  if(mem.mode !== 'charge'){
    mem.mode = 'charge';
    mem.dockT = 0;
    mem.dockNoGainT = 0;
    mem.dockLastBatt = batt;
    mem.dockStartBatt = batt;
  } else {
    mem.dockT += mem.dt;
    if(batt > mem.dockLastBatt + 0.0005){
      mem.dockNoGainT = 0;
    } else {
      mem.dockNoGainT += mem.dt;
    }
    mem.dockLastBatt = batt;
  }

  const needCharge = batt < capTarget && fin(obs.timeLeft,0) > 90;
  if(needCharge && mem.dockT < 30 && mem.dockNoGainT < 10){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;

  const ok = chooseTask(obs,mem);
  if(ok){
    if(mem.mode === 'travel') return doTravel(obs,mem);
    if(mem.mode === 'search') return doSearch(obs,mem);
    if(mem.mode === 'approach') return doApproach(obs,mem);
    if(mem.mode === 'return') return doReturn(obs,mem);
  }
  mem.wantV = 0;
  return brakeCmd(obs,mem);
}

function shouldAcceptSite(obs,mem,val,d){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap) return false;
  if(!(val > 0)) return false;
  if(carried < Math.min(2,mem.cap-1)) return true;
  const maxv = Math.max(0.1,mem.maxHintVal);
  if(val >= 0.045*maxv) return true;
  if(d < 2.5) return true;
  return false;
}

function chooseTask(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried >= mem.returnAfter || carried >= mem.cap){
    mem.mode = 'return';
    mem.task = null;
    mem.pathDirty = true;
    return false;
  }

  const atBase = !!obs.docked || hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y) < 3.5;
  let best = null;
  let bestScore = -1e100;
  let active = 0;

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    active++;
    const d1 = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    const d2 = hyp(h.x-mem.base.x, h.y-mem.base.y);
    const timeNeed = (d1+d2)/0.75 + 55 + (h.pseudo ? 25 : 0);
    if(fin(obs.timeLeft,0) < timeNeed + 20) continue;
    const energyNeed = (d1+d2+40)*mem.epm*(1+0.08*(carried+1))*1.8 + 0.08;
    if(!atBase && fin(obs.battery,0) < energyNeed) continue;
    let score = Math.pow(h.v + 0.1, 1.1) / (12 + d1 + 0.38*d2);
    if(h.pseudo) score *= 0.72;
    if(score > bestScore){
      bestScore = score;
      best = h;
    }
  }

  if(!best && active === 0 && mem.pseudoSearches < 6 && fin(obs.timeLeft,0) > 140 && fin(obs.battery,0) > 0.35){
    let cx;
    let cy;
    if(fin(obs.science,0) > 0.01){
      cx = mem.pos.x;
      cy = mem.pos.y;
    } else {
      mem.rng = (mem.rng * 1664525 + 1013904223) >>> 0;
      const a = (mem.rng % 1000000) / 1000000 * 2*PI;
      const rr = 55 + ((mem.rng >>> 9) % 1000000) / 1000000 * 105;
      cx = clamp(mem.pos.x + Math.cos(a)*rr, 8, mem.size-8);
      cy = clamp(mem.pos.y + Math.sin(a)*rr, 8, mem.size-8);
    }
    const id = mem.hints.length;
    const hv = Math.max(0.1, mem.maxHintVal*0.25);
    const h = {id:id,x:cx,y:cy,v:hv,status:0,pseudo:true};
    mem.hints.push(h);
    mem.pseudoSearches++;
    best = h;
    active++;
  }

  if(best){
    mem.task = {type:'hint',id:best.id,x:best.x,y:best.y,v:best.v,startT:mem.t};
    mem.mode = 'travel';
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathIdx = 0;
    mem.pathDirty = true;
    return true;
  }

  if(carried > 0){
    mem.mode = 'return';
    mem.task = null;
    mem.pathDirty = true;
    return false;
  }

  if(!atBase && (active > 0 || fin(obs.battery,0) < 0.25)){
    mem.mode = 'return';
    mem.task = null;
    mem.pathDirty = true;
    return false;
  }

  mem.mode = 'idle';
  mem.task = null;
  return false;
}

function act(obs,mem){
  if(!mem.init) initMission(obs,mem);
  updateSensors(obs,mem);
  updateGrid(obs,mem);

  mem.tick = (mem.tick || 0) + 1;
  const sci = fin(obs.science,0);
  if(sci > mem.sciMax) mem.sciMax = sci;

  mem.returnAfter = (fin(obs.delivered,0) > 0) ? Math.min(mem.cap,3) : 1;

  if(mem.maxWheel > 0.15 && !obs.docked && !obs.bumped){
    mem.goodMoveT += mem.dt;
    if(mem.goodMoveT > 3.0) mem.recoverCount = 0;
  } else {
    mem.goodMoveT = 0;
  }

  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(mem.recoverUntil > mem.t) return doRecovery(obs,mem);

  if(obs.bumped){
    startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  if(mem.mode !== 'drill' && !obs.docked){
    if(Math.abs(mem.wantV) > 0.25 && mem.maxWheel < 0.05){
      mem.stallT += mem.dt;
    } else {
      mem.stallT = 0;
    }
    if(mem.stallT > 1.5){
      startRecovery(obs,mem,false);
      return doRecovery(obs,mem);
    }
  } else {
    mem.stallT = 0;
  }

  if(obs.docked) return handleDocked(obs,mem);

  if(mem.mode === 'charge') mem.mode = 'return';

  const carried = fin(obs.carried,0);
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  let returnNow = false;

  if(carried > 0){
    const needE = bd*mem.epm*(1+0.08*carried)*1.8 + 0.06;
    const timeNeed = bd/0.75 + 25;
    if(carried >= mem.returnAfter) returnNow = true;
    if(fin(obs.battery,0) < needE + 0.03) returnNow = true;
    if(fin(obs.timeLeft,1200) < timeNeed + 15) returnNow = true;
  } else {
    if(fin(obs.battery,0) < 0.15 && bd > 20) returnNow = true;
    if(fin(obs.timeLeft,1200) < bd/0.75 + 10) returnNow = true;
  }
  if(mem.mode === 'return') returnNow = true;

  if(returnNow && mem.mode !== 'return'){
    cancelSearch(mem,false);
    mem.mode = 'return';
    mem.task = null;
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathDirty = true;
  }

  if(mem.mode !== 'return'){
    const os = obs.site;
    if(os && carried < mem.cap){
      const val = fin(os.value,0);
      const d = fin(os.distance,0);
      const bear = fin(os.bearing,0) * D2R;
      const ang = mem.head + bear;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      let ignored = false;
      if(mem.t < mem.ignoreUntil && hyp(sx-mem.ignoreX,sy-mem.ignoreY) < 3.0) ignored = true;
      if(!ignored && shouldAcceptSite(obs,mem,val,d)){
        if(mem.mode !== 'approach' || !mem.approach || hyp(mem.approach.x-sx,mem.approach.y-sy) > 2.5){
          cancelSearch(mem,false);
          mem.mode = 'approach';
          mem.approach = {
            x:sx,
            y:sy,
            value:val,
            startT:mem.t,
            lastSeen:mem.t
          };
          mem.task = null;
          mem.path = [];
          mem.pathDirty = true;
        }
      }
    }

    if((mem.mode === 'idle' || (!mem.task && mem.mode !== 'approach' && mem.mode !== 'search'))){
      chooseTask(obs,mem);
    }
  }

  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);

  mem.wantV = 0;
  return brakeCmd(obs,mem);
}

const PI=Math.PI;
const D2R=PI/180;
const R2D=180/PI;
const WB=0.6;
const RAYA=[-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];
const DX8=[1,0,-1,0,1,1,-1,-1];
const DY8=[0,1,0,-1,1,-1,1,-1];

function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function wrap(a){a=a%(2*PI);if(a>PI)a-=2*PI;if(a<-PI)a+=2*PI;return a;}
function hyp(x,y){return Math.sqrt(x*x+y*y);}
function fin(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}

function initMission(obs,mem){
  mem.init=true;
  mem.tick=0;
  mem.t=fin(obs.t,0);
  mem.dt=0.1;
  const M=obs.mission||{};
  mem.size=fin(M.size,400);
  mem.seconds=fin(M.seconds,1200);
  mem.cap=Math.max(1,Math.floor(fin(M.capacity,5)));
  const b=M.base||{x:fin(obs.x,0),y:fin(obs.y,0)};
  mem.base={x:fin(b.x,fin(obs.x,0)),y:fin(b.y,fin(obs.y,0))};
  mem.hints=[];
  const hs=Array.isArray(M.hints)?M.hints:[];
  for(let i=0;i<hs.length;i++){
    const h=hs[i]||{};
    let x=fin(h.x,NaN),y=fin(h.y,NaN),v=fin(h.estimate,0.1);
    if(!isFinite(x)||!isFinite(y))continue;
    x=clamp(x,0,mem.size);y=clamp(y,0,mem.size);
    if(!(v>0))v=0.1;
    mem.hints.push({id:mem.hints.length,x:x,y:y,v:v,status:0});
  }
  mem.maxHintVal=0.5;
  for(let i=0;i<mem.hints.length;i++)if(mem.hints[i].v>mem.maxHintVal)mem.maxHintVal=mem.hints[i].v;
  mem.maxValSeen=mem.maxHintVal;

  mem.res=1.0;
  mem.gw=Math.ceil(mem.size/mem.res)+3;
  mem.gh=mem.gw;
  mem.n=mem.gw*mem.gh;
  mem.obsc=new Uint8Array(mem.n);
  mem.freec=new Uint8Array(mem.n);
  mem.dist=new Int32Array(mem.n);
  mem.par=new Int32Array(mem.n);
  mem.q=new Int32Array(mem.n);

  mem.pos={x:clamp(fin(obs.x,0),0.3,mem.size-0.3),y:clamp(fin(obs.y,0),0.3,mem.size-0.3)};
  mem.head=wrap(fin(obs.heading,0)*D2R);
  mem.rawLast=mem.head;
  mem.lastRawDeg=fin(obs.heading,0);
  mem.bias=0;
  mem.compassBad=0;
  mem.headStuck=0;

  mem.wheelL=fin(obs.wheelLeft,0);
  mem.wheelR=fin(obs.wheelRight,0);
  mem.vMeas=(mem.wheelL+mem.wheelR)/2;
  mem.yawMeas=(mem.wheelR-mem.wheelL)/WB;

  mem.lastGX=fin(obs.x,mem.pos.x);
  mem.lastGY=fin(obs.y,mem.pos.y);
  mem.prevGX=mem.lastGX;
  mem.prevGY=mem.lastGY;
  mem.prevGpsT=mem.t;
  mem.gpsLastChangeT=mem.t;
  mem.gpsInterval=0.5;
  mem.gpsStale=false;
  mem.gpsWasStale=false;
  mem.slip=1;

  mem.ctlL={i:0,prev:0};
  mem.ctlR={i:0,prev:0};
  mem.wantV=0;

  mem.lastBatt=fin(obs.battery,1);
  mem.epm=0.0010;
  mem.drillRate=0.0045;
  mem.chargeRate=0;

  mem.mode='idle';
  mem.task=null;
  mem.search=null;
  mem.approach=null;
  mem.drill=null;
  mem.path=[];
  mem.pathIdx=0;
  mem.pathGoal=null;
  mem.pathDirty=true;
  mem.lastPlan=-999;

  mem.sites=[];
  mem.nextSiteId=1;
  mem.visibleSite=null;
  mem.sciMax=0;

  mem.recoverUntil=-1;
  mem.recoverBackUntil=-1;
  mem.recoverTurn=1;
  mem.recoverCount=0;
  mem.lastRecoveryT=-999;
  mem.lowFrontT=0;
  mem.progressPos={x:mem.pos.x,y:mem.pos.y};
  mem.lastProgressT=mem.t;

  mem.rayLast=new Float32Array(9);
  mem.rayStuck=new Int16Array(9);
  for(let i=0;i<9;i++){mem.rayLast[i]=15;mem.rayStuck[i]=0;}

  mem.sampleCount=0;
  mem.lastDelivered=fin(obs.delivered,0);
  mem.lastCarried=fin(obs.carried,0);
  mem.dockEnterT=0;
  mem.dockLastBatt=mem.lastBatt;
  mem.dockNoGain=0;

  mem.exploreCounter=0;
  mem.lastScienceSearch=-999;
}

function updateSensors(obs,mem){
  let t=fin(obs.t,mem.t+0.1);
  let dt=t-mem.t;
  if(!(dt>0)||dt>1.2)dt=0.1;
  if(dt<0.02)dt=0.02;
  mem.dt=dt;mem.t=t;

  const wl=fin(obs.wheelLeft,0),wr=fin(obs.wheelRight,0);
  mem.wheelL=wl;mem.wheelR=wr;
  const v=(wl+wr)/2;
  const yaw=(wr-wl)/WB;
  mem.vMeas=v;mem.yawMeas=yaw;

  const raw=wrap(fin(obs.heading,mem.lastRawDeg)*D2R);
  mem.lastRawDeg=raw*R2D;
  const pred=wrap(mem.head+yaw*dt);
  const meas=wrap(raw-mem.bias);
  const diff=wrap(meas-pred);
  let jump=false;
  if(Math.abs(diff)>1.05&&Math.abs(yaw)<0.9)jump=true;
  if(Math.abs(raw-(mem.rawLast||raw))<0.000001&&Math.abs(yaw)>0.12)mem.headStuck++;
  else mem.headStuck=0;
  mem.rawLast=raw;
  if(jump||mem.headStuck>20){
    mem.compassBad=Math.min(80,mem.compassBad+1);
    mem.head=pred;
  }else{
    mem.compassBad=Math.max(0,mem.compassBad-0.2);
    let alpha=mem.compassBad>8?0.22:0.65;
    mem.head=wrap(pred+wrap(meas-pred)*alpha);
  }

  mem.pos.x+=v*Math.cos(mem.head)*dt;
  mem.pos.y+=v*Math.sin(mem.head)*dt;

  const gx=fin(obs.x,mem.lastGX),gy=fin(obs.y,mem.lastGY);
  const gmove=hyp(gx-mem.lastGX,gy-mem.lastGY);
  const gpsNew=gmove>0.006;
  if(gpsNew){
    const interval=t-mem.gpsLastChangeT;
    if(interval>0.03&&interval<10)mem.gpsInterval=mem.gpsInterval*0.8+interval*0.2;
    mem.gpsLastChangeT=t;
  }
  const staleLimit=Math.max(1.5,mem.gpsInterval*3.5);
  const since=t-mem.gpsLastChangeT;
  let stale=(since>staleLimit&&(Math.abs(v)>0.04||Math.abs(yaw)>0.08));
  if(since>6.0&&Math.abs(v)>0.03)stale=true;
  mem.gpsStale=stale;

  if(!stale&&gpsNew){
    const ex=gx-mem.pos.x,ey=gy-mem.pos.y;
    const ed=hyp(ex,ey);
    let alpha=0.35;
    if(ed<3)alpha=0.55;
    if(ed<0.7)alpha=0.8;
    if(ed>25)alpha=0.25;
    if(mem.gpsWasStale){
      if(ed<70)alpha=0.9;
      else alpha=0.45;
      mem.gpsWasStale=false;
    }
    mem.pos.x+=ex*alpha;
    mem.pos.y+=ey*alpha;
    if(ed>8)mem.pathDirty=true;

    const interval=t-mem.prevGpsT;
    if(interval>0.05&&interval<4){
      const ground=hyp(gx-mem.prevGX,gy-mem.prevGY);
      if(Math.abs(v)>0.2&&Math.abs(wr-wl)<0.45){
        const ratio=ground/Math.max(0.05,Math.abs(v)*interval);
        mem.slip=clamp(mem.slip*0.86+ratio*0.14,0.1,1.8);
      }
      if(Math.abs(v)>0.45&&Math.abs(wr-wl)<0.35&&ground>0.05){
        let course=Math.atan2(gy-mem.prevGY,gx-mem.prevGX);
        if(v<0)course=wrap(course+PI);
        mem.head=wrap(mem.head+wrap(course-mem.head)*0.18);
        const bm=wrap(raw-course);
        if(Math.abs(bm)<1.1)mem.bias=wrap(mem.bias*0.985+bm*0.015);
      }
      mem.prevGpsT=t;
      mem.prevGX=gx;
      mem.prevGY=gy;
    }
  }else if(stale){
    mem.gpsWasStale=true;
  }

  mem.pos.x=clamp(mem.pos.x,0.25,mem.size-0.25);
  mem.pos.y=clamp(mem.pos.y,0.25,mem.size-0.25);
  mem.lastGX=gx;mem.lastGY=gy;
}

function updateEnergy(obs,mem){
  const batt=fin(obs.battery,mem.lastBatt);
  const dt=mem.dt;
  const drop=mem.lastBatt-batt;
  const wl=fin(obs.wheelLeft,0),wr=fin(obs.wheelRight,0);
  const wd=Math.abs((wl+wr)/2)*dt;
  if(!obs.drilling&&wd>0.005&&drop>0){
    const load=1+0.08*fin(obs.carried,0);
    const r=drop/(wd*load);
    if(r>0.00003&&r<0.03)mem.epm=clamp(mem.epm*0.975+r*0.025,0.0004,0.02);
  }
  if(obs.drilling&&drop>0){
    const r=drop/dt;
    if(r>0&&r<0.06)mem.drillRate=clamp(mem.drillRate*0.95+r*0.05,0.0005,0.03);
  }
  if(obs.docked&&batt>mem.lastBatt){
    const r=(batt-mem.lastBatt)/dt;
    if(r>0)mem.chargeRate=mem.chargeRate*0.8+r*0.2;
  }
  mem.lastBatt=batt;
}

function markFree(mem,x,y){
  if(!isFinite(x)||!isFinite(y))return;
  const ix=Math.round(x/mem.res),iy=Math.round(y/mem.res);
  if(ix<0||iy<0||ix>=mem.gw||iy>=mem.gh)return;
  const idx=iy*mem.gw+ix;
  if(mem.freec[idx]<255)mem.freec[idx]++;
}

function markObs(mem,x,y,s){
  if(!isFinite(x)||!isFinite(y))return;
  const ix=Math.round(x/mem.res),iy=Math.round(y/mem.res);
  const strength=Math.max(1,s||2);
  for(let dx=-1;dx<=1;dx++){
    for(let dy=-1;dy<=1;dy++){
      const nx=ix+dx,ny=iy+dy;
      if(nx<0||ny<0||nx>=mem.gw||ny>=mem.gh)continue;
      const idx=ny*mem.gw+nx;
      let add=1;
      if(dx===0&&dy===0)add=strength;
      else add=Math.max(1,Math.floor(strength/2));
      const v=mem.obsc[idx]+add;
      mem.obsc[idx]=v>255?255:v;
    }
  }
}

function markHard(mem,x,y){
  if(!isFinite(x)||!isFinite(y))return;
  const ix=Math.round(x/mem.res),iy=Math.round(y/mem.res);
  for(let dx=-1;dx<=1;dx++){
    for(let dy=-1;dy<=1;dy++){
      const nx=ix+dx,ny=iy+dy;
      if(nx<0||ny<0||nx>=mem.gw||ny>=mem.gh)continue;
      const idx=ny*mem.gw+nx;
      if(dx===0&&dy===0)mem.obsc[idx]=255;
      else {
        const v=mem.obsc[idx]+10;
        mem.obsc[idx]=v>255?255:v;
      }
    }
  }
}

function updateGrid(obs,mem){
  const rays=obs.rays||[];
  const moving=Math.abs(mem.wheelL)+Math.abs(mem.wheelR)>0.2;
  for(let i=0;i<9;i++){
    let r=fin(rays[i],15);
    if(!isFinite(r)||r<0)r=15;
    if(r>15)r=15;
    const last=mem.rayLast[i];
    if(Math.abs(r-last)<0.0005&&moving)mem.rayStuck[i]=Math.min(30000,mem.rayStuck[i]+1);
    else mem.rayStuck[i]=0;
    mem.rayLast[i]=r;

    const ang=mem.head+RAYA[i];
    const ca=Math.cos(ang),sa=Math.sin(ang);
    const maxd=Math.min(r,14.7);
    for(let d=0.55;d<maxd-0.15;d+=0.9){
      markFree(mem,mem.pos.x+ca*d,mem.pos.y+sa*d);
    }
    if(r<14.6&&r>0.18){
      const strength=r<1.4?4:(r<2.5?3:2);
      markObs(mem,mem.pos.x+ca*r,mem.pos.y+sa*r,strength);
      if(r<1.6)mem.pathDirty=true;
    }
  }
  markFree(mem,mem.pos.x,mem.pos.y);
}

function cellBlocked(mem,ix,iy){
  if(ix<1||iy<1||ix>=mem.gw-1||iy>=mem.gh-1)return true;
  const wx=ix*mem.res,wy=iy*mem.res;
  if(wx<0.7||wx>mem.size-0.7||wy<0.7||wy>mem.size-0.7)return true;
  const idx=iy*mem.gw+ix;
  const o=mem.obsc[idx],f=mem.freec[idx];
  if(o>=2&&f===0)return true;
  if(o>=4&&f<3)return true;
  if(o>=8&&f<10)return true;
  return false;
}

function blockedWorld(mem,x,y){
  if(x<0.5||x>mem.size-0.5||y<0.5||y>mem.size-0.5)return true;
  const ix=Math.round(x/mem.res),iy=Math.round(y/mem.res);
  if(ix<0||iy<0||ix>=mem.gw||iy>=mem.gh)return true;
  return cellBlocked(mem,ix,iy);
}

function nearestFreeCell(mem,cx,cy,maxR){
  if(!cellBlocked(mem,cx,cy))return cy*mem.gw+cx;
  for(let r=1;r<=maxR;r++){
    for(let dx=-r;dx<=r;dx++){
      for(let dy=-r;dy<=r;dy++){
        if(Math.max(Math.abs(dx),Math.abs(dy))!==r)continue;
        const nx=cx+dx,ny=cy+dy;
        if(nx<1||ny<1||nx>=mem.gw-1||ny>=mem.gh-1)continue;
        if(!cellBlocked(mem,nx,ny))return ny*mem.gw+nx;
      }
    }
  }
  return -1;
}

function planPath(mem,gx,gy){
  const gw=mem.gw,n=mem.n;
  let sx=Math.round(mem.pos.x/mem.res);
  let sy=Math.round(mem.pos.y/mem.res);
  let gxi=Math.round(gx/mem.res);
  let gyi=Math.round(gy/mem.res);
  sx=clamp(sx,1,gw-2);sy=clamp(sy,1,mem.gh-2);
  gxi=clamp(gxi,1,gw-2);gyi=clamp(gyi,1,mem.gh-2);

  let start=nearestFreeCell(mem,sx,sy,7);
  if(start<0)start=sy*gw+sx;
  let goal=nearestFreeCell(mem,gxi,gyi,12);
  if(goal<0)goal=start;

  if(start===goal){
    mem.path=[start];
    mem.pathIdx=0;
    mem.pathGoal={x:gx,y:gy};
    mem.lastPlan=mem.t;
    return true;
  }

  mem.dist.fill(-1);
  const q=mem.q,par=mem.par,dist=mem.dist;
  let qh=0,qt=0;
  dist[start]=0;par[start]=-1;q[qt++]=start;
  let found=false;
  let best=start;
  let bestD=1e100;
  const gxc=goal%gw,gyc=(goal/gw)|0;

  while(qh<qt&&qh<n){
    const cur=q[qh++];
    const cx=cur%gw,cy=(cur/gw)|0;
    const ddx=cx-gxc,ddy=cy-gyc;
    const dd=ddx*ddx+ddy*ddy;
    if(dd<bestD){bestD=dd;best=cur;}
    if(cur===goal){found=true;break;}
    const nd=dist[cur]+1;
    for(let k=0;k<8;k++){
      const nx=cx+DX8[k],ny=cy+DY8[k];
      if(nx<1||ny<1||nx>=gw-1||ny>=mem.gh-1)continue;
      const ni=ny*gw+nx;
      if(dist[ni]!==-1)continue;
      if(cellBlocked(mem,nx,ny))continue;
      if(k>=4){
        if(cellBlocked(mem,cx+DX8[k],cy)||cellBlocked(mem,cx,cy+DY8[k]))continue;
      }
      dist[ni]=nd;par[ni]=cur;q[qt++]=ni;
      if(qt>=n)break;
    }
  }

  const end=found?goal:best;
  const arr=[];
  let cur=end,guard=0;
  while(cur!==-1&&guard++<n+10){
    arr.push(cur);
    if(cur===start)break;
    cur=par[cur];
  }
  if(arr.length===0||arr[arr.length-1]!==start){
    mem.path=[start];
  }else{
    arr.reverse();
    mem.path=arr;
  }
  mem.pathIdx=0;
  mem.pathGoal={x:gx,y:gy};
  mem.lastPlan=mem.t;
  return found;
}

function ensurePath(mem,gx,gy){
  let need=false;
  if(!mem.path||mem.path.length<1)need=true;
  else if(!mem.pathGoal||hyp(mem.pathGoal.x-gx,mem.pathGoal.y-gy)>2.0)need=true;
  else if(mem.pathDirty)need=true;
  else if(mem.t-mem.lastPlan>2.0)need=true;
  if(need&&mem.t-mem.lastPlan>0.25){
    planPath(mem,gx,gy);
    mem.pathDirty=false;
  }
}

function getWaypoint(mem){
  if(!mem.path||mem.path.length===0)return null;
  const gw=mem.gw;
  let idx=mem.pathIdx||0;
  while(idx<mem.path.length-1){
    const id=mem.path[idx];
    const x=(id%gw)*mem.res;
    const y=((id/gw)|0)*mem.res;
    if(hyp(x-mem.pos.x,y-mem.pos.y)<1.1)idx++;
    else break;
  }
  mem.pathIdx=idx;
  let chosen=idx;
  const look=2.6+Math.min(2.0,Math.abs(mem.vMeas)*1.4);
  for(let k=idx;k<mem.path.length&&k<idx+12;k++){
    const id=mem.path[k];
    const x=(id%gw)*mem.res;
    const y=((id/gw)|0)*mem.res;
    const d=hyp(x-mem.pos.x,y-mem.pos.y);
    chosen=k;
    if(d>look)break;
  }
  const id=mem.path[chosen];
  return {x:(id%mem.gw)*mem.res,y:((id/mem.gw)|0)*mem.res};
}

function clearLine(mem,x1,y1,x2,y2){
  const dx=x2-x1,dy=y2-y1;
  const d=hyp(dx,dy);
  if(d<0.15)return true;
  const n=Math.ceil(d/0.8);
  for(let i=1;i<n;i++){
    const f=i/n;
    if(blockedWorld(mem,x1+dx*f,y1+dy*f))return false;
  }
  return true;
}

function wheelControl(target,meas,st,dt){
  target=clamp(target,-3.0,3.0);
  if(st.prev!==undefined&&st.prev*target<-0.01)st.i*=0.25;
  st.prev=target;
  const err=target-meas;
  st.i+=err*dt*1.7;
  st.i=clamp(st.i,-0.9,0.9);
  let u=target/3.0+0.52*err+st.i;
  if(u>1){
    u=1;
    if(err>0)st.i-=err*dt*1.7;
  }else if(u<-1){
    u=-1;
    if(err<0)st.i-=err*dt*1.7;
  }
  if(Math.abs(target)<0.02&&Math.abs(meas)<0.03){
    st.i*=Math.exp(-dt*2.5);
    if(Math.abs(st.i)<0.02)st.i=0;
  }
  if(target>0.05&&u<0.05)u=0.05;
  if(target<-0.05&&u>-0.05)u=-0.05;
  return clamp(u,-1,1);
}

function brakeCmd(obs,mem){
  mem.wantV=0;
  return {
    left:wheelControl(0,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(0,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays=obs.rays||[];
  const head=mem.head;
  let vx=Math.cos(desired),vy=Math.sin(desired);
  let front=15,leftOpen=0,rightOpen=0;

  for(let i=0;i<9;i++){
    let r=fin(rays[i],15);
    if(!isFinite(r)||r<0)r=15;
    if(r>15)r=15;
    if(i>=3&&i<=5&&r<front)front=r;
    if(i>4)leftOpen+=Math.min(r,10);
    else if(i<4)rightOpen+=Math.min(r,10);

    if(r<4.5){
      const ang=head+RAYA[i];
      let w=(4.5-r)/4.5;
      if(i===4)w*=2.0;
      else if(i>=3&&i<=5)w*=1.5;
      else w*=0.72;
      if(r<1.5)w*=2.0;
      vx-=Math.cos(ang)*w*1.35;
      vy-=Math.sin(ang)*w*1.35;
    }
  }

  const m=3.0;
  if(mem.pos.x<m)vx+=(m-mem.pos.x)/m*1.8;
  if(mem.pos.x>mem.size-m)vx-=(mem.pos.x-(mem.size-m))/m*1.8;
  if(mem.pos.y<m)vy+=(m-mem.pos.y)/m*1.8;
  if(mem.pos.y>mem.size-m)vy-=(mem.pos.y-(mem.size-m))/m*1.8;

  if(hyp(vx,vy)>0.05)desired=Math.atan2(vy,vx);
  let err=wrap(desired-head);

  let sp=Math.min(speedLimit,2.6);
  if(front<3.0){
    const cap=Math.max(0,(front-0.7)*0.85);
    if(sp>cap)sp=cap;
  }
  if(front<0.9){
    sp=0;
    err=(leftOpen>=rightOpen?1:-1)*1.35;
  }else if(Math.abs(err)>1.05){
    sp=0;
  }else if(Math.abs(err)>0.6){
    sp=Math.min(sp,0.75);
  }

  let v=Math.max(0,sp);
  let w=clamp(err*2.6,-2.2,2.2);
  if(v<0.02){
    v=0;
    if(Math.abs(err)>0.15)w=clamp(err*2.2,-2.0,2.0);
    else w=0;
  }

  if(mem.slip<0.75)v*=0.85;
  if(mem.slip<0.5)v*=0.8;
  if(fin(obs.pitch,0)>15)v*=0.82;
  if(fin(obs.battery,1)<0.2)v=Math.min(v,1.0);
  if(fin(obs.battery,1)<0.12)v=Math.min(v,0.6);

  let L=clamp(v-w*0.3,-3.0,3.0);
  let R=clamp(v+w*0.3,-3.0,3.0);
  mem.wantV=v;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveTo(obs,mem,gx,gy,speed,arrive){
  const dx=gx-mem.pos.x,dy=gy-mem.pos.y;
  const d=hyp(dx,dy);
  if(d<=arrive)return brakeCmd(obs,mem);

  let tx=gx,ty=gy;
  if(d>3.0&&d>=8.0){
    ensurePath(mem,gx,gy);
    const wp=getWaypoint(mem);
    if(wp&&mem.path&&mem.path.length>1){
      const dw=hyp(wp.x-mem.pos.x,wp.y-mem.pos.y);
      if(dw>0.35){
        tx=wp.x;ty=wp.y;
      }
    }
  }else if(d>3.0&&d<8.0){
    if(clearLine(mem,mem.pos.x,mem.pos.y,gx,gy)){
      tx=gx;ty=gy;
    }else{
      ensurePath(mem,gx,gy);
      const wp=getWaypoint(mem);
      if(wp&&mem.path&&mem.path.length>1){
        tx=wp.x;ty=wp.y;
      }
    }
  }

  let desired=Math.atan2(ty-mem.pos.y,tx-mem.pos.x);
  let sp=speed;
  if(d<5.0)sp=Math.min(sp,Math.max(0.22,(d-arrive)*0.58));
  return driveHeading(obs,mem,desired,sp);
}

function updateSites(obs,mem){
  mem.visibleSite=null;
  const os=obs.site;
  if(os){
    let d=fin(os.distance,999);
    let bear=fin(os.bearing,0);
    let val=fin(os.value,0);
    if(d>=0&&d<8.6&&val>0){
      const ang=mem.head+bear*D2R;
      const sx=mem.pos.x+Math.cos(ang)*d;
      const sy=mem.pos.y+Math.sin(ang)*d;
      let best=null,bd=20;
      for(let i=0;i<mem.sites.length;i++){
        const s=mem.sites[i];
        if(s.sampled)continue;
        const ddx=s.x-sx,ddy=s.y-sy;
        const dd=ddx*ddx+ddy*ddy;
        if(dd<bd){bd=dd;best=s;}
      }
      if(best){
        best.x+=(sx-best.x)*0.32;
        best.y+=(sy-best.y)*0.32;
        best.value=val;
        best.lastSeen=mem.t;
        best.ignoreUntil=0;
      }else if(mem.sites.length<350){
        best={id:mem.nextSiteId++,x:sx,y:sy,value:val,sampled:false,lastSeen:mem.t,ignoreUntil:0};
        mem.sites.push(best);
      }
      if(best){
        mem.visibleSite={id:best.id,x:best.x,y:best.y,value:best.value,rawDist:d,rawBearing:bear};
        if(val>mem.maxValSeen)mem.maxValSeen=val;
      }
    }
  }
  const sci=fin(obs.science,0);
  if(sci>mem.sciMax)mem.sciMax=sci;
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++)if(mem.sites[i].id===id)return mem.sites[i];
  return null;
}

function findSiteNear(mem,x,y,rad){
  let best=null,bd=rad*rad;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.sampled)continue;
    const dx=s.x-x,dy=s.y-y;
    const d2=dx*dx+dy*dy;
    if(d2<bd){bd=d2;best=s;}
  }
  return best;
}

function markNearestHintDone(mem,x,y,rad){
  let best=-1,bd=rad*rad;
  for(let i=0;i<mem.hints.length;i++){
    const h=mem.hints[i];
    if(h.status>=2)continue;
    const dx=h.x-x,dy=h.y-y;
    const d2=dx*dx+dy*dy;
    if(d2<bd){bd=d2;best=i;}
  }
  if(best>=0)mem.hints[best].status=2;
}

function cancelSearch(mem){
  if(mem.search){
    const id=mem.search.hintId;
    if(id>=0&&id<mem.hints.length&&mem.hints[id].status===1)mem.hints[id].status=0;
    mem.search=null;
  }
}

function finishSearch(mem){
  if(mem.search){
    const id=mem.search.hintId;
    if(id>=0&&id<mem.hints.length&&mem.hints[id].status<2)mem.hints[id].status=2;
  }
  mem.search=null;
  mem.task=null;
  mem.mode='idle';
  mem.approach=null;
  mem.path=[];
  mem.pathDirty=true;
}

function beginSearch(obs,mem,task){
  let rMax=task.searchR||12;
  if(task.type==='hint'){
    const h=mem.hints[task.id];
    if(h){
      h.status=1;
      const maxv=Math.max(0.5,mem.maxValSeen||mem.maxHintVal);
      const ratio=clamp(task.value/maxv,0,1);
      rMax=12+9*ratio;
      if(task.value<0.15*Math.max(0.5,mem.maxHintVal))rMax=12;
    }
  }
  if(obs.timeLeft<260)rMax=Math.min(rMax,16);
  const spacing=9.0;
  const dth=0.35;
  const pts=[{x:clamp(task.x,2,mem.size-2),y:clamp(task.y,2,mem.size-2)}];
  const maxTheta=2*PI*rMax/spacing;
  for(let th=0.1;th<=maxTheta;th+=dth){
    const r=spacing*th/(2*PI);
    if(r<0.8)continue;
    let x=task.x+Math.cos(th)*r;
    let y=task.y+Math.sin(th)*r;
    x=clamp(x,2,mem.size-2);
    y=clamp(y,2,mem.size-2);
    pts.push({x:x,y:y});
  }
  let len=0;
  for(let i=1;i<pts.length;i++){
    len+=hyp(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);
  }
  let timeout=clamp(len/1.1+20,25,105);
  if(task.type==='hint'){
    const h=mem.hints[task.id];
    if(h&&h.v<0.18*Math.max(0.5,mem.maxHintVal))timeout=Math.min(timeout,48);
  }
  mem.search={
    taskType:task.type,
    hintId:task.type==='hint'?task.id:-1,
    cx:task.x,
    cy:task.y,
    pts:pts,
    idx:0,
    tStart:mem.t,
    ptT:mem.t,
    timeout:timeout,
    checkedCenter:false,
    centerZeroT:0
  };
  mem.mode='search';
  mem.approach=null;
  mem.path=[];
  mem.pathDirty=true;
  return true;
}

function doSearch(obs,mem){
  const S=mem.search;
  if(!S){mem.mode='idle';return brakeCmd(obs,mem);}
  const task=mem.task;
  if(!task){finishSearch(mem);return brakeCmd(obs,mem);}

  const cd=hyp(mem.pos.x-S.cx,mem.pos.y-S.cy);
  if(!S.checkedCenter&&cd<2.2){
    S.centerZeroT+=mem.dt;
    const sci=fin(obs.science,0);
    if(sci>1e-8||mem.visibleSite)S.checkedCenter=true;
    else if(S.centerZeroT>0.8){
      finishSearch(mem);
      return brakeCmd(obs,mem);
    }
  }

  if(mem.t-S.tStart>S.timeout){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  while(S.idx<S.pts.length){
    const p=S.pts[S.idx];
    const d=hyp(p.x-mem.pos.x,p.y-mem.pos.y);
    if(d<1.3){
      S.idx++;
      S.ptT=mem.t;
      mem.pathDirty=true;
    }else break;
  }

  if(S.idx>=S.pts.length){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  const p=S.pts[S.idx];
  const d=hyp(p.x-mem.pos.x,p.y-mem.pos.y);
  if(mem.t-S.ptT>10&&d>2.0){
    S.idx++;
    S.ptT=mem.t;
    mem.pathDirty=true;
    return brakeCmd(obs,mem);
  }

  let speed=1.8;
  if(S.hintId>=0){
    const h=mem.hints[S.hintId];
    if(h&&h.v>0.5*Math.max(0.5,mem.maxHintVal))speed=2.0;
  }
  return driveTo(obs,mem,p.x,p.y,speed,1.2);
}

function startRecovery(obs,mem,isBump){
  mem.recoverUntil=mem.t+1.8;
  mem.recoverBackUntil=mem.t+0.65;
  const rays=obs.rays||[];
  let left=0,right=0;
  for(let i=0;i<9;i++){
    let r=fin(rays[i],15);
    if(!isFinite(r)||r<0)r=15;
    if(r>15)r=15;
    if(i>4)left+=Math.min(r,10);
    else if(i<4)right+=Math.min(r,10);
  }
  if(Math.abs(left-right)<0.05)mem.recoverTurn=(mem.recoverTurn===1?-1:1);
  else mem.recoverTurn=left>=right?1:-1;

  const bx=mem.pos.x+Math.cos(mem.head)*0.85;
  const by=mem.pos.y+Math.sin(mem.head)*0.85;
  if(isBump)markHard(mem,bx,by);
  else markObs(mem,bx,by,4);

  if(mem.t-mem.lastRecoveryT<12)mem.recoverCount++;
  else mem.recoverCount=1;
  mem.lastRecoveryT=mem.t;
  mem.path=[];
  mem.pathDirty=true;
  mem.progressPos={x:mem.pos.x,y:mem.pos.y};
  mem.lastProgressT=mem.t;
  mem.lowFrontT=0;

  if(mem.recoverCount>=3)abandonCurrent(mem,obs);
}

function doRecovery(obs,mem){
  let v=0,w=0;
  if(mem.t<mem.recoverBackUntil){
    v=-0.55;
    w=mem.recoverTurn*0.8;
  }else{
    v=-0.04;
    w=mem.recoverTurn*1.6;
  }
  let L=clamp(v-w*0.3,-2.2,2.2);
  let R=clamp(v+w*0.3,-2.2,2.2);
  mem.wantV=0;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function abandonCurrent(mem,obs){
  if(mem.search){
    const id=mem.search.hintId;
    if(id>=0&&id<mem.hints.length)mem.hints[id].status=2;
    mem.search=null;
  }
  if(mem.task){
    if(mem.task.type==='hint'){
      const h=mem.hints[mem.task.id];
      if(h)h.status=2;
    }else if(mem.task.type==='site'){
      const s=findSiteById(mem,mem.task.id);
      if(s)s.ignoreUntil=mem.t+120;
    }
  }
  if(mem.approach){
    const s=findSiteById(mem,mem.approach.id);
    if(s)s.ignoreUntil=mem.t+120;
  }
  mem.task=null;
  mem.approach=null;
  mem.mode='idle';
  mem.path=[];
  mem.pathDirty=true;
  mem.recoverCount=0;
}

function checkProgress(obs,mem){
  if(mem.mode==='drill'||obs.docked)return false;
  let px=mem.pos.x,py=mem.pos.y;
  if(!mem.gpsStale){
    px=mem.lastGX;py=mem.lastGY;
  }
  const dx=px-mem.progressPos.x,dy=py-mem.progressPos.y;
  if(hyp(dx,dy)>0.65){
    mem.progressPos={x:px,y:py};
    mem.lastProgressT=mem.t;
    mem.lowFrontT*=0.5;
  }

  const rays=obs.rays||[];
  let front=15;
  for(let i=2;i<=6;i++){
    let r=fin(rays[i],15);
    if(r>=0&&r<front)front=r;
  }
  if(front<0.78&&Math.abs(mem.vMeas)>0.15)mem.lowFrontT+=mem.dt;
  else mem.lowFrontT*=0.8;
  if(mem.lowFrontT>1.8){
    mem.lowFrontT=0;
    startRecovery(obs,mem,false);
    return true;
  }

  if(mem.wantV>0.45&&mem.t-mem.lastProgressT>4.8){
    startRecovery(obs,mem,false);
    return true;
  }
  return false;
}

function startApproach(obs,mem,vis){
  if(mem.search)cancelSearch(mem);
  mem.task=null;
  mem.path=[];
  mem.pathDirty=true;
  mem.mode='approach';
  mem.approach={
    id:vis.id,
    x:vis.x,
    y:vis.y,
    value:vis.value,
    startT:mem.t,
    lastSeen:mem.t,
    lastDist:vis.rawDist
  };
}

function doApproach(obs,mem){
  const app=mem.approach;
  if(!app){mem.mode='idle';return brakeCmd(obs,mem);}
  const carried=fin(obs.carried,0);
  if(carried>=mem.cap){
    startReturn(mem,obs);
    return brakeCmd(obs,mem);
  }

  let useActual=false;
  let actualDist=999;
  let actualBear=0;
  const os=obs.site;
  if(os){
    const d=fin(os.distance,999);
    const bear=fin(os.bearing,0);
    const val=fin(os.value,0);
    actualDist=d;actualBear=bear;
    const ang=mem.head+bear*D2R;
    const sx=mem.pos.x+Math.cos(ang)*d;
    const sy=mem.pos.y+Math.sin(ang)*d;
    const dd=hyp(sx-app.x,sy-app.y);
    if(dd<3.5||(mem.visibleSite&&mem.visibleSite.id===app.id)){
      app.x+=(sx-app.x)*0.35;
      app.y+=(sy-app.y)*0.35;
      app.value=val;
      app.lastSeen=mem.t;
      app.lastDist=d;
      if(mem.visibleSite)app.id=mem.visibleSite.id;
      useActual=true;
    }
  }

  let d=useActual?actualDist:hyp(app.x-mem.pos.x,app.y-mem.pos.y);
  let desired=useActual?wrap(mem.head+actualBear*D2R):Math.atan2(app.y-mem.pos.y,app.x-mem.pos.x);
  const maxWheel=Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));

  if(useActual&&d<1.45&&maxWheel<0.15){
    return startDrill(obs,mem,app);
  }
  if(!useActual&&d<1.25&&maxWheel<0.12&&mem.t-app.lastSeen<8&&app.lastDist<1.5){
    return startDrill(obs,mem,app);
  }

  if(mem.t-app.startT>45){
    const s=findSiteById(mem,app.id);
    if(s)s.ignoreUntil=mem.t+90;
    mem.approach=null;
    mem.task=null;
    mem.mode='idle';
    mem.path=[];
    mem.pathDirty=true;
    return brakeCmd(obs,mem);
  }

  let speed=1.7;
  if(d<4.5)speed=Math.min(speed,Math.max(0.14,(d-1.0)*0.52));
  if(d<2.2)speed=Math.min(speed,0.34);
  if(d<1.5)speed=0;

  if(d<1.55&&maxWheel>0.09)return brakeCmd(obs,mem);
  if(d>1.15)return driveHeading(obs,mem,desired,speed);
  return brakeCmd(obs,mem);
}

function startDrill(obs,mem,app){
  mem.mode='drill';
  mem.drill={
    id:app.id,
    sx:app.x,
    sy:app.y,
    value:app.value,
    before:fin(obs.carried,0),
    startT:mem.t,
    started:false,
    startedT:0,
    x:mem.pos.x,
    y:mem.pos.y,
    heading:mem.head
  };
  mem.approach=null;
  mem.path=[];
  mem.pathDirty=true;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  if(mem.drill){
    const s=findSiteNear(mem,mem.drill.sx,mem.drill.sy,5);
    if(s)s.ignoreUntil=mem.t+90;
  }
  mem.drill=null;
  mem.approach=null;
  mem.task=null;
  mem.search=null;
  mem.path=[];
  mem.pathDirty=true;
  if(fin(obs.carried,0)>0&&needReturn(obs,mem))startReturn(mem,obs);
  else mem.mode='idle';
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D=mem.drill;
  if(!D){mem.mode='idle';return brakeCmd(obs,mem);}
  const carried=fin(obs.carried,0);

  if(carried>D.before){
    const s=findSiteNear(mem,D.sx,D.sy,4.5);
    if(s)s.sampled=true;
    markNearestHintDone(mem,D.sx,D.sy,34);
    mem.sampleCount++;
    mem.drill=null;
    mem.approach=null;
    mem.search=null;
    mem.task=null;
    mem.path=[];
    mem.pathDirty=true;
    if(carried>=mem.cap||needReturn(obs,mem))startReturn(mem,obs);
    else mem.mode='idle';
    return brakeCmd(obs,mem);
  }

  const drilling=fin(obs.drilling,0);
  const maxWheel=Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));

  if(!D.started){
    let actual=false,dist=999;
    if(mem.visibleSite&&(mem.visibleSite.id===D.id||hyp(mem.visibleSite.x-D.sx,mem.visibleSite.y-D.sy)<3.0)){
      actual=true;
      dist=mem.visibleSite.rawDist;
    }else{
      dist=hyp(mem.pos.x-D.sx,mem.pos.y-D.sy);
    }
    if((actual&&dist<1.45&&maxWheel<0.15)||(!actual&&dist<1.08&&maxWheel<0.12)){
      D.started=true;
      D.startedT=mem.t;
      D.x=mem.pos.x;
      D.y=mem.pos.y;
      D.heading=mem.head;
    }else{
      if(mem.t-D.startT>8)return abortDrill(obs,mem);
      if(actual&&dist>1.12&&mem.visibleSite){
        const desired=mem.head+mem.visibleSite.rawBearing*D2R;
        return driveHeading(obs,mem,desired,0.22);
      }
      return brakeCmd(obs,mem);
    }
  }

  const bd=hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const epm=Math.max(0.0007,mem.epm);
  const need=bd*epm*(1+0.10*carried)*2.1+0.07;
  const remain=Math.max(0,6-drilling);
  if(drilling<5.65&&(fin(obs.battery,0)<need+remain*mem.drillRate+0.015||fin(obs.timeLeft,1200)<bd/0.85+remain+12)){
    return abortDrill(obs,mem);
  }
  if(mem.t-D.startedT>15&&carried<=D.before)return abortDrill(obs,mem);

  const ex=D.x-mem.pos.x,ey=D.y-mem.pos.y;
  const hErr=wrap(D.heading-mem.head);
  const fwd=ex*Math.cos(mem.head)+ey*Math.sin(mem.head);
  let v=clamp(fwd*0.55,-0.12,0.12);
  let w=clamp(hErr*1.1,-0.25,0.25);
  let L=clamp(v-w*0.3,-0.35,0.35);
  let R=clamp(v+w*0.3,-0.35,0.35);
  mem.wantV=0;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:true
  };
}

function doTravel(obs,mem){
  const task=mem.task;
  if(!task){mem.mode='idle';return brakeCmd(obs,mem);}

  if(task.type==='hint'){
    if(task.id<0||task.id>=mem.hints.length){
      mem.task=null;mem.mode='idle';return brakeCmd(obs,mem);
    }
    const h=mem.hints[task.id];
    if(!h||h.status>=2){
      mem.task=null;mem.mode='idle';return brakeCmd(obs,mem);
    }
  }

  const d=hyp(task.x-mem.pos.x,task.y-mem.pos.y);
  if(d<3.0){
    beginSearch(obs,mem,task);
    return doSearch(obs,mem);
  }

  if(mem.t-task.startT>330&&d>5){
    if(task.type==='hint'){
      const h=mem.hints[task.id];
      if(h)h.status=2;
    }
    mem.task=null;
    mem.mode='idle';
    mem.path=[];
    mem.pathDirty=true;
    return brakeCmd(obs,mem);
  }

  let speed=2.25;
  if(fin(obs.carried,0)>0)speed=2.1;
  if(fin(obs.battery,0)<0.25)speed=1.35;
  if(mem.slip<0.6)speed*=0.8;
  return driveTo(obs,mem,task.x,task.y,speed,1.2);
}

function needReturn(obs,mem){
  const carried=fin(obs.carried,0);
  const bd=hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  if(carried<=0){
    if(bd>25&&fin(obs.battery,0)<0.16)return true;
    return false;
  }
  if(carried>=mem.cap)return true;
  const epm=Math.max(0.0007,mem.epm);
  const need=bd*epm*(1+0.10*carried)*2.2+0.07;
  if(fin(obs.battery,0)<need+0.015)return true;
  const rt=bd/0.85+18;
  if(fin(obs.timeLeft,1200)<rt+8)return true;
  return false;
}

function startReturn(mem,obs){
  if(mem.mode==='return')return;
  if(mem.search)cancelSearch(mem);
  mem.task=null;
  mem.approach=null;
  mem.search=null;
  mem.mode='return';
  mem.path=[];
  mem.pathDirty=true;
}

function doReturn(obs,mem){
  const bd=hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  let d=bd;
  let desired=Math.atan2(mem.base.y-mem.pos.y,mem.base.x-mem.pos.x);
  let useBeacon=false;

  const beacon=obs.beacon;
  if(beacon&&isFinite(Number(beacon.distance))&&isFinite(Number(beacon.bearing))){
    const bdist=Number(beacon.distance);
    const bb=Number(beacon.bearing)*D2R;
    if(bdist<20&&(mem.gpsStale||bdist<5||bdist<bd+4)){
      d=bdist;
      desired=mem.head+bb;
      useBeacon=true;
    }
  }

  if(d<1.45)return brakeCmd(obs,mem);
  if(d<2.2&&Math.abs(mem.vMeas)<0.2)return brakeCmd(obs,mem);

  let speed=2.25;
  if(d<8)speed=Math.min(speed,Math.max(0.28,d*0.42));
  if(d<4)speed=Math.min(speed,Math.max(0.18,d*0.30));
  if(fin(obs.battery,0)<0.2)speed=Math.min(speed,1.0);
  if(mem.slip<0.55)speed*=0.8;
  if(useBeacon)return driveHeading(obs,mem,desired,speed);
  return driveTo(obs,mem,mem.base.x,mem.base.y,speed,0.9);
}

function shouldTakeVisible(obs,mem,vis){
  const carried=fin(obs.carried,0);
  if(carried>=mem.cap)return false;
  if(!(vis.value>0))return false;
  if(mem.mode==='return'||mem.mode==='drill')return false;

  if(mem.mode==='approach'&&mem.approach){
    const same=hyp(vis.x-mem.approach.x,vis.y-mem.approach.y)<3.0;
    if(same)return false;
    if(vis.rawDist<4.0&&vis.value>mem.approach.value*1.8+0.5)return true;
    return false;
  }
  if(mem.mode==='search')return true;
  if(mem.mode==='travel'){
    const cur=mem.task?mem.task.value:0;
    if(vis.rawDist<2.8)return true;
    if(vis.value>=Math.max(0.45,cur*0.65))return true;
    if(mem.task&&mem.task.pseudo)return true;
    if(obs.timeLeft<250&&vis.rawDist<5.0)return true;
    return false;
  }
  if(mem.mode==='idle')return true;
  return false;
}

function makeExploration(obs,mem,maxv){
  mem.exploreCounter++;
  const n=mem.exploreCounter;
  const ang=((n*137.507764)%360)*D2R;
  const rad=65+((n*53)%105);
  let cx=mem.base.x+Math.cos(ang)*rad;
  let cy=mem.base.y+Math.sin(ang)*rad;
  cx=clamp(cx,10,mem.size-10);
  cy=clamp(cy,10,mem.size-10);
  const val=Math.max(0.15,maxv*0.12);
  mem.task={type:'explore',id:-1,x:cx,y:cy,value:val,searchR:12,pseudo:true,startT:mem.t};
  mem.mode='travel';
  mem.search=null;
  mem.approach=null;
  mem.path=[];
  mem.pathDirty=true;
}

function chooseTask(obs,mem){
  const carried=fin(obs.carried,0);
  if(carried>=mem.cap){
    startReturn(mem,obs);
    return false;
  }
  const bd=hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const maxv=Math.max(0.5,mem.maxValSeen||mem.maxHintVal||1);
  let best=null,bestScore=-1e100;

  function consider(c){
    if(!(c.value>0))return;
    if(carried+1>mem.cap)return;
    const d1=hyp(c.x-mem.pos.x,c.y-mem.pos.y);
    const d2=hyp(c.x-mem.base.x,c.y-mem.base.y);
    const searchR=c.type==='hint'?(10+10*clamp(c.value/maxv,0,1)):(c.type==='explore'?14:0);
    const searchCost=c.type==='hint'?(15+searchR*1.2):(c.type==='explore'?20:2);
    let cost;
    if(carried>0)cost=d1*1.15+Math.max(0,d2-bd)*0.65+searchCost+10;
    else cost=d1*1.05+d2*0.55+searchCost+10;
    let score=Math.pow(c.value+0.05,1.35)*(c.conf||1)/(cost+1);
    if(c.type==='site')score*=1.12;

    const timeNeed=(d1*1.3+d2*1.3+searchR*1.5)/1.0+22+searchCost*0.25;
    if(fin(obs.timeLeft,1200)<timeNeed+15)return;
    const epm=Math.max(0.0007,mem.epm);
    const energyNeed=(d1+d2+searchR)*epm*(1+0.08*(carried+1))*1.25+0.035;
    if(fin(obs.battery,0)<energyNeed+(carried>0?0.01:0))return;

    if(score>bestScore){
      bestScore=score;
      best={
        type:c.type,
        id:c.id,
        x:c.x,
        y:c.y,
        value:c.value,
        searchR:searchR,
        pseudo:c.pseudo||false,
        startT:mem.t
      };
    }
  }

  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.sampled)continue;
    if(s.ignoreUntil&&s.ignoreUntil>mem.t)continue;
    const seenAge=mem.t-(s.lastSeen||0);
    consider({type:'site',id:s.id,x:s.x,y:s.y,value:s.value,conf:seenAge<80?1.0:0.65,pseudo:false});
  }

  for(let i=0;i<mem.hints.length;i++){
    const h=mem.hints[i];
    if(h.status!==0)continue;
    consider({type:'hint',id:h.id,x:h.x,y:h.y,value:h.v,conf:0.72,pseudo:false});
  }

  if(best){
    mem.search=null;
    mem.approach=null;
    mem.path=[];
    mem.pathDirty=true;
    if(best.type==='site'){
      mem.task=null;
      mem.mode='approach';
      mem.approach={
        id:best.id,
        x:best.x,
        y:best.y,
        value:best.value,
        startT:mem.t,
        lastSeen:mem.t,
        lastDist:99
      };
    }else{
      mem.task=best;
      mem.mode='travel';
    }
    return true;
  }

  if(carried>0){
    startReturn(mem,obs);
    return false;
  }

  if(fin(obs.timeLeft,0)>80&&fin(obs.battery,0)>0.25){
    const sci=fin(obs.science,0);
    if(sci>1e-8&&mem.t-mem.lastScienceSearch>25){
      mem.lastScienceSearch=mem.t;
      mem.task={
        type:'explore',
        id:-1,
        x:mem.pos.x,
        y:mem.pos.y,
        value:Math.max(0.2,maxv*0.25),
        searchR:12,
        pseudo:true,
        startT:mem.t
      };
      mem.mode='travel';
      mem.search=null;
      mem.approach=null;
      mem.path=[];
      mem.pathDirty=true;
      return true;
    }
    makeExploration(obs,mem,maxv);
    return true;
  }

  if(bd>8&&fin(obs.timeLeft,0)>20)startReturn(mem,obs);
  else{
    mem.task=null;
    mem.mode='idle';
    mem.path=[];
    mem.pathDirty=true;
  }
  return false;
}

function handleDocked(obs,mem){
  const carried=fin(obs.carried,0);
  if(carried>0){
    if(mem.mode!=='docked'){
      mem.mode='docked';
      mem.dockEnterT=mem.t;
      mem.dockLastBatt=fin(obs.battery,0);
      mem.dockNoGain=0;
    }
    mem.wantV=0;
    return brakeCmd(obs,mem);
  }

  if(mem.mode!=='docked'){
    mem.mode='docked';
    mem.dockEnterT=mem.t;
    mem.dockLastBatt=fin(obs.battery,0);
    mem.dockNoGain=0;
  }

  const elapsed=mem.t-mem.dockEnterT;
  const batt=fin(obs.battery,0);
  const wantCharge=batt<0.92||(fin(obs.timeLeft,1200)>300&&batt<0.985);
  if(wantCharge&&elapsed<20&&mem.dockNoGain<4&&fin(obs.timeLeft,0)>25){
    if(batt>mem.dockLastBatt+0.0002)mem.dockNoGain=0;
    else mem.dockNoGain+=mem.dt;
    mem.dockLastBatt=batt;
    mem.wantV=0;
    return brakeCmd(obs,mem);
  }

  mem.mode='idle';
  mem.task=null;
  mem.search=null;
  mem.approach=null;
  mem.path=[];
  mem.pathDirty=true;
  mem.dockEnterT=0;

  if(fin(obs.timeLeft,0)<15)return brakeCmd(obs,mem);
  if(chooseTask(obs,mem)){
    if(mem.mode==='return')return doReturn(obs,mem);
    if(mem.mode==='approach')return doApproach(obs,mem);
    if(mem.mode==='search')return doSearch(obs,mem);
    if(mem.mode==='travel')return doTravel(obs,mem);
    if(mem.mode==='drill')return doDrill(obs,mem);
  }
  return brakeCmd(obs,mem);
}

function dispatchMode(obs,mem){
  if(mem.mode==='return')return doReturn(obs,mem);
  if(mem.mode==='approach')return doApproach(obs,mem);
  if(mem.mode==='search')return doSearch(obs,mem);
  if(mem.mode==='travel')return doTravel(obs,mem);
  if(mem.mode==='drill')return doDrill(obs,mem);
  return brakeCmd(obs,mem);
}

function act(obs,mem){
  if(!mem.init){
    initMission(obs,mem);
    mem.wantV=0;
    return brakeCmd(obs,mem);
  }

  updateSensors(obs,mem);
  updateGrid(obs,mem);
  updateSites(obs,mem);
  updateEnergy(obs,mem);

  mem.tick=(mem.tick||0)+1;

  if(obs.docked)return handleDocked(obs,mem);

  if(mem.mode==='drill')return doDrill(obs,mem);

  if(obs.bumped){
    if(mem.recoverUntil<=mem.t)startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  if(mem.recoverUntil>mem.t)return doRecovery(obs,mem);

  if(checkProgress(obs,mem))return doRecovery(obs,mem);

  if(mem.mode!=='return'&&mem.mode!=='docked'){
    if(needReturn(obs,mem))startReturn(mem,obs);
  }

  if(mem.mode==='return')return doReturn(obs,mem);

  if(mem.visibleSite&&fin(obs.carried,0)<mem.cap){
    if(shouldTakeVisible(obs,mem,mem.visibleSite)){
      startApproach(obs,mem,mem.visibleSite);
    }
  }

  if(mem.mode==='approach')return doApproach(obs,mem);
  if(mem.mode==='search')return doSearch(obs,mem);
  if(mem.mode==='travel')return doTravel(obs,mem);

  if(mem.mode==='idle'){
    if(chooseTask(obs,mem))return dispatchMode(obs,mem);
    return brakeCmd(obs,mem);
  }

  return brakeCmd(obs,mem);
}

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const RAYA = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];
const DX8 = [1,0,-1,0,1,1,-1,-1];
const DY8 = [0,1,0,-1,1,-1,1,-1];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % (2*PI);
  if(a > PI) a -= 2*PI;
  if(a < -PI) a += 2*PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function fin(v,d){ return (typeof v === 'number' && isFinite(v)) ? v : d; }

function initMission(obs,mem){
  mem.init = true;
  mem.t = fin(obs.t,0);
  mem.dt = 0.1;
  mem.tick = 0;
  const M = obs.mission || {};
  mem.size = fin(M.size,400);
  mem.seconds = fin(M.seconds,1200);
  mem.cap = Math.max(1,Math.floor(fin(M.capacity,5)));
  const b = M.base || {x:fin(obs.x,0),y:fin(obs.y,0)};
  mem.base = {x:fin(b.x,fin(obs.x,0)), y:fin(b.y,fin(obs.y,0))};

  mem.hints = [];
  const hs = Array.isArray(M.hints) ? M.hints : [];
  for(let i=0;i<hs.length;i++){
    const h = hs[i] || {};
    let x = fin(h.x,NaN), y = fin(h.y,NaN), v = fin(h.estimate,0.1);
    if(!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x,0,mem.size);
    y = clamp(y,0,mem.size);
    if(!(v>0)) v = 0.1;
    mem.hints.push({id:mem.hints.length,x:x,y:y,v:v,status:0});
  }
  mem.maxHintVal = 0.5;
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;

  mem.res = 2.0;
  mem.gw = Math.ceil(mem.size/mem.res)+4;
  mem.gh = mem.gw;
  mem.n = mem.gw*mem.gh;
  mem.obsc = new Uint8Array(mem.n);
  mem.freec = new Uint8Array(mem.n);
  mem.dist = new Int32Array(mem.n);
  mem.par = new Int32Array(mem.n);
  mem.q = new Int32Array(mem.n);

  mem.pos = {x:clamp(fin(obs.x,0),0.3,mem.size-0.3), y:clamp(fin(obs.y,0),0.3,mem.size-0.3)};
  mem.head = wrap(fin(obs.heading,0)*D2R);
  mem.rawHead = mem.head;
  mem.bias = 0;
  mem.compassBad = 0;

  mem.wheelL = fin(obs.wheelLeft,0);
  mem.wheelR = fin(obs.wheelRight,0);
  mem.vMeas = (mem.wheelL+mem.wheelR)/2;
  mem.yawMeas = (mem.wheelR-mem.wheelL)/0.6;
  mem.wantV = 0;
  mem.slip = 1;

  mem.ctlL = {i:0,prev:0};
  mem.ctlR = {i:0,prev:0};

  mem.lastBatt = fin(obs.battery,1);
  mem.epm = 0.0007;
  mem.drillRate = 0.005;
  mem.lastGX = fin(obs.x,mem.pos.x);
  mem.lastGY = fin(obs.y,mem.pos.y);
  mem.gpsStaleT = 0;
  mem.gpsWasStale = false;
  mem.lastGpsNewT = mem.t;

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;

  mem.path = [];
  mem.pathIdx = 0;
  mem.pathGoal = null;
  mem.pathDirty = true;
  mem.lastPlan = -999;

  mem.sites = [];
  mem.nextSiteId = 1;
  mem.visibleSite = null;
  mem.avgValue = 1;
  mem.samples = 0;
  mem.sciMax = 0;

  mem.recoverUntil = -1;
  mem.recoverBackUntil = -1;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.lastRecoverT = -999;
  mem.stallT = 0;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;

  mem.rayLast = new Float32Array(9);
  mem.rayStuck = new Int16Array(9);
  for(let i=0;i<9;i++){ mem.rayLast[i] = 15; mem.rayStuck[i] = 0; }

  mem.dockedWait = false;
  mem.chargeStart = -1;
  mem.chargeLastBatt = mem.lastBatt;
  mem.dockNoGain = 0;

  mem.exploreCount = 0;
  mem.lastScienceSearch = -999;
  mem.rng = (Math.floor(Math.abs(mem.pos.x*1000 + mem.pos.y*17 + mem.base.x*31 + mem.base.y*13))+1234567)>>>0;
}

function updateSensors(obs,mem){
  let t = fin(obs.t,mem.t+0.1);
  let dt = t-mem.t;
  if(!(dt>0) || dt>1.2) dt = 0.1;
  if(dt<0.02) dt = 0.02;
  mem.dt = dt; mem.t = t;

  const wl = fin(obs.wheelLeft,0);
  const wr = fin(obs.wheelRight,0);
  mem.wheelL = wl; mem.wheelR = wr;
  const v = (wl+wr)/2;
  const yaw = (wr-wl)/0.6;
  mem.vMeas = v; mem.yawMeas = yaw;

  const raw = wrap(fin(obs.heading, mem.rawHead*R2D)*D2R);
  const pred = wrap(mem.head + yaw*dt);
  const meas = wrap(raw - mem.bias);
  const diff = wrap(meas - pred);
  const jump = Math.abs(diff) > 1.0 && Math.abs(yaw) < 0.9;
  if(jump){
    mem.compassBad = Math.min(100,mem.compassBad+1);
    mem.head = pred;
  }else{
    mem.compassBad = Math.max(0,mem.compassBad-0.15);
    let alpha = mem.compassBad > 10 ? 0.22 : 0.66;
    mem.head = wrap(pred + wrap(meas-pred)*alpha);
  }
  mem.rawHead = raw;

  const gx = fin(obs.x,mem.lastGX);
  const gy = fin(obs.y,mem.lastGY);
  const gd = hyp(gx-mem.lastGX,gy-mem.lastGY);
  const gpsNew = gd > 0.008;

  if(gpsNew){
    mem.gpsStaleT = 0;
    const interval = t - mem.lastGpsNewT;
    if(interval > 0.05 && interval < 3.0 && Math.abs(v) > 0.15){
      const expected = Math.abs(v)*interval;
      if(expected > 0.04){
        const ratio = gd/expected;
        if(ratio > 0.05 && ratio < 2.5) mem.slip = clamp(mem.slip*0.9 + ratio*0.1,0.05,1.6);
      }
    }
    mem.lastGpsNewT = t;
  }else if(Math.abs(v) > 0.06){
    mem.gpsStaleT += dt;
  }else{
    mem.gpsStaleT = 0;
  }

  const stale = mem.gpsStaleT > 1.3;
  if(!stale){
    const ex = gx-mem.pos.x;
    const ey = gy-mem.pos.y;
    const ed = hyp(ex,ey);
    let alpha = 0.45;
    if(ed < 1.0) alpha = 0.7;
    if(ed > 8.0) alpha = 0.32;
    if(mem.gpsWasStale) alpha = 0.9;
    mem.pos.x += ex*alpha;
    mem.pos.y += ey*alpha;
    if(ed > 4.0) mem.pathDirty = true;
    mem.gpsWasStale = false;
  }else{
    mem.pos.x += v*Math.cos(mem.head)*dt;
    mem.pos.y += v*Math.sin(mem.head)*dt;
    mem.gpsWasStale = true;
  }
  mem.pos.x = clamp(mem.pos.x,0.3,mem.size-0.3);
  mem.pos.y = clamp(mem.pos.y,0.3,mem.size-0.3);

  if(gpsNew && Math.abs(v) > 0.35 && Math.abs(wr-wl) < 0.35){
    const mdx = gx-mem.lastGX;
    const mdy = gy-mem.lastGY;
    if(hyp(mdx,mdy) > 0.06){
      let course = Math.atan2(mdy,mdx);
      if(v < 0) course = wrap(course+PI);
      const bm = wrap(raw-course);
      if(Math.abs(bm) < 1.0) mem.bias = wrap(mem.bias*0.985 + bm*0.015);
    }
  }

  mem.lastGX = gx;
  mem.lastGY = gy;

  const batt = fin(obs.battery,mem.lastBatt);
  const solar = fin(obs.solar,0);
  if(!obs.docked && dt>0){
    const moved = Math.abs(v)*dt;
    const consumed = (mem.lastBatt-batt) + Math.max(0,solar)*dt;
    if(moved > 0.015 && consumed > 0.0000001){
      const load = 1 + 0.08*fin(obs.carried,0);
      const e = consumed/(moved*load);
      if(e > 0.00003 && e < 0.03){
        mem.epm = clamp(mem.epm*0.972 + e*0.028,0.00025,0.02);
      }
    }
    if(obs.drilling && consumed > 0.0000001){
      const r = consumed/dt;
      if(r > 0 && r < 0.05) mem.drillRate = clamp(mem.drillRate*0.96 + r*0.04,0.0004,0.03);
    }
  }
  mem.lastBatt = batt;
}

function markFree(mem,x,y){
  if(!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<0 || iy<0 || ix>=mem.gw || iy>=mem.gh) return;
  const idx = iy*mem.gw+ix;
  if(mem.freec[idx] < 255) mem.freec[idx]++;
}

function markObs(mem,x,y,s){
  if(!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<1 || iy<1 || ix>=mem.gw-1 || iy>=mem.gh-1) return;
  const add = Math.max(1,Math.floor(s||2));
  const idx = iy*mem.gw+ix;
  mem.obsc[idx] = Math.min(255,mem.obsc[idx]+add);
  for(let dx=-1;dx<=1;dx++){
    for(let dy=-1;dy<=1;dy++){
      if(dx===0 && dy===0) continue;
      const nx = ix+dx, ny = iy+dy;
      if(nx<0 || ny<0 || nx>=mem.gw || ny>=mem.gh) continue;
      const ni = ny*mem.gw+nx;
      mem.obsc[ni] = Math.min(255,mem.obsc[ni]+1);
    }
  }
}

function markHard(mem,x,y){
  if(!isFinite(x) || !isFinite(y)) return;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<1 || iy<1 || ix>=mem.gw-1 || iy>=mem.gh-1) return;
  const idx = iy*mem.gw+ix;
  mem.obsc[idx] = 255;
  for(let dx=-1;dx<=1;dx++){
    for(let dy=-1;dy<=1;dy++){
      if(dx===0 && dy===0) continue;
      const nx = ix+dx, ny = iy+dy;
      if(nx<0 || ny<0 || nx>=mem.gw || ny>=mem.gh) continue;
      const ni = ny*mem.gw+nx;
      mem.obsc[ni] = Math.min(255,mem.obsc[ni]+12);
    }
  }
}

function updateGrid(obs,mem){
  const rays = obs.rays || [];
  const moving = (Math.abs(mem.wheelL)+Math.abs(mem.wheelR)) > 0.12;
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;

    if(Math.abs(r-mem.rayLast[i]) < 0.0005 && moving) mem.rayStuck[i]++;
    else mem.rayStuck[i] = 0;
    mem.rayLast[i] = r;
    if(mem.rayStuck[i] > 70) continue;

    const ang = mem.head + RAYA[i];
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const maxd = Math.min(r,14.4);
    for(let d=0.7; d<maxd-0.35; d+=1.2){
      markFree(mem,mem.pos.x + ca*d, mem.pos.y + sa*d);
    }
    if(r > 0.22 && r < 14.5){
      const strength = r<1.6 ? 6 : (r<3.5 ? 4 : 3);
      markObs(mem,mem.pos.x + ca*r, mem.pos.y + sa*r, strength);
    }
  }
  markFree(mem,mem.pos.x,mem.pos.y);
}

function cellBlocked(mem,ix,iy){
  if(ix<2 || iy<2 || ix>=mem.gw-2 || iy>=mem.gh-2) return true;
  const wx = ix*mem.res;
  const wy = iy*mem.res;
  if(wx < 1.0 || wx > mem.size-1.0 || wy < 1.0 || wy > mem.size-1.0) return true;
  const idx = iy*mem.gw+ix;
  const o = mem.obsc[idx];
  const f = mem.freec[idx];
  if(o >= 12) return true;
  if(o >= 5 && f < 2) return true;
  if(o >= 3 && f === 0) return true;
  return false;
}

function blockedWorld(mem,x,y){
  if(x < 0.8 || x > mem.size-0.8 || y < 0.8 || y > mem.size-0.8) return true;
  const ix = Math.round(x/mem.res);
  const iy = Math.round(y/mem.res);
  if(ix<0 || iy<0 || ix>=mem.gw || iy>=mem.gh) return true;
  return cellBlocked(mem,ix,iy);
}

function nearestFreeCell(mem,cx,cy,maxR){
  if(!cellBlocked(mem,cx,cy)) return cy*mem.gw+cx;
  for(let r=1;r<=maxR;r++){
    for(let dx=-r;dx<=r;dx++){
      for(let dy=-r;dy<=r;dy++){
        if(Math.max(Math.abs(dx),Math.abs(dy)) !== r) continue;
        const nx = cx+dx, ny = cy+dy;
        if(nx<2 || ny<2 || nx>=mem.gw-2 || ny>=mem.gh-2) continue;
        if(!cellBlocked(mem,nx,ny)) return ny*mem.gw+nx;
      }
    }
  }
  return -1;
}

function planPath(mem,gx,gy){
  const gw = mem.gw;
  const n = mem.n;
  let sx = Math.round(mem.pos.x/mem.res);
  let sy = Math.round(mem.pos.y/mem.res);
  let gxi = Math.round(gx/mem.res);
  let gyi = Math.round(gy/mem.res);
  sx = clamp(sx,2,gw-3); sy = clamp(sy,2,mem.gh-3);
  gxi = clamp(gxi,2,gw-3); gyi = clamp(gyi,2,mem.gh-3);

  const start = nearestFreeCell(mem,sx,sy,7);
  let goal = nearestFreeCell(mem,gxi,gyi,11);
  if(start < 0){
    mem.path = [];
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = mem.t;
    return false;
  }
  if(goal < 0) goal = start;

  if(start === goal){
    mem.path = [start];
    mem.pathIdx = 0;
    mem.pathGoal = {x:gx,y:gy};
    mem.lastPlan = mem.t;
    mem.pathDirty = false;
    return true;
  }

  mem.dist.fill(-1);
  mem.par.fill(-1);
  const q = mem.q, par = mem.par, dist = mem.dist;
  let qh = 0, qt = 0;
  dist[start] = 0; par[start] = -1; q[qt++] = start;
  let found = false;
  let best = start;
  let bestH = 1e100;
  const gxc = goal % gw;
  const gyc = (goal/gw)|0;

  while(qh < qt && qh < n){
    const cur = q[qh++];
    const cx = cur % gw;
    const cy = (cur/gw)|0;
    const ddx = cx-gxc, ddy = cy-gyc;
    const hh = ddx*ddx+ddy*ddy;
    if(hh < bestH){ bestH = hh; best = cur; }
    if(cur === goal){ found = true; break; }
    const nd = dist[cur]+1;
    for(let k=0;k<8;k++){
      const nx = cx+DX8[k];
      const ny = cy+DY8[k];
      if(nx<2 || ny<2 || nx>=gw-2 || ny>=mem.gh-2) continue;
      const ni = ny*gw+nx;
      if(dist[ni] !== -1) continue;
      if(cellBlocked(mem,nx,ny)) continue;
      if(k >= 4){
        if(cellBlocked(mem,cx+DX8[k],cy) || cellBlocked(mem,cx,cy+DY8[k])) continue;
      }
      dist[ni] = nd;
      par[ni] = cur;
      q[qt++] = ni;
      if(qt >= n) break;
    }
  }

  const end = found ? goal : best;
  const arr = [];
  let cur = end;
  let guard = 0;
  while(cur !== -1 && guard++ < n+10){
    arr.push(cur);
    if(cur === start) break;
    cur = par[cur];
  }
  if(arr.length === 0 || arr[arr.length-1] !== start){
    mem.path = [start];
  }else{
    arr.reverse();
    mem.path = arr;
  }
  mem.pathIdx = 0;
  mem.pathGoal = {x:gx,y:gy};
  mem.lastPlan = mem.t;
  mem.pathDirty = false;
  return found;
}

function ensurePath(mem,gx,gy){
  let need = false;
  if(!mem.path || mem.path.length < 2) need = true;
  else if(!mem.pathGoal || hyp(mem.pathGoal.x-gx,mem.pathGoal.y-gy) > 2.5) need = true;
  else if(mem.pathDirty) need = true;
  else if(mem.t-mem.lastPlan > 2.5) need = true;
  if(need && mem.t-mem.lastPlan > 0.2) planPath(mem,gx,gy);
}

function getWaypoint(mem){
  if(!mem.path || mem.path.length === 0) return null;
  const gw = mem.gw;
  let idx = mem.pathIdx || 0;
  while(idx < mem.path.length-1){
    const id = mem.path[idx];
    const x = (id%gw)*mem.res;
    const y = ((id/gw)|0)*mem.res;
    if(hyp(x-mem.pos.x,y-mem.pos.y) < 1.1) idx++;
    else break;
  }
  mem.pathIdx = idx;
  let chosen = idx;
  const look = 3.0 + Math.min(2.0,Math.abs(mem.vMeas)*1.5);
  for(let k=idx;k<mem.path.length && k<idx+14;k++){
    const id = mem.path[k];
    const x = (id%gw)*mem.res;
    const y = ((id/gw)|0)*mem.res;
    const d = hyp(x-mem.pos.x,y-mem.pos.y);
    chosen = k;
    if(d > look) break;
  }
  if(chosen < mem.path.length-1){
    const id = mem.path[chosen];
    const x = (id%gw)*mem.res;
    const y = ((id/gw)|0)*mem.res;
    if(hyp(x-mem.pos.x,y-mem.pos.y) < 0.35) chosen++;
  }
  const id = mem.path[Math.min(chosen,mem.path.length-1)];
  return {x:(id%gw)*mem.res, y:((id/gw)|0)*mem.res};
}

function clearLine(mem,x1,y1,x2,y2){
  const dx = x2-x1, dy = y2-y1;
  const d = hyp(dx,dy);
  if(d < 0.3) return true;
  const n = Math.ceil(d/1.3);
  for(let i=1;i<n;i++){
    const f = i/n;
    if(blockedWorld(mem,x1+dx*f,y1+dy*f)) return false;
  }
  return true;
}

function wheelControl(target,meas,st,dt){
  target = clamp(target,-3.0,3.0);
  if(st.prev !== undefined && st.prev*target < -0.01) st.i *= 0.22;
  st.prev = target;
  const err = target-meas;
  st.i += err*dt*1.6;
  st.i = clamp(st.i,-0.9,0.9);
  let raw = target/3.0 + 0.55*err + st.i;
  let u = clamp(raw,-1,1);
  if(raw !== u){
    if((raw>u && err>0) || (raw<u && err<0)) st.i -= err*dt*1.4;
    st.i = clamp(st.i,-0.9,0.9);
  }
  if(Math.abs(target) < 0.012 && Math.abs(meas) < 0.025){
    st.i *= Math.exp(-dt*2.8);
    if(Math.abs(st.i) < 0.015) st.i = 0;
  }
  if(target > 0.035 && u < 0.055) u = 0.055;
  if(target < -0.035 && u > -0.055) u = -0.055;
  return clamp(u,-1,1);
}

function brakeCmd(obs,mem){
  mem.wantV = 0;
  return {
    left:wheelControl(0,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(0,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays = obs.rays || [];
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let front = 15;
  let leftOpen = 0;
  let rightOpen = 0;

  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayStuck && mem.rayStuck[i] > 70) r = 15;

    if(i >= 3 && i <= 5 && r < front) front = r;
    if(i > 4) leftOpen += Math.min(r,10);
    else if(i < 4) rightOpen += Math.min(r,10);

    if(r < 6.0){
      const ang = mem.head + RAYA[i];
      let w = (6.0-r)/6.0;
      if(i === 4) w *= 2.0;
      else if(i >= 3 && i <= 5) w *= 1.45;
      else w *= 0.75;
      if(r < 2.0) w *= 1.7;
      vx -= Math.cos(ang)*w*1.25;
      vy -= Math.sin(ang)*w*1.25;
    }
  }

  const m = 3.2;
  if(mem.pos.x < m) vx += (m-mem.pos.x)/m*2.0;
  if(mem.pos.x > mem.size-m) vx -= (mem.pos.x-(mem.size-m))/m*2.0;
  if(mem.pos.y < m) vy += (m-mem.pos.y)/m*2.0;
  if(mem.pos.y > mem.size-m) vy -= (mem.pos.y-(mem.size-m))/m*2.0;

  if(hyp(vx,vy) > 0.08) desired = Math.atan2(vy,vx);
  let err = wrap(desired-mem.head);

  let sp = Math.min(speedLimit,2.75);
  if(front < 4.6){
    const cap = Math.max(0.05,(front-0.65)*0.58);
    if(sp > cap) sp = cap;
  }
  if(front < 1.0){
    sp = 0;
    err = (leftOpen >= rightOpen ? 1 : -1)*1.35;
  }else if(Math.abs(err) > 1.2){
    sp = 0;
  }else if(Math.abs(err) > 0.68){
    sp = Math.min(sp,0.72);
  }

  let v = Math.max(0,sp);
  let w = clamp(err*2.6,-2.4,2.4);
  if(v < 0.03){
    v = 0;
    if(Math.abs(err) > 0.10) w = clamp(err*2.2,-2.1,2.1);
    else w = 0;
  }

  if(mem.slip < 0.65) v *= 0.86;
  if(mem.slip < 0.45) v *= 0.78;
  const pitch = fin(obs.pitch,0);
  if(Math.abs(pitch) > 18) v *= 0.82;
  const batt = fin(obs.battery,1);
  if(batt < 0.15) v = Math.min(v,0.85);
  if(batt < 0.10) v = Math.min(v,0.55);

  let L = clamp(v - w*0.3,-3.0,3.0);
  let R = clamp(v + w*0.3,-3.0,3.0);
  mem.wantV = v;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function driveTo(obs,mem,gx,gy,speed,arrive){
  const dx = gx-mem.pos.x;
  const dy = gy-mem.pos.y;
  const d = hyp(dx,dy);
  if(d <= arrive) return brakeCmd(obs,mem);

  let tx = gx, ty = gy;
  if(d > 5.5){
    const direct = clearLine(mem,mem.pos.x,mem.pos.y,gx,gy);
    if(!direct){
      ensurePath(mem,gx,gy);
      if(mem.path && mem.path.length > 1){
        const wp = getWaypoint(mem);
        if(wp && hyp(wp.x-mem.pos.x,wp.y-mem.pos.y) > 0.35){
          tx = wp.x; ty = wp.y;
        }
      }
    }else{
      mem.path = [];
    }
  }

  let sp = speed;
  if(d < 8.0){
    sp = Math.min(sp, Math.max(0.22,(d-arrive)*0.62+0.16));
  }
  const desired = Math.atan2(ty-mem.pos.y,tx-mem.pos.x);
  return driveHeading(obs,mem,desired,sp);
}

function updateSites(obs,mem){
  mem.visibleSite = null;
  const os = obs.site;
  if(os && isFinite(os.distance) && fin(os.distance,999) < 8.6){
    const d = fin(os.distance,999);
    const bear = fin(os.bearing,0);
    const val = fin(os.value,0);
    if(d >= 0 && d < 8.6 && val > 0){
      const ang = mem.head + bear*D2R;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      let best = null;
      let bd = 3.2*3.2;
      for(let i=0;i<mem.sites.length;i++){
        const s = mem.sites[i];
        if(s.sampled) continue;
        const ddx = s.x-sx, ddy = s.y-sy;
        const dd = ddx*ddx+ddy*ddy;
        if(dd < bd){ bd = dd; best = s; }
      }
      if(best){
        best.x += (sx-best.x)*0.35;
        best.y += (sy-best.y)*0.35;
        best.value = val;
        best.lastSeen = mem.t;
      }else if(mem.sites.length < 350){
        best = {id:mem.nextSiteId++, x:sx, y:sy, value:val, sampled:false, lastSeen:mem.t, ignoreUntil:0};
        mem.sites.push(best);
      }
      if(best){
        mem.visibleSite = {id:best.id,x:best.x,y:best.y,value:best.value,rawDist:d,rawBearing:bear};
      }
    }
  }
  const sci = fin(obs.science,0);
  if(sci > mem.sciMax) mem.sciMax = sci;
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++) if(mem.sites[i].id === id) return mem.sites[i];
  return null;
}

function findSiteNear(mem,x,y,rad){
  let best = null;
  let bd = rad*rad;
  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    const dx = s.x-x, dy = s.y-y;
    const dd = dx*dx+dy*dy;
    if(dd < bd){ bd = dd; best = s; }
  }
  return best;
}

function markHintDone(mem,x,y){
  let best = -1;
  let bd = 30*30;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x, dy = h.y-y;
    const dd = dx*dx+dy*dy;
    if(dd < bd){ bd = dd; best = i; }
  }
  if(best >= 0) mem.hints[best].status = 2;
}

function cancelSearch(mem){
  if(mem.search){
    const id = mem.search.hintId;
    if(id >= 0 && id < mem.hints.length && mem.hints[id].status === 1) mem.hints[id].status = 0;
    mem.search = null;
  }
}

function finishSearch(mem){
  if(mem.search){
    const id = mem.search.hintId;
    if(id >= 0 && id < mem.hints.length){
      if(mem.hints[id].status < 2) mem.hints[id].status = 2;
    }
  }
  mem.search = null;
  mem.task = null;
  mem.mode = 'idle';
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
}

function makeSpiral(cx,cy,R,spacing){
  const pts = [];
  const rr = clamp(R,10,30);
  const sp = clamp(spacing,10,16);
  const a = sp/(2*PI);
  const maxTh = (2*PI*rr)/sp;
  let lastX = cx, lastY = cy;
  pts.push({x:cx,y:cy});
  for(let th=0.03; th<=maxTh; th+=0.035){
    const r = a*th;
    if(r > rr) break;
    const x = clamp(cx + Math.cos(th)*r,2,398);
    const y = clamp(cy + Math.sin(th)*r,2,398);
    if(hyp(x-lastX,y-lastY) >= 4.0){
      pts.push({x:x,y:y});
      lastX = x; lastY = y;
    }
  }
  return pts;
}

function beginSearch(obs,mem,id,cx,cy,value,R){
  if(id >= 0 && id < mem.hints.length) mem.hints[id].status = 1;
  const rad = clamp(R||18,12,26);
  const pts = makeSpiral(cx,cy,rad,14);
  const maxT = clamp(22 + rad*2.6,48,100);
  mem.search = {
    hintId:id,
    cx:cx,
    cy:cy,
    pts:pts,
    idx:0,
    startT:mem.t,
    ptT:mem.t,
    maxT:maxT,
    value:value||0.2,
    centerChecked:false
  };
  mem.mode = 'search';
  mem.approach = null;
  mem.task = null;
  mem.path = [];
  mem.pathDirty = true;
  return doSearch(obs,mem);
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(mem.t-S.startT > S.maxT){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  if(!S.centerChecked && hyp(mem.pos.x-S.cx,mem.pos.y-S.cy) < 2.8){
    S.centerChecked = true;
    const sci = fin(obs.science,0);
    if(sci < 1e-8 && !obs.site && !mem.visibleSite){
      finishSearch(mem);
      return brakeCmd(obs,mem);
    }
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    if(hyp(p.x-mem.pos.x,p.y-mem.pos.y) < 1.3){
      S.idx++;
      S.ptT = mem.t;
      mem.path = [];
      mem.pathDirty = true;
    }else break;
  }

  if(S.idx >= S.pts.length){
    finishSearch(mem);
    return brakeCmd(obs,mem);
  }

  if(mem.t-S.ptT > 17){
    S.idx++;
    S.ptT = mem.t;
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }

  const p = S.pts[S.idx];
  let sp = 1.9;
  if(S.value > 0.45*mem.maxHintVal) sp = 2.15;
  if(fin(obs.timeLeft,0) < 120) sp = 1.55;
  return driveTo(obs,mem,p.x,p.y,sp,1.15);
}

function startApproach(obs,mem,vis){
  cancelSearch(mem);
  mem.mode = 'approach';
  mem.task = null;
  mem.approach = {
    id:vis.id,
    x:vis.x,
    y:vis.y,
    value:vis.value,
    startT:mem.t,
    lastSeen:mem.t,
    lastDist:vis.rawDist
  };
  mem.path = [];
  mem.pathDirty = true;
}

function startDrill(obs,mem,app){
  mem.mode = 'drill';
  mem.drill = {
    id:app.id,
    sx:app.x,
    sy:app.y,
    value:app.value,
    before:fin(obs.carried,0),
    startT:mem.t,
    x:mem.pos.x,
    y:mem.pos.y
  };
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
  mem.wantV = 0;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  if(mem.drill){
    const s = findSiteNear(mem,mem.drill.sx,mem.drill.sy,5.0);
    if(s) s.ignoreUntil = mem.t+80;
  }
  mem.drill = null;
  mem.approach = null;
  mem.task = null;
  mem.search = null;
  mem.path = [];
  mem.pathDirty = true;
  mem.mode = 'idle';
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(mem,obs);
  return brakeCmd(obs,mem);
}

function onSampleSuccess(obs,mem,D){
  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(hyp(s.x-D.sx,s.y-D.sy) < 4.2 || hyp(s.x-D.x,s.y-D.y) < 4.2) s.sampled = true;
  }
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status < 2 && hyp(h.x-D.sx,h.y-D.sy) < 32) h.status = 2;
  }
  mem.samples++;
  mem.avgValue = (mem.avgValue*(mem.samples-1)+D.value)/Math.max(1,mem.samples);
  mem.drill = null;
  mem.approach = null;
  mem.search = null;
  mem.task = null;
  mem.mode = 'idle';
  mem.path = [];
  mem.pathDirty = true;
  mem.wantV = 0;
  if(fin(obs.carried,0) >= mem.cap || needReturn(obs,mem)) startReturn(mem,obs);
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D = mem.drill;
  if(!D){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried > D.before){
    return onSampleSuccess(obs,mem,D);
  }

  const drilling = fin(obs.drilling,0);
  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const em = clamp(mem.epm,0.00025,0.02);
  if(drilling < 5.35){
    if(fin(obs.timeLeft,1200) < bd/1.2 + 8){
      return abortDrill(obs,mem);
    }
    if(fin(obs.battery,0) < bd*em*1.6 + 0.03){
      return abortDrill(obs,mem);
    }
  }
  if(mem.t-D.startT > 11.5 && carried <= D.before){
    return abortDrill(obs,mem);
  }

  let dx = D.x-mem.pos.x;
  let dy = D.y-mem.pos.y;
  let dd = hyp(dx,dy);
  let v = 0;
  let w = 0;
  if(dd > 0.035){
    const desired = Math.atan2(dy,dx);
    const err = wrap(desired-mem.head);
    const localF = dx*Math.cos(mem.head)+dy*Math.sin(mem.head);
    v = clamp(localF*0.55,-0.12,0.12);
    w = clamp(err*0.75,-0.20,0.20);
  }
  const L = clamp(v-w*0.3,-0.35,0.35);
  const R = clamp(v+w*0.3,-0.35,0.35);
  mem.wantV = 0;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:true
  };
}

function doApproach(obs,mem){
  const app = mem.approach;
  if(!app){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap){
    startReturn(mem,obs);
    return brakeCmd(obs,mem);
  }

  let useActual = false;
  let d = 999;
  let bear = 0;
  const os = obs.site;
  if(os && isFinite(os.distance) && fin(os.distance,999) < 8.6){
    d = fin(os.distance,999);
    bear = fin(os.bearing,0);
    const val = fin(os.value,app.value);
    const ang = mem.head + bear*D2R;
    const sx = mem.pos.x + Math.cos(ang)*d;
    const sy = mem.pos.y + Math.sin(ang)*d;
    app.x += (sx-app.x)*0.4;
    app.y += (sy-app.y)*0.4;
    app.value = val;
    app.lastSeen = mem.t;
    app.lastDist = d;
    useActual = true;
  }else{
    d = hyp(app.x-mem.pos.x,app.y-mem.pos.y);
    if(d < 0.8 && mem.t-app.lastSeen > 2.0){
      const s = findSiteNear(mem,app.x,app.y,6);
      if(s) s.ignoreUntil = mem.t+80;
      mem.approach = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
  }

  if(mem.t-app.startT > 55){
    const s = findSiteNear(mem,app.x,app.y,6);
    if(s) s.ignoreUntil = mem.t+100;
    mem.approach = null;
    mem.mode = 'idle';
    mem.path = [];
    mem.pathDirty = true;
    return brakeCmd(obs,mem);
  }

  const maxWheel = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  if(useActual && d <= 1.47){
    if(maxWheel < 0.14) return startDrill(obs,mem,app);
    return brakeCmd(obs,mem);
  }
  if(!useActual && d < 1.0 && maxWheel < 0.14 && mem.t-app.lastSeen < 6){
    return startDrill(obs,mem,app);
  }

  let desired;
  if(useActual) desired = mem.head + bear*D2R;
  else desired = Math.atan2(app.y-mem.pos.y,app.x-mem.pos.x);

  let sp = 2.2;
  if(d < 8.0) sp = Math.min(sp,1.45);
  if(d < 5.0) sp = Math.min(sp,0.85);
  if(d < 3.0) sp = Math.min(sp,0.38);
  if(d < 1.9) sp = Math.min(sp,0.16);
  return driveHeading(obs,mem,desired,sp);
}

function doTravel(obs,mem){
  const task = mem.task;
  if(!task){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  let sp = 2.45;
  if(carried > 0) sp = 2.25;
  if(fin(obs.battery,0) < 0.28) sp = 1.55;
  if(mem.slip < 0.7) sp *= 0.88;

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const d = hyp(h.x-mem.pos.x,h.y-mem.pos.y);
    if(d < 3.1){
      return beginSearch(obs,mem,h.id,h.x,h.y,h.v,task.searchR||18);
    }
    if(mem.t-task.startT > 330 && d > 15){
      h.status = 2;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
    return driveTo(obs,mem,h.x,h.y,sp,2.6);
  }

  if(task.type === 'site'){
    const s = findSiteById(mem,task.id);
    if(!s || s.sampled){
      mem.task = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const d = hyp(s.x-mem.pos.x,s.y-mem.pos.y);
    if(d < 1.2 && !obs.site){
      s.ignoreUntil = mem.t+70;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
    if(mem.t-task.startT > 280 && d > 10){
      s.ignoreUntil = mem.t+120;
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
    return driveTo(obs,mem,s.x,s.y,sp,0.75);
  }

  if(task.type === 'explore'){
    const d = hyp(task.x-mem.pos.x,task.y-mem.pos.y);
    if(d < 3.2 || (fin(obs.science,0) > 1e-7 && d < 13)){
      return beginSearch(obs,mem,-1,task.x,task.y,task.value||0.3,task.searchR||25);
    }
    if(mem.t-task.startT > 260 && d > 12){
      mem.task = null;
      mem.mode = 'idle';
      mem.path = [];
      mem.pathDirty = true;
      return brakeCmd(obs,mem);
    }
    return driveTo(obs,mem,task.x,task.y,sp,2.6);
  }

  mem.task = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function needReturn(obs,mem){
  if(obs.docked) return false;
  const carried = fin(obs.carried,0);
  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const timeLeft = fin(obs.timeLeft,1200);
  const batt = fin(obs.battery,1);
  const em = clamp(mem.epm,0.00025,0.02);
  const load = 1 + 0.08*carried;
  const eNeed = bd*em*load*1.55 + 0.04;
  const tNeed = bd/1.2 + 15;

  if(carried > 0){
    if(batt < eNeed + 0.02) return true;
    if(timeLeft < tNeed + 15) return true;
    if(timeLeft < 24) return true;
  }else{
    if(bd > 18 && batt < eNeed + 0.025) return true;
    if(batt < 0.13) return true;
    if(timeLeft < tNeed + 8) return true;
  }
  return false;
}

function startReturn(mem,obs){
  if(mem.mode === 'return') return;
  cancelSearch(mem);
  mem.task = null;
  mem.approach = null;
  mem.search = null;
  mem.mode = 'return';
  mem.path = [];
  mem.pathDirty = true;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function doReturn(obs,mem){
  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  let d = bd;
  let desired = Math.atan2(mem.base.y-mem.pos.y,mem.base.x-mem.pos.x);
  let useBeacon = false;

  const beacon = obs.beacon;
  if(beacon && isFinite(beacon.distance) && isFinite(beacon.bearing)){
    const bdist = fin(beacon.distance,999);
    const bb = fin(beacon.bearing,0)*D2R;
    if(bdist < 20 && (mem.gpsStaleT > 1.0 || bdist < bd+4 || bdist < 6)){
      d = bdist;
      desired = mem.head + bb;
      useBeacon = true;
    }
  }

  if(d < 1.8 && Math.abs(mem.vMeas) < 0.16) return brakeCmd(obs,mem);
  if(d < 2.5 && Math.abs(mem.vMeas) < 0.22) return brakeCmd(obs,mem);

  if(useBeacon){
    let sp = d < 5 ? Math.max(0.18,d*0.42) : 2.05;
    return driveHeading(obs,mem,desired,sp);
  }
  let sp = 2.5;
  if(d < 9) sp = Math.min(sp,Math.max(0.22,d*0.38));
  if(d < 4) sp = Math.min(sp,0.45);
  return driveTo(obs,mem,mem.base.x,mem.base.y,sp,1.0);
}

function shouldTakeVisible(obs,mem,vis){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap) return false;
  if(mem.mode === 'return' || mem.mode === 'drill') return false;
  if(mem.mode === 'approach') return true;
  if(!(vis.value > 0)) return false;
  if(carried < mem.cap-1) return true;

  let tval = 0;
  let tx = vis.x, ty = vis.y;
  if(mem.task){
    tval = fin(mem.task.value,0);
    tx = mem.task.x; ty = mem.task.y;
  }else if(mem.search){
    tval = fin(mem.search.value,0);
    tx = mem.search.cx; ty = mem.search.cy;
  }
  if(tval <= 0) return true;
  const dt = hyp(tx-mem.pos.x,ty-mem.pos.y);
  if(vis.value >= tval*0.75) return true;
  if(dt < 12) return true;
  if(vis.value >= tval*0.35 && dt > 70) return true;
  return false;
}

function startExplore(obs,mem){
  const sci = fin(obs.science,0);
  if(sci > 1e-7 && mem.t-mem.lastScienceSearch > 22){
    mem.lastScienceSearch = mem.t;
    mem.task = {
      type:'explore',
      id:-1,
      x:mem.pos.x,
      y:mem.pos.y,
      value:0.35,
      searchR:30,
      startT:mem.t
    };
    mem.mode = 'travel';
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathDirty = true;
    return true;
  }

  const bd = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  if(fin(obs.timeLeft,0) < 65 || fin(obs.battery,0) < 0.17){
    if(bd > 6) startReturn(mem,obs);
    return false;
  }

  const n = mem.exploreCount++;
  let ang = n*2.399963229728653 + ((mem.rng>>>8)%1000)*0.0001;
  let rad = 50 + ((n*37)%120);
  let cx, cy;
  if(bd > 145 && (n%2 === 0)){
    cx = mem.pos.x + Math.cos(ang)*80;
    cy = mem.pos.y + Math.sin(ang)*80;
  }else{
    cx = mem.base.x + Math.cos(ang)*rad;
    cy = mem.base.y + Math.sin(ang)*rad;
  }
  cx = clamp(cx,10,mem.size-10);
  cy = clamp(cy,10,mem.size-10);
  if(hyp(cx-mem.pos.x,cy-mem.pos.y) < 18){
    ang += 1.1;
    cx = clamp(cx + Math.cos(ang)*45,10,mem.size-10);
    cy = clamp(cy + Math.sin(ang)*45,10,mem.size-10);
  }
  mem.task = {
    type:'explore',
    id:-1,
    x:cx,
    y:cy,
    value:0.32,
    searchR:25,
    startT:mem.t
  };
  mem.mode = 'travel';
  mem.search = null;
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
  return true;
}

function chooseNext(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap){
    startReturn(mem,obs);
    return false;
  }

  const bdNow = hyp(mem.pos.x-mem.base.x,mem.pos.y-mem.base.y);
  const timeLeft = fin(obs.timeLeft,1200);
  const batt = fin(obs.battery,1);
  const em = clamp(mem.epm,0.00025,0.02);
  const load = 1 + 0.08*carried;
  let best = null;
  let bestScore = -1e100;

  function consider(x,y,val,type,id,conf,searchR){
    if(!(val > 0) || !isFinite(x) || !isFinite(y)) return;
    const dcur = hyp(x-mem.pos.x,y-mem.pos.y);
    const dbase = hyp(x-mem.base.x,y-mem.base.y);
    const sr = type === 'hint' ? (searchR||18) : 0;
    const extra = dcur + Math.max(0,dbase-bdNow);
    const denom = extra + sr*0.72 + 10;
    const timeTo = dcur/1.8 + (type === 'hint' ? sr/1.55 + 8 : 6) + 8;
    const timeBack = dbase/1.4 + 12;
    if(timeLeft < timeTo + timeBack + 8) return;
    const eNeed = (dcur + dbase + sr)*em*load*1.5 + 0.045;
    if(batt < eNeed) return;
    const vv = Math.max(0.05,val*conf);
    let s = Math.pow(vv+0.10,1.40)/denom;
    if(type === 'site') s *= 1.10;
    if(s > bestScore){
      bestScore = s;
      best = {
        type:type,
        id:id,
        x:x,
        y:y,
        value:val,
        searchR:sr,
        startT:mem.t
      };
    }
  }

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    const ratio = clamp(h.v/Math.max(0.5,mem.maxHintVal),0,1);
    const sr = 15 + 9*ratio;
    consider(h.x,h.y,h.v,'hint',h.id,0.72,sr);
  }

  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(s.ignoreUntil && s.ignoreUntil > mem.t) continue;
    const age = mem.t-(s.lastSeen||0);
    const conf = age < 90 ? 1.0 : 0.78;
    consider(s.x,s.y,s.value,'site',s.id,conf,0);
  }

  if(best){
    mem.search = null;
    mem.approach = null;
    mem.path = [];
    mem.pathDirty = true;
    if(best.type === 'site'){
      mem.mode = 'approach';
      mem.task = null;
      mem.approach = {
        id:best.id,
        x:best.x,
        y:best.y,
        value:best.value,
        startT:mem.t,
        lastSeen:mem.t,
        lastDist:99
      };
    }else{
      mem.task = best;
      mem.mode = 'travel';
    }
    return true;
  }

  if(carried > 0){
    startReturn(mem,obs);
    return false;
  }

  if(startExplore(obs,mem)) return true;

  if(bdNow > 6){
    startReturn(mem,obs);
    return false;
  }
  mem.task = null;
  mem.mode = 'idle';
  return false;
}

function dispatchMode(obs,mem){
  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);
  return brakeCmd(obs,mem);
}

function handleDocked(obs,mem){
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,0);
  const timeLeft = fin(obs.timeLeft,1200);

  if(carried > 0){
    mem.mode = 'dockedWait';
    mem.wantV = 0;
    mem.dockNoGain = 0;
    return brakeCmd(obs,mem);
  }

  if(mem.mode !== 'charge'){
    mem.mode = 'charge';
    mem.chargeStart = mem.t;
    mem.chargeLastBatt = batt;
    mem.dockNoGain = 0;
  }

  let target = 0.92;
  if(timeLeft > 650) target = 0.97;
  if(timeLeft < 160) target = 0.76;
  if(timeLeft < 70) target = 0.55;

  if(batt > mem.chargeLastBatt + 0.0002) mem.dockNoGain = 0;
  else mem.dockNoGain += mem.dt;
  mem.chargeLastBatt = batt;

  if(batt < target && mem.t-mem.chargeStart < 38 && mem.dockNoGain < 7 && timeLeft > 28){
    mem.wantV = 0;
    return brakeCmd(obs,mem);
  }

  mem.mode = 'idle';
  mem.task = null;
  mem.search = null;
  mem.approach = null;
  mem.path = [];
  mem.pathDirty = true;
  mem.chargeStart = -1;

  if(timeLeft < 10) return brakeCmd(obs,mem);
  if(chooseNext(obs,mem)) return dispatchMode(obs,mem);
  return brakeCmd(obs,mem);
}

function startRecovery(obs,mem,isBump){
  mem.recoverUntil = mem.t+1.7;
  mem.recoverBackUntil = mem.t+0.65;
  const rays = obs.rays || [];
  let left = 0, right = 0;
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i > 4) left += Math.min(r,10);
    else if(i < 4) right += Math.min(r,10);
  }
  if(Math.abs(left-right) < 0.1) mem.recoverTurn = (mem.recoverTurn === 1 ? -1 : 1);
  else mem.recoverTurn = left >= right ? 1 : -1;

  const bx = mem.pos.x + Math.cos(mem.head)*0.85;
  const by = mem.pos.y + Math.sin(mem.head)*0.85;
  if(isBump) markHard(mem,bx,by);
  else markObs(mem,bx,by,5);

  if(mem.t-mem.lastRecoverT < 15) mem.recoverCount++;
  else mem.recoverCount = 1;
  mem.lastRecoverT = mem.t;

  mem.path = [];
  mem.pathDirty = true;
  mem.stallT = 0;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;

  if(mem.recoverCount > 5 && mem.mode !== 'return'){
    if(mem.search){
      const id = mem.search.hintId;
      if(id >= 0 && id < mem.hints.length) mem.hints[id].status = 2;
    }
    if(mem.task){
      if(mem.task.type === 'hint'){
        const h = mem.hints[mem.task.id];
        if(h) h.status = 2;
      }else if(mem.task.type === 'site'){
        const s = findSiteById(mem,mem.task.id);
        if(s) s.ignoreUntil = mem.t+120;
      }
    }
    if(mem.approach){
      const s = findSiteById(mem,mem.approach.id);
      if(s) s.ignoreUntil = mem.t+120;
    }
    mem.task = null;
    mem.search = null;
    mem.approach = null;
    mem.mode = 'idle';
    mem.recoverCount = 0;
  }
}

function doRecovery(obs,mem){
  let v = 0;
  let w = mem.recoverTurn*1.25;
  if(mem.t < mem.recoverBackUntil){
    v = -0.48;
    w = mem.recoverTurn*0.55;
  }
  const L = clamp(v-w*0.3,-2.2,2.2);
  const R = clamp(v+w*0.3,-2.2,2.2);
  mem.wantV = 0;
  return {
    left:wheelControl(L,mem.wheelL,mem.ctlL,mem.dt),
    right:wheelControl(R,mem.wheelR,mem.ctlR,mem.dt),
    drill:false
  };
}

function act(obs,mem){
  if(!mem.init){
    initMission(obs,mem);
    return {left:0,right:0,drill:false};
  }

  updateSensors(obs,mem);
  updateGrid(obs,mem);
  updateSites(obs,mem);
  mem.tick = (mem.tick||0)+1;

  if(obs.docked) return handleDocked(obs,mem);

  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(obs.bumped){
    if(mem.recoverUntil <= mem.t) startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  if(mem.recoverUntil > mem.t) return doRecovery(obs,mem);

  if(mem.mode !== 'drill' && mem.mode !== 'idle'){
    if(Math.abs(mem.wantV) > 0.32 && Math.abs(mem.wheelL)+Math.abs(mem.wheelR) < 0.055){
      mem.stallT += mem.dt;
    }else{
      mem.stallT = Math.max(0,mem.stallT-mem.dt*1.5);
    }
    if(mem.stallT > 1.8){
      startRecovery(obs,mem,false);
      return doRecovery(obs,mem);
    }

    const moved = hyp(mem.pos.x-mem.progressX,mem.pos.y-mem.progressY);
    if(moved > 0.85){
      mem.progressX = mem.pos.x;
      mem.progressY = mem.pos.y;
      mem.progressT = mem.t;
    }
    if(mem.t-mem.progressT > 8.0 && Math.abs(mem.wantV) > 0.28 && mem.mode !== 'idle'){
      startRecovery(obs,mem,false);
      return doRecovery(obs,mem);
    }
  }else{
    mem.stallT = 0;
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    if(needReturn(obs,mem)) startReturn(mem,obs);
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    const vis = mem.visibleSite;
    if(vis && fin(obs.carried,0) < mem.cap){
      const s = findSiteById(mem,vis.id);
      const ignored = s && s.ignoreUntil && s.ignoreUntil > mem.t;
      if(!ignored){
        if(mem.mode !== 'approach'){
          if(shouldTakeVisible(obs,mem,vis)){
            startApproach(obs,mem,vis);
          }else if(s){
            s.ignoreUntil = mem.t + 28;
          }
        }
      }
    }
  }

  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(mem.mode === 'idle' || !mem.mode){
    if(chooseNext(obs,mem)) return dispatchMode(obs,mem);
    return brakeCmd(obs,mem);
  }

  return brakeCmd(obs,mem);
}

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const RAYA = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % (2*PI);
  if(a > PI) a -= 2*PI;
  if(a < -PI) a += 2*PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function fin(v,d){ return (typeof v === 'number' && isFinite(v)) ? v : d; }

function motorCmd(target, meas, st, dt){
  target = clamp(target,-3.0,3.0);
  if(st.prev !== undefined && st.prev * target < 0) st.i *= 0.3;
  st.prev = target;
  const err = target - meas;
  st.i += err * dt * 1.45;
  st.i = clamp(st.i,-0.85,0.85);
  let u = target / 2.8 + err * 0.9 + st.i;
  if(u > 1){
    u = 1;
    if(err > 0) st.i -= err * dt * 1.45;
  }else if(u < -1){
    u = -1;
    if(err < 0) st.i -= err * dt * 1.45;
  }
  if(target > 0.05 && u < 0.06) u = 0.06;
  if(target < -0.05 && u > -0.06) u = -0.06;
  if(Math.abs(target) < 0.02 && Math.abs(meas) < 0.03){
    st.i *= Math.exp(-dt * 2.2);
    if(Math.abs(st.i) < 0.01) st.i = 0;
  }
  return clamp(u,-1,1);
}

function brakeCmd(obs, mem){
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(0, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(0, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function initMission(obs, mem){
  mem.init = true;
  mem.t = fin(obs.t,0);
  mem.dt = 0.1;
  mem.size = fin((obs.mission||{}).size,400);
  mem.seconds = fin((obs.mission||{}).seconds,1200);
  mem.cap = Math.max(1,Math.floor(fin((obs.mission||{}).capacity,5)));
  const b = (obs.mission||{}).base || {x:fin(obs.x,0),y:fin(obs.y,0)};
  mem.base = {x:fin(b.x,fin(obs.x,0)), y:fin(b.y,fin(obs.y,0))};

  mem.hints = [];
  const hs = (obs.mission||{}).hints;
  if(Array.isArray(hs)){
    for(let i=0;i<hs.length;i++){
      const h = hs[i] || {};
      let x = fin(h.x,NaN), y = fin(h.y,NaN), v = fin(h.estimate,0.1);
      if(!isFinite(x) || !isFinite(y)) continue;
      if(!(v > 0)) v = 0.1;
      mem.hints.push({id:mem.hints.length,x:clamp(x,0,mem.size),y:clamp(y,0,mem.size),v:v,status:0});
    }
  }
  mem.maxHintVal = 0.5;
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;
  mem.maxValSeen = mem.maxHintVal;

  mem.sites = [];
  mem.nextSiteId = 1;
  mem.visible = null;
  mem.siteSamples = 0;
  mem.sciMax = 0;

  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;

  mem.ctlL = {i:0,prev:0};
  mem.ctlR = {i:0,prev:0};

  mem.pos = {x:clamp(fin(obs.x,mem.base.x),0.3,mem.size-0.3), y:clamp(fin(obs.y,mem.base.y),0.3,mem.size-0.3)};
  mem.head = wrap(fin(obs.heading,0)*D2R);
  mem.lastRawDeg = fin(obs.heading,0);
  mem.headBias = 0;
  mem.compassBad = 0;
  mem.wheelL = fin(obs.wheelLeft,0);
  mem.wheelR = fin(obs.wheelRight,0);
  mem.vMeas = (mem.wheelL+mem.wheelR)/2;
  mem.wantV = 0;
  mem.lastWant = 0;
  mem.slip = 1;

  mem.lastGpsX = fin(obs.x,mem.pos.x);
  mem.lastGpsY = fin(obs.y,mem.pos.y);
  mem.gpsStaleT = 0;
  mem.gpsWasStale = false;

  mem.lastBatt = fin(obs.battery,1);
  mem.epm = 0.0010;
  mem.drillE = 0.004;

  mem.rayLast = [];
  mem.rayStill = [];
  for(let i=0;i<9;i++){ mem.rayLast[i] = 15; mem.rayStill[i] = 0; }

  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;

  mem.recoverUntil = -1;
  mem.recoverStart = -999;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.lastRecoverT = -999;

  mem.chargeStart = -1;
  mem.chargeLastBatt = mem.lastBatt;
  mem.chargeNoGain = 0;
  mem.leaveBase = -999;
  mem.exploreCount = 0;
}

function markHintsNear(mem,x,y,rad){
  const r2 = rad*rad;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x, dy = h.y-y;
    if(dx*dx+dy*dy < r2) h.status = 2;
  }
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++) if(mem.sites[i].id === id) return mem.sites[i];
  return null;
}

function updateSites(obs,mem){
  mem.visible = null;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const d = fin(os.distance,999);
    const bear = fin(os.bearing,0);
    const val = fin(os.value,0);
    if(d >= 0 && d < 8.6 && val > 0){
      const ang = mem.head + bear*D2R;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      let best = null;
      let bestD2 = 9.0;
      for(let i=0;i<mem.sites.length;i++){
        const s = mem.sites[i];
        if(s.sampled) continue;
        const dx = s.x-sx, dy = s.y-sy;
        const dd = dx*dx+dy*dy;
        if(dd < bestD2){ bestD2 = dd; best = s; }
      }
      if(best){
        best.x += (sx-best.x)*0.35;
        best.y += (sy-best.y)*0.35;
        best.value = val;
        best.lastSeen = mem.t;
      }else if(mem.sites.length < 320){
        best = {id:mem.nextSiteId++, x:sx, y:sy, value:val, sampled:false, lastSeen:mem.t, ignoreUntil:0};
        mem.sites.push(best);
      }
      if(best){
        if(val > mem.maxValSeen) mem.maxValSeen = val;
        if(!best.ignoreUntil || best.ignoreUntil <= mem.t) mem.visible = best;
      }
    }
  }
  const sci = fin(obs.science,0);
  mem.sci = sci;
  if(sci > mem.sciMax) mem.sciMax = sci;
}

function updateCore(obs,mem){
  let t = fin(obs.t, mem.t + 0.1);
  let dt = t - mem.t;
  if(!(dt > 0) || dt > 1.0) dt = 0.1;
  if(dt < 0.02) dt = 0.02;
  mem.dt = dt;
  mem.t = t;

  const wl = fin(obs.wheelLeft,0);
  const wr = fin(obs.wheelRight,0);
  mem.wheelL = wl;
  mem.wheelR = wr;
  const v = (wl+wr)/2;
  mem.vMeas = v;
  const yaw = (wr-wl)/0.6;

  const rawDeg = fin(obs.heading, mem.lastRawDeg);
  mem.lastRawDeg = rawDeg;
  const raw = wrap(rawDeg*D2R);
  const pred = wrap(mem.head + yaw*dt);
  const meas = wrap(raw - mem.headBias);
  const diff = wrap(meas - pred);
  if(Math.abs(diff) > 1.15 && Math.abs(yaw) < 1.0){
    mem.head = pred;
    mem.compassBad = (mem.compassBad||0) + 1;
  }else{
    mem.compassBad = Math.max(0,(mem.compassBad||0) - 0.2);
    const alpha = mem.compassBad > 8 ? 0.25 : 0.65;
    mem.head = wrap(pred + diff*alpha);
  }

  const gx = fin(obs.x, mem.lastGpsX);
  const gy = fin(obs.y, mem.lastGpsY);
  const oldGX = mem.lastGpsX;
  const oldGY = mem.lastGpsY;
  const gd = hyp(gx-oldGX, gy-oldGY);
  const gpsNew = gd > 0.003;
  if(gpsNew){
    mem.gpsStaleT = 0;
  }else if(Math.abs(v) > 0.05){
    mem.gpsStaleT = (mem.gpsStaleT||0) + dt;
  }

  const estX = mem.pos.x + v*Math.cos(mem.head)*dt;
  const estY = mem.pos.y + v*Math.sin(mem.head)*dt;
  const stale = (mem.gpsStaleT||0) > 1.5 && Math.abs(v) > 0.05;
  if(!stale){
    const ex = gx - estX;
    const ey = gy - estY;
    const ed = hyp(ex,ey);
    let alpha = ed < 1 ? 0.65 : (ed < 5 ? 0.42 : 0.22);
    if(mem.gpsWasStale) alpha = Math.max(alpha,0.85);
    mem.pos.x = estX + ex*alpha;
    mem.pos.y = estY + ey*alpha;
    mem.gpsWasStale = false;
  }else{
    mem.pos.x = estX;
    mem.pos.y = estY;
    mem.gpsWasStale = true;
  }

  if(gpsNew && Math.abs(v) > 0.20 && dt > 0.02){
    const expected = Math.abs(v) * Math.max(0.1, dt);
    if(expected > 0.02){
      const ratio = gd / expected;
      if(ratio > 0.05 && ratio < 2.5) mem.slip = clamp(mem.slip*0.98 + ratio*0.02,0.10,1.5);
    }
  }

  if(gpsNew && Math.abs(v) > 0.40 && Math.abs(wr-wl) < 0.35){
    let course = Math.atan2(gy-oldGY, gx-oldGX);
    if(v < 0) course = wrap(course + PI);
    const b = wrap(raw - course);
    if(Math.abs(b) < 1.0) mem.headBias = wrap(mem.headBias*0.995 + b*0.005);
  }

  mem.pos.x = clamp(mem.pos.x,0.3,mem.size-0.3);
  mem.pos.y = clamp(mem.pos.y,0.3,mem.size-0.3);
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;

  const moving = (Math.abs(wl)+Math.abs(wr)) > 0.2;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayLast[i] !== undefined && Math.abs(r-mem.rayLast[i]) < 0.001 && moving){
      mem.rayStill[i] = (mem.rayStill[i]||0) + 1;
    }else{
      mem.rayStill[i] = 0;
    }
    mem.rayLast[i] = r;
  }

  const batt = fin(obs.battery,mem.lastBatt);
  const solar = fin(obs.solar,0);
  const drop = mem.lastBatt - batt;
  if(!obs.docked && dt > 0){
    const dist = Math.abs(v)*dt;
    const consumed = drop + Math.max(0,solar)*dt;
    if(dist > 0.02 && consumed > 0){
      const load = 1 + 0.08*fin(obs.carried,0);
      const e = consumed / (dist*load);
      if(e > 0.00002 && e < 0.03) mem.epm = clamp(mem.epm*0.98 + e*0.02,0.0002,0.02);
    }
    if(obs.drilling && consumed > 0){
      const r = consumed/dt;
      if(r > 0 && r < 0.05) mem.drillE = mem.drillE*0.95 + r*0.05;
    }
  }
  mem.lastBatt = batt;

  updateSites(obs,mem);
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays = obs.rays || [];
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let minFront = 15;
  let leftOpen = 0;
  let rightOpen = 0;

  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayStill && mem.rayStill[i] > 25) r = 15;

    if(i >= 3 && i <= 5 && r < minFront) minFront = r;
    if(i > 4) leftOpen += Math.min(r,10);
    else if(i < 4) rightOpen += Math.min(r,10);

    if(r < 5.5){
      const ang = mem.head + RAYA[i];
      let w = Math.pow((5.5-r)/5.5,2);
      if(i === 4) w *= 2.5;
      else if(i >= 3 && i <= 5) w *= 1.6;
      else w *= 0.8;
      if(r < 1.5) w *= 2.0;
      vx -= Math.cos(ang)*w*1.6;
      vy -= Math.sin(ang)*w*1.6;
    }
  }

  const m = 4.0;
  if(mem.pos.x < m) vx += (m-mem.pos.x)/m*2.0;
  if(mem.pos.x > mem.size-m) vx -= (mem.pos.x-(mem.size-m))/m*2.0;
  if(mem.pos.y < m) vy += (m-mem.pos.y)/m*2.0;
  if(mem.pos.y > mem.size-m) vy -= (mem.pos.y-(mem.size-m))/m*2.0;

  if(hyp(vx,vy) > 0.05) desired = Math.atan2(vy,vx);
  let err = wrap(desired - mem.head);

  let sp = Math.min(speedLimit,2.2);
  const batt = fin(obs.battery,1);
  const carried = fin(obs.carried,0);
  if(carried > 0) sp *= (1 - 0.03*carried);
  if(batt < 0.25) sp = Math.min(sp,1.3);
  if(batt < 0.15) sp = Math.min(sp,0.8);
  if(mem.slip < 0.70) sp *= 0.85;
  if(mem.slip < 0.45) sp *= 0.80;

  if(minFront < 3.0){
    const cap = Math.max(0.0,(minFront-0.7)*0.7);
    sp = Math.min(sp,cap);
  }
  if(minFront < 0.9){
    sp = 0;
    err = (leftOpen >= rightOpen ? 1 : -1)*1.3;
  }else if(Math.abs(err) > 1.0){
    sp = 0;
  }else if(Math.abs(err) > 0.55){
    sp = Math.min(sp,0.65);
  }

  let v = Math.max(0,sp);
  let w = clamp(err*2.4,-2.6,2.6);
  if(v < 0.02){
    v = 0;
    if(Math.abs(err) > 0.08) w = clamp(err*2.2,-2.0,2.0);
    else w = 0;
  }

  const vL = v - w*0.3;
  const vR = v + w*0.3;
  mem.wantV = v;
  mem.lastWant = v;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function driveTo(obs,mem,tx,ty,speed,arrive){
  const dx = tx - mem.pos.x;
  const dy = ty - mem.pos.y;
  const d = hyp(dx,dy);
  if(d <= arrive) return brakeCmd(obs,mem);
  const desired = Math.atan2(dy,dx);
  let sp = speed;
  if(d < arrive + 4.0) sp = Math.min(sp, Math.max(0.15,(d-arrive)*0.60));
  return driveHeading(obs,mem,desired,sp);
}

function makeSpiral(cx,cy,R,spacing,size){
  const pts = [];
  if(R < 1) return [{x:cx,y:cy}];
  const b = spacing/(2*PI);
  const maxTh = 2*PI*R/spacing;
  let lastX = cx;
  let lastY = cy;
  pts.push({x:cx,y:cy});
  for(let th=0.15; th<=maxTh; th+=0.15){
    const r = b*th;
    const x = cx + Math.cos(th)*r;
    const y = cy + Math.sin(th)*r;
    if(x < 3 || x > size-3 || y < 3 || y > size-3) continue;
    if(hyp(x-lastX,y-lastY) >= 3.5){
      pts.push({x:x,y:y});
      lastX = x;
      lastY = y;
    }
  }
  return pts;
}

function startApproach(obs,mem,site){
  if(mem.mode === 'approach' && mem.approach && mem.approach.id === site.id){
    mem.approach.x += (site.x - mem.approach.x)*0.5;
    mem.approach.y += (site.y - mem.approach.y)*0.5;
    mem.approach.value = site.value;
    mem.approach.lastSeen = mem.t;
    return;
  }
  mem.mode = 'approach';
  mem.target = null;
  mem.search = null;
  mem.approach = {
    id: site.id,
    x: site.x,
    y: site.y,
    value: site.value,
    startT: mem.t,
    lastSeen: mem.t
  };
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function abortApproach(obs,mem){
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s) s.ignoreUntil = mem.t + 90;
  }
  mem.approach = null;
  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  return brakeCmd(obs,mem);
}

function startDrill(obs,mem,app){
  mem.mode = 'drill';
  mem.drill = {
    id: app.id,
    sx: app.x,
    sy: app.y,
    value: app.value,
    before: fin(obs.carried,0),
    startT: mem.t,
    hx: mem.pos.x,
    hy: mem.pos.y,
    hHeading: mem.head,
    lastDrilling: 0,
    resetT: 0
  };
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.wantV = 0;
  mem.lastWant = 0;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  if(mem.drill){
    let s = findSiteById(mem,mem.drill.id);
    if(s) s.ignoreUntil = mem.t + 100;
    for(let i=0;i<mem.sites.length;i++){
      const ss = mem.sites[i];
      if(!ss.sampled && hyp(ss.x-mem.drill.hx,ss.y-mem.drill.hy) < 3.5) ss.ignoreUntil = mem.t + 100;
    }
  }
  mem.drill = null;
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.mode = 'idle';
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(obs,mem);
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D = mem.drill;
  if(!D){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);

  if(carried > D.before){
    for(let i=0;i<mem.sites.length;i++){
      const s = mem.sites[i];
      if(s.id === D.id || hyp(s.x-D.hx,s.y-D.hy) < 3.0) s.sampled = true;
    }
    markHintsNear(mem,D.hx,D.hy,35);
    mem.siteSamples = (mem.siteSamples||0) + 1;
    mem.drill = null;
    mem.mode = 'idle';
    mem.target = null;
    mem.search = null;
    mem.approach = null;
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
    if(carried >= mem.cap || needReturn(obs,mem)) startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  const elapsed = mem.t - D.startT;
  const dh = hyp(mem.pos.x-D.hx, mem.pos.y-D.hy);
  const dr = fin(obs.drilling,0);
  if(D.lastDrilling > 0.4 && dr < D.lastDrilling - 0.4) D.resetT += mem.dt;
  else if(dr < 0.2) D.resetT = Math.max(0,D.resetT - mem.dt*0.5);
  D.lastDrilling = dr;

  let tooFar = false;
  if(obs.site && fin(obs.site.distance,99) > 1.55 && elapsed > 0.6) tooFar = true;
  if(dh > 1.25 || D.resetT > 1.0 || elapsed > 9.0 || tooFar){
    return abortDrill(obs,mem);
  }

  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  const epm = clamp(mem.epm,0.0002,0.02);
  const needE = bd*epm*(1+0.08*carried)*2.0 + 0.06;
  if(fin(obs.battery,1) < needE + 0.02 && elapsed > 1.0) return abortDrill(obs,mem);

  let ddx = D.hx - mem.pos.x;
  let ddy = D.hy - mem.pos.y;
  const dist = hyp(ddx,ddy);
  let v = 0;
  let w = 0;
  if(dist > 0.045){
    const desiredAng = Math.atan2(ddy,ddx);
    const errH = wrap(desiredAng - mem.head);
    const speed = Math.min(0.085, dist*0.6);
    v = speed * Math.cos(errH);
    w = clamp(errH*1.8,-0.4,0.4);
  }else{
    const yawErr = wrap(D.hHeading - mem.head);
    w = clamp(yawErr*0.9,-0.25,0.25);
  }
  const vL = clamp(v - w*0.3,-0.085,0.085);
  const vR = clamp(v + w*0.3,-0.085,0.085);
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: true
  };
}

function doApproach(obs,mem){
  const app = mem.approach;
  if(!app){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap || needReturn(obs,mem)){
    startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  let useActual = false;
  let d = 999;
  let bear = 0;
  const os = obs.site;
  if(os && isFinite(os.distance) && fin(os.distance,999) < 8.6){
    d = fin(os.distance,999);
    bear = fin(os.bearing,0);
    if(d < 8.6){
      const ang = mem.head + bear*D2R;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      app.x += (sx-app.x)*0.45;
      app.y += (sy-app.y)*0.45;
      app.value = fin(os.value,app.value);
      app.lastSeen = mem.t;
      useActual = true;
    }
  }

  const maxW = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  if(useActual){
    if(d <= 1.38 && maxW < 0.12) return startDrill(obs,mem,app);
    if(d <= 1.55 && maxW >= 0.10) return brakeCmd(obs,mem);
  }else{
    const dd = hyp(app.x-mem.pos.x,app.y-mem.pos.y);
    if(dd < 0.65 && mem.t-app.lastSeen > 2.5) return abortApproach(obs,mem);
  }

  if(mem.t - app.startT > 30.0) return abortApproach(obs,mem);

  let desired;
  let sp;
  if(useActual){
    desired = mem.head + bear*D2R;
    if(d > 4.0) sp = 1.35;
    else if(d > 2.0) sp = 0.70;
    else if(d > 1.45) sp = 0.26;
    else sp = 0;
    if(sp <= 0.02) return brakeCmd(obs,mem);
  }else{
    const dx = app.x-mem.pos.x;
    const dy = app.y-mem.pos.y;
    const dd = hyp(dx,dy);
    desired = Math.atan2(dy,dx);
    if(dd > 4.0) sp = 1.25;
    else if(dd > 2.0) sp = 0.65;
    else if(dd > 1.0) sp = 0.28;
    else sp = 0;
    if(sp <= 0.02) return brakeCmd(obs,mem);
  }
  return driveHeading(obs,mem,desired,sp);
}

function startSearch(obs,mem,hintId,cx,cy,val){
  const maxV = Math.max(0.5, mem.maxHintVal||0.5, mem.maxValSeen||0.5);
  const ratio = clamp(val/maxV,0,1);
  let R = 12 + 10*ratio;
  const timeLeft = fin(obs.timeLeft,1200);
  if(timeLeft < 300) R = Math.min(R,18);
  if(fin(obs.battery,1) < 0.35) R = Math.min(R,16);
  mem.search = {
    hintId: hintId,
    cx: cx,
    cy: cy,
    value: val,
    R: R,
    pts: [],
    idx: 0,
    startT: mem.t,
    centerT: 0,
    centerChecked: false,
    pointT: mem.t,
    timeout: 18 + R*2.0,
    zeroSciT: 0
  };
  mem.mode = 'search';
  mem.target = null;
  mem.approach = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function finishSearch(obs,mem){
  if(mem.search && mem.search.hintId >= 0 && mem.search.hintId < mem.hints.length){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  mem.search = null;
  mem.target = null;
  mem.mode = 'idle';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(mem.t - S.startT > S.timeout){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  if(!S.centerChecked){
    const d = hyp(S.cx-mem.pos.x, S.cy-mem.pos.y);
    if(d > 2.2){
      return driveTo(obs,mem,S.cx,S.cy,1.2,0.5);
    }
    if(S.centerT === 0) S.centerT = mem.t;
    const waited = mem.t - S.centerT;
    if(waited < 1.0){
      return brakeCmd(obs,mem);
    }
    const sci = fin(obs.science,0);
    if(sci <= 1e-12 && !mem.visible){
      finishSearch(obs,mem);
      return brakeCmd(obs,mem);
    }
    S.centerChecked = true;
    S.pts = makeSpiral(S.cx,S.cy,S.R,8.0,mem.size);
    S.idx = 0;
    S.pointT = mem.t;
    return brakeCmd(obs,mem);
  }

  const sci = fin(obs.science,0);
  if(sci <= 1e-12) S.zeroSciT += mem.dt;
  else S.zeroSciT = 0;
  if(S.zeroSciT > 8.0 && S.idx > 2){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    if(hyp(p.x-mem.pos.x,p.y-mem.pos.y) < 2.0 || (mem.t-S.pointT) > 8.0){
      S.idx++;
      S.pointT = mem.t;
    }else{
      break;
    }
  }
  if(S.idx >= S.pts.length){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  const p = S.pts[S.idx];
  const d = hyp(p.x-mem.pos.x,p.y-mem.pos.y);
  let sp = 1.8;
  if(d < 3.0) sp = 0.8;
  if(mem.slip < 0.70) sp *= 0.9;
  return driveTo(obs,mem,p.x,p.y,sp,0.35);
}

function startReturn(obs,mem){
  if(mem.mode === 'return') return;
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.mode = 'return';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function needReturn(obs,mem){
  if(mem.mode === 'return') return true;
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  const epm = clamp(mem.epm,0.0002,0.02);
  const load = 1 + 0.08*carried;
  const needE = bd*epm*load*2.0 + 0.05;
  const timeNeed = bd/1.1 + 18;

  if(carried > 0){
    if(carried >= mem.cap) return true;
    if(batt < needE + 0.025) return true;
    if(timeLeft < timeNeed + 12) return true;
    if(carried >= 4) return true;
    if(carried >= 3 && bd > 70) return true;
    if(carried >= 2 && bd > 220 && timeLeft < 420) return true;
  }else{
    if(bd > 10 && batt < 0.15) return true;
    if(bd > 10 && timeLeft < timeNeed + 8) return true;
    if(batt < 0.08) return true;
  }
  return false;
}

function doReturn(obs,mem){
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  let d = bd;
  let desired = Math.atan2(mem.base.y-mem.pos.y, mem.base.x-mem.pos.x);
  let useBeacon = false;

  const bc = obs.beacon;
  if(bc && isFinite(bc.distance) && isFinite(bc.bearing)){
    const bdist = fin(bc.distance,999);
    const bb = fin(bc.bearing,0)*D2R;
    if(bdist < 20){
      d = bdist;
      desired = mem.head + bb;
      useBeacon = true;
    }
  }

  const maxW = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  if(d < 1.9 && maxW < 0.16) return brakeCmd(obs,mem);
  if(d < 2.6 && maxW < 0.10) return brakeCmd(obs,mem);

  let sp;
  if(useBeacon){
    if(d < 3.0) sp = Math.max(0.16,d*0.35);
    else sp = 1.75;
    if(d < 1.2) sp = 0;
    if(sp <= 0.02) return brakeCmd(obs,mem);
    return driveHeading(obs,mem,desired,sp);
  }

  if(d < 3.0) sp = Math.max(0.16,d*0.35);
  else sp = 2.0;
  if(fin(obs.battery,1) < 0.20) sp = Math.min(sp,1.0);
  if(mem.slip < 0.55) sp *= 0.85;
  return driveTo(obs,mem,mem.base.x,mem.base.y,sp,0.8);
}

function chooseTarget(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap) return false;
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);
  const epm = clamp(mem.epm,0.0002,0.02);
  const load = 1 + 0.08*carried;
  const maxV = Math.max(0.5, mem.maxHintVal||0.5, mem.maxValSeen||0.5);
  let best = null;
  let bestScore = -1e100;

  function consider(type,x,y,v,conf,searchR,id){
    if(!(v > 0) || !isFinite(x) || !isFinite(y)) return;
    const d = hyp(x-mem.pos.x, y-mem.pos.y);
    const dB = hyp(x-mem.base.x, y-mem.base.y);
    const sr = searchR || 0;
    const estTime = d/1.7 + dB/1.25 + sr*1.6 + 22;
    if(timeLeft < estTime + 10) return;
    const needE = (d + dB + sr*1.5)*epm*load*1.7 + 0.06;
    if(batt < needE + 0.02) return;
    const vv = v + 0.08;
    let score = Math.pow(vv,1.55) * conf / (10 + d + 0.45*dB + sr*0.9);
    if(type === 'site') score *= 1.15;
    if(score > bestScore){
      bestScore = score;
      best = {type:type, id:id, x:x, y:y, value:v, searchR:sr, startT:mem.t};
    }
  }

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    const ratio = clamp(h.v/maxV,0,1);
    const sr = 12 + 10*ratio;
    consider('hint',h.x,h.y,h.v,0.82,sr,h.id);
  }

  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(s.ignoreUntil && s.ignoreUntil > mem.t) continue;
    const age = mem.t - (s.lastSeen||0);
    let conf = age < 100 ? 1.0 : 0.72;
    consider('site',s.x,s.y,s.value,conf,0,s.id);
  }

  if(!best) return false;

  if(best.type === 'site'){
    mem.mode = 'approach';
    mem.target = null;
    mem.search = null;
    mem.approach = {
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      startT: mem.t,
      lastSeen: mem.t
    };
  }else{
    mem.mode = 'travel';
    mem.approach = null;
    mem.search = null;
    mem.target = {
      type: best.type,
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      searchR: best.searchR,
      startT: mem.t
    };
  }
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  return true;
}

function startExplore(obs,mem){
  let n = mem.exploreCount++;
  let ang = n * 2.399963229728653;
  let rad = 60 + ((n*47)%140);
  let cx = mem.base.x + Math.cos(ang)*rad;
  let cy = mem.base.y + Math.sin(ang)*rad;
  cx = clamp(cx,15,mem.size-15);
  cy = clamp(cy,15,mem.size-15);
  if(hyp(cx-mem.pos.x,cy-mem.pos.y) < 25){
    ang += 1.7;
    rad = 90 + ((n*73)%110);
    cx = mem.base.x + Math.cos(ang)*rad;
    cy = mem.base.y + Math.sin(ang)*rad;
    cx = clamp(cx,15,mem.size-15);
    cy = clamp(cy,15,mem.size-15);
  }
  mem.target = {
    type: 'explore',
    id: -1,
    x: cx,
    y: cy,
    value: 0.45,
    searchR: 20,
    startT: mem.t
  };
  mem.mode = 'travel';
  mem.approach = null;
  mem.search = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function doTravel(obs,mem){
  const task = mem.target;
  if(!task){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const d = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    if(d < 4.5){
      startSearch(obs,mem,h.id,h.x,h.y,h.v);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 260 && d > 10){
      h.status = 2;
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    let sp = 2.10;
    if(fin(obs.carried,0) > 0) sp = 1.95;
    if(fin(obs.battery,1) < 0.30) sp = 1.35;
    if(mem.slip < 0.70) sp *= 0.88;
    return driveTo(obs,mem,h.x,h.y,sp,0.5);
  }

  if(task.type === 'explore'){
    const d = hyp(task.x-mem.pos.x, task.y-mem.pos.y);
    if(d < 4.0){
      startSearch(obs,mem,-1,task.x,task.y,task.value||0.45);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 230 && d > 15){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    let sp = 1.95;
    if(fin(obs.carried,0) > 0) sp = 1.85;
    if(fin(obs.battery,1) < 0.30) sp = 1.30;
    if(mem.slip < 0.70) sp *= 0.88;
    return driveTo(obs,mem,task.x,task.y,sp,0.5);
  }

  mem.target = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function startRecovery(obs,mem){
  if(mem.recoverUntil > mem.t) return;
  mem.recoverStart = mem.t;
  mem.recoverUntil = mem.t + 1.8;
  let L = 0;
  let R = 0;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i > 4) L += Math.min(r,10);
    else if(i < 4) R += Math.min(r,10);
  }
  if(Math.abs(L-R) < 0.15) mem.recoverTurn = -(mem.recoverTurn||1);
  else mem.recoverTurn = L > R ? 1 : -1;
  mem.stallT = 0;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t + 2.0;
}

function doRecovery(obs,mem){
  const el = mem.t - mem.recoverStart;
  let v;
  let w;
  if(el < 0.6){
    v = -0.45;
    w = mem.recoverTurn*0.7;
  }else if(el < 1.4){
    v = 0;
    w = mem.recoverTurn*1.3;
  }else{
    v = -0.15;
    w = mem.recoverTurn*0.45;
  }
  const vL = v - w*0.3;
  const vR = v + w*0.3;
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function cancelCurrent(mem,obs){
  if(mem.search && mem.search.hintId >= 0 && mem.search.hintId < mem.hints.length){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.target && mem.target.type === 'hint' && mem.target.id >= 0 && mem.target.id < mem.hints.length){
    const h = mem.hints[mem.target.id];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s) s.ignoreUntil = mem.t + 90;
  }
  mem.search = null;
  mem.approach = null;
  mem.target = null;
  mem.drill = null;
  mem.mode = 'idle';
}

function checkStuck(obs,mem){
  const moved = hyp(mem.pos.x-mem.progressX, mem.pos.y-mem.progressY);
  if(moved > 0.60){
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
  }
  const speed = Math.abs(mem.wheelL) + Math.abs(mem.wheelR);
  if((mem.lastWant||0) > 0.35 && speed < 0.08){
    mem.stallT += mem.dt;
  }else{
    mem.stallT = Math.max(0,mem.stallT - mem.dt*1.5);
  }

  if(((mem.lastWant||0) > 0.35 && mem.t-mem.progressT > 4.0) || mem.stallT > 2.2){
    if(mem.t - mem.lastRecoverT < 12) mem.recoverCount++;
    else mem.recoverCount = 1;
    mem.lastRecoverT = mem.t;
    if(mem.recoverCount >= 3 && mem.mode !== 'return'){
      cancelCurrent(mem,obs);
      mem.recoverCount = 0;
      mem.mode = 'idle';
    }
    return true;
  }
  return false;
}

function dispatchMode(obs,mem){
  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);
  return brakeCmd(obs,mem);
}

function handleDocked(obs,mem){
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);

  if(carried > 0){
    mem.mode = 'dockedWait';
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  if(mem.leaveBase && mem.t-mem.leaveBase < 2.5 &&
     (mem.mode === 'travel' || mem.mode === 'approach' || mem.mode === 'search' || mem.mode === 'return')){
    return dispatchMode(obs,mem);
  }

  if(mem.mode !== 'charge'){
    mem.mode = 'charge';
    mem.chargeStart = mem.t;
    mem.chargeLastBatt = batt;
    mem.chargeNoGain = 0;
  }

  if(batt > mem.chargeLastBatt + 0.0002) mem.chargeNoGain = 0;
  else mem.chargeNoGain += mem.dt;
  mem.chargeLastBatt = batt;

  let target = 0;
  if(timeLeft > 650 && batt < 0.95) target = 0.95;
  else if(timeLeft > 350 && batt < 0.88) target = 0.88;
  else if(timeLeft > 150 && batt < 0.78) target = 0.78;
  else if(timeLeft > 80 && batt < 0.55) target = 0.55;
  if(timeLeft > 60 && batt < 0.50) target = Math.max(target,0.62);
  if(timeLeft > 40 && batt < 0.30) target = Math.max(target,0.45);

  if(target > 0 && batt < target && (mem.t-mem.chargeStart) < 25 && mem.chargeNoGain < 8 && timeLeft > 20){
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  mem.mode = 'idle';
  mem.chargeStart = -1;
  mem.target = null;
  mem.search = null;
  mem.approach = null;

  if(timeLeft < 10) return brakeCmd(obs,mem);

  if(chooseTarget(obs,mem)){
    mem.leaveBase = mem.t;
    return dispatchMode(obs,mem);
  }

  if(timeLeft > 30){
    startExplore(obs,mem);
    mem.leaveBase = mem.t;
    return dispatchMode(obs,mem);
  }

  return brakeCmd(obs,mem);
}

function act(obs,mem){
  if(!mem.init){
    initMission(obs,mem);
    return {left:0,right:0,drill:false};
  }

  updateCore(obs,mem);

  if(mem.mode === 'drill'){
    return doDrill(obs,mem);
  }

  if(obs.docked){
    return handleDocked(obs,mem);
  }

  if(obs.bumped){
    if(mem.recoverUntil <= mem.t) startRecovery(obs,mem);
    return doRecovery(obs,mem);
  }

  if(mem.recoverUntil > mem.t){
    return doRecovery(obs,mem);
  }

  if(mem.mode !== 'idle' && mem.mode !== 'dockedWait' && mem.mode !== 'charge'){
    if(checkStuck(obs,mem)){
      startRecovery(obs,mem);
      return doRecovery(obs,mem);
    }
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    if(needReturn(obs,mem)) startReturn(obs,mem);
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    const vis = mem.visible;
    if(vis && fin(obs.carried,0) < mem.cap && !needReturn(obs,mem)){
      startApproach(obs,mem,vis);
    }
  }

  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);

  if(mem.mode === 'idle' || !mem.mode){
    if(chooseTarget(obs,mem)) return dispatchMode(obs,mem);
    if(fin(obs.carried,0) > 0){
      startReturn(obs,mem);
      return doReturn(obs,mem);
    }
    if(fin(obs.timeLeft,0) > 30){
      startExplore(obs,mem);
      return doTravel(obs,mem);
    }
    return brakeCmd(obs,mem);
  }

  return brakeCmd(obs,mem);
}

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const RAYA = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % (2*PI);
  if(a > PI) a -= 2*PI;
  if(a < -PI) a += 2*PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function fin(v,d){ return (typeof v === 'number' && isFinite(v)) ? v : d; }

function motorCmd(target, meas, st, dt){
  target = clamp(target,-3.0,3.0);
  if(st.prev !== undefined && st.prev * target < 0) st.i *= 0.28;
  st.prev = target;
  const err = target - meas;
  st.i += err * dt * 1.5;
  st.i = clamp(st.i,-0.9,0.9);
  let u = target / 2.8 + err * 0.9 + st.i;
  if(u > 1){
    u = 1;
    if(err > 0) st.i -= err * dt * 1.5;
  }else if(u < -1){
    u = -1;
    if(err < 0) st.i -= err * dt * 1.5;
  }
  if(target > 0.04 && u < 0.055) u = 0.055;
  if(target < -0.04 && u > -0.055) u = -0.055;
  if(Math.abs(target) < 0.02 && Math.abs(meas) < 0.03){
    st.i *= Math.exp(-dt * 2.2);
    if(Math.abs(st.i) < 0.01) st.i = 0;
  }
  return clamp(u,-1,1);
}

function brakeCmd(obs, mem){
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(0, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(0, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function initMission(obs, mem){
  mem.init = true;
  mem.t = fin(obs.t,0);
  mem.dt = 0.1;
  const M = obs.mission || {};
  mem.size = fin(M.size,400);
  mem.seconds = fin(M.seconds,1200);
  mem.cap = Math.max(1, Math.floor(fin(M.capacity,5)));
  const b = M.base || {x:fin(obs.x,0), y:fin(obs.y,0)};
  mem.base = {x:fin(b.x,fin(obs.x,0)), y:fin(b.y,fin(obs.y,0))};

  mem.hints = [];
  const hs = Array.isArray(M.hints) ? M.hints : [];
  for(let i=0;i<hs.length;i++){
    const h = hs[i] || {};
    let x = fin(h.x,NaN), y = fin(h.y,NaN), v = fin(h.estimate,0.1);
    if(!isFinite(x) || !isFinite(y)) continue;
    if(!(v > 0)) v = 0.1;
    mem.hints.push({id:mem.hints.length, x:clamp(x,0,mem.size), y:clamp(y,0,mem.size), v:v, status:0});
  }
  mem.maxHintVal = 0.5;
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;
  mem.maxValSeen = mem.maxHintVal;

  mem.sites = [];
  mem.nextSiteId = 1;
  mem.visible = null;
  mem.sci = 0;
  mem.sciMax = 0;
  mem.sampleCount = 0;
  mem.lastSampleT = -999;

  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;

  mem.ctlL = {i:0, prev:0};
  mem.ctlR = {i:0, prev:0};

  mem.pos = {x:clamp(fin(obs.x,mem.base.x),0.3,mem.size-0.3), y:clamp(fin(obs.y,mem.base.y),0.3,mem.size-0.3)};
  mem.head = wrap(fin(obs.heading,0)*D2R);
  mem.lastRawDeg = fin(obs.heading,0);
  mem.headBias = 0;
  mem.compassBad = 0;
  mem.wheelL = fin(obs.wheelLeft,0);
  mem.wheelR = fin(obs.wheelRight,0);
  mem.vMeas = (mem.wheelL + mem.wheelR) / 2;
  mem.wantV = 0;
  mem.lastWant = 0;
  mem.slip = 1;

  mem.lastGpsX = fin(obs.x,mem.pos.x);
  mem.lastGpsY = fin(obs.y,mem.pos.y);
  mem.gpsStaleT = 0;
  mem.gpsWasStale = false;

  mem.lastBatt = fin(obs.battery,1);
  mem.epm = 0.0010;
  mem.drillE = 0.0035;

  mem.rayLast = [];
  mem.rayStill = [];
  for(let i=0;i<9;i++){ mem.rayLast[i] = 15; mem.rayStill[i] = 0; }

  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;

  mem.recoverStart = -999;
  mem.recoverUntil = -999;
  mem.recoverRevUntil = -999;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.lastRecoverT = -999;

  mem.chargeStart = -1;
  mem.chargeLastBatt = mem.lastBatt;
  mem.chargeNoGain = 0;
  mem.leaveBase = -999;
  mem.exploreCount = 0;

  mem.lastLocalSearch = -999;
  mem.lastScienceSearch = -999;
  mem.avoidUntil = -999;
  mem.avoidStart = -999;
  mem.avoidHeading = 0;
  mem.avoidSide = 1;
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++) if(mem.sites[i].id === id) return mem.sites[i];
  return null;
}

function markHintsNear(mem,x,y,rad){
  const r2 = rad*rad;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x, dy = h.y-y;
    if(dx*dx + dy*dy < r2) h.status = 2;
  }
}

function updateSites(obs,mem){
  mem.visible = null;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const d = fin(os.distance,999);
    const bear = fin(os.bearing,0);
    const val = fin(os.value,0);
    if(d >= 0 && d < 8.6 && val > 0){
      const ang = mem.head + bear*D2R;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      let best = null;
      let bestD2 = 16.0;
      for(let i=0;i<mem.sites.length;i++){
        const s = mem.sites[i];
        if(s.sampled) continue;
        const dx = s.x-sx, dy = s.y-sy;
        const dd = dx*dx + dy*dy;
        if(dd < bestD2){ bestD2 = dd; best = s; }
      }
      if(best){
        best.x += (sx-best.x)*0.35;
        best.y += (sy-best.y)*0.35;
        best.value = val;
        best.lastSeen = mem.t;
      }else if(mem.sites.length < 320){
        best = {id:mem.nextSiteId++, x:sx, y:sy, value:val, sampled:false, lastSeen:mem.t, ignoreUntil:0};
        mem.sites.push(best);
      }
      if(best){
        if(val > mem.maxValSeen) mem.maxValSeen = val;
        mem.visible = best;
      }
    }
  }
  const sci = fin(obs.science,0);
  mem.sci = sci;
  if(sci > mem.sciMax) mem.sciMax = sci;
}

function updateCore(obs,mem){
  let t = fin(obs.t, mem.t + 0.1);
  let dt = t - mem.t;
  if(!(dt > 0) || dt > 1.2) dt = 0.1;
  if(dt < 0.02) dt = 0.02;
  mem.dt = dt;
  mem.t = t;

  const wl = fin(obs.wheelLeft,0);
  const wr = fin(obs.wheelRight,0);
  mem.wheelL = wl;
  mem.wheelR = wr;
  const v = (wl + wr) / 2;
  mem.vMeas = v;
  const yaw = (wr - wl) / 0.6;

  const rawDeg = fin(obs.heading, mem.lastRawDeg);
  mem.lastRawDeg = rawDeg;
  const raw = wrap(rawDeg*D2R);
  const pred = wrap(mem.head + yaw*dt);
  const meas = wrap(raw - mem.headBias);
  const diff = wrap(meas - pred);
  if(Math.abs(diff) > 1.15 && Math.abs(yaw) < 1.2){
    mem.head = pred;
    mem.compassBad = Math.min(100, (mem.compassBad||0) + 1);
  }else{
    mem.compassBad = Math.max(0, (mem.compassBad||0) - 0.2);
    const alpha = mem.compassBad > 8 ? 0.25 : 0.65;
    mem.head = wrap(pred + diff*alpha);
  }

  const gx = fin(obs.x, mem.lastGpsX);
  const gy = fin(obs.y, mem.lastGpsY);
  const oldGX = mem.lastGpsX;
  const oldGY = mem.lastGpsY;
  const gd = hyp(gx-oldGX, gy-oldGY);
  const gpsNew = gd > 0.004;
  if(gpsNew){
    mem.gpsStaleT = 0;
  }else if(Math.abs(v) > 0.05){
    mem.gpsStaleT = (mem.gpsStaleT||0) + dt;
  }

  const estX = mem.pos.x + v*Math.cos(mem.head)*dt;
  const estY = mem.pos.y + v*Math.sin(mem.head)*dt;
  const stale = (mem.gpsStaleT||0) > 1.6 && Math.abs(v) > 0.04;
  if(!stale){
    const ex = gx - estX;
    const ey = gy - estY;
    const ed = hyp(ex,ey);
    let alpha = ed < 1 ? 0.65 : (ed < 5 ? 0.42 : 0.22);
    if(mem.gpsWasStale) alpha = Math.max(alpha,0.85);
    mem.pos.x = estX + ex*alpha;
    mem.pos.y = estY + ey*alpha;
    mem.gpsWasStale = false;
  }else{
    mem.pos.x = estX;
    mem.pos.y = estY;
    mem.gpsWasStale = true;
  }

  if(gpsNew && Math.abs(v) > 0.20 && dt > 0.02){
    const expected = Math.abs(v) * Math.max(0.1, dt);
    if(expected > 0.02){
      const ratio = gd / expected;
      if(ratio > 0.05 && ratio < 2.5) mem.slip = clamp(mem.slip*0.98 + ratio*0.02, 0.10, 1.5);
    }
  }

  if(gpsNew && Math.abs(v) > 0.35 && Math.abs(wr-wl) < 0.4){
    let course = Math.atan2(gy-oldGY, gx-oldGX);
    if(v < 0) course = wrap(course + PI);
    const b = wrap(raw - course);
    if(Math.abs(b) < 1.0) mem.headBias = wrap(mem.headBias*0.995 + b*0.005);
  }

  mem.pos.x = clamp(mem.pos.x,0.3,mem.size-0.3);
  mem.pos.y = clamp(mem.pos.y,0.3,mem.size-0.3);
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;

  const moving = (Math.abs(wl)+Math.abs(wr)) > 0.18;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayLast[i] !== undefined && Math.abs(r-mem.rayLast[i]) < 0.001 && moving){
      mem.rayStill[i] = (mem.rayStill[i]||0) + 1;
    }else{
      mem.rayStill[i] = 0;
    }
    mem.rayLast[i] = r;
  }

  const batt = fin(obs.battery,mem.lastBatt);
  const solar = fin(obs.solar,0);
  const drop = mem.lastBatt - batt;
  if(!obs.docked && dt > 0){
    const dist = Math.abs(v)*dt;
    const consumed = drop + Math.max(0,solar)*dt;
    if(dist > 0.015 && consumed > 0){
      const load = 1 + 0.08*fin(obs.carried,0);
      const e = consumed / (dist*load);
      if(e > 0.00002 && e < 0.03) mem.epm = clamp(mem.epm*0.98 + e*0.02, 0.0002, 0.02);
    }
    if(obs.drilling && consumed > 0){
      const r = consumed/dt;
      if(r > 0 && r < 0.05) mem.drillE = mem.drillE*0.95 + r*0.05;
    }
  }
  mem.lastBatt = batt;

  updateSites(obs,mem);
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays = obs.rays || [];
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let minFront = 15;
  let leftClear = 0;
  let rightClear = 0;
  const rr = [];

  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayStill && mem.rayStill[i] > 32) r = 15;
    rr[i] = r;

    if(i >= 3 && i <= 5 && r < minFront) minFront = r;
    if(i > 4) leftClear += Math.min(r,8);
    else if(i < 4) rightClear += Math.min(r,8);

    if(r < 4.6){
      const ang = mem.head + RAYA[i];
      let w = (4.6-r)/4.6;
      if(i === 4) w *= 2.2;
      else if(i >= 3 && i <= 5) w *= 1.5;
      else w *= 0.55;
      if(r < 1.2) w *= 2.0;
      vx -= Math.cos(ang)*w*1.35;
      vy -= Math.sin(ang)*w*1.35;
    }
  }

  const m = 4.0;
  if(mem.pos.x < m) vx += (m-mem.pos.x)/m*2.0;
  if(mem.pos.x > mem.size-m) vx -= (mem.pos.x-(mem.size-m))/m*2.0;
  if(mem.pos.y < m) vy += (m-mem.pos.y)/m*2.0;
  if(mem.pos.y > mem.size-m) vy -= (mem.pos.y-(mem.size-m))/m*2.0;

  if(hyp(vx,vy) > 0.05) desired = Math.atan2(vy,vx);

  if(mem.avoidUntil > mem.t){
    if(minFront > 3.2 && mem.t > mem.avoidStart + 0.35){
      mem.avoidUntil = -999;
    }else{
      desired = mem.avoidHeading;
    }
  }

  if(mem.avoidUntil <= mem.t && minFront < 1.95){
    const side = (leftClear >= rightClear ? 1 : -1);
    mem.avoidSide = side;
    mem.avoidStart = mem.t;
    mem.avoidUntil = mem.t + 1.0;
    mem.avoidHeading = wrap(mem.head + side*(1.12 + (1.95-minFront)*0.45));
    desired = mem.avoidHeading;
  }

  let err = wrap(desired - mem.head);
  let sp = Math.min(speedLimit,2.2);

  const batt = fin(obs.battery,1);
  const carried = fin(obs.carried,0);
  if(carried > 0) sp *= (1 - 0.025*carried);
  if(batt < 0.25) sp = Math.min(sp,1.25);
  if(batt < 0.15) sp = Math.min(sp,0.75);
  if(mem.slip < 0.70) sp *= 0.86;
  if(mem.slip < 0.45) sp *= 0.80;
  const pitch = fin(obs.pitch,0);
  if(Math.abs(pitch) > 18) sp *= 0.82;

  if(minFront < 4.0){
    const cap = Math.max(0.0, (minFront-0.55)*0.65);
    sp = Math.min(sp,cap);
  }
  if(minFront < 0.92){
    sp = 0;
    const side = (leftClear >= rightClear ? 1 : -1);
    mem.avoidSide = side;
    mem.avoidUntil = Math.max(mem.avoidUntil, mem.t+0.55);
    mem.avoidHeading = wrap(mem.head + side*1.25);
    err = wrap(mem.avoidHeading - mem.head);
  }else if(Math.abs(err) > 1.05){
    sp = 0;
  }else if(Math.abs(err) > 0.58){
    sp = Math.min(sp,0.62);
  }

  let v = Math.max(0,sp);
  let w = clamp(err*2.25,-2.5,2.5);
  if(v < 0.02){
    v = 0;
    if(Math.abs(err) > 0.06) w = clamp(err*2.0,-1.9,1.9);
    else w = 0;
  }

  const vL = clamp(v - w*0.3,-3.0,3.0);
  const vR = clamp(v + w*0.3,-3.0,3.0);
  mem.wantV = v;
  mem.lastWant = v;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function driveTo(obs,mem,tx,ty,speed,arrive){
  const dx = tx - mem.pos.x;
  const dy = ty - mem.pos.y;
  const d = hyp(dx,dy);
  if(d <= arrive) return brakeCmd(obs,mem);
  let sp = speed;
  if(d < arrive + 3.5) sp = Math.min(sp, Math.max(0.12,(d-arrive)*0.62));
  const desired = Math.atan2(dy,dx);
  return driveHeading(obs,mem,desired,sp);
}

function makeSpiral(cx,cy,R,spacing,size){
  const pts = [];
  if(R < 1) return [{x:cx,y:cy}];
  const b = spacing/(2*PI);
  const maxTh = 2*PI*R/spacing;
  let lastX = cx, lastY = cy;
  pts.push({x:cx,y:cy});
  for(let th=0.12; th<=maxTh; th+=0.12){
    const r = b*th;
    const x = cx + Math.cos(th)*r;
    const y = cy + Math.sin(th)*r;
    if(x < 3 || x > size-3 || y < 3 || y > size-3) continue;
    if(hyp(x-lastX,y-lastY) >= 3.2){
      pts.push({x:x,y:y});
      lastX = x;
      lastY = y;
      if(pts.length > 180) break;
    }
  }
  return pts;
}

function startSearch(obs,mem,hintId,cx,cy,val){
  const maxV = Math.max(0.5, mem.maxHintVal||0.5, mem.maxValSeen||0.5);
  const ratio = clamp(val/maxV,0,1);
  let R = 17 + 7*ratio;
  if(fin(obs.timeLeft,1200) < 260) R = Math.min(R,20);
  if(fin(obs.battery,1) < 0.35) R = Math.min(R,18);
  const pts = makeSpiral(cx,cy,R,8.0,mem.size);
  mem.search = {
    hintId: hintId,
    cx: cx,
    cy: cy,
    value: val,
    R: R,
    pts: pts,
    idx: 0,
    startT: mem.t,
    centerT: 0,
    centerChecked: false,
    pointT: mem.t,
    timeout: 30 + R*1.25,
    zeroSciT: 0
  };
  mem.mode = 'search';
  mem.target = null;
  mem.approach = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
}

function finishSearch(obs,mem){
  if(mem.search && mem.search.hintId >= 0 && mem.search.hintId < mem.hints.length){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  mem.search = null;
  mem.target = null;
  mem.approach = null;
  mem.mode = 'idle';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(mem.t - S.startT > S.timeout){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  if(!S.centerChecked){
    const d = hyp(S.cx-mem.pos.x, S.cy-mem.pos.y);
    if(d > 3.0 && mem.t - S.startT < 8.0){
      return driveTo(obs,mem,S.cx,S.cy,1.1,0.4);
    }
    S.centerChecked = true;
    S.centerT = mem.t;
    S.pointT = mem.t;
    const sci = fin(obs.science,0);
    if(sci <= 1e-9 && !mem.visible){
      finishSearch(obs,mem);
      return brakeCmd(obs,mem);
    }
    return brakeCmd(obs,mem);
  }

  const sci = fin(obs.science,0);
  if(sci <= 1e-9) S.zeroSciT += mem.dt;
  else S.zeroSciT = 0;
  if(S.zeroSciT > 9.0 && S.idx > 1){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    const d = hyp(p.x-mem.pos.x, p.y-mem.pos.y);
    if(d < 1.65 || (mem.t - S.pointT) > 7.0){
      S.idx++;
      S.pointT = mem.t;
    }else{
      break;
    }
  }

  if(S.idx >= S.pts.length){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  const p = S.pts[S.idx];
  const d = hyp(p.x-mem.pos.x,p.y-mem.pos.y);
  let sp = 1.65;
  if(S.value > 0.45*(mem.maxHintVal||0.5)) sp = 1.9;
  if(fin(obs.timeLeft,1200) < 120) sp = 1.2;
  if(d < 3.0) sp = Math.min(sp,0.85);
  return driveTo(obs,mem,p.x,p.y,sp,0.35);
}

function startApproach(obs,mem,site){
  if(mem.mode === 'approach' && mem.approach && mem.approach.id === site.id){
    mem.approach.x += (site.x - mem.approach.x)*0.45;
    mem.approach.y += (site.y - mem.approach.y)*0.45;
    mem.approach.value = site.value;
    mem.approach.lastSeen = mem.t;
    return;
  }
  mem.mode = 'approach';
  mem.target = null;
  mem.search = null;
  mem.approach = {
    id: site.id,
    x: site.x,
    y: site.y,
    value: site.value,
    startT: mem.t,
    lastSeen: mem.t,
    lastDist: 99
  };
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
}

function abortApproach(obs,mem){
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s) s.ignoreUntil = mem.t + 25;
  }
  mem.approach = null;
  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(obs,mem);
  return brakeCmd(obs,mem);
}

function startDrill(obs,mem,app){
  mem.mode = 'drill';
  mem.drill = {
    id: app.id,
    sx: app.x,
    sy: app.y,
    value: app.value,
    before: fin(obs.carried,0),
    startT: mem.t,
    hx: mem.pos.x,
    hy: mem.pos.y,
    lastDrill: 0,
    resetT: 0,
    lastSeen: mem.t
  };
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.wantV = 0;
  mem.lastWant = 0;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  if(mem.drill){
    let s = findSiteById(mem,mem.drill.id);
    if(s) s.ignoreUntil = mem.t + 25;
    for(let i=0;i<mem.sites.length;i++){
      const ss = mem.sites[i];
      if(!ss.sampled && hyp(ss.x-mem.drill.hx,ss.y-mem.drill.hy) < 4.0) ss.ignoreUntil = mem.t + 18;
    }
  }
  mem.drill = null;
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.mode = 'idle';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t + 1.0;
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(obs,mem);
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D = mem.drill;
  if(!D){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);

  if(carried > D.before){
    for(let i=0;i<mem.sites.length;i++){
      const s = mem.sites[i];
      if(s.sampled) continue;
      if(s.id === D.id || hyp(s.x-D.hx,s.y-D.hy) < 4.2 || hyp(s.x-mem.pos.x,s.y-mem.pos.y) < 4.2) s.sampled = true;
    }
    markHintsNear(mem,D.hx,D.hy,38);
    mem.sampleCount = (mem.sampleCount||0) + 1;
    mem.lastSampleT = mem.t;
    mem.drill = null;
    mem.approach = null;
    mem.search = null;
    mem.target = null;
    mem.mode = 'idle';
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
    mem.stallT = 0;
    if(carried >= mem.cap || needReturn(obs,mem)) startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  const elapsed = mem.t - D.startT;
  const dr = fin(obs.drilling,0);
  if(D.lastDrill > 0.8 && dr < D.lastDrill - 0.35) D.resetT += mem.dt;
  else if(dr < 0.2) D.resetT = Math.max(0, D.resetT - mem.dt*0.6);
  D.lastDrill = dr;

  let d = null;
  let bear = 0;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const dd = fin(os.distance,999);
    if(dd >= 0 && dd < 8.6){
      d = dd;
      bear = fin(os.bearing,0);
      D.lastSeen = mem.t;
    }
  }

  if(elapsed > 11.5) return abortDrill(obs,mem);
  if(D.resetT > 2.2) return abortDrill(obs,mem);
  if(d !== null && d > 1.85 && elapsed > 0.8) return abortDrill(obs,mem);
  if(d === null && elapsed > 3.0 && dr < 0.25) return abortDrill(obs,mem);

  let v = 0;
  let w = 0;
  if(d !== null){
    let err = wrap(bear*D2R);
    if(d > 0.95) v = clamp((d-0.80)*0.15, -0.08, 0.08);
    else if(d < 0.42) v = 0;
    else v = 0;
    if(d < 0.65) err *= 0.25;
    w = clamp(err*1.15, -0.28, 0.28);
  }

  const vL = clamp(v - w*0.3, -0.10, 0.10);
  const vR = clamp(v + w*0.3, -0.10, 0.10);
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: true
  };
}

function doApproach(obs,mem){
  const app = mem.approach;
  if(!app){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap || needReturn(obs,mem)){
    startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  let useActual = false;
  let d = 999;
  let bear = 0;
  const os = obs.site;
  if(os && isFinite(os.distance) && fin(os.distance,999) < 8.6){
    d = fin(os.distance,999);
    bear = fin(os.bearing,0);
    const ang = mem.head + bear*D2R;
    const sx = mem.pos.x + Math.cos(ang)*d;
    const sy = mem.pos.y + Math.sin(ang)*d;
    app.x += (sx-app.x)*0.45;
    app.y += (sy-app.y)*0.45;
    app.value = fin(os.value,app.value);
    app.lastSeen = mem.t;
    app.lastDist = d;
    useActual = true;
  }

  if(mem.t - app.startT > 38.0) return abortApproach(obs,mem);

  const maxW = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  if(useActual){
    if(d <= 1.05 && maxW < 0.13) return startDrill(obs,mem,app);
    if(d <= 1.35 && maxW >= 0.08) return brakeCmd(obs,mem);

    const desired = mem.head + bear*D2R;
    let sp;
    if(d > 6.0) sp = 1.75;
    else if(d > 3.0) sp = 1.05;
    else if(d > 1.6) sp = 0.52;
    else if(d > 1.08) sp = 0.22;
    else sp = 0.10;
    return driveHeading(obs,mem,desired,sp);
  }else{
    const dx = app.x-mem.pos.x;
    const dy = app.y-mem.pos.y;
    const dd = hyp(dx,dy);
    if(dd < 1.15 && mem.t - app.lastSeen > 2.5) return abortApproach(obs,mem);
    const desired = Math.atan2(dy,dx);
    let sp;
    if(dd > 6.0) sp = 1.65;
    else if(dd > 3.0) sp = 0.95;
    else if(dd > 1.5) sp = 0.45;
    else sp = 0.16;
    return driveHeading(obs,mem,desired,sp);
  }
}

function needReturn(obs,mem){
  if(obs.docked) return false;
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  const epm = clamp(mem.epm,0.0002,0.02);
  const load = 1 + 0.08*carried;
  const needE = bd*epm*load*2.2 + 0.06;
  const timeNeed = bd/1.25 + 20;

  if(carried > 0){
    if(carried >= mem.cap) return true;
    if(carried >= 3) return true;
    if(carried >= 2 && (bd > 130 || timeLeft < 520)) return true;
    if(timeLeft < timeNeed + 30) return true;
    if(batt < needE + 0.04) return true;
    if(mem.t - mem.lastSampleT > 210) return true;
    if(carried >= 1 && bd < 45 && mem.t - mem.lastSampleT > 45) return true;
    if(batt < 0.34) return true;
  }else{
    if(bd > 15 && batt < needE + 0.03) return true;
    if(timeLeft < timeNeed + 10) return true;
    if(batt < 0.13) return true;
  }
  return false;
}

function startReturn(obs,mem){
  if(mem.mode === 'return') return;
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.mode = 'return';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
}

function doReturn(obs,mem){
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  let d = bd;
  let desired = Math.atan2(mem.base.y-mem.pos.y, mem.base.x-mem.pos.x);
  let useBeacon = false;

  const bc = obs.beacon;
  if(bc && isFinite(bc.distance) && isFinite(bc.bearing)){
    const bdist = fin(bc.distance,999);
    const bb = fin(bc.bearing,0)*D2R;
    if(bdist < 20){
      d = bdist;
      desired = mem.head + bb;
      useBeacon = true;
    }
  }

  const maxW = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));
  if(d < 1.9 && maxW < 0.16) return brakeCmd(obs,mem);
  if(d < 2.35) return brakeCmd(obs,mem);
  if(d < 3.0 && maxW < 0.12) return brakeCmd(obs,mem);

  if(useBeacon){
    let sp = 1.85;
    if(d < 5.0) sp = Math.max(0.14, d*0.34);
    if(fin(obs.battery,1) < 0.20) sp = Math.min(sp,0.95);
    return driveHeading(obs,mem,desired,sp);
  }

  let sp = 2.0;
  if(d < 8.0) sp = Math.min(sp, Math.max(0.16, d*0.34));
  if(fin(obs.battery,1) < 0.20) sp = Math.min(sp,0.95);
  if(mem.slip < 0.55) sp *= 0.85;
  return driveTo(obs,mem,mem.base.x,mem.base.y,sp,0.7);
}

function chooseTarget(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap) return false;
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);
  const epm = clamp(mem.epm,0.0002,0.02);
  const load = 1 + 0.08*carried;
  const maxV = Math.max(0.5, mem.maxHintVal||0.5, mem.maxValSeen||0.5);
  let best = null;
  let bestScore = -1e100;

  function consider(type,x,y,v,conf,searchR,id){
    if(!(v > 0) || !isFinite(x) || !isFinite(y)) return;
    const d = hyp(x-mem.pos.x, y-mem.pos.y);
    const dB = hyp(x-mem.base.x, y-mem.base.y);
    const sr = searchR || 0;
    const estTime = d/1.6 + dB/1.2 + sr*1.25 + 24;
    if(timeLeft < estTime + 10) return;
    const needE = (d + dB + sr*1.5)*epm*load*1.9 + 0.06;
    if(batt < needE + 0.02) return;
    const vv = v + 0.06;
    let score = Math.pow(vv,1.35) * conf / (10 + d + 0.42*dB + sr*0.65);
    if(type === 'site') score *= 1.20;
    if(score > bestScore){
      bestScore = score;
      best = {type:type, id:id, x:x, y:y, value:v, searchR:sr, startT:mem.t};
    }
  }

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    const ratio = clamp(h.v/maxV,0,1);
    const sr = 17 + 7*ratio;
    consider('hint',h.x,h.y,h.v,0.80,sr,h.id);
  }

  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(s.ignoreUntil && s.ignoreUntil > mem.t && (mem.t - (s.lastSeen||0) > 0.5)) continue;
    const age = mem.t - (s.lastSeen||0);
    let conf = age < 100 ? 1.0 : 0.72;
    consider('site',s.x,s.y,s.value,conf,0,s.id);
  }

  if(!best) return false;

  if(best.type === 'site'){
    mem.mode = 'approach';
    mem.target = null;
    mem.search = null;
    mem.approach = {
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      startT: mem.t,
      lastSeen: mem.t,
      lastDist: 99
    };
  }else{
    mem.mode = 'travel';
    mem.approach = null;
    mem.search = null;
    mem.target = {
      type: best.type,
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      searchR: best.searchR,
      startT: mem.t
    };
  }
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
  return true;
}

function startExplore(obs,mem){
  let n = mem.exploreCount++;
  let ang = n * 2.399963229728653;
  let rad = 55 + ((n*53)%145);
  let cx = mem.base.x + Math.cos(ang)*rad;
  let cy = mem.base.y + Math.sin(ang)*rad;
  cx = clamp(cx,14,mem.size-14);
  cy = clamp(cy,14,mem.size-14);
  if(hyp(cx-mem.pos.x,cy-mem.pos.y) < 22){
    ang += 1.6;
    rad = 85 + ((n*71)%120);
    cx = clamp(mem.base.x + Math.cos(ang)*rad,14,mem.size-14);
    cy = clamp(mem.base.y + Math.sin(ang)*rad,14,mem.size-14);
  }
  mem.target = {
    type: 'explore',
    id: -1,
    x: cx,
    y: cy,
    value: 0.42,
    searchR: 20,
    startT: mem.t
  };
  mem.mode = 'travel';
  mem.approach = null;
  mem.search = null;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
}

function doTravel(obs,mem){
  const task = mem.target;
  if(!task){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const d = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    if(d < 5.5){
      startSearch(obs,mem,h.id,h.x,h.y,h.v);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 180 && d > 10){
      h.status = 2;
      mem.target = null;
      mem.mode = 'idle';
      mem.progressT = mem.t;
      return brakeCmd(obs,mem);
    }
    let sp = 1.9;
    if(fin(obs.carried,0) > 0) sp = 1.72;
    if(fin(obs.battery,1) < 0.30) sp = 1.15;
    if(mem.slip < 0.70) sp *= 0.90;
    return driveTo(obs,mem,h.x,h.y,sp,0.5);
  }

  if(task.type === 'explore'){
    const d = hyp(task.x-mem.pos.x, task.y-mem.pos.y);
    if(d < 4.5){
      startSearch(obs,mem,-1,task.x,task.y,task.value||0.42);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 165 && d > 14){
      mem.target = null;
      mem.mode = 'idle';
      mem.progressT = mem.t;
      return brakeCmd(obs,mem);
    }
    let sp = 1.8;
    if(fin(obs.carried,0) > 0) sp = 1.68;
    if(fin(obs.battery,1) < 0.30) sp = 1.12;
    if(mem.slip < 0.70) sp *= 0.90;
    return driveTo(obs,mem,task.x,task.y,sp,0.5);
  }

  mem.target = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function cancelCurrent(obs,mem){
  if(mem.search && mem.search.hintId >= 0 && mem.search.hintId < mem.hints.length){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.target && mem.target.type === 'hint' && mem.target.id >= 0 && mem.target.id < mem.hints.length){
    const h = mem.hints[mem.target.id];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s) s.ignoreUntil = mem.t + 25;
  }
  if(mem.drill){
    let s = findSiteById(mem,mem.drill.id);
    if(s) s.ignoreUntil = mem.t + 20;
  }
  mem.search = null;
  mem.approach = null;
  mem.target = null;
  mem.drill = null;
  mem.mode = 'idle';
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
}

function startRecovery(obs,mem,isBump){
  if(mem.recoverUntil > mem.t) return;
  mem.recoverStart = mem.t;
  mem.recoverUntil = mem.t + 1.75;
  mem.recoverRevUntil = mem.t + 0.58;

  let L = 0, R = 0;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i > 4) L += Math.min(r,9);
    else if(i < 4) R += Math.min(r,9);
  }
  if(Math.abs(L-R) < 0.2) mem.recoverTurn = -(mem.recoverTurn||1);
  else mem.recoverTurn = L > R ? 1 : -1;

  mem.stallT = 0;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t + 1.8;

  if(mem.t - mem.lastRecoverT < 10) mem.recoverCount = (mem.recoverCount||0) + 1;
  else mem.recoverCount = 1;
  mem.lastRecoverT = mem.t;

  if(mem.recoverCount >= 3 && mem.mode !== 'return'){
    cancelCurrent(obs,mem);
    mem.recoverCount = 0;
    mem.lastCancelT = mem.t;
  }
}

function doRecovery(obs,mem){
  const el = mem.t - mem.recoverStart;
  let v, w;
  if(el < 0.58){
    v = -0.46;
    w = mem.recoverTurn*0.38;
  }else if(el < 1.18){
    v = 0;
    w = mem.recoverTurn*1.42;
  }else{
    v = 0.16;
    w = mem.recoverTurn*0.65;
  }
  const vL = clamp(v - w*0.3,-2.2,2.2);
  const vR = clamp(v + w*0.3,-2.2,2.2);
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function dispatchMode(obs,mem){
  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);
  return brakeCmd(obs,mem);
}

function handleDocked(obs,mem){
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft,1200);

  if(carried > 0){
    mem.mode = 'dockedWait';
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  if(mem.mode !== 'charge'){
    mem.mode = 'charge';
    mem.chargeStart = mem.t;
    mem.chargeLastBatt = batt;
    mem.chargeNoGain = 0;
  }

  if(batt > mem.chargeLastBatt + 0.0002) mem.chargeNoGain = 0;
  else mem.chargeNoGain += mem.dt;
  mem.chargeLastBatt = batt;

  let target = 0.55;
  if(timeLeft > 700) target = 0.84;
  else if(timeLeft > 400) target = 0.72;
  else if(timeLeft > 180) target = 0.60;
  else target = 0.42;
  if(timeLeft < 70) target = Math.min(target,0.30);

  if(batt < target && (mem.t - mem.chargeStart) < 22 && mem.chargeNoGain < 8 && timeLeft > 18){
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  mem.mode = 'idle';
  mem.chargeStart = -1;
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;

  if(timeLeft < 10) return brakeCmd(obs,mem);

  if(chooseTarget(obs,mem)){
    mem.leaveBase = mem.t;
    return dispatchMode(obs,mem);
  }

  if(timeLeft > 25){
    startExplore(obs,mem);
    mem.leaveBase = mem.t;
    return doTravel(obs,mem);
  }

  return brakeCmd(obs,mem);
}

function act(obs,mem){
  if(!mem.init){
    initMission(obs,mem);
    return {left:0,right:0,drill:false};
  }

  updateCore(obs,mem);

  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(obs.docked) return handleDocked(obs,mem);

  if(obs.bumped){
    if(mem.recoverUntil <= mem.t) startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  if(mem.recoverUntil > mem.t) return doRecovery(obs,mem);

  const carried = fin(obs.carried,0);
  const activeMode = (mem.mode === 'travel' || mem.mode === 'search' || mem.mode === 'approach');

  if(activeMode){
    const moved = hyp(mem.pos.x-mem.progressX, mem.pos.y-mem.progressY);
    if(moved > 0.65){
      mem.progressX = mem.pos.x;
      mem.progressY = mem.pos.y;
      mem.progressT = mem.t;
      mem.stallT = 0;
    }

    const wheelAct = Math.abs(mem.wheelL) + Math.abs(mem.wheelR);
    if(mem.lastWant > 0.22 && wheelAct < 0.06){
      mem.stallT += mem.dt;
    }else{
      mem.stallT = Math.max(0, mem.stallT - mem.dt*1.3);
    }

    let stuck = false;
    if((mem.lastWant > 0.20 || wheelAct > 0.22) && (mem.t - mem.progressT > 6.2)) stuck = true;
    if(mem.stallT > 2.3) stuck = true;

    if(stuck){
      mem.progressX = mem.pos.x;
      mem.progressY = mem.pos.y;
      mem.progressT = mem.t + 1.0;
      mem.stallT = 0;
      startRecovery(obs,mem,false);
      return doRecovery(obs,mem);
    }
  }else{
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
    mem.stallT = 0;
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    if(needReturn(obs,mem)) startReturn(obs,mem);
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill' && carried < mem.cap){
    const vis = mem.visible;
    if(vis && (!vis.ignoreUntil || vis.ignoreUntil <= mem.t)){
      if(mem.mode !== 'approach' || !mem.approach || mem.approach.id !== vis.id){
        startApproach(obs,mem,vis);
      }
    }
  }

  const sci = fin(obs.science,0);
  if(mem.mode !== 'return' && mem.mode !== 'drill' && mem.mode !== 'approach' && mem.mode !== 'search' && !mem.visible){
    const shouldLocal = (mem.mode === 'idle' || sci > 4.0 || (sci > 1.2 && mem.t - mem.progressT > 4.0));
    if(shouldLocal && mem.t - mem.lastLocalSearch > 38){
      mem.lastLocalSearch = mem.t;
      startSearch(obs,mem,-1,mem.pos.x,mem.pos.y,Math.max(0.40,sci*0.15));
      return doSearch(obs,mem);
    }
  }

  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(mem.mode === 'idle' || !mem.mode){
    if(chooseTarget(obs,mem)) return dispatchMode(obs,mem);
    if(carried > 0){
      startReturn(obs,mem);
      return doReturn(obs,mem);
    }
    if(fin(obs.timeLeft,0) > 20){
      startExplore(obs,mem);
      return doTravel(obs,mem);
    }
    return brakeCmd(obs,mem);
  }

  return brakeCmd(obs,mem);
}

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;
const RAYA = [-80*D2R,-60*D2R,-40*D2R,-20*D2R,0,20*D2R,40*D2R,60*D2R,80*D2R];

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = a % (2*PI);
  if(a > PI) a -= 2*PI;
  if(a < -PI) a += 2*PI;
  return a;
}
function hyp(x,y){ return Math.sqrt(x*x+y*y); }
function fin(v,d){ return (typeof v === 'number' && isFinite(v)) ? v : d; }

function motorCmd(target, meas, st, dt){
  target = clamp(target,-3.0,3.0);
  if(st.prev !== undefined && st.prev * target < 0) st.i *= 0.30;
  st.prev = target;
  const err = target - meas;
  st.i += err * dt * 1.55;
  st.i = clamp(st.i,-1.0,1.0);
  let u = target / 2.8 + err * 0.92 + st.i;
  if(u > 1){
    u = 1;
    if(err > 0) st.i -= err * dt * 1.55;
  }else if(u < -1){
    u = -1;
    if(err < 0) st.i -= err * dt * 1.55;
  }
  if(target > 0.045 && u < 0.055) u = 0.055;
  if(target < -0.045 && u > -0.055) u = -0.055;
  if(Math.abs(target) < 0.02 && Math.abs(meas) < 0.03){
    st.i *= Math.exp(-dt * 2.2);
    if(Math.abs(st.i) < 0.01) st.i = 0;
  }
  return clamp(u,-1,1);
}

function brakeCmd(obs, mem){
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(0, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(0, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function resetProgress(mem){
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;
}

function initGrid(mem){
  const cell = 2.0;
  const n = Math.ceil(mem.size / cell) + 1;
  mem.cell = cell;
  mem.gn = n;
  mem.grid = new Uint8Array(n*n);
  mem.path = null;
  mem.pathTarget = null;
  mem.pathIdx = 0;
  mem.planT = -999;
}

function initMission(obs, mem){
  mem.init = true;
  mem.t = fin(obs.t,0);
  mem.dt = 0.1;
  const M = obs.mission || {};
  mem.size = fin(M.size,400);
  mem.seconds = fin(M.seconds,1200);
  mem.cap = Math.max(1, Math.floor(fin(M.capacity,5)));
  const b = M.base || {x:fin(obs.x,0), y:fin(obs.y,0)};
  mem.base = {x:fin(b.x,fin(obs.x,0)), y:fin(b.y,fin(obs.y,0))};

  mem.hints = [];
  const hs = Array.isArray(M.hints) ? M.hints : [];
  for(let i=0;i<hs.length;i++){
    const h = hs[i] || {};
    let x = fin(h.x,NaN), y = fin(h.y,NaN), v = fin(h.estimate,0.1);
    if(!isFinite(x) || !isFinite(y)) continue;
    if(!(v > 0)) v = 0.1;
    mem.hints.push({id:mem.hints.length, x:clamp(x,0,mem.size), y:clamp(y,0,mem.size), v:v, status:0});
  }
  mem.maxHintVal = 0.5;
  for(let i=0;i<mem.hints.length;i++) if(mem.hints[i].v > mem.maxHintVal) mem.maxHintVal = mem.hints[i].v;
  mem.maxValSeen = mem.maxHintVal;

  mem.sites = [];
  mem.nextSiteId = 1;
  mem.visible = null;
  mem.sci = 0;
  mem.sciMax = 0;
  mem.sampleCount = 0;

  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;

  mem.ctlL = {i:0, prev:0};
  mem.ctlR = {i:0, prev:0};

  mem.pos = {x:clamp(fin(obs.x,mem.base.x),0.3,mem.size-0.3), y:clamp(fin(obs.y,mem.base.y),0.3,mem.size-0.3)};
  mem.head = wrap(fin(obs.heading,0)*D2R);
  mem.lastRawDeg = fin(obs.heading,0);
  mem.headBias = 0;
  mem.compassBad = 0;
  mem.wheelL = fin(obs.wheelLeft,0);
  mem.wheelR = fin(obs.wheelRight,0);
  mem.vMeas = (mem.wheelL + mem.wheelR)/2;
  mem.wantV = 0;
  mem.lastWant = 0;
  mem.slip = 1;

  mem.lastGpsX = fin(obs.x,mem.pos.x);
  mem.lastGpsY = fin(obs.y,mem.pos.y);
  mem.gpsStaleT = 0;
  mem.gpsWasStale = false;

  mem.lastBatt = fin(obs.battery,1);
  mem.epm = 0.0012;
  mem.drillE = 0.0035;

  mem.rayLast = [];
  mem.rayStill = [];
  for(let i=0;i<9;i++){ mem.rayLast[i] = 15; mem.rayStill[i] = 0; }

  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t;
  mem.stallT = 0;

  mem.recoverStart = -999;
  mem.recoverUntil = -999;
  mem.recoverRevUntil = -999;
  mem.recoverTurn = 1;
  mem.recoverCount = 0;
  mem.lastRecoverT = -999;
  mem.preRecoverMode = 'idle';
  mem.recoverCancel = false;

  mem.chargeStart = -1;
  mem.chargeLastBatt = mem.lastBatt;
  mem.chargeNoGain = 0;
  mem.leaveBaseT = -999;
  mem.exploreCount = 0;

  mem.avoidUntil = -999;
  mem.avoidStart = -999;
  mem.avoidHeading = 0;
  mem.avoidSide = 1;

  initGrid(mem);
}

function findSiteById(mem,id){
  for(let i=0;i<mem.sites.length;i++) if(mem.sites[i].id === id) return mem.sites[i];
  return null;
}

function markHintsNear(mem,x,y,rad){
  const r2 = rad*rad;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const dx = h.x-x, dy = h.y-y;
    if(dx*dx + dy*dy < r2) h.status = 2;
  }
}

function markHintSampled(mem,x,y){
  let nearest = -1;
  let nd = 1e9;
  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status >= 2) continue;
    const d = hyp(h.x-x,h.y-y);
    if(d < nd){ nd = d; nearest = i; }
  }
  if(nearest >= 0 && nd < 32) mem.hints[nearest].status = 2;
  markHintsNear(mem,x,y,11);
}

function updateSites(obs,mem){
  mem.visible = null;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const d = fin(os.distance,999);
    const bear = fin(os.bearing,0);
    const val = fin(os.value,0);
    if(d >= 0 && d < 8.6 && val > 0){
      const ang = mem.head + bear*D2R;
      const sx = mem.pos.x + Math.cos(ang)*d;
      const sy = mem.pos.y + Math.sin(ang)*d;
      let best = null;
      let bestD2 = 16.0;
      for(let i=0;i<mem.sites.length;i++){
        const s = mem.sites[i];
        if(s.sampled) continue;
        const dx = s.x-sx, dy = s.y-sy;
        const dd = dx*dx + dy*dy;
        if(dd < bestD2){ bestD2 = dd; best = s; }
      }
      if(best){
        best.x += (sx-best.x)*0.38;
        best.y += (sy-best.y)*0.38;
        best.value = val;
        best.lastSeen = mem.t;
      }else if(mem.sites.length < 320){
        best = {id:mem.nextSiteId++, x:sx, y:sy, value:val, sampled:false, lastSeen:mem.t, ignoreUntil:0, fails:0};
        mem.sites.push(best);
      }
      if(best){
        if(val > mem.maxValSeen) mem.maxValSeen = val;
        mem.visible = best;
      }
    }
  }
  const sci = fin(obs.science,0);
  mem.sci = sci;
  if(sci > mem.sciMax) mem.sciMax = sci;
}

function updateMap(obs,mem){
  const n = mem.gn;
  const cell = mem.cell;
  if(!mem.grid) return;
  let cx = Math.floor(mem.pos.x/cell);
  let cy = Math.floor(mem.pos.y/cell);
  if(cx>=0 && cy>=0 && cx<n && cy<n){
    const ci = cy*n+cx;
    if(mem.grid[ci] !== 2) mem.grid[ci] = 1;
  }
  for(let i=0;i<9;i++){
    let r = mem.rayLast[i];
    if(!(r >= 0) || r >= 14.9) continue;
    if(mem.rayStill[i] > 32) continue;
    const ang = mem.head + RAYA[i];
    const ex = mem.pos.x + Math.cos(ang)*r;
    const ey = mem.pos.y + Math.sin(ang)*r;
    const steps = Math.max(2, Math.floor(r/cell*2));
    for(let s=1;s<steps;s++){
      const d = (s/steps)*r;
      const x = mem.pos.x + Math.cos(ang)*d;
      const y = mem.pos.y + Math.sin(ang)*d;
      const gx = Math.floor(x/cell);
      const gy = Math.floor(y/cell);
      if(gx>=0 && gy>=0 && gx<n && gy<n){
        const gi = gy*n+gx;
        if(mem.grid[gi] !== 2) mem.grid[gi] = 1;
      }
    }
    const gx = Math.floor(ex/cell);
    const gy = Math.floor(ey/cell);
    if(gx>=0 && gy>=0 && gx<n && gy<n){
      mem.grid[gy*n+gx] = 2;
    }
  }
}

function updateCore(obs,mem){
  let t = fin(obs.t, mem.t + 0.1);
  let dt = t - mem.t;
  if(!(dt > 0) || dt > 1.2) dt = 0.1;
  if(dt < 0.02) dt = 0.02;
  mem.dt = dt;
  mem.t = t;

  const wl = fin(obs.wheelLeft,0);
  const wr = fin(obs.wheelRight,0);
  mem.wheelL = wl;
  mem.wheelR = wr;
  const v = (wl+wr)/2;
  mem.vMeas = v;
  const yaw = (wr-wl)/0.6;

  const rawDeg = fin(obs.heading, mem.lastRawDeg);
  mem.lastRawDeg = rawDeg;
  const raw = wrap(rawDeg*D2R);
  const pred = wrap(mem.head + yaw*dt);
  const meas = wrap(raw - mem.headBias);
  const diff = wrap(meas - pred);
  if(Math.abs(diff) > 1.15 && Math.abs(yaw) < 1.2){
    mem.head = pred;
    mem.compassBad = Math.min(100, (mem.compassBad||0) + 1);
  }else{
    mem.compassBad = Math.max(0, (mem.compassBad||0) - 0.2);
    const alpha = mem.compassBad > 8 ? 0.25 : 0.65;
    mem.head = wrap(pred + diff*alpha);
  }

  const gx = fin(obs.x, mem.lastGpsX);
  const gy = fin(obs.y, mem.lastGpsY);
  const oldGX = mem.lastGpsX;
  const oldGY = mem.lastGpsY;
  const gd = hyp(gx-oldGX, gy-oldGY);
  const gpsNew = gd > 0.004;
  if(gpsNew){
    mem.gpsStaleT = 0;
  }else if(Math.abs(v) > 0.05){
    mem.gpsStaleT = (mem.gpsStaleT||0) + dt;
  }

  const estX = mem.pos.x + v*Math.cos(mem.head)*dt;
  const estY = mem.pos.y + v*Math.sin(mem.head)*dt;
  const stale = (mem.gpsStaleT||0) > 1.6 && Math.abs(v) > 0.04;
  if(!stale){
    const ex = gx - estX;
    const ey = gy - estY;
    const ed = hyp(ex,ey);
    let alpha = ed < 1 ? 0.68 : (ed < 5 ? 0.42 : 0.22);
    if(mem.gpsWasStale) alpha = Math.max(alpha,0.85);
    mem.pos.x = estX + ex*alpha;
    mem.pos.y = estY + ey*alpha;
    mem.gpsWasStale = false;
  }else{
    mem.pos.x = estX;
    mem.pos.y = estY;
    mem.gpsWasStale = true;
  }

  if(gpsNew && Math.abs(v) > 0.20 && dt > 0.02){
    const expected = Math.abs(v) * Math.max(0.1, dt);
    if(expected > 0.02){
      const ratio = gd / expected;
      if(ratio > 0.05 && ratio < 2.5) mem.slip = clamp(mem.slip*0.98 + ratio*0.02, 0.10, 1.5);
    }
  }

  if(gpsNew && Math.abs(v) > 0.35 && Math.abs(wr-wl) < 0.40){
    let course = Math.atan2(gy-oldGY, gx-oldGX);
    if(v < 0) course = wrap(course + PI);
    const b = wrap(raw - course);
    if(Math.abs(b) < 1.0) mem.headBias = wrap(mem.headBias*0.995 + b*0.005);
  }

  mem.pos.x = clamp(mem.pos.x,0.3,mem.size-0.3);
  mem.pos.y = clamp(mem.pos.y,0.3,mem.size-0.3);
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;

  const moving = (Math.abs(wl)+Math.abs(wr)) > 0.18;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayLast[i] !== undefined && Math.abs(r-mem.rayLast[i]) < 0.001 && moving){
      mem.rayStill[i] = (mem.rayStill[i]||0) + 1;
    }else{
      mem.rayStill[i] = 0;
    }
    mem.rayLast[i] = r;
  }

  const batt = fin(obs.battery,mem.lastBatt);
  if(!obs.docked && dt > 0){
    const dist = Math.abs(v)*dt;
    const drop = mem.lastBatt - batt;
    if(dist > 0.02 && drop > 0){
      const load = 1 + 0.08*fin(obs.carried,0);
      const e = drop / (dist*load);
      if(e > 0.00003 && e < 0.02) mem.epm = clamp(mem.epm*0.97 + e*0.03, 0.0004, 0.01);
    }
  }
  mem.lastBatt = batt;

  updateSites(obs,mem);
  updateMap(obs,mem);
}

function heuristicCell(nx,ny,gx,gy){
  return Math.hypot(nx-gx, ny-gy);
}

function planPath(mem, tx, ty){
  const n = mem.gn;
  const cell = mem.cell;
  if(!mem.grid || n < 2) return null;
  let sx = Math.floor(mem.pos.x/cell);
  let sy = Math.floor(mem.pos.y/cell);
  let gx = Math.floor(tx/cell);
  let gy = Math.floor(ty/cell);
  if(sx < 0) sx = 0; if(sy < 0) sy = 0;
  if(sx >= n) sx = n-1; if(sy >= n) sy = n-1;
  if(gx < 0) gx = 0; if(gy < 0) gy = 0;
  if(gx >= n) gx = n-1; if(gy >= n) gy = n-1;
  const startIdx = sy*n+sx;
  let goalIdx = gy*n+gx;
  if(mem.grid[startIdx] === 2) mem.grid[startIdx] = 1;
  if(mem.grid[goalIdx] === 2){
    let found = false;
    let bestD = 1e9;
    for(let dy=-3;dy<=3;dy++){
      for(let dx=-3;dx<=3;dx++){
        const nx = gx+dx, ny = gy+dy;
        if(nx<0||ny<0||nx>=n||ny>=n) continue;
        const ni = ny*n+nx;
        if(mem.grid[ni] === 2) continue;
        const d = dx*dx+dy*dy;
        if(d < bestD){ bestD = d; goalIdx = ni; found = true; }
      }
    }
    if(!found) return null;
  }
  if(startIdx === goalIdx) return [{x:tx,y:ty}];

  const size = n*n;
  const gScore = new Float32Array(size);
  gScore.fill(Infinity);
  const came = new Int32Array(size);
  came.fill(-1);
  const closed = new Uint8Array(size);
  gScore[startIdx] = 0;

  const heap = [];
  function heapPush(i,f){
    heap.push({i:i,f:f});
    let idx = heap.length-1;
    while(idx > 0){
      const p = (idx-1)>>1;
      if(heap[p].f <= heap[idx].f) break;
      const tmp = heap[p]; heap[p] = heap[idx]; heap[idx] = tmp;
      idx = p;
    }
  }
  function heapPop(){
    if(heap.length === 0) return -1;
    const res = heap[0].i;
    const last = heap.pop();
    if(heap.length > 0){
      heap[0] = last;
      let idx = 0;
      while(true){
        const l = idx*2+1;
        const r = l+1;
        let small = idx;
        if(l < heap.length && heap[l].f < heap[small].f) small = l;
        if(r < heap.length && heap[r].f < heap[small].f) small = r;
        if(small === idx) break;
        const tmp = heap[idx]; heap[idx] = heap[small]; heap[small] = tmp;
        idx = small;
      }
    }
    return res;
  }

  const goalX = goalIdx % n;
  const goalY = (goalIdx / n) | 0;
  heapPush(startIdx, heuristicCell(sx,sy,goalX,goalY));
  let found = false;
  let iter = 0;

  while(heap.length > 0 && iter < 15000){
    iter++;
    const ci = heapPop();
    if(ci < 0) break;
    if(closed[ci]) continue;
    closed[ci] = 1;
    if(ci === goalIdx){ found = true; break; }
    const cx = ci % n;
    const cy = (ci / n) | 0;
    for(let dy=-1;dy<=1;dy++){
      for(let dx=-1;dx<=1;dx++){
        if(dx === 0 && dy === 0) continue;
        const nx = cx+dx;
        const ny = cy+dy;
        if(nx < 0 || ny < 0 || nx >= n || ny >= n) continue;
        const ni = ny*n+nx;
        if(mem.grid[ni] === 2) continue;
        if(dx !== 0 && dy !== 0){
          const a = cy*n+(cx+dx);
          const b = (cy+dy)*n+cx;
          if(mem.grid[a] === 2 || mem.grid[b] === 2) continue;
        }
        if(closed[ni]) continue;
        const step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1.0;
        const ng = gScore[ci] + step;
        if(ng < gScore[ni]){
          gScore[ni] = ng;
          came[ni] = ci;
          heapPush(ni, ng + 1.05*heuristicCell(nx,ny,goalX,goalY));
        }
      }
    }
  }
  if(!found) return null;

  const path = [];
  let cur = goalIdx;
  while(cur !== -1 && cur !== startIdx){
    const x = cur % n;
    const y = (cur / n) | 0;
    path.push({x:(x+0.5)*cell, y:(y+0.5)*cell});
    cur = came[cur];
  }
  path.reverse();
  if(path.length === 0) path.push({x:tx,y:ty});
  return path;
}

function getWaypoint(mem,tx,ty){
  const d = hyp(tx-mem.pos.x, ty-mem.pos.y);
  if(d < 12.0) return {x:tx,y:ty};
  let need = false;
  if(!mem.path || !mem.pathTarget) need = true;
  else if(hyp(mem.pathTarget.x-tx, mem.pathTarget.y-ty) > 4.0) need = true;
  else if(mem.t - mem.planT > 2.8) need = true;
  else if(!mem.path || mem.pathIdx >= mem.path.length) need = true;
  if(need){
    mem.path = planPath(mem,tx,ty);
    mem.pathTarget = {x:tx,y:ty};
    mem.pathIdx = 0;
    mem.planT = mem.t;
  }
  if(!mem.path || mem.path.length === 0) return {x:tx,y:ty};
  while(mem.pathIdx < mem.path.length-1 &&
        hyp(mem.path[mem.pathIdx].x-mem.pos.x, mem.path[mem.pathIdx].y-mem.pos.y) < 2.2){
    mem.pathIdx++;
  }
  return mem.path[mem.pathIdx];
}

function driveHeading(obs,mem,desired,speedLimit){
  const rays = obs.rays || [];
  let vx = Math.cos(desired);
  let vy = Math.sin(desired);
  let minFront = 15;
  let leftClear = 0;
  let rightClear = 0;

  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(mem.rayStill && mem.rayStill[i] > 32) r = 15;

    if(i >= 3 && i <= 5 && r < minFront) minFront = r;
    if(i > 4) leftClear += Math.min(r,8);
    else if(i < 4) rightClear += Math.min(r,8);

    if(r < 4.8){
      const ang = mem.head + RAYA[i];
      let w = (4.8-r)/4.8;
      if(i === 4) w *= 2.3;
      else if(i >= 3 && i <= 5) w *= 1.5;
      else w *= 0.55;
      if(r < 1.2) w *= 2.0;
      vx -= Math.cos(ang)*w*1.45;
      vy -= Math.sin(ang)*w*1.45;
    }
  }

  const m = 4.0;
  if(mem.pos.x < m) vx += (m-mem.pos.x)/m*2.0;
  if(mem.pos.x > mem.size-m) vx -= (mem.pos.x-(mem.size-m))/m*2.0;
  if(mem.pos.y < m) vy += (m-mem.pos.y)/m*2.0;
  if(mem.pos.y > mem.size-m) vy -= (mem.pos.y-(mem.size-m))/m*2.0;

  if(hyp(vx,vy) > 0.05) desired = Math.atan2(vy,vx);

  if(mem.avoidUntil > mem.t){
    if(minFront > 3.2 && mem.t > mem.avoidStart + 0.35){
      mem.avoidUntil = -999;
    }else{
      desired = mem.avoidHeading;
    }
  }

  if(mem.avoidUntil <= mem.t && minFront < 2.0){
    const side = (leftClear >= rightClear ? 1 : -1);
    mem.avoidSide = side;
    mem.avoidStart = mem.t;
    mem.avoidUntil = mem.t + 0.7;
    mem.avoidHeading = wrap(mem.head + side*(1.15 + (2.0-minFront)*0.35));
    desired = mem.avoidHeading;
  }

  let err = wrap(desired - mem.head);
  let sp = Math.min(speedLimit,2.2);

  const batt = fin(obs.battery,1);
  const carried = fin(obs.carried,0);
  if(carried > 0) sp *= (1 - 0.025*carried);
  if(batt < 0.25) sp = Math.min(sp,1.25);
  if(batt < 0.15) sp = Math.min(sp,0.75);
  if(mem.slip < 0.70) sp *= 0.86;
  if(mem.slip < 0.45) sp *= 0.80;
  const pitch = fin(obs.pitch,0);
  if(Math.abs(pitch) > 18) sp *= 0.82;

  if(minFront < 5.2){
    const cap = Math.max(0.0,(minFront-0.78)*0.58);
    sp = Math.min(sp,cap);
  }
  if(minFront < 1.05){
    sp = 0;
    const side = (leftClear >= rightClear ? 1 : -1);
    mem.avoidSide = side;
    mem.avoidUntil = Math.max(mem.avoidUntil, mem.t+0.55);
    mem.avoidHeading = wrap(mem.head + side*1.25);
    err = wrap(mem.avoidHeading - mem.head);
  }else if(Math.abs(err) > 1.05){
    sp = 0;
  }else if(Math.abs(err) > 0.56){
    sp = Math.min(sp,0.62);
  }

  let v = Math.max(0,sp);
  let w = clamp(err*2.22,-2.5,2.5);
  if(v < 0.02){
    v = 0;
    if(Math.abs(err) > 0.06) w = clamp(err*2.0,-1.95,1.95);
    else w = 0;
  }

  const vL = clamp(v - w*0.3,-3.0,3.0);
  const vR = clamp(v + w*0.3,-3.0,3.0);
  mem.wantV = v;
  mem.lastWant = v;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function driveTo(obs,mem,tx,ty,speed,arrive){
  const dx = tx - mem.pos.x;
  const dy = ty - mem.pos.y;
  const d = hyp(dx,dy);
  if(d <= arrive) return brakeCmd(obs,mem);
  const wp = getWaypoint(mem,tx,ty);
  const wdx = wp.x - mem.pos.x;
  const wdy = wp.y - mem.pos.y;
  const wd = hyp(wdx,wdy);
  if(wd < 0.05) return brakeCmd(obs,mem);
  let desired = Math.atan2(wdy,wdx);
  let sp = speed;
  if(d < arrive + 4.0) sp = Math.min(sp, Math.max(0.12,(d-arrive)*0.60));
  if(wd < 2.2) sp = Math.min(sp, Math.max(0.14,wd*0.45));
  return driveHeading(obs,mem,desired,sp);
}

function makeSpiralPath(cx,cy,R,spacing,size){
  const pts = [{x:cx,y:cy}];
  const dxs = [1,0,-1,0];
  const dys = [0,1,0,-1];
  let x = 0, y = 0;
  let dir = 0;
  let leg = 1;
  const maxR = R/spacing + 1;
  let guard = 0;
  while(leg <= 2*maxR+2 && guard++ < 400){
    for(let rep=0;rep<2;rep++){
      for(let s=0;s<leg;s++){
        x += dxs[dir];
        y += dys[dir];
        const wx = cx + x*spacing;
        const wy = cy + y*spacing;
        const rr = Math.hypot(x*spacing,y*spacing);
        if(rr <= R + spacing*0.7 && wx > 2 && wx < size-2 && wy > 2 && wy < size-2){
          const last = pts[pts.length-1];
          if(Math.hypot(wx-last.x, wy-last.y) >= spacing*0.55){
            pts.push({x:wx,y:wy});
          }
        }
        if(pts.length > 260) return pts;
      }
      dir = (dir+1) % 4;
    }
    leg++;
  }
  return pts;
}

function startSearch(obs,mem,hintId,cx,cy,val,R){
  cx = clamp(cx,3,mem.size-3);
  cy = clamp(cy,3,mem.size-3);
  R = clamp(R,11,28);
  const pts = makeSpiralPath(cx,cy,R,7.6,mem.size);
  mem.search = {
    hintId: hintId,
    cx: cx,
    cy: cy,
    value: val,
    R: R,
    pts: pts,
    idx: 0,
    startT: mem.t,
    centerT: 0,
    centerChecked: false,
    pointT: mem.t,
    timeout: 34 + R*2.6,
    zeroSciT: 0
  };
  mem.mode = 'search';
  mem.target = null;
  mem.approach = null;
  mem.drill = null;
  mem.path = null;
  resetProgress(mem);
}

function finishSearch(obs,mem){
  const S = mem.search;
  if(S && S.hintId >= 0 && S.hintId < mem.hints.length){
    const h = mem.hints[S.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  mem.search = null;
  mem.target = null;
  mem.approach = null;
  mem.mode = 'idle';
  mem.path = null;
  resetProgress(mem);
}

function doSearch(obs,mem){
  const S = mem.search;
  if(!S){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(mem.visible && (!mem.visible.ignoreUntil || mem.visible.ignoreUntil <= mem.t)){
    startApproach(obs,mem,mem.visible);
    return doApproach(obs,mem);
  }

  if(mem.t - S.startT > S.timeout){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  if(!S.centerChecked){
    const d = hyp(S.cx-mem.pos.x, S.cy-mem.pos.y);
    if(d > 2.4 && mem.t - S.startT < 12.0){
      return driveTo(obs,mem,S.cx,S.cy,1.15,0.35);
    }
    S.centerChecked = true;
    S.centerT = mem.t;
    const sci = fin(obs.science,0);
    if(sci <= 1e-9 && !mem.visible){
      finishSearch(obs,mem);
      return brakeCmd(obs,mem);
    }
    return brakeCmd(obs,mem);
  }

  const sci = fin(obs.science,0);
  if(sci <= 1e-9) S.zeroSciT += mem.dt;
  else S.zeroSciT = 0;
  if(S.zeroSciT > 8.0 && S.idx > 2){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  while(S.idx < S.pts.length){
    const p = S.pts[S.idx];
    const d = hyp(p.x-mem.pos.x, p.y-mem.pos.y);
    const limit = Math.max(6.0, Math.min(14.0, d*0.9 + 5.0));
    if(d < 1.8 || mem.t - S.pointT > limit){
      S.idx++;
      S.pointT = mem.t;
    }else{
      break;
    }
  }

  if(S.idx >= S.pts.length){
    finishSearch(obs,mem);
    return brakeCmd(obs,mem);
  }

  const p = S.pts[S.idx];
  let sp = 1.55;
  if(S.value > 0.65*(mem.maxHintVal||1.0)) sp = 1.85;
  if(fin(obs.timeLeft,1200) < 130) sp = Math.min(sp,1.15);
  if(hyp(p.x-mem.pos.x,p.y-mem.pos.y) < 3.0) sp = Math.min(sp,0.78);
  return driveTo(obs,mem,p.x,p.y,sp,0.4);
}

function startApproach(obs,mem,site){
  if(mem.mode === 'approach' && mem.approach && mem.approach.id === site.id){
    mem.approach.x += (site.x - mem.approach.x)*0.45;
    mem.approach.y += (site.y - mem.approach.y)*0.45;
    mem.approach.value = site.value;
    mem.approach.lastSeen = mem.t;
    return;
  }
  mem.mode = 'approach';
  mem.target = null;
  mem.search = null;
  mem.approach = {
    id: site.id,
    x: site.x,
    y: site.y,
    value: site.value,
    startT: mem.t,
    lastSeen: mem.t,
    lastDist: 99
  };
  mem.drill = null;
  mem.path = null;
  resetProgress(mem);
}

function abortApproach(obs,mem){
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s){
      s.fails = (s.fails||0) + 1;
      s.ignoreUntil = mem.t + (s.fails >= 2 ? 260 : 45);
    }
  }
  mem.approach = null;
  mem.mode = 'idle';
  mem.target = null;
  mem.search = null;
  mem.path = null;
  resetProgress(mem);
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(obs,mem);
  return brakeCmd(obs,mem);
}

function startDrill(obs,mem,app){
  mem.mode = 'drill';
  mem.drill = {
    id: app.id,
    value: app.value,
    before: fin(obs.carried,0),
    startT: mem.t,
    hx: mem.pos.x,
    hy: mem.pos.y,
    hHeading: mem.head,
    lastDr: 0,
    resets: 0,
    lastSeen: mem.t
  };
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.path = null;
  mem.wantV = 0;
  mem.lastWant = 0;
  return doDrill(obs,mem);
}

function abortDrill(obs,mem){
  if(mem.drill){
    const s = findSiteById(mem,mem.drill.id);
    if(s){
      s.fails = (s.fails||0) + 1;
      s.ignoreUntil = mem.t + (s.fails >= 2 ? 320 : 35);
    }
  }
  mem.drill = null;
  mem.approach = null;
  mem.search = null;
  mem.target = null;
  mem.mode = 'idle';
  mem.path = null;
  resetProgress(mem);
  if(fin(obs.carried,0) > 0 && needReturn(obs,mem)) startReturn(obs,mem);
  return brakeCmd(obs,mem);
}

function doDrill(obs,mem){
  const D = mem.drill;
  if(!D){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);

  if(carried > D.before){
    for(let i=0;i<mem.sites.length;i++){
      const s = mem.sites[i];
      if(s.sampled) continue;
      if(s.id === D.id || hyp(s.x-D.hx,s.y-D.hy) < 2.8 || hyp(s.x-mem.pos.x,s.y-mem.pos.y) < 2.8) s.sampled = true;
    }
    markHintSampled(mem,D.hx,D.hy);
    mem.sampleCount = (mem.sampleCount||0) + 1;
    mem.drill = null;
    mem.approach = null;
    mem.search = null;
    mem.target = null;
    mem.mode = 'idle';
    mem.path = null;
    resetProgress(mem);
    if(carried >= mem.cap || needReturn(obs,mem)) startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  const elapsed = mem.t - D.startT;
  const dr = fin(obs.drilling,0);
  if(D.lastDr > 0.6 && dr < D.lastDr - 0.35) D.resets++;
  D.lastDr = dr;

  let d = 99;
  let bear = 0;
  let haveSite = false;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const dd = fin(os.distance,999);
    if(dd >= 0 && dd < 8.6){
      d = dd;
      bear = fin(os.bearing,0);
      haveSite = true;
      D.lastSeen = mem.t;
    }
  }

  if(elapsed > 12.0) return abortDrill(obs,mem);
  if(D.resets > 1) return abortDrill(obs,mem);
  if(haveSite && d > 1.55 && elapsed > 1.0) return abortDrill(obs,mem);
  if(!haveSite && elapsed > 2.5 && dr < 0.25) return abortDrill(obs,mem);
  if(elapsed > 1.0 && needReturn(obs,mem)) return abortDrill(obs,mem);

  let v = 0;
  let w = 0;
  if(haveSite){
    const err = wrap(bear*D2R);
    if(d > 1.30) v = clamp((d-1.12)*0.10, -0.045, 0.075);
    else if(d < 0.72) v = -0.018;
    else v = 0;
    w = clamp(err*0.72,-0.18,0.18);
  }
  const vL = clamp(v - w*0.3,-0.09,0.09);
  const vR = clamp(v + w*0.3,-0.09,0.09);
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: true
  };
}

function doApproach(obs,mem){
  const A = mem.approach;
  if(!A){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap || needReturn(obs,mem)){
    startReturn(obs,mem);
    return brakeCmd(obs,mem);
  }

  let d = null;
  let bear = 0;
  const os = obs.site;
  if(os && isFinite(os.distance) && isFinite(os.bearing)){
    const dd = fin(os.distance,999);
    if(dd >= 0 && dd < 8.6){
      d = dd;
      bear = fin(os.bearing,0);
      if(mem.visible && mem.visible.id !== A.id){
        A.id = mem.visible.id;
        A.x = mem.visible.x;
        A.y = mem.visible.y;
        A.value = mem.visible.value;
      }else if(mem.visible){
        A.x = mem.visible.x;
        A.y = mem.visible.y;
        A.value = mem.visible.value;
      }
      A.lastSeen = mem.t;
      A.lastDist = dd;
    }
  }

  if(mem.t - A.startT > 42.0) return abortApproach(obs,mem);

  const maxW = Math.max(Math.abs(mem.wheelL),Math.abs(mem.wheelR));

  if(d !== null){
    if(d <= 1.38 && maxW < 0.13) return startDrill(obs,mem,A);
    if(d <= 1.55 && maxW >= 0.08) return brakeCmd(obs,mem);

    const desired = mem.head + bear*D2R;
    let sp;
    if(d > 7.0) sp = 1.70;
    else if(d > 3.5) sp = 1.02;
    else if(d > 1.8) sp = 0.56;
    else if(d > 1.38) sp = 0.22;
    else sp = 0.10;
    return driveHeading(obs,mem,desired,sp);
  }else{
    const dd = hyp(A.x-mem.pos.x, A.y-mem.pos.y);
    if(dd < 0.75 && mem.t - A.lastSeen > 2.5) return abortApproach(obs,mem);
    const wp = getWaypoint(mem,A.x,A.y);
    const dx = wp.x-mem.pos.x;
    const dy = wp.y-mem.pos.y;
    const wd = hyp(dx,dy);
    if(wd < 0.06) return brakeCmd(obs,mem);
    const desired = Math.atan2(dy,dx);
    let sp;
    if(dd > 6.0) sp = 1.55;
    else if(dd > 2.5) sp = 0.90;
    else sp = 0.42;
    return driveHeading(obs,mem,desired,sp);
  }
}

function needReturn(obs,mem){
  if(obs.docked) return false;
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft, mem.seconds - mem.t);
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  const epm = clamp(mem.epm,0.0006,0.01);
  const load = 1 + 0.08*carried;
  const needE = bd*epm*load*2.15 + 0.07;
  const needT = bd/0.95 + 24;

  if(carried >= mem.cap) return true;
  if(carried > 0){
    if(batt < needE + 0.045) return true;
    if(timeLeft < needT + 28) return true;
    if(batt < 0.16) return true;
    if(timeLeft < 70) return true;
  }else{
    if(bd > 25 && batt < needE + 0.03) return true;
    if(timeLeft < needT + 12) return true;
    if(batt < 0.12) return true;
  }
  return false;
}

function startReturn(obs,mem){
  if(mem.mode === 'return') return;
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;
  mem.mode = 'return';
  mem.path = null;
  resetProgress(mem);
}

function doReturn(obs,mem){
  const bd = hyp(mem.pos.x-mem.base.x, mem.pos.y-mem.base.y);
  let d = bd;
  let desired = Math.atan2(mem.base.y-mem.pos.y, mem.base.x-mem.pos.x);
  let useBeacon = false;

  const bc = obs.beacon;
  if(bc && isFinite(bc.distance) && isFinite(bc.bearing)){
    const bdist = fin(bc.distance,999);
    const bb = fin(bc.bearing,0)*D2R;
    if(bdist < 20){
      d = bdist;
      desired = mem.head + bb;
      useBeacon = true;
    }
  }

  if(d < 2.0) return brakeCmd(obs,mem);

  let sp = 1.9;
  if(d < 6.0) sp = Math.max(0.14, d*0.36);
  if(fin(obs.battery,1) < 0.20) sp = Math.min(sp,0.95);
  if(mem.slip < 0.55) sp *= 0.86;

  if(useBeacon){
    return driveHeading(obs,mem,desired,sp);
  }
  return driveTo(obs,mem,mem.base.x,mem.base.y,sp,0.35);
}

function chooseTarget(obs,mem){
  const carried = fin(obs.carried,0);
  if(carried >= mem.cap) return false;
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft, mem.seconds - mem.t);
  const epm = clamp(mem.epm,0.0006,0.01);
  const load = 1 + 0.08*carried;
  const maxV = Math.max(0.5, mem.maxHintVal||0.5, mem.maxValSeen||0.5);
  let best = null;
  let bestScore = -1e100;

  for(let i=0;i<mem.sites.length;i++){
    const s = mem.sites[i];
    if(s.sampled) continue;
    if(s.ignoreUntil && s.ignoreUntil > mem.t) continue;
    if(!(s.value > 0) || !isFinite(s.x) || !isFinite(s.y)) continue;
    const d = hyp(s.x-mem.pos.x, s.y-mem.pos.y);
    const dB = hyp(s.x-mem.base.x, s.y-mem.base.y);
    const needT = d/1.35 + dB/1.15 + 15;
    if(timeLeft < needT + 18) continue;
    const needE = (d + dB)*epm*load*1.8 + 0.06;
    if(batt < needE + 0.035) continue;
    const age = mem.t - (s.lastSeen||0);
    let conf = age < 110 ? 1.0 : 0.72;
    let score = Math.pow(s.value + 0.10, 1.45) * conf / (8 + d + 0.40*dB);
    if(score > bestScore){
      bestScore = score;
      best = {type:'site', id:s.id, x:s.x, y:s.y, value:s.value};
    }
  }

  for(let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if(h.status !== 0) continue;
    const d = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    const dB = hyp(h.x-mem.base.x, h.y-mem.base.y);
    const ratio = clamp(h.v/maxV,0,1);
    let R = 14.0 + 10.0*ratio;
    if(timeLeft < 300) R = Math.min(R,18);
    if(batt < 0.35) R = Math.min(R,16);
    const searchPath = R*2.15;
    const needT = d/1.35 + dB/1.15 + searchPath/1.25 + 18;
    if(timeLeft < needT + 14) continue;
    const needE = (d + dB + searchPath*1.15)*epm*load*1.8 + 0.065;
    if(batt < needE + 0.035) continue;
    const conf = 0.86;
    let score = Math.pow(h.v + 0.08, 1.35) * conf / (8 + d + 0.40*dB + searchPath*0.58);
    if(score > bestScore){
      bestScore = score;
      best = {type:'hint', id:i, x:h.x, y:h.y, value:h.v, searchR:R};
    }
  }

  if(!best) return false;

  if(best.type === 'site'){
    mem.mode = 'approach';
    mem.target = null;
    mem.search = null;
    mem.approach = {
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      startT: mem.t,
      lastSeen: mem.t,
      lastDist: 99
    };
    mem.drill = null;
  }else{
    mem.mode = 'travel';
    mem.approach = null;
    mem.search = null;
    mem.target = {
      type: 'hint',
      id: best.id,
      x: best.x,
      y: best.y,
      value: best.value,
      searchR: best.searchR,
      startT: mem.t
    };
  }
  mem.path = null;
  resetProgress(mem);
  return true;
}

function startExplore(obs,mem){
  let n = mem.exploreCount++;
  let ang = n * 2.399963229728653;
  let rad = 58 + ((n*47)%145);
  let cx = mem.base.x + Math.cos(ang)*rad;
  let cy = mem.base.y + Math.sin(ang)*rad;
  cx = clamp(cx,14,mem.size-14);
  cy = clamp(cy,14,mem.size-14);
  if(hyp(cx-mem.pos.x,cy-mem.pos.y) < 24){
    ang += 1.7;
    rad = 85 + ((n*71)%110);
    cx = clamp(mem.base.x + Math.cos(ang)*rad,14,mem.size-14);
    cy = clamp(mem.base.y + Math.sin(ang)*rad,14,mem.size-14);
  }
  mem.target = {
    type: 'explore',
    id: -1,
    x: cx,
    y: cy,
    value: 0.30,
    searchR: 18.0,
    startT: mem.t
  };
  mem.mode = 'travel';
  mem.approach = null;
  mem.search = null;
  mem.drill = null;
  mem.path = null;
  resetProgress(mem);
}

function doTravel(obs,mem){
  const task = mem.target;
  if(!task){
    mem.mode = 'idle';
    return brakeCmd(obs,mem);
  }

  if(task.type === 'hint'){
    if(task.id < 0 || task.id >= mem.hints.length){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const h = mem.hints[task.id];
    if(!h || h.status >= 2){
      mem.target = null;
      mem.mode = 'idle';
      return brakeCmd(obs,mem);
    }
    const d = hyp(h.x-mem.pos.x, h.y-mem.pos.y);
    if(d < 4.2){
      startSearch(obs,mem,h.id,h.x,h.y,h.v,task.searchR||18.0);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 240 && d > 12){
      h.status = 2;
      mem.target = null;
      mem.mode = 'idle';
      mem.path = null;
      return brakeCmd(obs,mem);
    }
    let sp = 1.85;
    if(fin(obs.carried,0) > 0) sp = 1.68;
    if(fin(obs.battery,1) < 0.30) sp = 1.15;
    if(mem.slip < 0.70) sp *= 0.90;
    return driveTo(obs,mem,h.x,h.y,sp,0.45);
  }

  if(task.type === 'explore'){
    const d = hyp(task.x-mem.pos.x, task.y-mem.pos.y);
    if(d < 4.0){
      startSearch(obs,mem,-1,task.x,task.y,task.value||0.30,task.searchR||18.0);
      return doSearch(obs,mem);
    }
    if(mem.t - task.startT > 205 && d > 14){
      mem.target = null;
      mem.mode = 'idle';
      mem.path = null;
      return brakeCmd(obs,mem);
    }
    let sp = 1.75;
    if(fin(obs.carried,0) > 0) sp = 1.62;
    if(fin(obs.battery,1) < 0.30) sp = 1.10;
    if(mem.slip < 0.70) sp *= 0.90;
    return driveTo(obs,mem,task.x,task.y,sp,0.45);
  }

  mem.target = null;
  mem.mode = 'idle';
  return brakeCmd(obs,mem);
}

function startRecovery(obs,mem,isBump){
  if(mem.mode === 'recover') return;
  mem.preRecoverMode = mem.mode;
  mem.mode = 'recover';
  mem.recoverStart = mem.t;
  mem.recoverUntil = mem.t + 1.65;
  mem.recoverRevUntil = mem.t + 0.55;

  let L = 0;
  let R = 0;
  const rays = obs.rays || [];
  for(let i=0;i<9;i++){
    let r = fin(rays[i],15);
    if(!isFinite(r) || r < 0) r = 15;
    if(r > 15) r = 15;
    if(i > 4) L += Math.min(r,9);
    else if(i < 4) R += Math.min(r,9);
  }
  if(Math.abs(L-R) < 0.2) mem.recoverTurn = -(mem.recoverTurn||1);
  else mem.recoverTurn = L > R ? 1 : -1;

  mem.stallT = 0;
  mem.progressX = mem.pos.x;
  mem.progressY = mem.pos.y;
  mem.progressT = mem.t + 1.6;
  mem.avoidUntil = -999;
}

function doRecovery(obs,mem){
  const el = mem.t - mem.recoverStart;
  let v, w;
  if(el < 0.55){
    v = -0.45;
    w = mem.recoverTurn*0.42;
  }else if(el < 1.15){
    v = 0;
    w = mem.recoverTurn*1.38;
  }else{
    v = 0.12;
    w = mem.recoverTurn*0.52;
  }
  const vL = clamp(v - w*0.3,-2.3,2.3);
  const vR = clamp(v + w*0.3,-2.3,2.3);
  mem.wantV = 0;
  mem.lastWant = 0;
  return {
    left: motorCmd(vL, mem.wheelL, mem.ctlL, mem.dt),
    right: motorCmd(vR, mem.wheelR, mem.ctlR, mem.dt),
    drill: false
  };
}

function cancelCurrent(obs,mem){
  if(mem.search && mem.search.hintId >= 0 && mem.search.hintId < mem.hints.length){
    const h = mem.hints[mem.search.hintId];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.target && mem.target.type === 'hint' && mem.target.id >= 0 && mem.target.id < mem.hints.length){
    const h = mem.hints[mem.target.id];
    if(h && h.status < 2) h.status = 2;
  }
  if(mem.approach){
    const s = findSiteById(mem,mem.approach.id);
    if(s){
      s.fails = (s.fails||0) + 1;
      s.ignoreUntil = mem.t + (s.fails >= 2 ? 300 : 60);
    }
  }
  if(mem.drill){
    const s = findSiteById(mem,mem.drill.id);
    if(s){
      s.fails = (s.fails||0) + 1;
      s.ignoreUntil = mem.t + (s.fails >= 2 ? 300 : 60);
    }
  }
  mem.search = null;
  mem.approach = null;
  mem.target = null;
  mem.drill = null;
  mem.mode = 'idle';
  mem.path = null;
  resetProgress(mem);
}

function checkStuck(obs,mem){
  if(!(mem.mode === 'travel' || mem.mode === 'search' || mem.mode === 'approach' || mem.mode === 'return')) return false;
  const moved = hyp(mem.pos.x-mem.progressX, mem.pos.y-mem.progressY);
  if(moved > 0.65){
    mem.progressX = mem.pos.x;
    mem.progressY = mem.pos.y;
    mem.progressT = mem.t;
    mem.stallT = 0;
  }
  const wheelAct = Math.abs(mem.wheelL) + Math.abs(mem.wheelR);
  if((mem.lastWant||0) > 0.16 && wheelAct < 0.06){
    mem.stallT += mem.dt;
  }else{
    mem.stallT = Math.max(0, mem.stallT - mem.dt*1.2);
  }

  let stuck = false;
  if(((mem.lastWant||0) > 0.12 || wheelAct > 0.18) && mem.t - mem.progressT > 6.3) stuck = true;
  if(mem.stallT > 2.5) stuck = true;
  if(!stuck) return false;

  if(mem.t - mem.lastRecoverT < 12) mem.recoverCount = (mem.recoverCount||0) + 1;
  else mem.recoverCount = 1;
  mem.lastRecoverT = mem.t;

  if(mem.recoverCount >= 3 && mem.mode !== 'return'){
    cancelCurrent(obs,mem);
    startRecovery(obs,mem,false);
  }else{
    startRecovery(obs,mem,false);
  }
  return true;
}

function dispatchMode(obs,mem){
  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);
  if(mem.mode === 'drill') return doDrill(obs,mem);
  if(mem.mode === 'recover') return doRecovery(obs,mem);
  return brakeCmd(obs,mem);
}

function handleDocked(obs,mem){
  const carried = fin(obs.carried,0);
  const batt = fin(obs.battery,1);
  const timeLeft = fin(obs.timeLeft, mem.seconds - mem.t);

  if(carried > 0){
    mem.mode = 'dockedWait';
    mem.target = null;
    mem.search = null;
    mem.approach = null;
    mem.drill = null;
    mem.path = null;
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  if(mem.mode === 'dockedWait') mem.mode = 'charge';
  if(mem.mode !== 'charge'){
    mem.mode = 'charge';
    mem.chargeStart = mem.t;
    mem.chargeLastBatt = batt;
    mem.chargeNoGain = 0;
  }

  if(batt > mem.chargeLastBatt + 0.0002) mem.chargeNoGain = 0;
  else mem.chargeNoGain += mem.dt;
  mem.chargeLastBatt = batt;

  let target = 0.55;
  if(timeLeft > 700) target = 0.90;
  else if(timeLeft > 400) target = 0.78;
  else if(timeLeft > 180) target = 0.65;
  else target = 0.45;
  if(mem.t - mem.chargeStart > 28) target = Math.min(target,0.30);
  if(timeLeft < 30) target = Math.min(target,0.24);

  if(batt < target && (mem.t - mem.chargeStart) < 30 && mem.chargeNoGain < 10 && timeLeft > 15){
    mem.wantV = 0;
    mem.lastWant = 0;
    return brakeCmd(obs,mem);
  }

  mem.mode = 'idle';
  mem.chargeStart = -1;
  mem.target = null;
  mem.search = null;
  mem.approach = null;
  mem.drill = null;
  mem.path = null;

  if(timeLeft < 10) return brakeCmd(obs,mem);

  if(chooseTarget(obs,mem)){
    mem.leaveBaseT = mem.t;
    return dispatchMode(obs,mem);
  }

  if(timeLeft > 25){
    startExplore(obs,mem);
    mem.leaveBaseT = mem.t;
    return doTravel(obs,mem);
  }

  return brakeCmd(obs,mem);
}

function act(obs,mem){
  if(!mem.init){
    initMission(obs,mem);
    return {left:0,right:0,drill:false};
  }

  updateCore(obs,mem);

  if(mem.mode === 'drill') return doDrill(obs,mem);

  if(mem.mode === 'recover'){
    if(mem.t < mem.recoverUntil) return doRecovery(obs,mem);
    mem.mode = mem.preRecoverMode || 'idle';
    resetProgress(mem);
  }

  if(obs.docked){
    const carried = fin(obs.carried,0);
    const leaving = mem.leaveBaseT > -900 && (mem.t - mem.leaveBaseT) < 8.0 &&
                    mem.mode !== 'charge' && mem.mode !== 'idle' && carried === 0;
    if(!leaving) return handleDocked(obs,mem);
  }

  if(obs.bumped){
    const ang = mem.head;
    if(mem.grid){
      const gx = Math.floor((mem.pos.x + Math.cos(ang)*0.9)/mem.cell);
      const gy = Math.floor((mem.pos.y + Math.sin(ang)*0.9)/mem.cell);
      if(gx>=0 && gy>=0 && gx<mem.gn && gy<mem.gn) mem.grid[gy*mem.gn+gx] = 2;
    }
    startRecovery(obs,mem,true);
    return doRecovery(obs,mem);
  }

  if(checkStuck(obs,mem)) return doRecovery(obs,mem);

  if(mem.mode !== 'return' && mem.mode !== 'drill'){
    if(needReturn(obs,mem)) startReturn(obs,mem);
  }

  if(mem.mode !== 'return' && mem.mode !== 'drill' && mem.visible &&
     (!mem.visible.ignoreUntil || mem.visible.ignoreUntil <= mem.t)){
    const v = mem.visible;
    let should = true;
    if(mem.mode === 'approach' && mem.approach && mem.approach.id !== v.id){
      if(mem.t - mem.approach.startT < 3.0 && mem.approach.value >= v.value*0.80) should = false;
    }
    if(should) startApproach(obs,mem,v);
  }

  if(mem.mode === 'return') return doReturn(obs,mem);
  if(mem.mode === 'approach') return doApproach(obs,mem);
  if(mem.mode === 'search') return doSearch(obs,mem);
  if(mem.mode === 'travel') return doTravel(obs,mem);

  if(mem.mode === 'idle' || !mem.mode){
    if(fin(obs.carried,0) >= mem.cap){
      startReturn(obs,mem);
      return doReturn(obs,mem);
    }
    if(chooseTarget(obs,mem)) return dispatchMode(obs,mem);
    if(fin(obs.carried,0) > 0){
      startReturn(obs,mem);
      return doReturn(obs,mem);
    }
    if(fin(obs.timeLeft,0) > 24){
      startExplore(obs,mem);
      return doTravel(obs,mem);
    }
    return brakeCmd(obs,mem);
  }

  return brakeCmd(obs,mem);
}

const ANG=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}

function init(obs,mem){
  const m=obs.mission||{};
  const b=m.base||{x:200,y:200};
  mem.base={x:b.x,y:b.y};
  mem.cap=m.capacity||5;
  mem.sites=[];
  const hints=m.hints||[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i];
    mem.sites.push({x:h.x,y:h.y,est:(typeof h.estimate==='number')?h.estimate:1,state:'todo',tries:0,ring:null,ringI:0,ringT:0});
  }
  mem.hoff=0; mem.hoffSet=false; mem.anchor=null;
  mem.sampled=[]; mem.explore=null;
  mem.target=null; mem.mode='nav';
  mem.drillT0=0; mem.drillIdx=-1;
  mem.rec=null; mem.stkT=-1; mem.stkX=0; mem.stkY=0;
  mem.cmd=0; mem.ierr=0; mem.chargeT=-1; mem.waitT=-1; mem.tgtKey=''; mem.tgtT0=0;
}

function updHeading(obs,mem){
  const x=obs.x,y=obs.y;
  if(!mem.anchor){mem.anchor={x:x,y:y};return;}
  const d=hyp(mem.anchor.x,mem.anchor.y,x,y);
  if(d>=5){
    const wl=obs.wheelLeft||0, wr=obs.wheelRight||0;
    const fwd=wl+wr;
    if(Math.abs(wl-wr)<0.25 && Math.abs(fwd)>1.0){
      let course=brg(mem.anchor.x,mem.anchor.y,x,y);
      if(fwd<0) course+=180;
      const diff=wrap(course-obs.heading);
      if(!mem.hoffSet){mem.hoff=diff;mem.hoffSet=true;}
      else mem.hoff=wrap(mem.hoff+0.15*wrap(diff-mem.hoff));
    }
    mem.anchor={x:x,y:y};
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const ang=rad(H+s.bearing);
  const sx=P.x+s.distance*Math.cos(ang), sy=P.y+s.distance*Math.sin(ang);
  for(const q of mem.sampled){ if(hyp(q.x,q.y,sx,sy)<4) return -1; }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const st=mem.sites[i];
    const d=hyp(st.x,st.y,sx,sy);
    if(st.state==='done' && d<12) return -1;
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0 && bd<12){
    const st=mem.sites[best];
    st.x=sx; st.y=sy;
    if(typeof s.value==='number') st.est=s.value;
    st.state='todo';
    return best;
  }
  mem.sites.push({x:sx,y:sy,est:(typeof s.value==='number')?s.value:1,state:'todo',tries:0,ring:null,ringI:0,ringT:0});
  return mem.sites.length-1;
}

function startRec(obs,mem,t,dur){
  const r=obs.rays||[];
  const R=[];
  for(let i=0;i<9;i++){const v=r[i]; R.push(typeof v==='number'&&isFinite(v)?v:15);}
  const lf=(R[5]+R[6]+R[7]+R[8])/4, rf=(R[0]+R[1]+R[2]+R[3])/4;
  const s=(lf>rf)?1:((rf>lf)?-1:(Math.random()<0.5?1:-1));
  mem.rec={until:t+dur,s:s};
  mem.ierr=0;
}

function doDrill(obs,mem,out,wl,wr,t){
  out.drill=true;
  const moving=Math.max(Math.abs(wl),Math.abs(wr))>0.12;
  if(moving){const s=(wl+wr)>0?-1:1; out.left=0.15*s; out.right=0.15*s;}
  else {out.left=0; out.right=0;}
  const dr=obs.drilling||0;
  const idx=mem.drillIdx;
  if(dr>=6.3 || t-mem.drillT0>25){
    const ok=dr>=6.3;
    if(idx>=0 && idx<mem.sites.length){
      const s=mem.sites[idx];
      if(ok){s.state='done'; mem.sampled.push({x:s.x,y:s.y});}
      else {s.tries++; if(s.tries>=2) s.state='bad'; else s.state='todo';}
    }
    mem.mode='nav'; out.drill=false; out.left=0; out.right=0; mem.target=null;
  }
  return out;
}

function ringPts(cx,cy,r,P){
  const pts=[];
  for(let k=0;k<8;k++){
    const a=k*Math.PI/4;
    pts.push({x:clamp(cx+r*Math.cos(a),4,396),y:clamp(cy+r*Math.sin(a),4,396)});
  }
  let bi=0,bd=1e9;
  for(let i=0;i<pts.length;i++){const d=hyp(P.x,P.y,pts[i].x,pts[i].y); if(d<bd){bd=d;bi=i;}}
  return pts.slice(bi).concat(pts.slice(0,bi));
}

function pickExplore(mem,P){
  if(!mem.explore){
    mem.explore=[];
    for(let gx=40;gx<=360;gx+=40) for(let gy=40;gy<=360;gy+=40) mem.explore.push({x:gx,y:gy,done:false});
  }
  let best=null,bd=1e9;
  for(const g of mem.explore){
    if(g.done) continue;
    const d=hyp(P.x,P.y,g.x,g.y);
    if(d<bd){bd=d;best=g;}
  }
  return best;
}

function chooseTarget(obs,mem,P,dB,carried,tl){
  const B=mem.base;
  const batLow=obs.battery<0.12+dB*0.0015;
  const needRet=carried>0 && (carried>=mem.cap || tl<dB/1.2+40 || batLow || dB<12);
  if(needRet) return {type:'base'};
  let best=-1,bs=-1,cur=-1,cs=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    const cost=dp/1.5+ds/1.5+10;
    if(cost>tl-20) continue;
    const sc=Math.max(s.est,0.1)/cost;
    if(mem.target && mem.target.type==='site' && mem.target.idx===i){cur=i;cs=sc;}
    if(sc>bs){bs=sc;best=i;}
  }
  if(best>=0){
    if(cur>=0 && bs<cs*1.3) return {type:'site',idx:cur};
    return {type:'site',idx:best};
  }
  if(carried>0) return {type:'base'};
  return {type:'explore'};
}

function drive(obs,mem,H,desired,vmax,out){
  const r=obs.rays||[];
  const R=[];
  for(let i=0;i<9;i++){const v=r[i]; R.push(typeof v==='number'&&isFinite(v)?v:15);}
  const lf=(R[5]+R[6]+R[7]+R[8])/4, rf=(R[0]+R[1]+R[2]+R[3])/4;
  let steer=0, minF=99;
  for(let i=0;i<9;i++){
    const d=R[i];
    if(!(d<4.5)) continue;
    const w=(4.5-d)/4.5;
    if(ANG[i]<0) steer+=w;
    else if(ANG[i]>0) steer-=w;
    else steer+=(lf>rf?1:-1)*w;
    if(Math.abs(ANG[i])<=20) minF=Math.min(minF,d);
  }
  const target=desired+steer*45;
  const e=wrap(target-H);
  const er=rad(e);
  mem.ierr=clamp(mem.ierr*0.98+er*0.1,-1,1);
  const w=clamp(2.2*er+0.5*mem.ierr,-2,2);
  let v=vmax*Math.max(0,Math.cos(er));
  if(Math.abs(e)>75) v=0;
  if(minF<2.0) v=Math.min(v,0.5);
  if(minF<1.0) v=0;
  const vL=v-w*0.3, vR=v+w*0.3;
  out.left=clamp(vL/3,-1,1);
  out.right=clamp(vR/3,-1,1);
  return out;
}

function core(obs,mem){
  if(!mem.init){init(obs,mem);mem.init=true;}
  const out={left:0,right:0,drill:false};
  const t=obs.t;
  const P={x:obs.x,y:obs.y};
  updHeading(obs,mem);
  const H=obs.heading+mem.hoff;
  const wl=obs.wheelLeft||0, wr=obs.wheelRight||0;
  const carried=(typeof obs.carried==='number')?obs.carried:((obs.carried&&obs.carried.length)||0);
  const tl=obs.timeLeft;
  const B=mem.base;
  const dB=hyp(P.x,P.y,B.x,B.y);
  if(carried===0) mem.waitT=-1;

  if(mem.mode!=='drill' && obs.bumped) startRec(obs,mem,t,1.5);

  let seenIdx=-1;
  if(obs.site && mem.mode!=='drill') seenIdx=registerSite(obs,mem,H,P);
  if(mem.mode==='drill') return doDrill(obs,mem,out,wl,wr,t);

  // opportunistic sampling of any site under us
  if(obs.site && obs.site.distance<=1.5 && carried<mem.cap && seenIdx>=0 && mem.sites[seenIdx].state==='todo'){
    mem.mode='drill'; mem.drillT0=t; mem.drillIdx=seenIdx;
    return doDrill(obs,mem,out,wl,wr,t);
  }

  // stuck detection
  if(mem.stkT<0 || t-mem.stkT>=3){
    if(mem.stkT>=0 && hyp(mem.stkX,mem.stkY,P.x,P.y)<0.25 && mem.cmd>0.1 && !obs.docked && !mem.rec){
      startRec(obs,mem,t,2.0);
    }
    mem.stkT=t; mem.stkX=P.x; mem.stkY=P.y;
  }

  if(mem.rec){
    if(t<mem.rec.until){
      out.left=clamp(-0.5+0.3*mem.rec.s,-1,1);
      out.right=clamp(-0.5-0.3*mem.rec.s,-1,1);
      return out;
    }
    mem.rec=null;
  }

  // charging hold at base
  if(dB<2.5 && carried===0 && obs.battery<0.4 && tl>300){
    if(mem.chargeT<0) mem.chargeT=t;
    if(t-mem.chargeT<30) return out;
  } else {
    mem.chargeT=-1;
  }

  const tgt=chooseTarget(obs,mem,P,dB,carried,tl);
  mem.target=tgt;
  const key=tgt.type+(tgt.idx===undefined?'':String(tgt.idx));
  if(key!==mem.tgtKey){mem.tgtKey=key; mem.tgtT0=t;}
  if(tgt.type==='site' && t-mem.tgtT0>150){
    const s=mem.sites[tgt.idx];
    s.tries++; s.state=s.tries>=2?'bad':'todo'; s.ring=null;
    mem.tgtT0=t; mem.tgtKey='';
    mem.target=null;
    return out;
  }

  if(tgt.type==='base'){
    const near=dB<2.5 || (obs.beacon && obs.beacon.distance<2.5);
    if(near){
      if(carried>0){
        if(mem.waitT<0) mem.waitT=t;
        if(t-mem.waitT<6) return out;
        return drive(obs,mem,H,brg(P.x,P.y,B.x,B.y),0.25,out);
      }
      return out;
    }
    let desired=brg(P.x,P.y,B.x,B.y);
    if(obs.beacon && typeof obs.beacon.bearing==='number' && obs.beacon.distance<20){
      desired=obs.heading+obs.beacon.bearing;
    }
    return drive(obs,mem,H,desired,dB<6?0.8:1.5,out);
  }

  if(tgt.type==='site'){
    const idx=tgt.idx;
    const S=mem.sites[idx];
    const dS=hyp(P.x,P.y,S.x,S.y);
    if(obs.site){
      S.ring=null;
      const d=obs.site.distance, b=obs.site.bearing;
      const vmax=d<3?0.4:(d<6?0.8:1.2);
      return drive(obs,mem,H,H+b,vmax,out);
    }
    if(!S.ring && dS<3.0){
      S.ring=ringPts(S.x,S.y,9,P); S.ringI=0; S.ringT=t;
    }
    if(S.ring){
      if(S.ringI>=S.ring.length){
        S.state='bad'; S.ring=null; mem.target=null;
        return out;
      }
      const wp=S.ring[S.ringI];
      if(hyp(P.x,P.y,wp.x,wp.y)<2.0 || t-S.ringT>25){
        S.ringI++; S.ringT=t;
        return out;
      }
      return drive(obs,mem,H,brg(P.x,P.y,wp.x,wp.y),0.9,out);
    }
    return drive(obs,mem,H,brg(P.x,P.y,S.x,S.y),dS<6?0.7:1.4,out);
  }

  // explore
  const g=pickExplore(mem,P);
  if(!g){
    return drive(obs,mem,H,brg(P.x,P.y,200,200),0.8,out);
  }
  if(hyp(P.x,P.y,g.x,g.y)<6){g.done=true; return out;}
  return drive(obs,mem,H,brg(P.x,P.y,g.x,g.y),1.4,out);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0,right:0,drill:false};
  }
  const L=(typeof o.left==='number'&&isFinite(o.left))?clamp(o.left,-1,1):0;
  const R=(typeof o.right==='number'&&isFinite(o.right))?clamp(o.right,-1,1):0;
  mem.cmd=Math.max(Math.abs(L),Math.abs(R));
  return {left:L,right:R,drill:!!o.drill};
}

function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function newSite(x,y,est,src){return {x:x,y:y,est:est,state:'todo',tries:0,src:src,seen:false};}

function init(obs,mem){
  const m=obs.mission||{};
  const b=m.base||{x:num(obs.x,200),y:num(obs.y,200)};
  mem.base={x:num(b.x,200),y:num(b.y,200)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=m.hints||[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i];
    mem.sites.push(newSite(num(h.x,0),num(h.y,0),num(h.estimate,1),'hint'));
  }
  mem.grid=[];
  for(let gx=25;gx<=375;gx+=50) for(let gy=25;gy<=375;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.hoff=0; mem.hoffSet=false; mem.anc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1;
  mem.lastGx=obs.x; mem.lastGy=obs.y; mem.still=0;
  mem.drX=num(obs.x,0); mem.drY=num(obs.y,0);
  mem.drAt={x:mem.drX,y:mem.drY};
  mem.px=mem.drX; mem.py=mem.drY; mem.frozen=false;
  mem.mode='nav';
  mem.goal='none'; mem.goalIdx=-1; mem.goalT0=0; mem.goalStuck=0;
  mem.search=null; mem.waitT=-1; mem.apprIdx=-1; mem.apprT0=0;
  mem.drillIdx=-1; mem.drillT0=0;
  mem.rec=null; mem.stuckT0=-1;
  mem.winT=num(obs.t,0); mem.winX=mem.px; mem.winY=mem.py;
  mem.explG=null; mem.explT0=0;
  mem.lastL=0; mem.lastR=0;
  mem.noDel=0; mem.sampN=0;
}

function startRec(mem,t,dur,l,r){mem.rec={until:t+dur,l:l,r:r};}

function hold(out,wl,wr){
  const avg=(wl+wr)/2;
  const c=clamp(-0.8*avg,-0.2,0.2);
  out.left=c; out.right=c;
  return out;
}

// position: GPS normally; dead reckoning from wheels+heading when GPS is frozen
function updatePos(obs,mem,H){
  const dt=clamp(num(obs.t,0)-mem.lastT,0,0.5);
  mem.lastT=num(obs.t,0);
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const moved=(obs.x!==mem.lastGx)||(obs.y!==mem.lastGy);
  if(moved){
    mem.lastGx=obs.x; mem.lastGy=obs.y; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else {
    mem.still+=dt;
  }
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=num(obs.x,mem.px); mem.py=num(obs.y,mem.py);
  }
}

// compass bias estimate from GPS course over straight runs
function updHeading(obs,mem){
  if(mem.frozen) return;
  if(!mem.anc){mem.anc={x:obs.x,y:obs.y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.35 || Math.abs(fwd)<0.4){mem.anc={x:obs.x,y:obs.y}; return;}
  const d=hyp(mem.anc.x,mem.anc.y,obs.x,obs.y);
  if(d<8) return;
  let course=brg(mem.anc.x,mem.anc.y,obs.x,obs.y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.anc={x:obs.x,y:obs.y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSeen(obs,mem,H,P){
  const s=obs.site;
  if(!s) return -1;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=(typeof s.value==='number'&&isFinite(s.value))?s.value:null;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<6) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?12:5;
    if(bd<lim){
      q.x=sx; q.y=sy; q.seen=true;
      if(val!==null) q.est=val;
      if(q.state==='bad' && q.tries<3) q.state='todo';
      return best;
    }
  }
  mem.sites.push(newSite(sx,sy,val!==null?val:1,'seen'));
  mem.sites[mem.sites.length-1].seen=true;
  return mem.sites.length-1;
}

function pickTarget(mem,P,tl){
  const B=mem.base;
  let best=-1,bs=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), db=hyp(s.x,s.y,B.x,B.y);
    if((dp+db)/0.6+40>tl) continue;
    const cost=dp+0.5*db+15;
    let sc=Math.max(s.est,0.2)/cost;
    if(s.seen) sc*=1.4;
    if(i===mem.goalIdx) sc*=1.2;
    if(sc>bs){bs=sc;best=i;}
  }
  return best;
}

// obstacle-aware steering toward a global desired heading
function steer(obs,mem,H,desired,vmax,out){
  const r=obs.rays||[];
  const R=[];
  for(let i=0;i<9;i++) R.push(Math.min(15,num(r[i],15)));
  let bias=0;
  const lf=(R[5]+R[6]+R[7]+R[8])/4, rf=(R[0]+R[1]+R[2]+R[3])/4;
  for(let i=0;i<9;i++){
    const d=R[i];
    if(d>=5) continue;
    const w=(5-d)/5;
    if(i<4) bias+=w;
    else if(i>4) bias-=w;
    else bias+=(lf>rf?w:-w);
  }
  const des=desired+clamp(bias,-1.5,1.5)*45;
  const e=wrap(des-H);
  const er=rad(e);
  const front=Math.min(R[3],R[4],R[5]);
  let v=vmax*Math.max(0,Math.cos(er));
  if(Math.abs(e)>80) v=0;
  if(front<8) v=Math.min(v,0.3);
  if(front<4) v=Math.min(v,0.2);
  if(front<1.5) v=0;
  const tq=clamp(0.2*er,-0.4,0.4);
  out.left=clamp(v-tq,-1,1);
  out.right=clamp(v+tq,-1,1);
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(out,wl,wr);
  const st=mem.sites[mem.drillIdx];
  const dr=num(obs.drilling,0);
  if(dr>=6.3){
    if(st) st.state='done';
    mem.sampN++;
    mem.mode='nav'; mem.winT=t;
    out.drill=false; out.left=0; out.right=0;
    return out;
  }
  if(t-mem.drillT0>25){
    if(st){st.tries++; st.state=st.tries>=2?'bad':'todo';}
    mem.mode='nav'; mem.winT=t;
    out.drill=false;
  }
  return out;
}

function driveBase(obs,mem,P,H,carried,out,t,dB,wl,wr){
  const B=mem.base;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  if(dB<2.2 || bcd<2.5){
    if(carried>0){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT<12) return hold(out,wl,wr);
      mem.waitT=-1; mem.noDel++;
      startRec(mem,t,2.5,-0.3,-0.3);
      out.left=-0.3; out.right=-0.3;
      return out;
    }
    return hold(out,wl,wr);
  }
  let desired=brg(P.x,P.y,B.x,B.y);
  if(bc && bcd<20 && typeof bc.bearing==='number') desired=H+bc.bearing;
  return steer(obs,mem,H,desired,dB<8?0.25:0.4,out);
}

function startSearch(mem,S,P,t){
  const a0=Math.atan2(P.y-S.y,P.x-S.x);
  const pts=[];
  for(let k=0;k<10;k++){
    const a=a0+k*Math.PI/5;
    pts.push({x:clamp(S.x+8*Math.cos(a),3,397),y:clamp(S.y+8*Math.sin(a),3,397)});
  }
  mem.search={pts:pts,i:0,t0:t};
}

function searchTick(obs,mem,P,H,out,t,S,wl,wr){
  const sr=mem.search;
  while(sr.i<sr.pts.length && hyp(P.x,P.y,sr.pts[sr.i].x,sr.pts[sr.i].y)<2.0){sr.i++; sr.t0=t;}
  if(sr.i>=sr.pts.length){
    S.state='bad'; mem.search=null; mem.goal='none';
    return hold(out,wl,wr);
  }
  if(t-sr.t0>30){sr.i++; sr.t0=t; return hold(out,wl,wr);}
  const w=sr.pts[sr.i];
  return steer(obs,mem,H,brg(P.x,P.y,w.x,w.y),0.3,out);
}

function driveSite(obs,mem,P,H,out,t,idx,wl,wr){
  const S=mem.sites[idx];
  if(mem.goalStuck>=4){
    S.state='bad'; mem.search=null; mem.goal='none';
    return hold(out,wl,wr);
  }
  if(mem.search) return searchTick(obs,mem,P,H,out,t,S,wl,wr);
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<6){
    startSearch(mem,S,P,t);
    return searchTick(obs,mem,P,H,out,t,S,wl,wr);
  }
  return steer(obs,mem,H,brg(P.x,P.y,S.x,S.y),dS<10?0.25:0.4,out);
}

function driveExplore(obs,mem,P,H,out,t){
  let best=null,bd=1e9;
  for(let i=0;i<mem.grid.length;i++){
    const g=mem.grid[i];
    if(g.done) continue;
    const d=hyp(P.x,P.y,g.x,g.y);
    if(d<bd){bd=d;best=g;}
  }
  if(!best) return out;
  if(bd<8){best.done=true; return out;}
  if(mem.explG!==best){mem.explG=best; mem.explT0=t;}
  if(t-mem.explT0>100){best.done=true; return out;}
  return steer(obs,mem,H,brg(P.x,P.y,best.x,best.y),0.4,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const B=mem.base;
  const bat=num(obs.battery,1);
  updatePos(obs,mem,wrap(num(obs.heading,0)+mem.hoff));
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  const s=Math.random()<0.5?1:-1;
  if(obs.bumped){
    mem.goalStuck++;
    startRec(mem,t,1.2,-0.4+0.25*s,-0.4-0.25*s);
    out.left=mem.rec.l; out.right=mem.rec.r;
    return out;
  }
  // wheels stalled while commanded
  const cm=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));
  if(cm>0.25 && Math.abs(wl)<0.1 && Math.abs(wr)<0.1){
    if(mem.stuckT0<0) mem.stuckT0=t;
    else if(t-mem.stuckT0>2.0){
      mem.stuckT0=-1; mem.goalStuck++;
      startRec(mem,t,1.5,-0.4+0.25*s,-0.4-0.25*s);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
  } else mem.stuckT0=-1;
  // no progress over 15 s away from base
  if(t-mem.winT>=15){
    if(hyp(mem.winX,mem.winY,P.x,P.y)<1.5 && dB>3){
      mem.goalStuck++;
      startRec(mem,t,2.0,-0.4-0.3*s,-0.4+0.3*s);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
    mem.winX=P.x; mem.winY=P.y; mem.winT=t;
  }

  // visible site: approach and sample
  const seen=registerSeen(obs,mem,H,P);
  if(obs.site && seen>=0 && carried<mem.cap && mem.sites[seen].state==='todo'){
    const st=mem.sites[seen];
    const d=num(obs.site.distance,99);
    if(d<=1.4){
      if(Math.abs(wl)<0.12 && Math.abs(wr)<0.12){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t; mem.apprIdx=-1;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(out,wl,wr);
    }
    if(mem.apprIdx!==seen){mem.apprIdx=seen; mem.apprT0=t;}
    if(t-mem.apprT0<=60){
      return steer(obs,mem,H,H+num(obs.site.bearing,0),d<3?0.25:0.4,out);
    }
    st.tries++; st.state=st.tries>=2?'bad':'todo'; mem.apprIdx=-1;
  }

  // choose goal
  let bestIdx=-1;
  if(carried<mem.cap) bestIdx=pickTarget(mem,P,tl);
  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || bestIdx<0 || tl<dB/0.6+60 || bat<0.15+dB*0.0015) wantBase=true;
    else {
      const sd=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,sd.x,sd.y);
      if(dp>45 && dB<dp) wantBase=true;
    }
  }
  const goal=wantBase?'base':(bestIdx>=0?'site':'explore');
  if(goal!==mem.goal || (goal==='site' && bestIdx!==mem.goalIdx)){
    mem.goal=goal;
    mem.goalIdx=(goal==='site')?bestIdx:-1;
    mem.goalT0=t; mem.goalStuck=0; mem.search=null; mem.waitT=-1;
  }
  if(goal==='site'){
    if(t-mem.goalT0>180){
      mem.sites[bestIdx].state='bad'; mem.goal='none';
      return hold(out,wl,wr);
    }
    return driveSite(obs,mem,P,H,out,t,bestIdx,wl,wr);
  }
  if(goal==='base') return driveBase(obs,mem,P,H,carried,out,t,dB,wl,wr);
  return driveExplore(obs,mem,P,H,out,t);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0,right:0,drill:false};
  }
  const L=clamp(num(o.left,0),-1,1), R=clamp(num(o.right,0),-1,1);
  mem.lastL=L; mem.lastR=R;
  return {left:L,right:R,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
const CMDG=1/1.75;
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};}
function getRays(obs){
  const r=obs.rays||[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}
function hold(out,wl,wr){
  const avg=(wl+wr)/2;
  const c=clamp(-0.6*avg,-0.15,0.15);
  out.left=c; out.right=c; out.hold=true;
  return out;
}
function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=m.hints||[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.anc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.stallT0=-1;
  mem.wasHold=false; mem.progT=0; mem.progX=x0; mem.progY=y0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.anc){mem.anc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.anc={x:x,y:y}; return;}
  const d=hyp(mem.anc.x,mem.anc.y,x,y);
  if(d<10) return;
  let course=brg(mem.anc.x,mem.anc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.anc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer using relative angles (positive = left); relDes = desired relative heading
function steerRel(obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.2?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  const f=Math.min(R[3],R[4],R[5]);
  let vg=Math.min(vcr,0.6*(f-1.2));
  if(bestCl<2.2) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const vc=vg*CMDG;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  hold(out,wl,wr);
  out.drill=true;
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.progX=mem.px; mem.progY=mem.py;
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>25){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[6,14,22];
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    const a0=Math.atan2(P.y-cy,P.x-cx);
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

// returns out while searching, null when the search is exhausted
function spiralTick(obs,mem,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>150) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>25){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(obs,mem,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(out,wl,wr);
  }
  return steerRel(obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.1,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.1,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>8){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    }
    return hold(out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped){
    mem.bumps++;
    startRec(mem,t,1.2,R);
    out.left=mem.rec.l; out.right=mem.rec.r;
    return out;
  }
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));
  if(cmdMag>0.25 && Math.abs(wl)<0.08 && Math.abs(wr)<0.08 && !obs.docked){
    if(mem.stallT0<0) mem.stallT0=t;
    else if(t-mem.stallT0>2.5){
      mem.stallT0=-1;
      startRec(mem,t,1.5,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
  } else mem.stallT0=-1;

  if(t-mem.progT>=20){
    const moved=hyp(mem.progX,mem.progY,P.x,P.y);
    if(!mem.wasHold && moved<3 && !obs.docked && mem.goal && mem.goal.type!=='base'){
      if(mem.goal.type==='site'){
        const s=mem.sites[mem.goal.idx];
        if(s){s.tries++; if(s.tries>=2) s.state='bad';}
      }
      mem.goal=null; mem.progT=t; mem.progX=P.x; mem.progY=P.y; mem.sp=null;
      startRec(mem,t,1.5,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
  }

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const st=mem.sites[seen];
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.3){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.1 && Math.abs(wr)<0.1){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=d<3?0.35:(d<6?0.7:1.0);
      return steerRel(obs,R,br,vcr,out);
    }
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: unknown site close by, create a record and search it
  if(!obs.site && sci>=1.0 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(hyp(q.x,q.y,P.x,P.y)<25){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo'){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+50 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let ng;
  if(wantBase) ng={type:'base'};
  else if(bestIdx>=0) ng={type:'site',idx:bestIdx};
  else ng={type:'explore'};

  let g=ng;
  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
    if(g.type!=='explore') mem.exG=null;
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0,right:0,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};}
function getRays(obs){
  const r=Array.isArray(obs.rays)?obs.rays:[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}

// integrating hold: drives wheel speed to zero, counters slopes
function hold(mem,out,wl,wr){
  const v=(wl+wr)/2;
  mem.hc=clamp(mem.hc-0.03*v,-0.5,0.5);
  const c=clamp(mem.hc-0.2*v,-0.5,0.5);
  out.left=c; out.right=c; out.hold=true;
  return out;
}

function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=m.hints||[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.anc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.drLast=0; mem.drMove=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.stallT0=-1;
  mem.progT=0; mem.progX=x0; mem.progY=y0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
  mem.hc=0; mem.kG=2.2;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.anc){mem.anc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.anc={x:x,y:y}; return;}
  const d=hyp(mem.anc.x,mem.anc.y,x,y);
  if(d<10) return;
  let course=brg(mem.anc.x,mem.anc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.anc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer with relative angles (positive = left)
function steerRel(mem,obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.5?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  const f=Math.min(R[3],R[4],R[5]);
  let vg=Math.min(vcr,0.5*(f-1.5));
  if(bestCl<2.5) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const wf=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  let vc=vg/mem.kG;
  if(vg<=0 && wf>0.5 && f<3.5) vc=-0.25;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(mem,out,wl,wr);
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>mem.drLast+0.01){mem.drLast=dr; mem.drMove=t;}
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.progX=mem.px; mem.progY=mem.py;
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>30 || t-mem.drMove>5){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[6,14,22];
  const a0=Math.atan2(P.y-cy,P.x-cx);
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

function spiralTick(mem,obs,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>150) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>25){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(mem,out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(mem,out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(mem,obs,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.0,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.1,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0 && !obs.docked){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>4){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    } else mem.waitT=-1;
    return hold(mem,out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(mem,obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped){
    mem.bumps++;
    startRec(mem,t,1.2,R);
    out.left=mem.rec.l; out.right=mem.rec.r;
    return out;
  }
  // wheels stalled while commanded
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));
  if(cmdMag>0.25 && Math.abs(wl)<0.08 && Math.abs(wr)<0.08 && !obs.docked){
    if(mem.stallT0<0) mem.stallT0=t;
    else if(t-mem.stallT0>2.5){
      mem.stallT0=-1;
      startRec(mem,t,1.5,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
  } else mem.stallT0=-1;

  // no progress check
  if(t-mem.progT>=20){
    const moved=hyp(mem.progX,mem.progY,P.x,P.y);
    if(!mem.wasHold && moved<3 && !obs.docked && mem.goal && mem.goal.type!=='base'){
      if(mem.goal.type==='site'){
        const s=mem.sites[mem.goal.idx];
        if(s){s.tries++; if(s.tries>=2) s.state='bad';}
      }
      mem.goal=null; mem.progT=t; mem.progX=P.x; mem.progY=P.y; mem.sp=null;
      startRec(mem,t,1.5,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
  }

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const st=mem.sites[seen];
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.4){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.3 && Math.abs(wr)<0.3){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        mem.drLast=0; mem.drMove=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(mem,out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=clamp(0.3*d,0.12,0.9);
      return steerRel(mem,obs,R,br,vcr,out);
    }
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: signal close by but no visible site, search around here
  if(!obs.site && sci>=1.0 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(q.state!=='done' && hyp(q.x,q.y,P.x,P.y)<20){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo' && carried<mem.cap){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+50 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let ng;
  if(wantBase) ng={type:'base'};
  else if(bestIdx>=0) ng={type:'site',idx:bestIdx};
  else ng={type:'explore'};

  let g=ng;
  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
    if(g.type!=='explore') mem.exG=null;
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0,right:0,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  // learn wheel-speed per command gain while driving straight
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  if(mem.init && mem.lastL>0.25 && mem.lastR>0.25 && Math.abs(wl-wr)<0.3 && wl>0.3){
    const ratio=clamp(((wl+wr)/2)/((mem.lastL+mem.lastR)/2),1.2,3.5);
    mem.kG+=0.02*(ratio-mem.kG);
  }
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};}
function getRays(obs){
  const r=Array.isArray(obs.rays)?obs.rays:[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}

// integrating hold: drives wheel speed to zero, counters slopes
function hold(mem,out,wl,wr){
  const v=(wl+wr)/2;
  mem.hc=clamp(mem.hc-0.03*v,-0.5,0.5);
  const c=clamp(mem.hc-0.2*v,-0.5,0.5);
  out.left=c; out.right=c; out.hold=true;
  return out;
}

function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

// escape cycle for a wedged rover: forward-turn, pivot, reverse-turn
function startEscape(mem,t,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  const k=mem.escN%3;
  let l,r,dur;
  if(k===0){ l=0.45-0.2*s; r=0.45+0.2*s; dur=1.5; }
  else if(k===1){ l=-0.5*s; r=0.5*s; dur=1.2; }
  else { l=-0.4-0.2*s; r=-0.4+0.2*s; dur=1.5; }
  mem.rec={until:t+dur,l:l,r:r};
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=m.hints||[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.anc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.drLast=0; mem.drMove=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.stallT0=-1; mem.escN=0;
  mem.progT=0; mem.progX=x0; mem.progY=y0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
  mem.hc=0; mem.kG=2.2; mem.wasHold=false;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.anc){mem.anc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.anc={x:x,y:y}; return;}
  const d=hyp(mem.anc.x,mem.anc.y,x,y);
  if(d<10) return;
  let course=brg(mem.anc.x,mem.anc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.anc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer with relative angles (positive = left)
function steerRel(mem,obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.5?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  const f=Math.min(R[3],R[4],R[5]);
  let vg=Math.min(vcr,0.5*(f-1.5));
  if(bestCl<2.5) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const wf=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  let vc=vg/mem.kG;
  if(vg<=0 && wf>0.5 && f<3.5) vc=-0.25;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(mem,out,wl,wr);
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>mem.drLast+0.01){mem.drLast=dr; mem.drMove=t;}
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.progX=mem.px; mem.progY=mem.py;
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>30 || t-mem.drMove>5){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[7,15];
  const a0=Math.atan2(P.y-cy,P.x-cx);
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

function spiralTick(mem,obs,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>150) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>20){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(mem,out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(mem,out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(mem,obs,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.0,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.0,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0 && !obs.docked){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>4){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    } else mem.waitT=-1;
    return hold(mem,out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(mem,obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped){
    mem.bumps++;
    startRec(mem,t,1.2,R);
    out.left=mem.rec.l; out.right=mem.rec.r;
    return out;
  }
  // wedged: commanded but wheels not turning (held positions excluded)
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));
  if(cmdMag>0.25 && !mem.wasHold && Math.abs(wl)<0.05 && Math.abs(wr)<0.05 && !obs.docked){
    if(mem.stallT0<0) mem.stallT0=t;
    else if(t-mem.stallT0>1.5){
      mem.stallT0=-1; mem.escN++;
      startEscape(mem,t,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
  } else mem.stallT0=-1;

  // no progress check
  if(t-mem.progT>=20){
    const moved=hyp(mem.progX,mem.progY,P.x,P.y);
    if(!mem.wasHold && moved<3 && !obs.docked && mem.goal && mem.goal.type!=='base'){
      if(mem.goal.type==='site'){
        const s=mem.sites[mem.goal.idx];
        if(s){s.tries++; if(s.tries>=2) s.state='bad';}
      }
      mem.goal=null; mem.progT=t; mem.progX=P.x; mem.progY=P.y; mem.sp=null;
      startRec(mem,t,1.5,R);
      out.left=mem.rec.l; out.right=mem.rec.r;
      return out;
    }
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
  }

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const st=mem.sites[seen];
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.4){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.3 && Math.abs(wr)<0.3){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        mem.drLast=0; mem.drMove=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(mem,out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=clamp(0.3*d,0.12,0.9);
      return steerRel(mem,obs,R,br,vcr,out);
    }
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: signal close by but no visible site, search around here
  if(!obs.site && sci>=1.0 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(q.state!=='done' && hyp(q.x,q.y,P.x,P.y)<20){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo' && carried<mem.cap){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+50 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let ng;
  if(wantBase) ng={type:'base'};
  else if(bestIdx>=0) ng={type:'site',idx:bestIdx};
  else ng={type:'explore'};

  let g=ng;
  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.progT=t; mem.progX=P.x; mem.progY=P.y;
    if(g.type!=='explore') mem.exG=null;
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0,right:0,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  // learn wheel-speed per command gain while driving straight
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  if(mem.init && mem.lastL>0.25 && mem.lastR>0.25 && Math.abs(wl-wr)<0.3 && wl>0.3){
    const ratio=clamp(((wl+wr)/2)/((mem.lastL+mem.lastR)/2),1.2,3.5);
    mem.kG+=0.02*(ratio-mem.kG);
  }
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){
  return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};
}
function getRays(obs){
  const r=Array.isArray(obs.rays)?obs.rays:[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}

// integrating hold: drives wheel speed to zero, counters slopes
function hold(mem,out,wl,wr){
  const v=(wl+wr)/2;
  mem.hc=clamp(mem.hc-0.03*v,-0.5,0.5);
  const c=clamp(mem.hc-0.2*v,-0.5,0.5);
  out.left=c; out.right=c; out.hold=true;
  return out;
}

function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

// timed escape: reverse, pivot toward open side, forward turn
function startEscape(mem,t,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  let s=ls>rs?1:-1;
  if(mem.escN%2===1) s=-s;
  mem.escN++;
  mem.esc={t0:t,s:s};
  if(mem.goal && mem.goal.type==='site'){
    const S=mem.sites[mem.goal.idx];
    if(S){S.tries++; if(S.tries>=3) S.state='bad';}
  }
  mem.goal=null; mem.sp=null; mem.stT=-1;
  mem.anc={x:mem.px,y:mem.py,t:t};
  mem.gBest=1e9; mem.gBestT=t;
}
function escapeTick(mem,t,out){
  const e=mem.esc;
  if(!e) return null;
  const el=t-e.t0;
  const s=e.s;
  if(el<1.6){ out.left=-0.6; out.right=-0.6; }
  else if(el<2.5){ out.left=-0.5*s; out.right=0.5*s; }
  else if(el<4.0){ out.left=0.45-0.2*s; out.right=0.45+0.2*s; }
  else { mem.esc=null; return null; }
  out.hold=false;
  return out;
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=Array.isArray(m.hints)?m.hints:[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.hanc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.drLast=0; mem.drMove=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.wasHold=false;
  mem.anc={x:x0,y:y0,t:num(obs.t,0)}; mem.stT=-1;
  mem.esc=null; mem.escN=0;
  mem.gBest=1e9; mem.gBestT=0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
  mem.hc=0; mem.kG=2.2;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.hanc){mem.hanc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.hanc={x:x,y:y}; return;}
  const d=hyp(mem.hanc.x,mem.hanc.y,x,y);
  if(d<10) return;
  let course=brg(mem.hanc.x,mem.hanc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.hanc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer with relative angles (positive = left)
function steerRel(mem,obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.5?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  const f=Math.min(R[3],R[4],R[5]);
  let vg=Math.min(vcr,0.5*(f-1.5));
  if(bestCl<2.5) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const wf=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  let vc=vg/mem.kG;
  if(vg<=0 && wf>0.5 && f<3.5) vc=-0.25;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(mem,out,wl,wr);
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>mem.drLast+0.01){mem.drLast=dr; mem.drMove=t;}
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.anc={x:mem.px,y:mem.py,t:t};
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>30 || t-mem.drMove>5){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[6,14];
  const a0=Math.atan2(P.y-cy,P.x-cx);
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

function spiralTick(mem,obs,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>130) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>20){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(mem,out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(mem,out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(mem,obs,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.0,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.0,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0 && !obs.docked){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>4){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    } else mem.waitT=-1;
    return hold(mem,out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(mem,obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const docked=!!obs.docked;
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.esc){
    const r=escapeTick(mem,t,out);
    if(r) return r;
  }
  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped && !docked){
    mem.bumps++;
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }

  // stuck: commanded to move but no displacement, or wheels not turning
  const moving=!mem.wasHold && cmdMag>0.2 && !docked;
  if(!moving || hyp(mem.anc.x,mem.anc.y,P.x,P.y)>1.0){
    mem.anc={x:P.x,y:P.y,t:t};
  } else if(t-mem.anc.t>8){
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }
  if(moving && Math.abs(wl)<0.1 && Math.abs(wr)<0.1){
    if(mem.stT<0) mem.stT=t;
    else if(t-mem.stT>1.5){
      startEscape(mem,t,R);
      return escapeTick(mem,t,out);
    }
  } else mem.stT=-1;

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.4){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.3 && Math.abs(wr)<0.3){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        mem.drLast=0; mem.drMove=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(mem,out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=clamp(0.3*d,0.12,0.9);
      return steerRel(mem,obs,R,br,vcr,out);
    }
    const st=mem.sites[seen];
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: signal nearby but no visible site, search around here
  if(!obs.site && sci>=1.5 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(q.state!=='done' && hyp(q.x,q.y,P.x,P.y)<20){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo' && carried<mem.cap){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+60 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let g;
  if(wantBase) g={type:'base'};
  else if(bestIdx>=0) g={type:'site',idx:bestIdx};
  else g={type:'explore'};

  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.gBest=1e9; mem.gBestT=t;
    if(g.type!=='explore') mem.exG=null;
  }

  // goal progress watchdog
  if(mem.goal.type!=='explore' && !mem.sp && dB>=3){
    let gd=dB;
    if(mem.goal.type==='site'){
      const S=mem.sites[mem.goal.idx];
      gd=S?hyp(P.x,P.y,S.x,S.y):1e9;
    }
    if(gd<mem.gBest-3){mem.gBest=gd; mem.gBestT=t;}
    else if(t-mem.gBestT>60){
      if(mem.goal.type==='site'){
        const S=mem.sites[mem.goal.idx];
        if(S){S.tries++; if(S.tries>=2) S.state='bad';}
      }
      mem.goal=null; mem.sp=null; mem.gBest=1e9; mem.gBestT=t;
      return hold(mem,out,wl,wr);
    }
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0.3,right:-0.3,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  // learn wheel-speed per command gain while driving straight
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  if(mem.init && mem.lastL>0.25 && mem.lastR>0.25 && Math.abs(wl-wr)<0.3 && wl>0.3){
    const ratio=clamp(((wl+wr)/2)/((mem.lastL+mem.lastR)/2),1.2,3.5);
    mem.kG+=0.02*(ratio-mem.kG);
  }
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){
  return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};
}
function getRays(obs){
  const r=Array.isArray(obs.rays)?obs.rays:[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}

// integrating hold: drives wheel speed to zero, counters slopes
function hold(mem,out,wl,wr){
  const v=(wl+wr)/2;
  mem.hc=clamp(mem.hc-0.03*v,-0.5,0.5);
  const c=clamp(mem.hc-0.2*v,-0.5,0.5);
  out.left=c; out.right=c; out.hold=true;
  return out;
}

function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

// timed escape: reverse, pivot toward open side, forward turn
function startEscape(mem,t,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  let s=ls>rs?1:-1;
  if(mem.escN%2===1) s=-s;
  mem.escN++;
  mem.esc={t0:t,s:s};
  if(mem.goal && mem.goal.type==='site'){
    const S=mem.sites[mem.goal.idx];
    if(S){S.tries++; if(S.tries>=3) S.state='bad';}
  }
  mem.goal=null; mem.sp=null; mem.stT=-1;
  mem.anc={x:mem.px,y:mem.py,t:t};
  mem.gBest=1e9; mem.gBestT=t;
}
function escapeTick(mem,t,out){
  const e=mem.esc;
  if(!e) return null;
  const el=t-e.t0;
  const s=e.s;
  if(el<1.6){ out.left=-0.6; out.right=-0.6; }
  else if(el<2.5){ out.left=-0.5*s; out.right=0.5*s; }
  else if(el<4.0){ out.left=0.45-0.2*s; out.right=0.45+0.2*s; }
  else { mem.esc=null; return null; }
  out.hold=false;
  return out;
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=Array.isArray(m.hints)?m.hints:[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.hanc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.drLast=0; mem.drMove=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.wasHold=false;
  mem.anc={x:x0,y:y0,t:num(obs.t,0)}; mem.stT=-1;
  mem.esc=null; mem.escN=0;
  mem.gBest=1e9; mem.gBestT=0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
  mem.hc=0; mem.kG=2.2;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.hanc){mem.hanc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.hanc={x:x,y:y}; return;}
  const d=hyp(mem.hanc.x,mem.hanc.y,x,y);
  if(d<10) return;
  let course=brg(mem.hanc.x,mem.hanc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.hanc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer with relative angles (positive = left)
function steerRel(mem,obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.5?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  // forward cone clearance (-40..40 deg) limits speed so the rover can stop
  const f=Math.min(R[2],R[3],R[4],R[5],R[6]);
  let vg=Math.min(vcr,0.9,0.5*(f-1.2));
  if(bestCl<2.5) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const wf=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  let vc=vg/mem.kG;
  if(vg<=0 && wf>0.5 && f<3.0) vc=-0.25;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(mem,out,wl,wr);
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>mem.drLast+0.01){mem.drLast=dr; mem.drMove=t;}
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.anc={x:mem.px,y:mem.py,t:t};
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>30 || t-mem.drMove>5){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[6,14];
  const a0=Math.atan2(P.y-cy,P.x-cx);
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

function spiralTick(mem,obs,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>130) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>20){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(mem,out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(mem,out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(mem,obs,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.0,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.0,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0 && !obs.docked){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>4){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    } else mem.waitT=-1;
    return hold(mem,out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(mem,obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const docked=!!obs.docked;
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));

  // coverage: grid cells within sensor reach count as explored
  for(const q of mem.grid){
    if(!q.done && hyp(P.x,P.y,q.x,q.y)<12) q.done=true;
  }

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.esc){
    const r=escapeTick(mem,t,out);
    if(r) return r;
  }
  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped && !docked){
    mem.bumps++;
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }

  // stuck: commanded to move but no displacement, or wheels not turning
  const moving=!mem.wasHold && cmdMag>0.2 && !docked;
  if(!moving || hyp(mem.anc.x,mem.anc.y,P.x,P.y)>1.0){
    mem.anc={x:P.x,y:P.y,t:t};
  } else if(t-mem.anc.t>8){
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }
  if(moving && Math.abs(wl)<0.1 && Math.abs(wr)<0.1){
    if(mem.stT<0) mem.stT=t;
    else if(t-mem.stT>1.5){
      startEscape(mem,t,R);
      return escapeTick(mem,t,out);
    }
  } else mem.stT=-1;

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.4){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.3 && Math.abs(wr)<0.3){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        mem.drLast=0; mem.drMove=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(mem,out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=clamp(0.3*d,0.12,0.9);
      return steerRel(mem,obs,R,br,vcr,out);
    }
    const st=mem.sites[seen];
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: signal nearby but no visible site, search around here
  if(!obs.site && sci>=1.5 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(q.state!=='done' && hyp(q.x,q.y,P.x,P.y)<20){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo' && carried<mem.cap){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+60 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let g;
  if(wantBase) g={type:'base'};
  else if(bestIdx>=0) g={type:'site',idx:bestIdx};
  else g={type:'explore'};

  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.gBest=1e9; mem.gBestT=t;
    if(g.type!=='explore') mem.exG=null;
  }

  // goal progress watchdog
  if(mem.goal.type!=='explore' && !mem.sp && dB>=3){
    let gd=dB;
    if(mem.goal.type==='site'){
      const S=mem.sites[mem.goal.idx];
      gd=S?hyp(P.x,P.y,S.x,S.y):1e9;
    }
    if(gd<mem.gBest-3){mem.gBest=gd; mem.gBestT=t;}
    else if(t-mem.gBestT>60){
      if(mem.goal.type==='site'){
        const S=mem.sites[mem.goal.idx];
        if(S){S.tries++; if(S.tries>=2) S.state='bad';}
      }
      mem.goal=null; mem.sp=null; mem.gBest=1e9; mem.gBestT=t;
      return hold(mem,out,wl,wr);
    }
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0.3,right:-0.3,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  // learn wheel-speed per command gain while driving straight
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  if(mem.init && mem.lastL>0.25 && mem.lastR>0.25 && Math.abs(wl-wr)<0.3 && wl>0.3){
    const ratio=clamp(((wl+wr)/2)/((mem.lastL+mem.lastR)/2),1.2,3.5);
    mem.kG+=0.02*(ratio-mem.kG);
  }
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}

const RA=[-80,-60,-40,-20,0,20,40,60,80];
function wrap(a){return ((a+180)%360+360)%360-180;}
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function hyp(ax,ay,bx,by){return Math.hypot(bx-ax,by-ay);}
function brg(ax,ay,bx,by){return Math.atan2(by-ay,bx-ax)*180/Math.PI;}
function rad(d){return d*Math.PI/180;}
function num(v,d){return (typeof v==='number'&&isFinite(v))?v:d;}
function carriedCount(obs){
  const c=obs.carried;
  if(typeof c==='number'&&isFinite(c)) return c;
  if(c&&typeof c.length==='number') return c.length;
  return 0;
}
function mkSite(x,y,est,src){
  return {x:x,y:y,est:est,state:'todo',tries:0,src:src,checked:false,spDone:false};
}
function getRays(obs){
  const r=Array.isArray(obs.rays)?obs.rays:[];
  const R=[];
  for(let i=0;i<9;i++) R.push(clamp(num(r[i],15),0.1,15));
  return R;
}

// integrating hold: drives wheel speed to zero, counters slopes
function hold(mem,out,wl,wr){
  const v=(wl+wr)/2;
  mem.hc=clamp(mem.hc-0.03*v,-0.5,0.5);
  const c=clamp(mem.hc-0.2*v,-0.5,0.5);
  out.left=c; out.right=c; out.hold=true;
  return out;
}

function startRec(mem,t,dur,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  const s=ls>rs?1:-1;
  mem.rec={until:t+dur,l:-0.3-0.2*s,r:-0.3+0.2*s};
}

// timed escape: reverse, pivot toward open side, forward turn
function startEscape(mem,t,R){
  const ls=R[5]+R[6]+R[7]+R[8], rs=R[0]+R[1]+R[2]+R[3];
  let s=ls>rs?1:-1;
  if(mem.escN%2===1) s=-s;
  mem.escN++;
  mem.esc={t0:t,s:s};
  if(mem.goal && mem.goal.type==='site'){
    const S=mem.sites[mem.goal.idx];
    if(S){S.tries++; if(S.tries>=3) S.state='bad';}
  }
  mem.goal=null; mem.sp=null; mem.stT=-1;
  mem.anc={x:mem.px,y:mem.py,t:t};
  mem.gBest=1e9; mem.gBestT=t;
}
function escapeTick(mem,t,out){
  const e=mem.esc;
  if(!e) return null;
  const el=t-e.t0;
  const s=e.s;
  if(el<1.6){ out.left=-0.6; out.right=-0.6; }
  else if(el<2.5){ out.left=-0.5*s; out.right=0.5*s; }
  else if(el<4.0){ out.left=0.45-0.2*s; out.right=0.45+0.2*s; }
  else { mem.esc=null; return null; }
  out.hold=false;
  return out;
}

function init(obs,mem){
  const m=obs.mission||{};
  const x0=num(obs.x,200), y0=num(obs.y,200);
  const b=m.base||{x:x0,y:y0};
  mem.B={x:num(b.x,x0),y:num(b.y,y0)};
  mem.cap=num(m.capacity,5);
  mem.sites=[];
  const hints=Array.isArray(m.hints)?m.hints:[];
  for(let i=0;i<hints.length;i++){
    const h=hints[i]||{};
    mem.sites.push(mkSite(num(h.x,200),num(h.y,200),num(h.estimate,1),'hint'));
  }
  mem.hoff=0; mem.hoffSet=false; mem.hanc=null; mem.hoffMiss=0;
  mem.lastT=num(obs.t,0)-0.1; mem.lastGx=x0; mem.lastGy=y0; mem.still=0;
  mem.drX=x0; mem.drY=y0; mem.drAt={x:x0,y:y0};
  mem.px=x0; mem.py=y0; mem.frozen=false;
  mem.mode='drive'; mem.goal=null; mem.pickT=0; mem.goalSince=0;
  mem.sp=null; mem.rec=null; mem.drillIdx=-1; mem.drillT0=0;
  mem.drLast=0; mem.drMove=0;
  mem.apprKey=-1; mem.apprT0=0; mem.waitT=-1;
  mem.lastL=0; mem.lastR=0; mem.wasHold=false;
  mem.anc={x:x0,y:y0,t:num(obs.t,0)}; mem.stT=-1;
  mem.esc=null; mem.escN=0;
  mem.gBest=1e9; mem.gBestT=0;
  mem.grid=[];
  for(let gx=30;gx<=370;gx+=50) for(let gy=30;gy<=370;gy+=50) mem.grid.push({x:gx,y:gy,done:false});
  mem.exG=null; mem.exT0=0;
  mem.forceIdx=-1; mem.samples=0; mem.bumps=0;
  mem.hc=0; mem.kG=2.2;
}

function updPos(obs,mem,H){
  const t=num(obs.t,0);
  const dt=clamp(t-mem.lastT,0,0.5);
  mem.lastT=t;
  const v=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  mem.drX+=v*Math.cos(rad(H))*dt;
  mem.drY+=v*Math.sin(rad(H))*dt;
  const ox=num(obs.x,mem.lastGx), oy=num(obs.y,mem.lastGy);
  if(ox!==mem.lastGx||oy!==mem.lastGy){
    mem.lastGx=ox; mem.lastGy=oy; mem.still=0;
    mem.drAt={x:mem.drX,y:mem.drY};
  } else mem.still+=dt;
  mem.frozen=mem.still>2.0;
  if(mem.frozen){
    mem.px=mem.lastGx+(mem.drX-mem.drAt.x);
    mem.py=mem.lastGy+(mem.drY-mem.drAt.y);
  } else {
    mem.px=ox; mem.py=oy;
  }
}

function updHeading(obs,mem){
  if(mem.frozen) return;
  const x=num(obs.x,0), y=num(obs.y,0);
  if(!mem.hanc){mem.hanc={x:x,y:y}; return;}
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const fwd=(wl+wr)/2;
  if(Math.abs(wl-wr)>0.3||Math.abs(fwd)<0.4){mem.hanc={x:x,y:y}; return;}
  const d=hyp(mem.hanc.x,mem.hanc.y,x,y);
  if(d<10) return;
  let course=brg(mem.hanc.x,mem.hanc.y,x,y);
  if(fwd<0) course+=180;
  const diff=wrap(course-num(obs.heading,0));
  mem.hanc={x:x,y:y};
  if(!mem.hoffSet){mem.hoff=diff; mem.hoffSet=true; mem.hoffMiss=0; return;}
  const err=wrap(diff-mem.hoff);
  if(Math.abs(err)>50){
    mem.hoffMiss++;
    if(mem.hoffMiss>=3){mem.hoff=diff; mem.hoffMiss=0;}
  } else {
    mem.hoffMiss=0;
    mem.hoff=wrap(mem.hoff+0.25*err);
  }
}

function registerSite(obs,mem,H,P){
  const s=obs.site;
  const dist=num(s.distance,0);
  const ang=rad(H+num(s.bearing,0));
  const sx=P.x+dist*Math.cos(ang), sy=P.y+dist*Math.sin(ang);
  const val=num(s.value,1);
  for(const q of mem.sites){
    if(q.state==='done' && hyp(q.x,q.y,sx,sy)<4) return -1;
  }
  let best=-1,bd=1e9;
  for(let i=0;i<mem.sites.length;i++){
    const q=mem.sites[i];
    if(q.state==='done') continue;
    const d=hyp(q.x,q.y,sx,sy);
    if(d<bd){bd=d;best=i;}
  }
  if(best>=0){
    const q=mem.sites[best];
    const lim=(q.src==='hint')?22:10;
    if(bd<lim){
      q.x=sx; q.y=sy; q.est=val;
      if(q.state==='bad'&&q.tries<2) q.state='todo';
      return best;
    }
  }
  mem.sites.push(mkSite(sx,sy,val,'seen'));
  return mem.sites.length-1;
}

// steer with relative angles (positive = left)
function steerRel(mem,obs,R,relDes,vcr,out){
  const d=clamp(num(relDes,0),-85,85);
  let bestA=d, bestS=-1e9, bestCl=15;
  const cands=RA.concat([d]);
  for(let c=0;c<cands.length;c++){
    const a=cands[c];
    let cl=15;
    for(let k=0;k<9;k++){
      if(Math.abs(RA[k]-a)<=20.5 && R[k]<cl) cl=R[k];
    }
    const s=Math.min(cl,8)-0.05*Math.abs(a-d)-(cl<2.5?10:0);
    if(s>bestS){bestS=s; bestA=a; bestCl=cl;}
  }
  // forward cone clearance (-40..40 deg) limits speed so the rover can stop
  const f=Math.min(R[2],R[3],R[4],R[5],R[6]);
  let vg=Math.min(vcr,0.9,0.5*(f-1.2));
  if(bestCl<2.5) vg=0;
  vg*=Math.max(0,Math.cos(rad(clamp(bestA,-90,90))));
  if(vg<0) vg=0;
  const tq=clamp(0.35*rad(bestA),-0.3,0.3);
  const wf=(num(obs.wheelLeft,0)+num(obs.wheelRight,0))/2;
  let vc=vg/mem.kG;
  if(vg<=0 && wf>0.5 && f<3.0) vc=-0.25;
  out.left=clamp(vc-tq,-1,1);
  out.right=clamp(vc+tq,-1,1);
  out.hold=false;
  return out;
}

function drillTick(obs,mem,out,t,wl,wr){
  out.drill=true;
  hold(mem,out,wl,wr);
  const dr=num(obs.drilling,0);
  const s=mem.sites[mem.drillIdx];
  if(dr>mem.drLast+0.01){mem.drLast=dr; mem.drMove=t;}
  if(dr>=6.3){
    if(s) s.state='done';
    mem.samples++;
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    mem.progT=t; mem.anc={x:mem.px,y:mem.py,t:t};
    out.drill=false; out.left=0; out.right=0; out.hold=false;
    return out;
  }
  if(t-mem.drillT0>30 || t-mem.drMove>5){
    if(s){s.tries++; s.state=s.tries>=2?'bad':'todo';}
    mem.mode='drive'; mem.drillIdx=-1; mem.goal=null;
    out.drill=false;
  }
  return out;
}

function startSpiral(mem,cx,cy,P,t){
  const pts=[];
  const rings=[6,14];
  const a0=Math.atan2(P.y-cy,P.x-cx);
  for(let q=0;q<rings.length;q++){
    const r=rings[q];
    const N=Math.max(6,Math.round(2*Math.PI*r/7));
    for(let k=0;k<N;k++){
      const a=a0+2*Math.PI*k/N;
      pts.push({x:clamp(cx+r*Math.cos(a),2,398),y:clamp(cy+r*Math.sin(a),2,398)});
    }
  }
  mem.sp={pts:pts,i:0,t0:t,T0:t};
}

function spiralTick(mem,obs,P,H,R,out,t){
  const sp=mem.sp;
  if(t-sp.T0>130) return null;
  while(sp.i<sp.pts.length && hyp(P.x,P.y,sp.pts[sp.i].x,sp.pts[sp.i].y)<2.0){
    sp.i++; sp.t0=t;
  }
  if(sp.i>=sp.pts.length) return null;
  if(t-sp.t0>20){
    sp.i++; sp.t0=t;
    if(sp.i>=sp.pts.length) return null;
  }
  const w=sp.pts[sp.i];
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,w.x,w.y)-H),0.6,out);
}

function siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci){
  const idx=mem.goal.idx;
  const S=mem.sites[idx];
  if(!S||S.state!=='todo'){mem.goal=null; return hold(mem,out,wl,wr);}
  if(t-mem.goalSince>170){
    S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  const dS=hyp(P.x,P.y,S.x,S.y);
  if(dS<=5 && !obs.site){
    if(S.src==='hint' && !S.checked){
      S.checked=true;
      if(sci<0.1){
        S.state='bad'; mem.goal=null; mem.forceIdx=-1;
        return hold(mem,out,wl,wr);
      }
    }
    if(!mem.sp && !S.spDone) startSpiral(mem,S.x,S.y,P,t);
  }
  if(mem.sp){
    const r=spiralTick(mem,obs,P,H,R,out,t);
    if(r) return r;
    S.spDone=true; S.state='bad'; mem.goal=null; mem.forceIdx=-1; mem.sp=null;
    return hold(mem,out,wl,wr);
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,S.x,S.y)-H),dS<10?0.5:1.0,out);
}

function exploreTick(obs,mem,out,t,P,H,R){
  let g=mem.exG;
  if(!g || g.done || hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90){
    if(g && !g.done && (hyp(P.x,P.y,g.x,g.y)<6 || t-mem.exT0>90)) g.done=true;
    let best=null,bd=1e9;
    for(const q of mem.grid){
      if(q.done) continue;
      const d=hyp(P.x,P.y,q.x,q.y);
      if(d<bd){bd=d;best=q;}
    }
    if(!best){
      for(const q of mem.grid) q.done=false;
      best=mem.grid[0];
    }
    g=best; mem.exG=g; mem.exT0=t;
  }
  return steerRel(mem,obs,R,wrap(brg(P.x,P.y,g.x,g.y)-H),1.0,out);
}

function baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr){
  const B=mem.B;
  const bc=obs.beacon;
  const bcd=(bc&&typeof bc.distance==='number')?bc.distance:99;
  const dd=(bc&&bcd<20)?bcd:dB;
  if(dd<2.6){
    if(carried>0 && !obs.docked){
      if(mem.waitT<0) mem.waitT=t;
      if(t-mem.waitT>4){
        mem.waitT=-1;
        startRec(mem,t,2.0,R);
        out.left=mem.rec.l; out.right=mem.rec.r;
        return out;
      }
    } else mem.waitT=-1;
    return hold(mem,out,wl,wr);
  }
  mem.waitT=-1;
  let rel;
  if(bc && bcd<18 && typeof bc.bearing==='number') rel=bc.bearing;
  else rel=wrap(brg(P.x,P.y,B.x,B.y)-H);
  return steerRel(mem,obs,R,rel,dd<8?0.5:1.2,out);
}

function core(obs,mem){
  if(!mem.init){init(obs,mem); mem.init=true;}
  const t=num(obs.t,0);
  const out={left:0,right:0,drill:false,hold:false};
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  const carried=carriedCount(obs);
  const tl=num(obs.timeLeft,0);
  const bat=num(obs.battery,1);
  const docked=!!obs.docked;
  const B=mem.B;
  const H0=wrap(num(obs.heading,0)+mem.hoff);
  updPos(obs,mem,H0);
  updHeading(obs,mem);
  const H=wrap(num(obs.heading,0)+mem.hoff);
  const P={x:mem.px,y:mem.py};
  const dB=hyp(P.x,P.y,B.x,B.y);
  const R=getRays(obs);
  const sci=num(obs.science,0);
  const cmdMag=Math.max(Math.abs(mem.lastL),Math.abs(mem.lastR));

  if(mem.mode==='drill') return drillTick(obs,mem,out,t,wl,wr);

  if(mem.esc){
    const r=escapeTick(mem,t,out);
    if(r) return r;
  }
  if(mem.rec){
    if(t<mem.rec.until){out.left=mem.rec.l; out.right=mem.rec.r; return out;}
    mem.rec=null;
  }
  if(obs.bumped && !docked){
    mem.bumps++;
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }

  // stuck: commanded to move but no displacement, or wheels not turning
  const moving=!mem.wasHold && cmdMag>0.2 && !docked;
  if(!moving || hyp(mem.anc.x,mem.anc.y,P.x,P.y)>1.0){
    mem.anc={x:P.x,y:P.y,t:t};
  } else if(t-mem.anc.t>8){
    startEscape(mem,t,R);
    return escapeTick(mem,t,out);
  }
  if(moving && Math.abs(wl)<0.1 && Math.abs(wr)<0.1){
    if(mem.stT<0) mem.stT=t;
    else if(t-mem.stT>1.5){
      startEscape(mem,t,R);
      return escapeTick(mem,t,out);
    }
  } else mem.stT=-1;

  // visible site: approach and sample
  let seen=-1;
  if(obs.site) seen=registerSite(obs,mem,H,P);
  if(obs.site && seen>=0 && mem.sites[seen].state==='todo' && carried<mem.cap){
    const d=num(obs.site.distance,99), br=num(obs.site.bearing,0);
    if(mem.apprKey!==seen){mem.apprKey=seen; mem.apprT0=t;}
    if(d<=1.4){
      mem.apprKey=-1;
      if(Math.abs(wl)<0.3 && Math.abs(wr)<0.3){
        mem.mode='drill'; mem.drillIdx=seen; mem.drillT0=t;
        mem.drLast=0; mem.drMove=t;
        return drillTick(obs,mem,out,t,wl,wr);
      }
      return hold(mem,out,wl,wr);
    }
    if(t-mem.apprT0<=45){
      const vcr=clamp(0.3*d,0.12,0.9);
      return steerRel(mem,obs,R,br,vcr,out);
    }
    const st=mem.sites[seen];
    st.tries=2; st.state='bad';
    mem.apprKey=-1;
  }

  // science trigger: signal nearby but no visible site, search around here
  if(!obs.site && sci>=1.5 && !mem.sp && carried<mem.cap){
    let near=false;
    for(const q of mem.sites){
      if(q.state!=='done' && hyp(q.x,q.y,P.x,P.y)<20){near=true; break;}
    }
    if(!near){
      mem.sites.push(mkSite(P.x,P.y,1.5,'sci'));
      mem.forceIdx=mem.sites.length-1;
    }
  }

  // goal selection
  let bestIdx=-1, bestSc=-1;
  for(let i=0;i<mem.sites.length;i++){
    const s=mem.sites[i];
    if(s.state!=='todo') continue;
    const dp=hyp(P.x,P.y,s.x,s.y), ds=hyp(s.x,s.y,B.x,B.y);
    if((dp+ds)/0.9+40>tl) continue;
    let sc=Math.max(s.est,0.3)/(dp+0.6*ds+25);
    if(mem.goal && mem.goal.type==='site' && mem.goal.idx===i) sc*=1.3;
    if(sc>bestSc){bestSc=sc; bestIdx=i;}
  }
  if(mem.forceIdx>=0 && mem.sites[mem.forceIdx] && mem.sites[mem.forceIdx].state==='todo' && carried<mem.cap){
    bestIdx=mem.forceIdx;
  } else mem.forceIdx=-1;

  let wantBase=false;
  if(carried>0){
    if(carried>=mem.cap || tl<dB/0.9+60 || bat<0.12+dB*0.0015 || bestIdx<0) wantBase=true;
    else {
      const s=mem.sites[bestIdx];
      const dp=hyp(P.x,P.y,s.x,s.y);
      if(dp>50 && dB<0.5*dp) wantBase=true;
    }
  }

  let g;
  if(wantBase) g={type:'base'};
  else if(bestIdx>=0) g={type:'site',idx:bestIdx};
  else g={type:'explore'};

  if(mem.goal && mem.goal.type==='site' && g.type==='site' && mem.goal.idx!==g.idx &&
     mem.sites[mem.goal.idx] && mem.sites[mem.goal.idx].state==='todo' &&
     t-mem.pickT<15 && mem.forceIdx<0) g=mem.goal;
  const same=mem.goal && mem.goal.type===g.type && (g.type!=='site' || mem.goal.idx===g.idx);
  if(!same){
    mem.goal=g; mem.pickT=t; mem.goalSince=t; mem.sp=null;
    mem.gBest=1e9; mem.gBestT=t;
    if(g.type!=='explore') mem.exG=null;
  }

  // goal progress watchdog
  if(mem.goal.type!=='explore' && !mem.sp && dB>=3){
    let gd=dB;
    if(mem.goal.type==='site'){
      const S=mem.sites[mem.goal.idx];
      gd=S?hyp(P.x,P.y,S.x,S.y):1e9;
    }
    if(gd<mem.gBest-3){mem.gBest=gd; mem.gBestT=t;}
    else if(t-mem.gBestT>60){
      if(mem.goal.type==='site'){
        const S=mem.sites[mem.goal.idx];
        if(S){S.tries++; if(S.tries>=2) S.state='bad';}
      }
      mem.goal=null; mem.sp=null; mem.gBest=1e9; mem.gBestT=t;
      return hold(mem,out,wl,wr);
    }
  }

  if(mem.goal.type==='base') return baseTick(obs,mem,out,t,P,H,R,carried,dB,wl,wr);
  if(mem.goal.type==='site') return siteGoal(obs,mem,out,t,P,H,R,wl,wr,sci);
  return exploreTick(obs,mem,out,t,P,H,R);
}

function act(obs,mem){
  let o;
  try{
    o=core(obs,mem);
  }catch(e){
    o={left:0.3,right:-0.3,drill:false,hold:false};
  }
  const L=clamp(num(o.left,0),-1,1), Rt=clamp(num(o.right,0),-1,1);
  // learn wheel-speed per command gain while driving straight
  const wl=num(obs.wheelLeft,0), wr=num(obs.wheelRight,0);
  if(mem.init && mem.lastL>0.25 && mem.lastR>0.25 && Math.abs(wl-wr)<0.3 && wl>0.3){
    const ratio=clamp(((wl+wr)/2)/((mem.lastL+mem.lastR)/2),1.2,3.5);
    mem.kG+=0.02*(ratio-mem.kG);
  }
  mem.lastL=L; mem.lastR=Rt;
  mem.wasHold=!!o.hold;
  return {left:L,right:Rt,drill:!!o.drill};
}
